# Skiplist in Go

Below is a self-contained, production-ready skiplist. I've highlighted the non-obvious parts in comments: sentinel usage, the `update` array, level promotion/shrinking, and the concurrency model.

```go
// Package skiplist implements a concurrent, in-memory skiplist map.
//
// A skiplist is a probabilistic alternative to a balanced tree. It supports
// O(log n) expected-time search, insert, and delete, with a dramatically
// simpler implementation than a red-black or AVL tree.
//
// Concurrency model
//
// Search takes a shared (read) lock; Insert and Delete take an exclusive
// lock. Readers therefore scale across cores, and writers serialize. This
// is the right trade-off for read-heavy services. If your workload is
// write-heavy, a lock-free variant (e.g. based on CAS on forward pointers)
// is possible but substantially harder to get right.
package skiplist

import (
	"math/rand"
	"sync"
)

// Ordered is the set of key types the skiplist can index. Keys must be
// totally ordered by the built-in < operator.
type Ordered interface {
	~int | ~int8 | ~int16 | ~int32 | ~int64 |
		~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~uintptr |
		~float32 | ~float64 | ~string
}

const (
	// defaultMaxLevel caps tower height. 32 levels with promotionProb=0.25
	// supports ~4^32 ≈ 1.8e19 entries before the expected depth saturates,
	// which is far beyond any realistic in-memory map.
	defaultMaxLevel = 32

	// promotionProb is the probability that a node's tower is extended by
	// one more level. With p = 1/4 the expected number of forward pointers
	// per node is 1/(1-p) = 1.33 — cheaper than p = 1/2 while still
	// yielding O(log n) expected depth.
	promotionProb = 0.25
)

// node is one entry in the skiplist. len(next) == the height of this
// node's tower; next[i] points to the next node at level i, or nil if
// this node is the last at that level.
type node[K Ordered, V any] struct {
	key   K
	value V
	next  []*node[K, V]
}

// Skiplist is a concurrent ordered map backed by a skiplist.
//
// The zero value is not usable; construct one with New or NewWithMaxLevel.
type Skiplist[K Ordered, V any] struct {
	mu sync.RWMutex

	// head is a sentinel whose tower has maxLevel levels. It holds no
	// user key/value. Using a sentinel removes every "x == nil" special
	// case from the traversal loops: the search always has a valid node
	// to read .next from.
	head *node[K, V]

	// level is the highest level currently in use, in [1, maxLevel].
	// Searches start at level-1, so keeping this tight (shrinking on
	// delete) avoids scanning empty top levels.
	level    int
	maxLevel int

	// rng is only touched while mu is held for writing (inside Insert),
	// so it needs no separate lock.
	rng *rand.Rand

	length int
}

// New returns a Skiplist with the default maximum level.
func New[K Ordered, V any]() *Skiplist[K, V] {
	return NewWithMaxLevel[K, V](defaultMaxLevel)
}

// NewWithMaxLevel returns a Skiplist whose towers are capped at maxLevel.
// maxLevel must be >= 1; it panics otherwise. A larger maxLevel trades
// memory for a lower probability of the random level generator saturating.
func NewWithMaxLevel[K Ordered, V any](maxLevel int) *Skiplist[K, V] {
	if maxLevel < 1 {
		panic("skiplist: maxLevel must be >= 1")
	}
	head := &node[K, V]{next: make([]*node[K, V], maxLevel)}
	return &Skiplist[K, V]{
		head:     head,
		level:    1,
		maxLevel: maxLevel,
		// rand.NewSource(rand.Int63()) uses the auto-seeded global source,
		// so this is safe to call concurrently across many Skiplist values.
		rng: rand.New(rand.NewSource(rand.Int63())),
	}
}

// Len returns the number of entries in the skiplist.
func (s *Skiplist[K, V]) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.length
}

// Search returns the value stored for key, or the zero value and false if
// key is absent.
func (s *Skiplist[K, V]) Search(key K) (V, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	x := s.head
	// Walk down from the top level. At each level, advance as far as
	// possible while staying strictly left of `key`. The classic trick:
	// we only ever need to move forward, never back, so the walk is a
	// sequence of "express" hops followed by finer-grained ones.
	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
	}
	// At level 0, x is the greatest node with x.key < key. The target,
	// if present, is immediately to its right.
	x = x.next[0]
	if x != nil && x.key == key {
		return x.value, true
	}
	var zero V
	return zero, false
}

// Insert adds key with value, or updates the value if key already exists.
// It returns true if a new entry was created, false if an existing entry
// was overwritten.
func (s *Skiplist[K, V]) Insert(key K, value V) (inserted bool) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// update[i] will hold the rightmost node at level i whose key is
	// strictly less than key. These are exactly the nodes whose forward
	// pointers must be rewired to include the new node.
	//
	// The array is sized maxLevel, not s.level, because we may grow the
	// list during this call.
	update := make([]*node[K, V], s.maxLevel)

	x := s.head
	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}

	// x is now the level-0 predecessor; its successor is either the
	// target key (update in place) or a larger key / nil (insert).
	if next := x.next[0]; next != nil && next.key == key {
		next.value = value
		return false
	}

	lvl := s.randomLevel()
	if lvl > s.level {
		// The new node reaches into levels that no existing node occupies.
		// At those levels the only possible predecessor is the head
		// sentinel, so point update at head and raise the list's level.
		//
		// This is the trickiest part of the algorithm: without it, the
		// rewire loop below would index update[i] for levels that were
		// never visited during the descent.
		for i := s.level; i < lvl; i++ {
			update[i] = s.head
		}
		s.level = lvl
	}

	n := &node[K, V]{
		key:   key,
		value: value,
		next:  make([]*node[K, V], lvl),
	}
	// Splice n in at every level of its tower. Order matters only in
	// that we must read the old successor before overwriting it.
	for i := 0; i < lvl; i++ {
		n.next[i] = update[i].next[i]
		update[i].next[i] = n
	}
	s.length++
	return true
}

// Delete removes key from the skiplist. It returns true if the key was
// present.
func (s *Skiplist[K, V]) Delete(key K) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	update := make([]*node[K, V], s.maxLevel)
	x := s.head
	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}

	target := x.next[0]
	if target == nil || target.key != key {
		return false
	}

	// Unlink target from every level of its tower. update[i] is a valid
	// predecessor at each level i < len(target.next) because the descent
	// above recorded the rightmost node left of key at every level, and
	// target is the first node with key >= `key`.
	for i := 0; i < len(target.next); i++ {
		update[i].next[i] = target.next[i]
	}

	// Shrink s.level if the top levels became empty. Without this, a
	// workload that inserts one tall node and then deletes it would leave
	// searches starting at a level with no nodes, wasting comparisons.
	for s.level > 1 && s.head.next[s.level-1] == nil {
		s.level--
	}

	s.length--
	return true
}

// randomLevel returns a value in [1, maxLevel] drawn from a geometric
// distribution with parameter promotionProb. The caller must hold the
// write lock so that s.rng is accessed safely.
func (s *Skiplist[K, V]) randomLevel() int {
	lvl := 1
	for lvl < s.maxLevel && s.rng.Float64() < promotionProb {
		lvl++
	}
	return lvl
}
```

## Notes on the tricky parts

**Sentinel head.** `head` is a permanent node whose tower has `maxLevel` levels. It carries no user key. This removes every `if x == nil` check from the descent loops — `x.next[i]` is always dereferenceable. Its key is never compared against user keys because the loops only advance while `x.next[i].key < key`, and `head.key` is never examined.

