# Skiplist in C

A skip list with `O(log n)` expected time for insert/delete/search, using a randomized level generator. Thread-unsafe (documented below) — wrap with a lock if you need concurrency.

```c
/*
 * skiplist.c - A generic-ish skiplist keyed by int64_t.
 *
 * Design notes:
 *   - Nodes store (key, value). Values are void* owned by the caller.
 *   - A single sentinel "head" node avoids NULL checks in the hot path.
 *   - Level generation uses a geometric distribution with p = 0.5, capped
 *     at SKIPLIST_MAX_LEVEL.  Probability of exceeding cap is 2^-cap, so
 *     with cap = 32 that's ~2e-10 — fine for any realistic key count.
 *   - Delete uses the classic "update[]" trick: after splicing the node
 *     out at every level, we walk the head's higher levels and shorten
 *     the list's current max level where the head now points to NULL.
 *     Without that, the list slowly "grows" stale empty levels.
 *
 * NOT thread-safe.  If you need concurrent use, put a single pthread_rwlock
 * around the whole structure (simplest, correct) or use a lock-free variant.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define SKIPLIST_MAX_LEVEL 32
#define SKIPLIST_P         0.5

typedef struct skiplist_node {
    int64_t                 key;
    void                   *value;
    struct skiplist_node  **forward; /* array of length `level` */
} skiplist_node;

typedef struct {
    skiplist_node   *head;       /* sentinel; key/value unused */
    size_t           level;      /* current highest level in use (>= 1) */
    size_t           count;      /* number of live entries */
    void           (*free_value)(void *);
} skiplist;

/* ---------- helpers ---------- */

/*
 * Allocate a node with `level` forward pointers.  The forward array is
 * stored inline after the struct to keep the allocation count at one.
 */
static skiplist_node *node_new(int64_t key, void *value, size_t level)
{
    /* sizeof(struct) + level * sizeof(ptr), all in one malloc. */
    skiplist_node *n = malloc(sizeof(*n) + level * sizeof(*n->forward));
    if (!n) return NULL;
    n->key   = key;
    n->value = value;
    /* forward[] lives immediately after the struct. */
    n->forward = (skiplist_node **)((char *)n + sizeof(*n));
    memset(n->forward, 0, level * sizeof(*n->forward));
    return n;
}

static void node_free(skiplist_node *n, void (*free_value)(void *))
{
    if (n->value && free_value)
        free_value(n->value);
    free(n);
}

/*
 * Random level in [1, SKIPLIST_MAX_LEVEL].  Uses rand(); if you need
 * reproducible quality, swap in xorshift64* or PCG — rand()'s low bits
 * are historically weak on some libc implementations.
 */
static size_t random_level(void)
{
    size_t lvl = 1;
    while (lvl < SKIPLIST_MAX_LEVEL &&
           ((double)rand() / (double)RAND_MAX) < SKIPLIST_P) {
        lvl++;
    }
    return lvl;
}

/* ---------- public API ---------- */

skiplist *skiplist_create(void (*free_value)(void *))
{
    skiplist *sl = malloc(sizeof(*sl));
    if (!sl) return NULL;

    sl->head = node_new(0, NULL, SKIPLIST_MAX_LEVEL);
    if (!sl->head) { free(sl); return NULL; }

    sl->level      = 1;
    sl->count      = 0;
    sl->free_value = free_value;
    return sl;
}

void skiplist_destroy(skiplist *sl)
{
    if (!sl) return;
    skiplist_node *n = sl->head->forward[0];
    while (n) {
        skiplist_node *next = n->forward[0];
        node_free(n, sl->free_value);
        n = next;
    }
    free(sl->head);
    free(sl);
}

/*
 * Insert (key, value).  Duplicate keys are rejected: returns false and
 * leaves the existing entry untouched (value is NOT freed — caller owns it).
 * Returns true on successful insertion.
 *
 * `update[]` holds, for each level, the rightmost node whose forward
 * pointer at that level will be spliced to the new node.
 */
bool skiplist_insert(skiplist *sl, int64_t key, void *value)
{
    skiplist_node *update[SKIPLIST_MAX_LEVEL];
    skiplist_node *x = sl->head;

    for (size_t i = sl->level; i-- > 0; ) {
        while (x->forward[i] && x->forward[i]->key < key)
            x = x->forward[i];
        update[i] = x;
    }

    x = x->forward[0];
    if (x && x->key == key)
        return false; /* duplicate */

    size_t lvl = random_level();
    if (lvl > sl->level) {
        /*
         * Bump the list's level.  update[] entries beyond the old level
         * must point at head, since head is the only node at those levels.
         */
        for (size_t i = sl->level; i < lvl; i++)
            update[i] = sl->head;
        sl->level = lvl;
    }

    skiplist_node *n = node_new(key, value, lvl);
    if (!n) return false;

    for (size_t i = 0; i < lvl; i++) {
        n->forward[i]     = update[i]->forward[i];
        update[i]->forward[i] = n;
    }

    sl->count++;
    return true;
}

/*
 * Search.  Returns the value if found, NULL otherwise.  Because values
 * can legitimately be NULL, prefer skiplist_contains() if you need to
 * distinguish "not found" from "found with NULL value".
 */
void *skiplist_search(const skiplist *sl, int64_t key)
{
    const skiplist_node *x = sl->head;
    for (size_t i = sl->level; i-- > 0; ) {
        while (x->forward[i] && x->forward[i]->key < key)
            x = x->forward[i];
    }
    x = x->forward[0];
    return (x && x->key == key) ? x->value : NULL;
}

bool skiplist_contains(const skiplist *sl, int64_t key)
{
    const skiplist_node *x = sl->head;
    for (size_t i = sl->level; i-- > 0; ) {
        while (x->forward[i] && x->forward[i]->key < key)
            x = x->forward[i];
    }
    x = x->forward[0];
    return x && x->key == key;
}

/*
 * Delete key.  Returns true if an entry was removed; the stored value is
 * freed via the destructor passed to skiplist_create (if any).  Returns
 * false if key was not present.
 */
bool skiplist_delete(skiplist *sl, int64_t key)
{
    skiplist_node *update[SKIPLIST_MAX_LEVEL];
    skiplist_node *x = sl->head;

    for (size_t i = sl->level; i-- > 0; ) {
        while (x->forward[i] && x->forward[i]->key < key)
            x = x->forward[i];
        update[i] = x;
    }

    x = x->forward[0];
    if (!x || x->key != key)
        return false;

    /* Splice x out at every level it appears in. */
    for (size_t i = 0; i < sl->level; i++) {
        if (update[i]->forward[i] != x)
            break; /* x doesn't exist at this level */
        update[i]->forward[i] = x->forward[i];
    }

    node_free(x, sl->free_value);
    sl->count--;

    /*
     * Contract the list's level: while the top level has no live nodes,
     * drop it.  This keeps search/insert loops tight.
     */
    while (sl->level > 1 && sl->head->forward[sl->level - 1] == NULL)
        sl->level--;

    return true;
}

size_t skiplist_count(const skiplist *sl)
{
    return sl->count;
}
```

## Usage sketch

```c
static void free_str(void *p) { free(p); }

int main(void) {
    skiplist *sl = skiplist_create(free_str);

    skiplist_insert(sl, 42, strdup("answer"));
    skiplist_insert(sl,  7, strdup("seven"));

    void *v = skiplist_search(sl, 42);
    if (v) printf("42 -> %s\n", (char *)v);

    skiplist_delete(sl, 7);          /* frees "seven" */
    assert(!skiplist_contains(sl, 7));

    skiplist_destroy(sl);
}
```

## The tricky parts, spelled out

1. **Sentinel head.** `head` is a full-height node with garbage key/value. Every level's chain starts at head, so the search loop never needs a NULL check on `update[i]`.

2. **`update[]` beyond the current level.** When `random_level()` returns a level taller than `sl->level`, the newly-created levels have no "predecessor" other than head — that's why we fill `update[i] = head` for those slots *before* splicing. Skipping this is the #1 bug in hand-rolled skip lists.

3. **Level contraction on delete.** It's tempting to leave `sl->level` alone. Don't: you'll accumulate empty top levels and search loops will run useless iterations, and `random_level()` will sometimes hand you levels that already exist but are empty. The `while` loop after a delete fixes this in O(1) amortized.

4. **Splice loop truncation.** In `skiplist_delete`, notice the `break` when `update[i]->forward[i] != x`. If `x`'s level is smaller than `sl->level`, upper levels don't contain `x` and shouldn't be touched. Do not splice blindly to `x->forward[i]` — that array is shorter than `sl->level`.

5. **Single allocation per node.** The forward array lives inside the node's malloc'd block. This halves allocator traffic versus two mallocs, and improves cache locality since the pointers sit next to the key.

6. **`rand()` quality.** glibc's `rand()` is a Lagged Fibonacci generator with poor low bits. Because our level generation only uses the *top* bit-ish comparison (`< P`), we're mostly safe — but for anything adversarial, swap in `xorshift64*` or PCG. The interface is intentionally not parameterized so a caller can substitute.

7. **NULL values vs. not-found.** `skiplist_search` returns `NULL` in both cases. Use `skiplist_contains` to disambiguate. This is a deliberate trade-off to keep the hot path return type simple; if you want a `bool *found` out-param, it's a two-line change.

8. **Ownership.** Values are caller-owned. On delete/destroy they're passed to `free_value` if non-NULL. Duplicate-key inserts return `false` and do **not** take ownership of the rejected value — the caller must free it.

9. **Not thread-safe.** Every operation mutates or reads shared pointers without synchronization. If you need concurrent access, the simplest correct thing is a single `pthread_rwlock_t` in the `skiplist` struct, taken exclusive for insert/delete and shared for search. Lock-free variants exist but reimplementing one for a production service is a project, not a patch.

```go
package main

type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func InorderTraversal(root *TreeNode) []int {
	result := []int{}
	stack := []*TreeNode{}
	curr := root

	for curr != nil || len(stack) > 0 {
		// Go as far left as possible, pushing nodes onto the stack.
		for curr != nil {
			stack = append(stack, curr)
			curr = curr.Left
		}

		// Pop the next node to visit.
		curr = stack[len(stack)-1]
		stack = stack[:len(stack)-1]

		// Visit it.
		result = append(result, curr.Val)

		// Then process its right subtree.
		curr = curr.Right
	}

	return result
}
```

### How it works

In-order traversal visits nodes in this order:

1. Left subtree
2. Current node
3. Right subtree

The explicit stack simulates the recursion call stack:

- Push all left descendants until reaching `nil`.
- Pop the most recent node, which is the next node in in-order sequence.
- Add its value to the result.
- Move to its right child and repeat.

### Complexity

- **Time complexity:** `O(n)`  
  Every node is pushed onto the stack once and popped once.

- **Space complexity:** `O(h)` auxiliary stack space  
  `h` is the height of the tree.
  - Balanced tree: `O(log n)`
  - Skewed tree: `O(n)`

If the returned `result` slice is included, then total space is `O(n)` because it stores all node values.

