```ts
export type WeightedEdge = {
  to: string;
  weight: number;
};

export type WeightedGraph = Map<string, WeightedEdge[]>;

export interface DijkstraResult {
  distances: Map<string, number>;
  previous: Map<string, string | null>;
}

/**
 * Binary min-heap.
 * O(log n) push/pop.
 */
class MinHeap<T> {
  private items: T[] = [];

  constructor(private readonly compare: (a: T, b: T) => number) {}

  get size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  peek(): T | undefined {
    return this.items[0];
  }

  push(item: T): void {
    this.items.push(item);
    this.bubbleUp(this.items.length - 1);
  }

  pop(): T | undefined {
    if (this.items.length === 0) return undefined;

    const root = this.items[0];
    const last = this.items.pop()!;

    if (this.items.length > 0) {
      this.items[0] = last;
      this.bubbleDown(0);
    }

    return root;
  }

  private bubbleUp(index: number): void {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);

      if (this.compare(this.items[index], this.items[parent]) >= 0) {
        break;
      }

      [this.items[index], this.items[parent]] = [
        this.items[parent],
        this.items[index],
      ];

      index = parent;
    }
  }

  private bubbleDown(index: number): void {
    const length = this.items.length;

    while (true) {
      const left = index * 2 + 1;
      const right = index * 2 + 2;
      let smallest = index;

      if (
        left < length &&
        this.compare(this.items[left], this.items[smallest]) < 0
      ) {
        smallest = left;
      }

      if (
        right < length &&
        this.compare(this.items[right], this.items[smallest]) < 0
      ) {
        smallest = right;
      }

      if (smallest === index) break;

      [this.items[index], this.items[smallest]] = [
        this.items[smallest],
        this.items[index],
      ];

      index = smallest;
    }
  }
}

type QueueItem = {
  node: string;
  dist: number;
};

/**
 * Dijkstra's shortest path using an adjacency list and binary min-heap.
 *
 * Assumes non-negative edge weights.
 * Throws if a negative edge weight is found.
 */
export function dijkstra(
  graph: WeightedGraph,
  source: string,
): DijkstraResult {
  const vertices = new Set<string>();

  for (const [from, edges] of graph) {
    vertices.add(from);

    for (const edge of edges) {
      if (edge.weight < 0) {
        throw new Error("Dijkstra does not support negative edge weights");
      }

      vertices.add(edge.to);
    }
  }

  vertices.add(source);

  const distances = new Map<string, number>();
  const previous = new Map<string, string | null>();

  for (const vertex of vertices) {
    distances.set(vertex, Infinity);
    previous.set(vertex, null);
  }

  distances.set(source, 0);

  const heap = new MinHeap<QueueItem>((a, b) => a.dist - b.dist);

  heap.push({ node: source, dist: 0 });

  while (!heap.isEmpty()) {
    const current = heap.pop()!;
    const { node, dist } = current;

    // Stale entry: a shorter distance was already found.
    if (dist > (distances.get(node) ?? Infinity)) {
      continue;
    }

    const edges = graph.get(node) ?? [];

    for (const edge of edges) {
      const nextDist = dist + edge.weight;
      const knownDist = distances.get(edge.to) ?? Infinity;

      if (nextDist < knownDist) {
        distances.set(edge.to, nextDist);
        previous.set(edge.to, node);

        heap.push({
          node: edge.to,
          dist: nextDist,
        });
      }
    }
  }

  return { distances, previous };
}

/**
 * Reconstructs the shortest path from source to target.
 * Returns null if target is unreachable.
 */
export function shortestPath(
  graph: WeightedGraph,
  source: string,
  target: string,
): string[] | null {
  const { distances, previous } = dijkstra(graph, source);

  const targetDistance = distances.get(target);

  if (targetDistance === undefined || targetDistance === Infinity) {
    return null;
  }

  const path: string[] = [];

  let current: string | null = target;

  while (current !== null) {
    path.push(current);

    if (current === source) {
      break;
    }

    current = previous.get(current) ?? null;
  }

  if (path[path.length - 1] !== source) {
    return null;
  }

  return path.reverse();
}
