// Path halving: compresses paths while finding the root.
__device__ int find_root(int* parent, int x) {
    while (true) {
        int p = parent[x];
        if (p == x) return x;
        int gp = parent[p];
        // Try to point x directly to its grandparent.
        atomicCAS(&parent[x], p, gp);
        x = gp;
    }
}

// Union by rank with atomic CAS on parent links.
__device__ void unite(int* parent, int* rank, int a, int b) {
    int ra = find_root(parent, a);
    int rb = find_root(parent, b);

    while (ra != rb) {
        int rra = rank[ra];
        int rrb = rank[rb];

        if (rra < rrb) {
            if (atomicCAS(&parent[ra], ra, rb) == ra) return;
        } else if (rra > rrb) {
            if (atomicCAS(&parent[rb], rb, ra) == rb) return;
        } else {
            if (atomicCAS(&parent[rb], rb, ra) == rb) {
                atomicAdd(&rank[ra], 1);
                return;
            }
        }

        // CAS failed; roots may have changed, so retry.
        ra = find_root(parent, ra);
        rb = find_root(parent, rb);
    }
}

__global__ void init_uf(int* parent, int* rank, int n) {
