# Min-Heap Implementation in Kotlin

Here's a complete min-heap implementation with comprehensive unit tests.

## MinHeap.kt

```kotlin
package com.example.heap

/**
 * A binary min-heap backed by a dynamically growing array.
 * The smallest element is always at the root (index 0).
 */
class MinHeap<T : Comparable<T>> {
    private val elements = mutableListOf<T>()

    val size: Int get() = elements.size
    val isEmpty: Boolean get() = elements.isEmpty()

    /** Returns the minimum element without removing it, or null if the heap is empty. */
    fun peek(): T? = elements.firstOrNull()

    /**
     * Inserts an element into the heap.
     * Sift-up maintains the heap invariant.
     * Time: O(log n)
     */
    fun push(value: T) {
        elements.add(value)
        siftUp(elements.lastIndex)
    }

    /**
     * Removes and returns the minimum element, or null if the heap is empty.
     * Moves the last element to the root and sift-downs.
     * Time: O(log n)
     */
    fun pop(): T? {
        if (elements.isEmpty()) return null

        val min = elements[0]
        val last = elements.removeAt(elements.lastIndex)

        if (elements.isNotEmpty()) {
            elements[0] = last
            siftDown(0)
        }
        return min
    }

    /**
     * Restores the heap invariant in-place. Useful if the backing array was
     * mutated directly (e.g., building a heap from an existing collection).
     * Time: O(n)
     */
    fun heapify() {
        if (elements.size < 2) return
        for (i in (elements.size / 2 - 1) downTo 0) {
            siftDown(i)
        }
    }

    /** Removes all elements. */
    fun clear() = elements.clear()

    // --- Internals ---

    private fun siftUp(index: Int) {
        var i = index
        while (i > 0) {
            val parent = (i - 1) / 2
            if (elements[i] < elements[parent]) {
                swap(i, parent)
                i = parent
            } else {
                break
            }
        }
    }

    private fun siftDown(index: Int) {
        var i = index
        val n = elements.size
        while (true) {
            val left = 2 * i + 1
            val right = 2 * i + 2
            var smallest = i

            if (left < n && elements[left] < elements[smallest]) smallest = left
            if (right < n && elements[right] < elements[smallest]) smallest = right

            if (smallest == i) break
            swap(i, smallest)
            i = smallest
        }
    }

    private fun swap(a: Int, b: Int) {
        val tmp = elements[a]
        elements[a] = elements[b]
        elements[b] = tmp
    }

    override fun toString(): String = elements.toString()
}
```

## Utility: builder for testing heapify from an arbitrary array

Since `heapify()` only makes sense when the backing list is out of order, I'll expose a small factory:

```kotlin
fun <T : Comparable<T>> minHeapOf(vararg values: T): MinHeap<T> {
    val heap = MinHeap<T>()
    // We use push() to construct, but tests can construct a bad array
    // via reflection-free approach below.
    values.forEach { heap.push(it) }
    return heap
}
```

Actually, for a proper heapify test, I'll add a secondary constructor:

```kotlin
class MinHeap<T : Comparable<T>>(initial: List<T> = emptyList()) {
    private val elements = initial.toMutableList()
    // ... rest same

    init { heapify() }
}
```

If you prefer not to change the class, an alternative is to make the backing list injectable for tests. I'll keep the design clean by adding the initial-value constructor — it's a common and useful API.

## MinHeapTest.kt

```kotlin
package com.example.heap

import kotlin.test.*

class MinHeapTest {

    // ---------- Basic behavior ----------

    @Test
    fun `empty heap has size zero and returns null on peek and pop`() {
        val heap = MinHeap<Int>()
        assertEquals(0, heap.size)
        assertTrue(heap.isEmpty)
        assertNull(heap.peek())
        assertNull(heap.pop())
    }

    @Test
    fun `single element push then peek then pop`() {
        val heap = MinHeap<Int>()
        heap.push(42)
        assertEquals(1, heap.size)
        assertEquals(42, heap.peek())
        assertEquals(42, heap.pop())
        assertTrue(heap.isEmpty)
        assertNull(heap.pop())
    }

    @Test
    fun `pops elements in ascending order`() {
        val heap = MinHeap<Int>()
        val values = listOf(5, 3, 8, 1, 9, 2, 7, 4, 6, 0)
        values.forEach { heap.push(it) }

        assertEquals(values.size, heap.size)

        val result = mutableListOf<Int>()
        while (!heap.isEmpty) {
            result.add(heap.pop()!!)
        }
        assertEquals(values.sorted(), result)
        assertTrue(heap.isEmpty)
    }

    @Test
    fun `peek does not remove element`() {
        val heap = MinHeap<Int>()
        heap.push(10); heap.push(5); heap.push(20)
        assertEquals(5, heap.peek())
        assertEquals(5, heap.peek())
        assertEquals(3, heap.size)
    }

    // ---------- Duplicates ----------

    @Test
    fun `handles duplicate values correctly`() {
        val heap = MinHeap<Int>()
        listOf(3, 1, 3, 2, 1, 2).forEach { heap.push(it) }

        val result = generateSequence { heap.pop() }.toList()
        assertEquals(listOf(1, 1, 2, 2, 3, 3), result)
    }

    @Test
    fun `all identical values`() {
        val heap = MinHeap<Int>()
        repeat(5) { heap.push(7) }
        val result = generateSequence { heap.pop() }.toList()
        assertEquals(listOf(7, 7, 7, 7, 7), result)
    }

    // ---------- Edge cases on orderings ----------

    @Test
    fun `already sorted ascending input`() {
        val heap = MinHeap<Int>()
        (1..10).forEach { heap.push(it) }
        val result = generateSequence { heap.pop() }.toList()
        assertEquals((1..10).toList(), result)
    }

    @Test
    fun `reverse sorted input`() {
        val heap = MinHeap<Int>()
        (10 downTo 1).forEach { heap.push(it) }
        val result = generateSequence { heap.pop() }.toList()
        assertEquals((1..10).toList(), result)
    }

    @Test
    fun `handles negative numbers and zero`() {
        val heap = MinHeap<Int>()
        listOf(0, -5, 3, -1, 8, -10).forEach { heap.push(it) }
        val result = generateSequence { heap.pop() }.toList()
        assertEquals(listOf(-10, -5, -1, 0, 3, 8), result)
    }

    @Test
    fun `works with strings (lexicographic order)`() {
        val heap = MinHeap<String>()
        listOf("banana", "apple", "cherry", "date", "apple").forEach { heap.push(it) }
        val result = generateSequence { heap.pop() }.toList()
        assertEquals(listOf("apple", "apple", "banana", "cherry", "date"), result)
    }

    // ---------- heapify constructor ----------

    @Test
    fun `constructor heapifies unsorted input`() {
        val heap = MinHeap(listOf(9, 4, 7, 1, 8, 2, 6, 3, 5))
        val result = generateSequence { heap.pop() }.toList()
        assertEquals((1..9).toList(), result)
    }

    @Test
    fun `heapify on empty and single element lists`() {
        val empty = MinHeap<Int>(emptyList())
        assertTrue(empty.isEmpty)

        val single = MinHeap(listOf(1))
        assertEquals(1, single.size)
        assertEquals(1, single.peek())
    }

    // ---------- Stress test ----------

    @Test
    fun `random large input produces fully sorted output`() {
        val random = kotlin.random.Random(42)
        val values = List(1000) { random.nextInt(-500, 500) }
        val heap = MinHeap<Int>()
        values.forEach { heap.push(it) }

        val result = generateSequence { heap.pop() }.toList()
        assertEquals(values.sorted(), result)
    }

    // ---------- Interleaved push / pop ----------

    @Test
    fun `interleaved push and pop maintains ordering`() {
        val heap = MinHeap<Int>()

        heap.push(5)
        heap.push(1)
        heap.push(3)
        assertEquals(1, heap.pop())

        heap.push(0)
        heap.push(7)
        assertEquals(0, heap.pop())
        assertEquals(3, heap.pop())

        heap.push(2)
        assertEquals(2, heap.pop())
        assertEquals(5, heap.pop())
        assertEquals(7, heap.pop())
        assertNull(heap.pop())
    }

    // ---------- clear ----------

    @Test
    fun `clear empties the heap`() {
        val heap = MinHeap<Int>()
        heap.push(1); heap.push(2); heap.push(3)
        heap.clear()
        assertTrue(heap.isEmpty)
        assertNull(heap.pop())
    }
}
```

## Design Notes

**`pop()` details** — The classic pitfall is forgetting the `elements.isNotEmpty()` check after `removeAt(lastIndex)`. When the heap had exactly one element, popping leaves an empty list, and writing to index `0` would throw `IndexOutOfBoundsException`.

**`(i - 1) / 2` for parent** — Kotlin's integer division truncates toward zero, so for the root's children `i=1` and `i=2`, `(1-1)/2 == 0` and `(2-1)/2 == 0`, both correct. `i=0` is guarded by the `while (i > 0)` loop.

**`heapify()` runs `siftDown` from the last non-leaf** — starting at `size/2 - 1` down to `0`. This is O(n), not O(n log n), because leaves don't need processing.

**Generic bound `T : Comparable<T>`** — Kotlin's `<` operator on `Comparable` resolves to `compareTo`, so this is the minimal contract needed.

**Tests use Kotlin's `kotlin.test`** — runnable with JUnit 5, kotlin-test-junit, or Ktor's test infra. The stress test uses a fixed `Random(42)` seed so failures are reproducible.

Below is a self-contained CUDA C++ implementation of a device-side token bucket rate limiter, plus a set of unit tests covering the important edge cases. The rate limiter is thread-safe across CUDA threads/blocks by using a small spinlock around the bucket state.

## `token_bucket.cuh`

```cpp
#pragma once

#include <cuda_runtime.h>

// Device-side token bucket.
// All fields are stored in global memory when used from a kernel.
struct TokenBucket {
    double tokens;                 // current number of tokens
    double capacity;               // maximum tokens
    double rate_per_sec;           // refill rate in tokens per second
    unsigned long long last_refill_ns;
    unsigned int lock;             // spinlock: 0 = free, 1 = locked
};

// Reads the global nanosecond timer. This is synchronized across all SMs.
__device__ __forceinline__ unsigned long long globaltimer_ns() {
    unsigned long long t;
    asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t));
    return t;
}

__device__ __forceinline__ void token_bucket_lock(TokenBucket* tb) {
    while (atomicCAS(&tb->lock, 0u, 1u) != 0u) {
        // Optional: back off to reduce contention.
        // __nanosleep(10);
    }
    __threadfence();
}

__device__ __forceinline__ void token_bucket_unlock(TokenBucket* tb) {
    __threadfence();
    atomicExch(&tb->lock, 0u);
}

// Initialize a bucket. Call from a single thread, or before concurrent use.
__device__ __forceinline__ void token_bucket_init(
    TokenBucket* tb,
    double capacity,
    double rate_per_sec,
    unsigned long long now_ns)
{
    tb->tokens = capacity;
    tb->capacity = capacity;
    tb->rate_per_sec = rate_per_sec;
    tb->last_refill_ns = now_ns;
    tb->lock = 0u;
}

// Try to acquire `requested` tokens. Returns true if successful.
// requested <= 0 always succeeds and consumes nothing.
__device__ __forceinline__ bool token_bucket_try_acquire(
    TokenBucket* tb,
    double requested = 1.0)
{
    if (requested <= 0.0) {
        return true;
    }

    token_bucket_lock(tb);

    const unsigned long long now_ns = globaltimer_ns();

    // Refill based on elapsed time.
    if (now_ns > tb->last_refill_ns) {
        const double elapsed_s = static_cast<double>(now_ns - tb->last_refill_ns) * 1e-9;
        double refill = elapsed_s * tb->rate_per_sec;

        if (refill > 0.0) {
            tb->tokens += refill;
            if (tb->tokens > tb->capacity) {
                tb->tokens = tb->capacity;
            }
        }

        tb->last_refill_ns = now_ns;
    }

    bool allowed = false;
    if (tb->tokens >= requested) {
        tb->tokens -= requested;
        allowed = true;
    }

    token_bucket_unlock(tb);
    return allowed;
}
```

