// min_heap.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CUDA_CHECK(call)                                                     \
    do {                                                                     \
        cudaError_t err = call;                                              \
        if (err != cudaSuccess) {                                            \
            fprintf(stderr, "CUDA error at %s:%d: %s\n", __FILE__, __LINE__, \
                    cudaGetErrorString(err));                                \
            exit(EXIT_FAILURE);                                              \
        }                                                                    \
    } while (0)

// ---------------------------------------------------------------------------
// Device-side min-heap
// ---------------------------------------------------------------------------
template <typename T>
class DeviceMinHeap {
public:
    __device__ DeviceMinHeap(T* data, int* size, int capacity)
        : data_(data), size_(size), capacity_(capacity) {}

    __device__ bool empty() const { return *size_ == 0; }
    __device__ int size() const { return *size_; }
    __device__ int capacity() const { return capacity_; }

    // Insert a new element. Returns false if the heap is full.
    __device__ bool push(const T& value) {
        if (*size_ >= capacity_) return false;
        int i = *size_;
        data_[i] = value;
        (*size_)++;
        sift_up(i);
        return true;
    }

    // Remove the minimum element and store it in `out`.
    // Returns false if the heap is empty.
    __device__ bool pop(T& out) {
        if (*size_ == 0) return false;
        out = data_[0];
        (*size_)--;
        if (*size_ > 0) {
            data_[0] = data_[*size_];
            sift_down(0);
        }
        return true;
    }

    // Peek at the minimum element without removing it.
    // Returns false if the heap is empty.
    __device__ bool top(T& out) const {
        if (*size_ == 0) return false;
        out = data_[0];
        return true;
    }

    // Build a heap from the current contents of `data_` (first `*size_` elements).
    __device__ void heapify() {
        if (*size_ <= 1) return;
        for (int i = (*size_ / 2) - 1; i >= 0; --i) {
            sift_down(i);
        }
    }

private:
    T* data_;
    int* size_;
    int capacity_;

    __device__ void sift_up(int i) {
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (data_[parent] <= data_[i]) break;
            T tmp = data_[parent];
            data_[parent] = data_[i];
            data_[i] = tmp;
            i = parent;
        }
    }

    __device__ void sift_down(int i) {
        int n = *size_;
        while (true) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;
            if (left < n && data_[left] < data_[smallest]) smallest = left;
            if (right < n && data_[right] < data_[smallest]) smallest = right;
            if (smallest == i) break;
            T tmp = data_[i];
            data_[i] = data_[smallest];
            data_[smallest] = tmp;
            i = smallest;
        }
    }
};

// ---------------------------------------------------------------------------
// Unit tests
// ---------------------------------------------------------------------------
__global__ void test_min_heap(int* results) {
    int test_idx = 0;
    const int CAP = 16;
    int data[CAP];
    int size;
    DeviceMinHeap<int> heap(data, &size, CAP);
    int out;

    // 1. Empty heap
    size = 0;
    results[test_idx++] = heap.empty() && heap.size() == 0 &&
