    // 3. Pop single element
    results[test_idx++] = heap.pop(out) && out == 42 && heap.empty();

    // 4. Push multiple elements and pop in sorted order
    size = 0;
    int vals[] = {5, 3, 8, 1, 9, 2, 7};
    for (int v : vals) heap.push(v);
    bool sorted = true;
    int prev = -1;
    for (int i = 0; i < 7; i++) {
        if (!heap.pop(out)) { sorted = false; break; }
        if (i > 0 && out < prev) sorted = false;
        prev = out;
    }
    results[test_idx++] = sorted && heap.empty();

    // 5. Duplicate values
    size = 0;
    int dups[] = {4, 2, 4, 1, 2, 4};
    for (int v : dups) heap.push(v);
    bool dups_sorted = true;
    prev = -1;
    for (int i = 0; i < 6; i++) {
        heap.pop(out);
        if (i > 0 && out < prev) dups_sorted = false;
        prev = out;
    }
    results[test_idx++] = dups_sorted;

    // 6. Negative numbers
    size = 0;
    int negs[] = {-5, -1, -10, 0, 3, -7};
    for (int v : negs) heap.push(v);
    bool neg_sorted = true;
    prev = -1000;
    for (int i = 0; i < 6; i++) {
        heap.pop(out);
        if (out < prev) neg_sorted = false;
        prev = out;
    }
    results[test_idx++] = neg_sorted;

    // 7. Heapify an unsorted array
    size = 7;
    int unsorted[] = {9, 4, 7, 1, 8, 2, 5};
    for (int i = 0; i < size; i++) data[i] = unsorted[i];
    heap.heapify();
    bool heapify_sorted = true;
    prev = -1;
    for (int i = 0; i < 7; i++) {
        heap.pop(out);
        if (i > 0 && out < prev) heapify_sorted = false;
        prev = out;
    }
    results[test_idx++] = heapify_sorted;

    // 8. Heapify an empty array
    size = 0;
    heap.heapify();
    results[test_idx++] = heap.empty();

    // 9. Heapify a single-element array
    size = 1;
    data[0] = 42;
    heap.heapify();
    results[test_idx++] = heap.size() == 1 && heap.top(out) && out == 42;

    // 10. Capacity full
    size = 0;
    for (int i = 0; i < CAP; i++) heap.push(i);
    results[test_idx++] = heap.size() == CAP && !heap.push(99);

    // 11. Pop until empty
    size = 0;
    for (int i = 0; i < 5; i++) heap.push(i);
    bool pop_all = true;
    for (int i = 0; i < 5; i++) {
        if (!heap.pop(out)) { pop_all = false; break; }
    }
    results[test_idx++] = pop_all && heap.empty() && !heap.pop(out);

    // 12. Heapify an already valid heap
    size = 5;
    int already_heap[] = {1, 2, 3, 4, 5};
    for (int i = 0; i < size; i++) data[i] = already_heap[i];
    heap.heapify();
    bool already_sorted = true;
    prev = -1;
    for (int i = 0; i < 5; i++) {
        heap.pop(out);
        if (i > 0 && out < prev) already_sorted = false;
        prev = out;
    }
    results[test_idx++] = already_sorted;

    // 13. Heapify a reverse-sorted array
    size = 5;
    int reverse[] = {5, 4, 3, 2, 1};
    for (int i = 0; i < size; i++) data[i] = reverse[i];
    heap.heapify();
    bool reverse_sorted = true;
    prev = -1;
    for (int i = 0; i < 5; i++) {
        heap.pop(out);
        if (i > 0 && out < prev) reverse_sorted = false;
        prev = out;
    }
    results[test_idx++] = reverse_sorted;
}

// ---------------------------------------------------------------------------
// Host main
// ---------------------------------------------------------------------------
int main() {
    const int num_tests = 13;
    int* results;
    CUDA_CHECK(cudaMallocManaged(&results, num_tests * sizeof(int)));

    test_min_heap<<<1, 1>>>(results);
