template <typename T>
struct DeviceMinHeap {
    T* data; int* size; int cap;

    __device__ DeviceMinHeap(T* d, int* s, int c) : data(d), size(s), cap(c) {}

    __device__ bool empty() const { return *size == 0; }

    __device__ bool push(const T& v) {
        if (*size >= cap) return false;
        int i = (*size)++;
        data[i] = v;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (data[p] <= data[i]) break;
            T t = data[p]; data[p] = data[i]; data[i] = t;
            i = p;
        }
        return true;
    }

    __device__ bool pop(T& out) {
        if (*size == 0) return false;
        out = data[0];
        if (--(*size) > 0) {
            data[0] = data[*size];
            int i = 0;
            while (true) {
                int l = 2*i+1, r = 2*i+2, m = i;
                if (l < *size && data[l] < data[m]) m = l;
                if (r < *size && data[r] < data[m]) m = r;
                if (m == i) break;
                T t = data[i]; data[i] = data[m]; data[m] = t;
                i = m;
            }
        }
        return true;
    }

    __device__ void heapify() {
        for (int i = (*size / 2) - 1; i >= 0; --i) {
            int j = i;
            while (true) {
                int l = 2*j+1, r = 2*j+2, m = j;
                if (l < *size && data[l] < data[m]) m = l;
                if (r < *size && data[r] < data[m]) m = r;
                if (m == j) break;
                T t = data[j]; data[j] = data[m]; data[m] = t;
                j = m;
            }
        }
    }
};

