use std::cmp::Ordering;

const MAX_LEVEL: usize = 16;

#[derive(Debug)]
struct Node<T> {
    key: T,
    forward: Vec<Option<usize>>,
}

#[derive(Debug)]
pub struct SkipList<T> {
    head: Vec<Option<usize>>,
    level: usize,
    nodes: Vec<Node<T>>,
    rng_state: u64,
}

impl<T: Ord> SkipList<T> {
    pub fn new() -> Self {
        Self {
            head: vec![None; MAX_LEVEL + 1],
            level: 0,
            nodes: Vec::new(),
            rng_state: 0x1234_5678_9abc_def0,
        }
    }

    fn next_random(&mut self) -> u64 {
        let mut x = self.rng_state;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.rng_state = x;
        x
    }

    fn random_level(&mut self) -> usize {
        let mut level = 0;
        while level < MAX_LEVEL && (self.next_random() & 1) == 1 {
            level += 1;
        }
        level
    }

    pub fn insert(&mut self, key: T) -> bool {
        let mut update: Vec<Option<usize>> = vec![None; MAX_LEVEL + 1];
        let mut current: Option<usize> = None;

        for i in (0..=self.level).rev() {
            loop {
                let next = match current {
                    Some(idx) => self.nodes[idx].forward[i],
                    None => self.head[i],
                };

                match next {
                    Some(next_idx) if self.nodes[next_idx].key < key => {
                        current = Some(next_idx);
                    }
                    _ => break,
                }
            }
            update[i] = current;
        }

        let next = match current {
            Some(idx) => self.nodes[idx].forward[0],
            None => self.head[0],
        };

        if let Some(next_idx) = next {
            if self.nodes[next_idx].key == key {
                return false;
            }
        }

        let new_level = self.random_level();

        if new_level > self.level {
            for i in (self.level + 1)..=new_level {
                update[i] = None;
            }
            self.level = new_level;
        }

        let new_idx = self.nodes.len();
        let mut forward = vec![None; new_level + 1];

        for i in 0..=new_level {
            let prev = update[i];
            match prev {
                Some(prev_idx) => {
                    forward[i] = self.nodes[prev_idx].forward[i];
                    self.nodes[prev_idx].forward[i] = Some(new_idx);
                }
                None => {
                    forward[i] = self.head[i];
                    self.head[i] = Some(new_idx);
                }
            }
        }

        self.nodes.push(Node { key, forward });
        true
    }

    pub fn search(&self, key: &T) -> bool {
        let mut current: Option<usize> = None;

        for i in (0..=self.level).rev() {
            loop {
                let next = match current {
                    Some(idx) => self.nodes[idx].forward[i],
                    None => self.head[i],
                };

                match next {
                    Some(next_idx) if &self.nodes[next_idx].key < key => {
                        current = Some(next_idx);
                    }
                    _ => break,
                }
            }
        }

        let next = match current {
            Some(idx) => self.nodes[idx].forward[0],
            None => self.head[0],
        };

        matches!(next, Some(idx) if &self.nodes[idx].key == key)
    }

    pub fn delete(&mut self, key: &T) -> bool {
        let mut update: Vec<Option<usize>> = vec![None; MAX_LEVEL + 1];
        let mut current: Option<usize> = None;

        for i in (0..=self.level).rev() {
            loop {
                let next = match current {
                    Some(idx) => self.nodes[idx].forward[i],
                    None => self.head[i],
                };

                match next {
                    Some(next_idx) if &self.nodes[next_idx].key < key => {
                        current = Some(next_idx);
                    }
                    _ => break,
                }
            }
            update[i] = current;
        }

        let target = match current {
            Some(idx) => self.nodes[idx].forward[0],
            None => self.head[0],
        };

        let target = match target {
            Some(idx) if &self.nodes[idx].key == key => idx,
            _ => return false,
        };

        for i in 0..self.nodes[target].forward.len() {
            let next_after = self.nodes[target].forward[i];

            match update[i] {
                Some(prev_idx) => {
                    if self.nodes[prev_idx].forward[i] == Some(target) {
                        self.nodes[prev_idx].forward[i] = next_after;
                    }
                }
                None => {
                    if self.head[i] == Some(target) {
                        self.head[i] = next_after;
                    }
                }
            }
        }

        while self.level > 0 && self.head[self.level].is_none() {
            self.level -= 1;
        }

        true
    }
}

impl<T: Ord> Default for SkipList<T> {
    fn default() -> Self {
        Self::new()
    }
}

