# Exponential Backoff with Jitter in C

Here's a production-ready implementation. I'll explain the design decisions and pitfalls inline.

```c
/* retry.h */
#ifndef RETRY_H
#define RETRY_H

#include <stdint.h>

/* Return values for the callback:
 *   0  -> success, stop retrying
 *  -1  -> retryable failure, back off and try again
 *  -2  -> permanent failure, stop retrying immediately
 * Other negative values are treated as retryable.
 */
typedef int (*retry_fn)(void *ctx);

struct retry_policy {
    unsigned max_attempts;      /* Total attempts, >= 1 */
    uint64_t base_delay_ms;     /* Initial backoff, e.g. 50 */
    uint64_t max_delay_ms;      /* Cap on sleep, e.g. 30000 */
    double   multiplier;        /* Growth factor, e.g. 2.0 */
    double   jitter;            /* 0.0 = none, 1.0 = full jitter */
};

/* Runs `fn(ctx)` under the given policy.
 * Returns the last value returned by `fn`.
 * Never sleeps after the final attempt. */
int retry_with_backoff(const struct retry_policy *p, retry_fn fn, void *ctx);

#endif
```

```c
/* retry.c */
#include "retry.h"

#include <errno.h>
#include <math.h>
#include <stddef.h>
#include <stdlib.h>
#include <time.h>

/* Sleep for `ms` milliseconds, tolerating EINTR.
 *
 * Why EINTR matters: any signal (SIGCHLD, SIGTERM handlers, etc.) will
 * interrupt nanosleep and return -1/EINTR. If we don't loop, backoff
 * collapses to near-zero for services that install signal handlers. */
static void sleep_ms(uint64_t ms)
{
    struct timespec ts;
    ts.tv_sec  = (time_t)(ms / 1000u);
    ts.tv_nsec = (long)((ms % 1000u) * 1000000u);

    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* ts is updated by nanosleep with the remaining time. */
    }
}

/* Compute the delay for attempt N (1-based).
 *
 * "Full jitter" (AWS): sleep = random(0, base * multiplier^(N-1))
 * This is the recommended default because it minimizes both retry
 * storms and total completion time on contention.
 *
 * We also support a fractional jitter scalar in [0,1] which applies
 * symmetric jitter around the deterministic delay. That's useful when
 * you want to keep a floor (e.g., avoid hammering a flaky dependency
 * with sub-millisecond retries). */
static uint64_t compute_delay(const struct retry_policy *p, unsigned attempt)
{
    /* attempt starts at 1; exponent is attempt-1 so first retry is base. */
    double exp   = (double)(attempt - 1);
    double delay = (double)p->base_delay_ms * pow(p->multiplier, exp);

    /* Clamp before jitter so that jitter can't exceed the cap. */
    if (delay > (double)p->max_delay_ms) {
        delay = (double)p->max_delay_ms;
    }

    double j = p->jitter;
    if (j < 0.0) j = 0.0;
    if (j > 1.0) j = 1.0;

    if (j > 0.0) {
        /* rand()/RAND_MAX in [0,1]. Use rand_r for thread-safety if
         * retry is called from multiple threads, or swap in a proper
         * PRNG (xoshiro, PCG). rand() is fine for jitter because the
         * security bar is low and we don't care about reproducibility. */
        double r = (double)rand() / (double)RAND_MAX;   /* [0,1] */
        /* Symmetric jitter: delay * (1 - j/2 + j*r) => range
         * [delay*(1 - j/2), delay*(1 + j/2)]. */
        delay *= (1.0 - j * 0.5) + j * r;
    }

    if (delay < 0.0) delay = 0.0;

    /* Cap after jitter as well, in case multiplier > cap already. */
    if (delay > (double)p->max_delay_ms) {
        delay = (double)p->max_delay_ms;
    }

    return (uint64_t)delay;
}

int retry_with_backoff(const struct retry_policy *p, retry_fn fn, void *ctx)
{
    if (p == NULL || fn == NULL || p->max_attempts == 0) {
        return -2;
    }

    int rc = 0;
    for (unsigned attempt = 1; attempt <= p->max_attempts; ++attempt) {
        rc = fn(ctx);
        if (rc == 0) {
            return 0;
        }
        if (rc == -2) {
            return rc;                 /* permanent failure */
        }
        if (attempt == p->max_attempts) {
            break;                     /* no sleep after last attempt */
        }
        sleep_ms(compute_delay(p, attempt));
    }
    return rc;
}
```

## Usage

```c
struct backend { int *fd; };

static int connect_backend(void *vctx)
{
    struct backend *b = vctx;
    if (connect_to(b->fd) == 0) return 0;
    if (errno == EACCES || errno == ENOENT) return -2;  /* don't retry */
    return -1;                                          /* retry */
}

void handle_request(struct backend *b)
{
    struct retry_policy p = {
        .max_attempts  = 6,
        .base_delay_ms = 50,
        .max_delay_ms  = 30000,
        .multiplier    = 2.0,
        .jitter        = 1.0,       /* full jitter */
    };
    int rc = retry_with_backoff(&p, connect_backend, b);
    if (rc != 0) {
        log_error("backend unavailable after retries: %d", rc);
    }
}
```

## The tricky parts, documented

**1. `EINTR` on sleep.** `nanosleep` is interrupted by *any* signal handler that isn't `SA_RESTART`-ed at the syscall level. Real services install handlers for `SIGTERM`, `SIGCHLD`, etc., so without the loop your backoff becomes noise. The loop reuses the `timespec` because the kernel fills it with remaining time.

**2. Clamp *before and after* jitter.** Clamping only before means additive jitter can push you past `max_delay_ms`. Clamping only after means you can lose the exponential shape when the cap is near the base. Doing both keeps the invariant "delay ≤ max_delay_ms" without distorting growth.

**3. The exponent.** Use `attempt - 1`, not `attempt`, so that the first retry waits `base_delay_ms`. Off-by-one here is the most common bug: people either double the initial delay or start at zero.

**4. Don't sleep after the final attempt.** You've exhausted the budget — sleeping delays the caller's error path by up to `max_delay_ms` for no benefit. The `attempt == max_attempts` check happens *before* the sleep.

**5. Jitter choice matters.** AWS's "full jitter" (`random(0, delay)`) is the default recommendation because it minimizes total work under contention. Symmetric ±jitter (what I implemented with `jitter` in `[0,1]`) is a reasonable compromise when you want a floor. Pick one and be consistent across your fleet — mixing strategies reintroduces synchronized retries.

**6. `rand()` is not thread-safe.** If `retry_with_backoff` can be called concurrently, either switch to `rand_r` with a per-thread `unsigned` seed, or use a thread-local PCG/xoshiro. Jitter doesn't need crypto quality, but it *does* need to be decorrelated across threads — a global `rand()` will serialize calls under glibc's internal lock and can actually correlate jitter due to the shared state.

**7. `pow` needs `-lm`.** Add it to your link line. If you want to avoid the dependency (e.g., tiny static binary), replace with an iterative `delay *= multiplier` accumulator and cap it — that also avoids any FP rounding surprises at high attempt counts.

**8. Overflow of `max_attempts`.** `unsigned` handles this in practice, but if `multiplier > 1.0` and `max_attempts` is huge, `pow` will hit `inf` long before the loop ends. The pre-jitter clamp handles that: anything ≥ `max_delay_ms` becomes `max_delay_ms`.

**9. Return-value contract.** The callback's return value is propagated verbatim, so callers can distinguish "gave up after N retries" (negative retryable value) from "hard failure" (`-2`). The `0` for success is non-negotiable; if your callbacks return `errno` values (positive), wrap them.

If you also need a **deadline** (wall-clock budget across all attempts), add a `uint64_t timeout_ms` to the policy and check `clock_gettime(CLOCK_MONOTONIC, …)` before each sleep — use `CLOCK_MONOTONIC`, not `CLOCK_REALTIME`, so NTP steps don't distort your budget.

```ts
type Token =
  | { kind: "num"; value: number }
  | { kind: "op"; value: "+" | "-" | "*" | "/" }
  | { kind: "paren"; value: "(" | ")" };

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < input.length) {
    const c = input[i];

    if (/\s/.test(c)) {
      i++;
      continue;
    }

    if (/[0-9.]/.test(c)) {
      let j = i + 1;
      while (j < input.length && /[0-9.]/.test(input[j])) j++;

      const raw = input.slice(i, j);
      const n = Number(raw);

      if (Number.isNaN(n)) throw new Error(`Invalid number: ${raw}`);
      tokens.push({ kind: "num", value: n });
      i = j;
      continue;
    }

    if (c === "(" || c === ")") {
      tokens.push({ kind: "paren", value: c });
      i++;
      continue;
    }

    if (c === "+" || c === "-" || c === "*" || c === "/") {
      tokens.push({ kind: "op", value: c });
      i++;
      continue;
    }

    throw new Error(`Unexpected character: ${c}`);
  }

  return tokens;
}

function evaluate(expr: string): number {
  const tokens = tokenize(expr);
  let pos = 0;

  const peek = (): Token | undefined => tokens[pos];

  const next = (): Token => {
    const t = tokens[pos++];
    if (!t) throw new Error("Unexpected end of expression");
    return t;
  };

  function parseExpr(): number {
    let value = parseTerm();

    while (true) {
      const t = peek();
      if (t && t.kind === "op" && (t.value === "+" || t.value === "-")) {
        next();
        const rhs = parseTerm();
        value = t.value === "+" ? value + rhs : value - rhs;
      } else {
        break;
      }
    }

    return value;
  }

  function parseTerm(): number {
    let value = parseFactor();

    while (true) {
      const t = peek();
      if (t && t.kind === "op" && (t.value === "*" || t.value === "/")) {
        next();
        const rhs = parseFactor();
        value = t.value === "*" ? value * rhs : value / rhs;
      } else {
        break;
      }
    }

    return value;
  }

  function parseFactor(): number {
    const t = peek();
    if (!t) throw new Error("Unexpected end of expression");

    if (t.kind === "num") {
      next();
      return t.value;
    }

    if (t.kind === "op" && (t.value === "+" || t.value === "-")) {
      next();
      const v = parseFactor();
      return t.value === "-" ? -v : v;
    }

    if (t.kind === "paren" && t.value === "(") {
      next();
      const v = parseExpr();

      const close = next();
      if (close.kind !== "paren" || close.value !== ")") {
        throw new Error("Expected )");
      }

      return v;
    }

    throw new Error(`Unexpected token: ${JSON.stringify(t)}`);
  }

  const result = parseExpr();

  if (pos !== tokens.length) {
    throw new Error("Unexpected token after expression");
  }

  return result;
}
