Below is a PostgreSQL implementation of a union-find (disjoint-set) structure using **path compression** in `find` and **union by rank** in `union`.

```sql
-- Disjoint-set table
CREATE TABLE uf (
    id      integer PRIMARY KEY,
    parent  integer NOT NULL,
    uf_rank integer NOT NULL DEFAULT 0
);

-- Create a new singleton set
CREATE OR REPLACE FUNCTION uf_make_set(p_id integer)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO uf (id, parent, uf_rank)
    VALUES (p_id, p_id, 0)
    ON CONFLICT (id) DO NOTHING;
END;
$$;

-- Find root with path compression
CREATE OR REPLACE FUNCTION uf_find(p_id integer)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    v_root integer;
    v_cur  integer := p_id;
    v_path integer[] := ARRAY[]::integer[];
BEGIN
    -- Walk up to the root, collecting the path
    LOOP
        SELECT parent INTO v_root
        FROM uf
        WHERE id = v_cur;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'uf_find: unknown id %', v_cur;
        END IF;

        v_path := v_path || v_cur;

        IF v_root = v_cur THEN
            EXIT;
        END IF;

        v_cur := v_root;
    END LOOP;

    -- Path compression: point all nodes on the path directly to the root
    UPDATE uf
       SET parent = v_root
     WHERE id = ANY(v_path)
       AND parent <> v_root;

    RETURN v_root;
END;
$$;

-- Union two sets by rank
CREATE OR REPLACE FUNCTION uf_union(p_a integer, p_b integer)
RETURNS boolean
LANGUAGE plpgsql
AS $$
DECLARE
    r_a    integer;
    r_b    integer;
    rank_a integer;
    rank_b integer;
    tmp    integer;
BEGIN
    r_a := uf_find(p_a);
    r_b := uf_find(p_b);

    IF r_a = r_b THEN
        RETURN false;  -- already in the same set
    END IF;

    SELECT uf_rank INTO rank_a FROM uf WHERE id = r_a;
    SELECT uf_rank INTO rank_b FROM uf WHERE id = r_b;

    -- Make r_a the root with the larger rank
    IF rank_a < rank_b THEN
        tmp := r_a;    r_a := r_b;    r_b := tmp;
        tmp := rank_a; rank_a := rank_b; rank_b := tmp;
    END IF;

    -- Attach smaller-rank tree under larger-rank tree
    UPDATE uf SET parent = r_a WHERE id = r_b;

    -- If ranks were equal, the new root's rank increases
    IF rank_a = rank_b THEN
        UPDATE uf SET uf_rank = uf_rank + 1 WHERE id = r_a;
    END IF;

    RETURN true;
END;
$$;
```

## Usage example

```sql
-- Create elements 1..5
SELECT uf_make_set(1);
SELECT uf_make_set(2);
SELECT uf_make_set(3);
SELECT uf_make_set(4);
SELECT uf_make_set(5);

-- Merge some sets
SELECT uf_union(1, 2);  -- true
SELECT uf_union(3, 4);  -- true
SELECT uf_union(2, 3);  -- true

-- Find root of 4; this also compresses the path
SELECT uf_find(4);      -- 1

-- Inspect the internal state
SELECT * FROM uf ORDER BY id;
```

After the example above, `1`, `2`, `3`, and `4` are in the same set, while `5` is still alone. The `uf_find(4)` call returns `1` and updates parent pointers so that nodes on the path point directly to `1`.

