Below is a simple recursive JSON pretty-printer in C. It reads all input from `stdin`, parses enough JSON structure to format it, and writes the formatted JSON to `stdout`. It does not use any JSON library.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

static void die(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

static char *read_all(FILE *fp) {
    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) die("out of memory");

    int c;
    while ((c = fgetc(fp)) != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) die("out of memory");
            buf = tmp;
        }
        buf[len++] = (char)c;
    }

    buf[len] = '\0';
    return buf;
}

static void skip_ws(const char **p) {
    while (isspace((unsigned char)**p)) {
        (*p)++;
    }
}

static void print_indent(int indent) {
    for (int i = 0; i < indent * 2; i++) {
        putchar(' ');
    }
}

static void print_string(const char **p) {
    if (**p != '"') die("expected string");

    putchar('"');
    (*p)++;

    while (**p) {
        if (**p == '\\') {
            putchar('\\');
            (*p)++;
            if (**p == '\0') die("unterminated escape");
            putchar(**p);
            (*p)++;
        } else if (**p == '"') {
            putchar('"');
            (*p)++;
            return;
        } else {
            putchar(**p);
            (*p)++;
        }
    }

    die("unterminated string");
}

static void print_primitive(const char **p) {
    while (**p &&
           !isspace((unsigned char)**p) &&
           **p != ',' &&
           **p != ']' &&
           **p != '}' &&
           **p != ':') {
        putchar(**p);
        (*p)++;
    }
}

static void print_value(const char **p, int indent);

static void print_array(const char **p, int indent) {
    putchar('[');
    (*p)++;

    skip_ws(p);

    if (**p == ']') {
        putchar(']');
        (*p)++;
        return;
    }

    putchar('\n');
    print_indent(indent + 1);

    while (1) {
        skip_ws(p);
        print_value(p, indent + 1);
        skip_ws(p);

        if (**p == ',') {
            putchar(',');
            (*p)++;
            putchar('\n');
            print_indent(indent + 1);
        } else if (**p == ']') {
            putchar('\n');
            print_indent(indent);
            putchar(']');
            (*p)++;
            return;
        } else {
            die("expected ',' or ']' in array");
        }
    }
}

static void print_object(const char **p, int indent) {
    putchar('{');
    (*p)++;

    skip_ws(p);

    if (**p == '}') {
        putchar('}');
        (*p)++;
        return;
    }

    putchar('\n');
    print_indent(indent + 1);

    while (1) {
        skip_ws(p);

        if (**p != '"') die("expected string key in object");
        print_string(p);

        skip_ws(p);
        if (**p != ':') die("expected ':' in object");
        (*p)++;

        putchar(':');
        putchar(' ');

        skip_ws(p);
        print_value(p, indent + 1);
        skip_ws(p);

        if (**p == ',') {
            putchar(',');
            (*p)++;
            putchar('\n');
            print_indent(indent + 1);
        } else if (**p == '}') {
            putchar('\n');
            print_indent(indent);
            putchar('}');
            (*p)++;
            return;
        } else {
            die("expected ',' or '}' in object");
        }
    }
}

static void print_value(const char **p, int indent) {
    skip_ws(p);

    switch (**p) {
        case '{':
            print_object(p, indent);
            break;
        case '[':
            print_array(p, indent);
            break;
        case '"':
            print_string(p);
            break;
        default:
            print_primitive(p);
            break;
    }
}

int main(void) {
    char *json = read_all(stdin);
    const char *p = json;

    skip_ws(&p);
    print_value(&p, 0);
    skip_ws(&p);

    if (*p != '\0') {
        die("trailing characters after JSON value");
    }

    putchar('\n');
    free(json);
    return 0;
}
```

### Example

Input:

```json
{"name":"Alice","age":30,"skills":["C","JSON"],"active":true}
```

Output:

```json
{
  "name": "Alice",
  "age": 30,
  "skills": [
    "C",
    "JSON"
  ],
  "active": true
}
```

### How it works

- `print_value` dispatches based on the current character:
  - `{` → object
  - `[` → array
  - `"` → string
  - otherwise → primitive such as number, `true`, `false`, or `null`
- `print_object` and `print_array` handle commas, indentation, and closing brackets.
- `print_string` copies string contents while respecting escape sequences, so braces or brackets inside strings are not treated as JSON structure.
- Whitespace outside strings is skipped and replaced by the pretty-printer’s own formatting.

### Time complexity

Let `n` be the number of input characters and `d` be the maximum nesting depth.

- Reading input takes `O(n)`.
- Parsing/scanning takes `O(n)`.
- Writing output takes time proportional to the output size. Because indentation grows with depth, the output size can be `O(n * d)`, and in the worst case `d = O(n)`, so the total worst-case time can be `O(n^2)` if we count emitted indentation spaces.
- If nesting depth is bounded, or if we ignore formatting-space output, the algorithm is effectively `O(n)`.

### Space complexity

- The program reads the whole input into memory, so it uses `O(n)` space for the input buffer.
- Recursion depth is at most the JSON nesting depth `d`, so it uses `O(d)` additional stack space.
- Therefore total extra space is `O(n + d)`, which is `O(n)` in the worst case.

A streaming version could avoid storing the whole input and use only `O(d)` recursion/stack space, or `O(1)` extra space with an iterative state machine.

