```go
// editdistance.go
package editdistance

// OpKind represents the type of an edit operation.
type OpKind int

const (
	Match OpKind = iota
	Insert
	Delete
	Substitute
)

// EditOp describes one operation in an edit script.
// SrcIndex/DstIndex are rune indexes in the source/target strings.
// Src/Dst are 0 when they do not apply to the operation.
type EditOp struct {
	Kind     OpKind
	SrcIndex int
	DstIndex int
	Src      rune
	Dst      rune
}

// EditDistance computes the Levenshtein distance between source and target
// and returns one optimal edit script.
func EditDistance(source, target string) (int, []EditOp) {
	s := []rune(source)
	t := []rune(target)

	n, m := len(s), len(t)

	// dp[i][j] = edit distance between s[:i] and t[:j].
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}

	for i := 0; i <= n; i++ {
		dp[i][0] = i
	}
	for j := 0; j <= m; j++ {
		dp[0][j] = j
	}

	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if s[i-1] == t[j-1] {
				dp[i][j] = dp[i-1][j-1]
			} else {
				dp[i][j] = min3(
					dp[i-1][j-1]+1, // substitute
					dp[i-1][j]+1,   // delete
					dp[i][j-1]+1,   // insert
				)
			}
		}
	}

	// Trace back from dp[n][m] to reconstruct an optimal edit script.
	ops := make([]EditOp, 0, dp[n][m])
	i, j := n, m

	for i > 0 || j > 0 {
		switch {
		case i > 0 && j > 0 && s[i-1] == t[j-1] && dp[i][j] == dp[i-1][j-1]:
			ops = append(ops, EditOp{
				Kind:     Match,
				SrcIndex: i - 1,
				DstIndex: j - 1,
				Src:      s[i-1],
				Dst:      t[j-1],
			})
			i--
			j--

		case i > 0 && j > 0 && dp[i][j] == dp[i-1][j-1]+1:
			ops = append(ops, EditOp{
				Kind:     Substitute,
				SrcIndex: i - 1,
				DstIndex: j - 1,
				Src:      s[i-1],
				Dst:      t[j-1],
			})
			i--
			j--

		case i > 0 && dp[i][j] == dp[i-1][j]+1:
			ops = append(ops, EditOp{
				Kind:     Delete,
				SrcIndex: i - 1,
				DstIndex: j,
				Src:      s[i-1],
			})
			i--

		case j > 0 && dp[i][j] == dp[i][j-1]+1:
			ops = append(ops, EditOp{
				Kind:     Insert,
				SrcIndex: i,
				DstIndex: j - 1,
				Dst:      t[j-1],
			})
			j--

		default:
			panic("editdistance: traceback failed")
		}
	}

	reverseOps(ops)
	return dp[n][m], ops
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}

func reverseOps(ops []EditOp) {
	for i, j := 0, len(ops)-1; i < j; i, j = i+1, j-1 {
		ops[i], ops[j] = ops[j], ops[i]
	}
}
```

