func applyOps(source string, ops []EditOp) string {
	s := []rune(source)
	var out []rune

	srcPos := 0

	for _, op := range ops {
		switch op.Kind {
		case Match:
			if srcPos >= len(s) || s[srcPos] != op.Src {
				panic("invalid match operation")
			}
			out = append(out, op.Dst)
			srcPos++

		case Substitute:
			if srcPos >= len(s) {
				panic("invalid substitute operation")
			}
			out = append(out, op.Dst)
			srcPos++

		case Delete:
			if srcPos >= len(s) {
				panic("invalid delete operation")
			}
			srcPos++

		case Insert:
			out = append(out, op.Dst)
		}
	}

	return string(out)
}

