```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public class Trie {

    private static final class Node {
        private final Map<Character, Node> children = new HashMap<>();
        private boolean isWord;
        private int prefixCount;
    }

    private final Node root = new Node();

    /**
     * Inserts a word into the trie.
     *
     * @return true if the word was newly inserted, false if it already existed
     */
    public boolean insert(String word) {
        Objects.requireNonNull(word, "word must not be null");

        Node node = root;
        List<Node> path = new ArrayList<>(word.length() + 1);
        path.add(root);

        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            node = node.children.computeIfAbsent(c, ignored -> new Node());
            path.add(node);
        }

        if (node.isWord) {
            return false;
        }

        node.isWord = true;

        for (Node n : path) {
            n.prefixCount++;
        }

        return true;
    }

    /**
     * Exact search for a word.
     */
    public boolean search(String word) {
        Objects.requireNonNull(word, "word must not be null");

        Node node = findNode(word);
        return node != null && node.isWord;
    }

    /**
     * Returns how many unique inserted words start with the given prefix.
     */
    public int prefixCount(String prefix) {
        Objects.requireNonNull(prefix, "prefix must not be null");

        Node node = findNode(prefix);
        return node == null ? 0 : node.prefixCount;
    }

    /**
     * Returns the number of unique words in the trie.
     */
    public int size() {
        return root.prefixCount;
    }

    private Node findNode(String value) {
        Node node = root;

        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            node = node.children.get(c);

            if (node == null) {
                return null;
            }
        }

        return node;
    }
}
