import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class TrieTest {

    private Trie trie;

    @BeforeEach
    void setUp() {
        trie = new Trie();
    }

    @Test
    void newTrieHasNoWords() {
        assertFalse(trie.search("anything"));
        assertEquals(0, trie.prefixCount(""));
        assertEquals(0, trie.prefixCount("a"));
        assertEquals(0, trie.size());
    }

    @Test
    void insertAndExactSearch() {
        assertTrue(trie.insert("apple"));

        assertTrue(trie.search("apple"));
        assertFalse(trie.search("app"));
        assertFalse(trie.search("apples"));

        assertEquals(1, trie.size());
    }

    @Test
    void duplicateInsertIsIgnored() {
        assertTrue(trie.insert("cat"));
        assertFalse(trie.insert("cat"));

        assertTrue(trie.search("cat"));
        assertEquals(1, trie.prefixCount(""));
        assertEquals(1, trie.prefixCount("ca"));
        assertEquals(1, trie.size());
    }

    @Test
    void prefixCountCountsWordsWithPrefix() {
        trie.insert("app");
        trie.insert("apple");
        trie.insert("apply");
        trie.insert("banana");

        assertEquals(3, trie.prefixCount("app"));
        assertEquals(2, trie.prefixCount("appl"));
        assertEquals(1, trie.prefixCount("b"));
        assertEquals(1, trie.prefixCount("banana"));
        assertEquals(0, trie.prefixCount("c"));
    }

    @Test
    void wordCanBePrefixOfAnother() {
        trie.insert("car");
        trie.insert("cart");

        assertTrue(trie.search("car"));
        assertTrue(trie.search("cart"));

        assertEquals(2, trie.prefixCount("car"));
        assertEquals(1, trie.prefixCount("cart"));
    }

    @Test
    void emptyStringIsSupported() {
        assertTrue(trie.insert(""));
        assertTrue(trie.search(""));
        assertEquals(1, trie.prefixCount(""));
        assertEquals(1, trie.size());

        assertFalse(trie.insert(""));

        trie.insert("a");

        assertEquals(2, trie.prefixCount(""));
        assertTrue(trie.search(""));
        assertTrue(trie.search("a"));
        assertEquals(1, trie.prefixCount("a"));
    }

    @Test
    void nullArgumentsThrow() {
        assertThrows(NullPointerException.class, () -> trie.insert(null));
        assertThrows(NullPointerException.class, () -> trie.search(null));
        assertThrows(NullPointerException.class, () -> trie.prefixCount(null));
    }

    @Test
    void caseSensitive() {
        trie.insert("Cat");

        assertTrue(trie.search("Cat"));
        assertFalse(trie.search("cat"));

        assertEquals(1, trie.prefixCount("C"));
        assertEquals(0, trie.prefixCount("c"));
    }

    @Test
    void unicodeCharactersAreSupported() {
        trie.insert("café");
        trie.insert("😀");

        assertTrue(trie.search("café"));
        assertTrue(trie.search("😀"));

        assertEquals(1, trie.prefixCount("caf"));
        assertEquals(1, trie.prefixCount("😀"));
    }

    @Test
    void prefixCountForNonExistentPrefixIsZero() {
        trie.insert("hello");

        assertEquals(0, trie.prefixCount("help"));
        assertEquals(0, trie.prefixCount("hx"));
    }

    @Test
    void insertReturnsFalseOnlyForDuplicate() {
        assertTrue(trie.insert("a"));
        assertTrue(trie.insert("ab"));

        assertFalse(trie.insert("a"));
        assertFalse(trie.insert("ab"));

        assertEquals(2, trie.prefixCount(""));
        assertEquals(2, trie.prefixCount("a"));
        assertEquals(1, trie.prefixCount("ab"));
    }
}
