Below is a PostgreSQL example. It implements a **fixed-window debounce**: calls for the same key inside the current window are coalesced; the first call in a new window is accepted.

```sql
-- PostgreSQL

create table if not exists debounce_state (
    key          text primary key,
    window_start timestamptz not null,
    expires_at   timestamptz not null,
    call_count   integer     not null default 1,
    updated_at   timestamptz not null default now()
);

create or replace function debounce(
    p_key    text,
    p_window interval,
    p_now    timestamptz default clock_timestamp()
)
returns boolean
language plpgsql
as $$
declare
    v_call_count integer;
begin
    if p_window < interval '0' then
        raise exception 'debounce window must be non-negative';
    end if;

    insert into debounce_state as d (
        key,
        window_start,
        expires_at,
        call_count,
        updated_at
    )
    values (
        p_key,
        p_now,
        p_now + p_window,
        1,
        p_now
    )
    on conflict (key) do update
    set
        window_start = case
            when d.expires_at <= p_now then p_now
            else d.window_start
        end,
        expires_at = case
            when d.expires_at <= p_now then p_now + p_window
            else d.expires_at
        end,
        call_count = case
            when d.expires_at <= p_now then 1
            else d.call_count + 1
        end,
        updated_at = p_now
    returning d.call_count into v_call_count;

    -- true means this call opened a new debounce window.
    -- false means it was coalesced into the existing window.
    return v_call_count = 1;
end;
$$;
```

Usage:

```sql
select debounce('user:42:email', interval '5 minutes');
```

If it returns `true`, run the action immediately. If it returns `false`, the call was coalesced into the current window.

A worker can also inspect coalesced counts after the window expires:

```sql
select key, call_count
from debounce_state
where expires_at <= now();
```

---

## Unit tests

These tests use PostgreSQL `DO` blocks with `ASSERT` and deterministic timestamps.

```sql
begin;

truncate debounce_state;

do $$
declare
    t0 timestamptz := '2024-01-01 00:00:00+00';
    w  interval    := interval '1 minute';
    r  boolean;
    st debounce_state%rowtype;
begin
    -- 1. First call in a new window is accepted.
    r := debounce('a', w, t0);
    assert r, 'first call should be accepted';

    select * into st from debounce_state where key = 'a';
    assert st.call_count = 1, 'first call should set call_count = 1';
    assert st.window_start = t0, 'first call should set window_start';
    assert st.expires_at = t0 + w, 'first call should set expires_at';

    -- 2. Second call inside the same window is coalesced.
    r := debounce('a', w, t0 + interval '10 seconds');
    assert not r, 'second call inside window should be coalesced';

    select * into st from debounce_state where key = 'a';
    assert st.call_count = 2, 'second call should increment call_count';
    assert st.expires_at = t0 + w, 'expiry must not change inside window';

    -- 3. Third call inside the same window is also coalesced.
    r := debounce('a', w, t0 + interval '59.999 seconds');
    assert not r, 'third call inside window should be coalesced';

    select * into st from debounce_state where key = 'a';
    assert st.call_count = 3, 'third call should increment call_count';

    -- 4. Exact boundary starts a new window.
    r := debounce('a', w, t0 + w);
    assert r, 'call exactly at expires_at should start new window';

    select * into st from debounce_state where key = 'a';
    assert st.call_count = 1, 'boundary call should reset call_count';
    assert st.window_start = t0 + w, 'boundary call should move window_start';
    assert st.expires_at = t0 + 2 * w, 'boundary call should set new expiry';

    -- 5. Different keys are independent.
    r := debounce('b', w, t0 + interval '30 seconds');
    assert r, 'different key first call should be accepted';

    select * into st from debounce_state where key = 'b';
    assert st.call_count = 1, 'different key should have its own count';

    -- 6. Zero-length window accepts every call.
    r := debounce('zero', interval '0', t0);
    assert r, 'zero window first call should be accepted';

    r := debounce('zero', interval '0', t0);
    assert r, 'zero window second call should also be accepted';

    -- 7. Negative window is rejected.
    begin
        perform debounce('negative', interval '-1 second', t0);
        assert false, 'negative window should raise an exception';
    exception
        when others then
            if sqlerrm <> 'debounce window must be non-negative' then
                raise;
            end if;
    end;
end $$;

rollback;
```

Edge cases covered:

- first call opens the window
- multiple calls inside the window are coalesced
- exact expiry boundary starts a new window
- call count resets on a new window
- different keys do not interfere
- zero-length window accepts every call
- negative window raises an error
- deterministic timestamps keep tests repeatable

For a traditional trailing debounce, where every call resets the timer, change the conflict update to always set:

```sql
expires_at = p_now + p_window,
call_count = d.call_count + 1
```

and have a worker process rows where `expires_at <= now()`.

