1. **Goroutine storm.** `O(n)` goroutines per level, `log n` levels. At large `n` or high concurrency, scheduler and GC overhead dwarf the actual work; a fixed worker pool chunked by `GOMAXPROCS` is required to scale.
2. **False sharing.** Adjacent workers write neighboring `a[]` slots on the same cache line, ping-ponging it between cores. Throughput collapses toward serial; use blocked partitioning or padding.

This is a trailing-edge debounce: many calls within the time window coalesce into one action, which becomes ready after the last call has been quiet for the window duration.

```c
#define _POSIX_C_SOURCE 199309L
#include <stdint.h>
#include <time.h>

typedef struct {
    struct timespec last_trigger;
    int64_t window_ns;
    int pending;
} debounce_t;

static int64_t ts_to_ns(const struct timespec *ts) {
    return (int64_t)ts->tv_sec * 1000000000LL + (int64_t)ts->tv_nsec;
}

void debounce_init(debounce_t *d, int64_t window_ms) {
    d->window_ns = window_ms * 1000000LL;
    d->pending = 0;
    clock_gettime(CLOCK_MONOTONIC, &d->last_trigger);
}

/* Call this whenever an event/request happens. */
void debounce_trigger(debounce_t *d) {
    clock_gettime(CLOCK_MONOTONIC, &d->last_trigger);
    d->pending = 1;
}

/* Call this periodically, e.g. from a main loop or timer.
 * Returns 1 once, after the last trigger has been quiet for window_ms. */
int debounce_ready(debounce_t *d) {
    if (!d->pending) {
        return 0;
    }

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    int64_t elapsed_ns = ts_to_ns(&now) - ts_to_ns(&d->last_trigger);
    if (elapsed_ns >= d->window_ns) {
        d->pending = 0;
        return 1;
    }

    return 0;
}
```

Short usage example:

```c
#include <stdio.h>
#include <time.h>

static void sleep_ms(long ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    debounce_t db;
    debounce_init(&db, 200); /* 200 ms */

    for (int i = 0; i < 10; i++) {
        debounce_trigger(&db); /* simulate rapid requests */
        sleep_ms(50);

        if (debounce_ready(&db)) {
            puts("Coalesced action: save file");
        }
    }

    sleep_ms(250); /* wait for quiet period */
    if (debounce_ready(&db)) {
        puts("Coalesced action: save file");
    }

    return 0;
}
```

Notes:

- Uses `CLOCK_MONOTONIC`, so it is unaffected by system clock changes.
- Not thread-safe. If triggers come from multiple threads, protect the struct with a mutex or use atomics.
- On some older glibc systems you may need `-lrt`.

