public final class Lcs {
    private Lcs() {
    }

    /**
     * Returns one longest common subsequence of two strings.
     *
     * If multiple LCSs exist, this method returns one of them.
     *
     * @throws IllegalArgumentException if either input is null
     */
    public static String longestCommonSubsequence(String a, String b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings must not be null");
        }

        int n = a.length();
        int m = b.length();

        // dp[i][j] = LCS length of a[0..i) and b[0..j)
        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            char ca = a.charAt(i - 1);

            for (int j = 1; j <= m; j++) {
                if (ca == b.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // Reconstruct one LCS from the DP table.
        StringBuilder sb = new StringBuilder(dp[n][m]);
        int i = n;
        int j = m;

        while (i > 0 && j > 0) {
            if (a.charAt(i - 1) == b.charAt(j - 1)) {
                sb.append(a.charAt(i - 1));
                i--;
                j--;
            } else if (dp[i - 1][j] >= dp[i][j - 1]) {
                i--;
            } else {
                j--;
            }
        }

        return sb.reverse().toString();
    }
}
