```python
import hashlib
import math


class BloomFilter:
    def __init__(self, expected_items, false_positive_rate=0.01):
        if expected_items <= 0:
            raise ValueError("expected_items must be > 0")
        if not 0 < false_positive_rate < 1:
            raise ValueError("false_positive_rate must be between 0 and 1")

        n = expected_items
        p = false_positive_rate

        # Optimal bit count and hash count for the requested false-positive rate.
        self.m = max(1, math.ceil(-n * math.log(p) / (math.log(2) ** 2)))
        self.k = max(1, round((self.m / n) * math.log(2)))
        self.bits = bytearray((self.m + 7) // 8)

    def _indices(self, item):
        if isinstance(item, str):
            data = item.encode()
        elif isinstance(item, (bytes, bytearray)):
            data = bytes(item)
        else:
            data = repr(item).encode()

        # One SHA-256 digest, split into two 128-bit values for double hashing.
        digest = hashlib.sha256(data).digest()
        h1 = int.from_bytes(digest[:16], "big")
        h2 = int.from_bytes(digest[16:], "big")

        if self.m > 1:
            h2 = (h2 % (self.m - 1)) + 1
        else:
            h2 = 1

        for i in range(self.k):
            yield (h1 + i * h2) % self.m

    def add(self, item):
        for idx in self._indices(item):
            self.bits[idx >> 3] |= 1 << (idx & 7)

    def __contains__(self, item):
        return all(
            self.bits[idx >> 3] & (1 << (idx & 7))
            for idx in self._indices(item)
        )
```

