```cpp
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <stdexcept>

class CSVParser {
public:
    // Parse a single CSV line into fields
    static std::vector<std::string> parseLine(const std::string& line, 
                                              char delimiter = ',',
                                              char quote = '"') {
        std::vector<std::string> fields;
        std::string field;
        bool inQuotes = false;
        bool fieldStarted = false;

        for (size_t i = 0; i < line.size(); ++i) {
            char c = line[i];

            if (inQuotes) {
                if (c == quote) {
                    // Check for escaped quote ("" inside quotes)
                    if (i + 1 < line.size() && line[i + 1] == quote) {
                        field += quote;
                        ++i; // skip the second quote
                    } else {
                        inQuotes = false;
                    }
                } else {
                    field += c;
                }
            } else {
                if (c == quote && !fieldStarted) {
                    // Starting a quoted field
                    inQuotes = true;
                    fieldStarted = true;
                } else if (c == delimiter) {
                    fields.push_back(field);
                    field.clear();
                    fieldStarted = false;
                } else {
                    field += c;
                    fieldStarted = true;
                }
            }
        }

        if (inQuotes) {
            throw std::runtime_error("Unterminated quoted field in CSV line");
        }

        fields.push_back(field);
        return fields;
    }

    // Parse an entire CSV string (multiple lines)
    static std::vector<std::vector<std::string>> parse(const std::string& input,
                                                       char delimiter = ',',
                                                       char quote = '"') {
        std::vector<std::vector<std::string>> rows;
        std::istringstream stream(input);
        std::string line;

        while (std::getline(stream, line)) {
            // Skip empty lines
            if (line.empty()) continue;
            // Handle Windows-style line endings
            if (!line.empty() && line.back() == '\r') {
                line.pop_back();
            }
            rows.push_back(parseLine(line, delimiter, quote));
        }
        return rows;
    }
};

// ---------- Usage Example ----------
int main() {
    std::string csv =
        "name,age,address,notes\n"
        "Alice,30,\"123 Main St, Apt 4\",\"Likes cats\"\n"
        "Bob,25,\"456 Oak Ave\",\"Says \"\"hello\"\" often\"\n"
        "Carol,42,\"789 Pine Rd, Suite 100\",plain text\n";

    auto rows = CSVParser::parse(csv);

    for (size_t r = 0; r < rows.size(); ++r) {
        std::cout << "Row " << r << ":\n";
        for (size_t c = 0; c < rows[r].size(); ++c) {
            std::cout << "  [" << c << "] = \"" << rows[r][c] << "\"\n";
        }
    }

    return 0;
}
