class BloomFilter {
public:
    BloomFilter(std::size_t expected_items, double false_positive_rate)
        : expected_items_(expected_items),
          target_fp_(false_positive_rate)
    {
        if (expected_items == 0) {
            throw std::invalid_argument("expected_items must be > 0");
        }
        if (!(false_positive_rate > 0.0 && false_positive_rate < 1.0)) {
            throw std::invalid_argument("false_positive_rate must be in (0, 1)");
        }

        const double ln2 = std::log(2.0);

        // Optimal number of bits:
        // m = -n * ln(p) / (ln 2)^2
        const double m =
            -static_cast<double>(expected_items) * std::log(false_positive_rate) /
            (ln2 * ln2);

        num_bits_ = static_cast<std::size_t>(std::ceil(m));
        if (num_bits_ == 0) num_bits_ = 1;

        // Optimal number of hash functions:
        // k = (m / n) * ln 2 = -log2(p)
        const double k =
            (static_cast<double>(num_bits_) / static_cast<double>(expected_items)) * ln2;

        num_hashes_ = static_cast<std::size_t>(std::round(k));
        if (num_hashes_ < 1) num_hashes_ = 1;

        // Use a vector of 64-bit words as the bit array.
        bits_.assign((num_bits_ + 63) / 64, 0);
    }

    void add(std::string_view key) {
        const auto [h1, h2] = hash_pair(key);

        for (std::size_t i = 0; i < num_hashes_; ++i) {
            set_bit(index(h1, h2, i));
        }
    }

    bool contains(std::string_view key) const {
        const auto [h1, h2] = hash_pair(key);

        for (std::size_t i = 0; i < num_hashes_; ++i) {
            if (!get_bit(index(h1, h2, i))) {
                return false;
            }
        }
        return true;
    }

    std::size_t bit_count() const noexcept { return num_bits_; }
    std::size_t hash_count() const noexcept { return num_hashes_; }
    std::size_t expected_items() const noexcept { return expected_items_; }
    double target_false_positive_rate() const noexcept { return target_fp_; }

private:
    std::size_t expected_items_;
    double target_fp_;
    std::size_t num_bits_;
    std::size_t num_hashes_;
    std::vector<std::uint64_t> bits_;

    void set_bit(std::size_t bit) {
        bits_[bit / 64] |= (std::uint64_t{1} << (bit % 64));
    }

    bool get_bit(std::size_t bit) const {
        return (bits_[bit / 64] & (std::uint64_t{1} << (bit % 64))) != 0;
    }

    // FNV-1a 64-bit hash.
    static std::uint64_t fnv1a(std::string_view key) {
        std::uint64_t hash = 14695981039346656037ULL;
        const std::uint64_t prime = 1099511628211ULL;

        for (unsigned char c : key) {
            hash ^= c;
            hash *= prime;
        }
        return hash;
    }

    // djb2 64-bit hash.
    static std::uint64_t djb2(std::string_view key) {
        std::uint64_t hash = 5381ULL;
        for (unsigned char c : key) {
            hash = ((hash << 5) + hash) + c; // hash * 33 + c
        }
        return hash;
    }

    static std::pair<std::uint64_t, std::uint64_t> hash_pair(std::string_view key) {
        std::uint64_t h1 = fnv1a(key);
        std::uint64_t h2 = djb2(key);

        // Ensure the second hash is non-zero and odd.
        h2 |= 1ULL;

        return {h1, h2};
    }

    std::size_t index(std::uint64_t h1, std::uint64_t h2, std::size_t i) const {
        // Double hashing: h1 + i*h2.  The extra i*i term is a common
        // enhancement that reduces clustering.
        const std::uint64_t combined = h1 + static_cast<std::uint64_t>(i) * h2 + i * i;
        return static_cast<std::size_t>(combined % num_bits_);
    }
};

### How it works

- The constructor computes the optimal bit count `m` and hash count `k` from:
  - `n` = expected number of inserted items
  - `p` = desired false-positive rate
- `add` sets `k` bits.
- `contains` checks those same `k` bits.
- False negatives never occur. False positives are possible.
- `index()` uses double hashing, so only two real hash computations are needed for `k` bit positions.

### Time complexity

Let `n` be the expected number of items, `k` the number of hash functions, and `L` the average key length.

- `add(key)`: `O(k * L)` if hashing the key takes `O(L)`.
- `contains(key)`: `O(k * L)`.
- Bit operations are `O(1)`.

Since `k ≈ -log2(p)`, the operations are very fast for practical false-positive rates.

### Space complexity

- The bit array uses `m` bits, where:

\[
m = \left\lceil \frac{-n \ln p}{(\ln 2)^2} \right\rceil
\]

- Therefore space is:

\[
O(m) = O\left(\frac{-n \ln p}{(\ln 2)^2}\right)
\]

In bytes, this is approximately `m / 8`, plus a small constant overhead for the object and vector metadata.

For example, for `n = 1,000,000` and `p = 0.01`, the filter uses roughly:

\[
m \approx \frac{-1{,}000{,}000 \ln 0.01}{(\ln 2)^2} \approx 9.6 \text{ million bits}
\]

or about `1.2 MB`.

