Here’s a production‑ready CSV parser in Swift that correctly handles quoted fields, embedded commas, escaped quotes (`""`), and multi‑line fields. It’s written as a small state machine over UTF‑8 bytes, which is fast and works safely with any Unicode content.

```swift
import Foundation

/// Errors thrown by `CSVParser`.
public enum CSVError: Error, Equatable, CustomStringConvertible {
    case unexpectedQuote(offset: Int)
    case unexpectedCharacterAfterClosingQuote(character: Character, offset: Int)
    case unterminatedQuotedField(offset: Int)

    public var description: String {
        switch self {
        case .unexpectedQuote(let offset):
            return "Unexpected quote in unquoted field at byte offset \(offset)"
        case .unexpectedCharacterAfterClosingQuote(let character, let offset):
            return "Unexpected character '\(character)' after closing quote at byte offset \(offset)"
        case .unterminatedQuotedField(let offset):
            return "Unterminated quoted field starting at byte offset \(offset)"
        }
    }
}

/// A simple, strict CSV parser compliant with RFC 4180 for the common cases.
public struct CSVParser {
    public init() {}

    /// Parses a `String` into rows of fields.
    public func parse(_ string: String) throws -> [[String]] {
        try parse(Array(string.utf8))
    }

    /// Parses raw UTF‑8 bytes. Useful when reading from a file or network stream.
    public func parse(_ bytes: [UInt8]) throws -> [[String]] {
        var rows: [[String]] = []
        var row: [String] = []
        var field: [UInt8] = []
        var state = State.startField
        var i = 0

        while i < bytes.count {
            let b = bytes[i]

            switch state {
            case .startField:
                switch b {
                case UInt8(ascii: ","):
                    row.append("")
                    i += 1

                case UInt8(ascii: "\""):
                    state = .quotedField
                    i += 1

                case UInt8(ascii: "\n"):
                    row.append("")
                    rows.append(row)
                    row = []
                    i += 1

                case UInt8(ascii: "\r"):
                    row.append("")
                    rows.append(row)
                    row = []
                    i += 1
                    if i < bytes.count, bytes[i] == UInt8(ascii: "\n") {
                        i += 1
                    }

                default:
                    field.append(b)
                    state = .unquotedField
                    i += 1
                }

            case .unquotedField:
                switch b {
                case UInt8(ascii: ","):
                    row.append(String(decoding: field, as: UTF8.self))
                    field = []
                    state = .startField
                    i += 1

                case UInt8(ascii: "\n"):
                    row.append(String(decoding: field, as: UTF8.self))
                    rows.append(row)
                    row = []
                    field = []
                    state = .startField
                    i += 1

                case UInt8(ascii: "\r"):
                    row.append(String(decoding: field, as: UTF8.self))
                    rows.append(row)
                    row = []
                    field = []
                    state = .startField
                    i += 1
                    if i < bytes.count, bytes[i] == UInt8(ascii: "\n") {
                        i += 1
                    }

                case UInt8(ascii: "\""):
                    throw CSVError.unexpectedQuote(offset: i)

                default:
                    field.append(b)
                    i += 1
                }

            case .quotedField:
                switch b {
                case UInt8(ascii: "\""):
                    // Check for escaped quote: "" inside a quoted field.
                    if i + 1 < bytes.count, bytes[i + 1] == UInt8(ascii: "\"") {
                        field.append(UInt8(ascii: "\""))
                        i += 2
                    } else {
                        state = .afterQuote
                        i += 1
                    }

                default:
                    // Anything else, including commas and newlines, is literal.
                    field.append(b)
                    i += 1
                }

            case .afterQuote:
                switch b {
                case UInt8(ascii: ","):
                    row.append(String(decoding: field, as: UTF8.self))
                    field = []
                    state = .startField
                    i += 1

                case UInt8(ascii: "\n"):
                    row.append(String(decoding: field, as: UTF8.self))
                    rows.append(row)
                    row = []
                    field = []
                    state = .startField
                    i += 1

                case UInt8(ascii: "\r"):
                    row.append(String(decoding: field, as: UTF8.self))
                    rows.append(row)
                    row = []
                    field = []
                    state = .startField
                    i += 1
                    if i < bytes.count, bytes[i] == UInt8(ascii: "\n") {
                        i += 1
                    }

                default:
                    let character = Character(UnicodeScalar(b))
                    throw CSVError.unexpectedCharacterAfterClosingQuote(
                        character: character,
                        offset: i
                    )
                }
            }
        }

        // Flush the final field/row if the file doesn't end with a newline.
        switch state {
        case .quotedField:
            throw CSVError.unterminatedQuotedField(offset: i)

        case .afterQuote, .unquotedField:
            row.append(String(decoding: field, as: UTF8.self))
            rows.append(row)

        case .startField:
            // If we have an unfinished row (e.g. "a,") we must add the empty field.
            if !row.isEmpty {
                row.append("")
                rows.append(row)
            }
        }

        return rows
    }

    private enum State {
        case startField
        case unquotedField
        case quotedField
        case afterQuote
    }
}
```

## Usage

```swift
let csv = """
name,description,price
Widget,"A small, useful widget",9.99
Gadget,"He said ""hello""",19.99
"""

do {
    let parser = CSVParser()
    let rows = try parser.parse(csv)

    for row in rows {
        print(row)
    }
    // ["name", "description", "price"]
    // ["Widget", "A small, useful widget", "9.99"]
    // ["Gadget", "He said \"hello\"", "19.99"]
} catch {
    print("CSV parsing failed: \(error)")
}
```

## Tricky parts documented

1. **Escaped quotes (`""`)**
   Inside a quoted field, a double quote is escaped by doubling it. The parser sees `""` and appends a single `"` to the field, then skips both bytes. This is why the parser works on bytes rather than `Character`s—the escape sequence is ASCII and must be detected at the byte level.

2. **Embedded commas and newlines**
   While in `.quotedField`, commas (` , `) and newlines (`\n`, `\r`) are treated as ordinary bytes and appended to the current field. They do **not** terminate the field or record. This allows multi‑line fields and fields containing commas.

3. **CRLF, LF, and CR line endings**
   The parser accepts `\r\n`, `\n`, and `\r` as record separators. When it encounters `\r`, it checks whether the next byte is `\n` and skips it if so. This prevents an extra empty row when parsing Windows‑style files.

4. **Final field without trailing newline**
   After the main loop, the parser flushes any remaining field and row. Special care is taken for the `.startField` state: if the file ends with a comma (e.g. `"a,"`), `row` is not empty but the final empty field must still be appended. If the file ends with a newline, `row` is empty and no extra row is added.

5. **Quotes in unquoted fields are rejected**
   RFC 4180 says quotes may only appear at the start of a field. If a quote appears in the middle of an unquoted field, the parser throws `unexpectedQuote`. This strictness helps catch malformed CSV early in a production service.

6. **Characters after a closing quote**
   After a quoted field closes, only a comma, newline, carriage return, or end‑of‑file is allowed. Anything else throws `unexpectedCharacterAfterClosingQuote`. This prevents silently accepting malformed input like `"abc"def`.

7. **Byte‑level parsing and Unicode**
   The parser operates on `[UInt8]` from `String.utf8`. CSV delimiters and escapes are all ASCII, so they can be detected safely without worrying about Unicode grapheme clusters. Field contents are reassembled with `String(decoding:as: UTF8.self)`, which handles any valid UTF‑8. If you need to reject invalid UTF‑8, use `String(bytes:encoding:)` and throw on `nil`.

8. **Empty lines**
   An empty line is parsed as a single empty field. If your service needs to skip blank lines, filter them after parsing or add a skip flag.

9. **Performance**
   This implementation is O(n) over the input and uses arrays of bytes. For very large files, consider a streaming parser that reads chunks and yields rows incrementally instead of materialising the entire `[[String]]`.

## Production considerations

- **Streaming**: The current API returns all rows at once. For multi‑gigabyte files, wrap the state machine in a `Sequence` or `AsyncSequence` that reads from a `FileHandle` or `URLSession` stream and emits rows as they complete.
- **Error context**: Errors include byte offsets. You can extend them to include line and column numbers by tracking them as you advance.
- **Dialect flexibility**: Some systems use semicolons, tabs, or different quote characters. The parser is easy to parameterise by replacing the hard‑coded ASCII bytes with configurable delimiters.
- **BOM handling**: UTF‑8 files sometimes begin with a byte order mark (`EF BB BF`). You may want to strip it before parsing.

This parser is deliberately strict, which is usually the right choice for a production service: it fails loudly on malformed input rather than silently producing corrupted data.

Below is a TypeScript implementation that parses ISO 8601 durations into seconds.

It supports the common components:

- `Y` years
- `M` months
- `W` weeks
- `D` days
- `H` hours
- `M` minutes
- `S` seconds
- optional leading `+` / `-`
- decimal fractions using `.` or `,`

> Important: years and months are ambiguous when converting to seconds. This implementation assumes:
> - 1 year = 365 days
> - 1 month = 30 days
>
> If you need exact calendar math, use a date library or a reference date instead.

```ts
const SECONDS_PER_MINUTE = 60;
const SECONDS_PER_HOUR = 60 * SECONDS_PER_MINUTE;
const SECONDS_PER_DAY = 24 * SECONDS_PER_HOUR;
const SECONDS_PER_WEEK = 7 * SECONDS_PER_DAY;
const SECONDS_PER_MONTH = 30 * SECONDS_PER_DAY;
const SECONDS_PER_YEAR = 365 * SECONDS_PER_DAY;

const ISO_8601_DURATION_RE =
  /^([+-])?P(?:(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)W)?(?:(\d+(?:[.,]\d+)?)D)?(?:T(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?)?)$/;

export function parseISO8601DurationToSeconds(duration: string): number {
  const match = ISO_8601_DURATION_RE.exec(duration);

  if (!match) {
    throw new Error(`Invalid ISO 8601 duration: ${duration}`);
  }

  const [
    ,
    sign,
    years,
    months,
    weeks,
    days,
    hours,
    minutes,
    seconds,
  ] = match;

  const hasAnyComponent = [
    years,
    months,
    weeks,
    days,
    hours,
    minutes,
    seconds,
  ].some((value) => value !== undefined);

  if (!hasAnyComponent) {
    throw new Error(`Invalid ISO 8601 duration: ${duration}`);
  }

  const hasTimeDesignator = duration.includes('T');
  const hasTimeComponent =
    hours !== undefined || minutes !== undefined || seconds !== undefined;

  if (hasTimeDesignator && !hasTimeComponent) {
    throw new Error(`Invalid ISO 8601 duration: ${duration}`);
  }

  // ISO 8601 does not allow weeks to be combined with other components.
  if (
    weeks !== undefined &&
    (years !== undefined ||
      months !== undefined ||
      days !== undefined ||
      hours !== undefined ||
      minutes !== undefined ||
      seconds !== undefined)
  ) {
    throw new Error(
      `Invalid ISO 8601 duration: weeks cannot be combined with other components`,
    );
  }

  const toNumber = (value: string | undefined): number => {
    if (value === undefined) return 0;
    return Number(value.replace(',', '.'));
  };

  const totalSeconds =
    toNumber(years) * SECONDS_PER_YEAR +
    toNumber(months) * SECONDS_PER_MONTH +
    toNumber(weeks) * SECONDS_PER_WEEK +
    toNumber(days) * SECONDS_PER_DAY +
    toNumber(hours) * SECONDS_PER_HOUR +
    toNumber(minutes) * SECONDS_PER_MINUTE +
    toNumber(seconds);

  return sign === '-' ? -totalSeconds : totalSeconds;
}
```

Example:

```ts
parseISO8601DurationToSeconds('P3DT4H5M');
// 3 days + 4 hours + 5 minutes
// 259200 + 14400 + 300
// => 273900
```

---

## Unit tests

These tests use Jest/Vitest-style syntax.

```ts
import { parseISO8601DurationToSeconds } from './parseISO8601DurationToSeconds';

describe('parseISO8601DurationToSeconds', () => {
  it('parses days, hours, and minutes', () => {
    expect(parseISO8601DurationToSeconds('P3DT4H5M')).toBe(273900);
  });

  it('parses days only', () => {
    expect(parseISO8601DurationToSeconds('P3D')).toBe(3 * 86400);
  });

  it('parses time-only durations', () => {
    expect(parseISO8601DurationToSeconds('PT1H30M')).toBe(5400);
  });

  it('parses seconds only', () => {
    expect(parseISO8601DurationToSeconds('PT45S')).toBe(45);
  });

  it('parses weeks', () => {
    expect(parseISO8601DurationToSeconds('P1W')).toBe(604800);
  });

  it('parses a full date/time duration', () => {
    expect(parseISO8601DurationToSeconds('P1Y2M3DT4H5M6S')).toBe(
      1 * 365 * 86400 +
        2 * 30 * 86400 +
        3 * 86400 +
        4 * 3600 +
        5 * 60 +
        6,
    );
  });

  it('parses zero durations', () => {
    expect(parseISO8601DurationToSeconds('P0D')).toBe(0);
    expect(parseISO8601DurationToSeconds('PT0S')).toBe(0);
  });

  it('parses fractional values with a dot', () => {
    expect(parseISO8601DurationToSeconds('PT1.5H')).toBe(5400);
  });

  it('parses fractional values with a comma', () => {
    expect(parseISO8601DurationToSeconds('PT1,5H')).toBe(5400);
  });

  it('parses negative durations', () => {
    expect(parseISO8601DurationToSeconds('-P1D')).toBe(-86400);
  });

  it('parses positive durations with explicit plus sign', () => {
    expect(parseISO8601DurationToSeconds('+P1D')).toBe(86400);
  });

  it('throws on an empty duration', () => {
    expect(() => parseISO8601DurationToSeconds('')).toThrow();
  });

  it('throws on a duration with only P', () => {
    expect(() => parseISO8601DurationToSeconds('P')).toThrow();
  });

  it('throws on a duration with only PT', () => {
    expect(() => parseISO8601DurationToSeconds('PT')).toThrow();
  });

  it('throws when time components appear without T', () => {
    expect(() => parseISO8601DurationToSeconds('P3H')).toThrow();
  });

  it('throws when date components appear after T', () => {
    expect(() => parseISO8601DurationToSeconds('PT1D')).toThrow();
  });

  it('throws when weeks are combined with other components', () => {
    expect(() => parseISO8601DurationToSeconds('P1W2D')).toThrow();
  });

  it('throws on malformed durations', () => {
    expect(() => parseISO8601DurationToSeconds('3D')).toThrow();
    expect(() => parseISO8601DurationToSeconds('P1DT')).toThrow();
    expect(() => parseISO8601DurationToSeconds('P1D2Y')).toThrow();
  });
});
```

The parser is intentionally strict about the common ISO 8601 rules: at least one component must be present, time components require `T`, and weeks cannot be mixed with other components.

