import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class LruCacheTest {

    @Test
    fun `put and get basic values`() {
        val cache = LruCache<Int, String>(2)

        cache.put(1, "a")
        cache.put(2, "b")

        assertEquals("a", cache.get(1))
        assertEquals("b", cache.get(2))
    }

    @Test
    fun `get missing key returns null`() {
        val cache = LruCache<Int, String>(2)

        assertNull(cache.get(42))
    }

    @Test
    fun `evicts least recently used on overflow`() {
        val cache = LruCache<Int, String>(2)

        cache.put(1, "a")
        cache.put(2, "b")
        cache.put(3, "c")

        assertNull(cache.get(1))
        assertEquals("b", cache.get(2))
        assertEquals("c", cache.get(3))
    }

    @Test
    fun `get refreshes recency`() {
        val cache = LruCache<Int, String>(2)

        cache.put(1, "a")
        cache.put(2, "b")

        cache.get(1) // 1 becomes most recently used

        cache.put(3, "c") // should evict 2

        assertNull(cache.get(2))
        assertEquals("a", cache.get(1))
        assertEquals("c", cache.get(3))
    }

    @Test
    fun `updating existing key refreshes recency and does not evict`() {
        val cache = LruCache<Int, String>(2)

        cache.put(1, "a")
        cache.put(2, "b")

        cache.put(1, "a2") // update 1, now most recently used

        cache.put(3, "c") // should evict 2

        assertNull(cache.get(2))
        assertEquals("a2", cache.get(1))
        assertEquals("c", cache.get(3))
    }

    @Test
    fun `capacity one evicts previous value`() {
        val cache = LruCache<Int, String>(1)

        cache.put(1, "a")
        cache.put(2, "b")

        assertNull(cache.get(1))
        assertEquals("b", cache.get(2))
    }

    @Test
    fun `size never exceeds capacity`() {
        val cache = LruCache<Int, String>(3)

        repeat(100) { i ->
            cache.put(i, "v$i")
            assertTrue(cache.size <= 3)
        }
    }

    @Test
    fun `capacity must be positive`() {
        assertThrows(IllegalArgumentException::class.java) {
            LruCache<Int, String>(0)
        }

        assertThrows(IllegalArgumentException::class.java) {
            LruCache<Int, String>(-1)
        }
    }

    @Test
    fun `eviction order follows access order`() {
        val cache = LruCache<Int, String>(3)

        cache.put(1, "a")
        cache.put(2, "b")
        cache.put(3, "c")

        cache.get(2)
        cache.get(1)

        cache.put(4, "d") // should evict 3

        assertNull(cache.get(3))
        assertEquals("a", cache.get(1))
        assertEquals("b", cache.get(2))
        assertEquals("d", cache.get(4))
    }

    @Test
    fun `put same key multiple times updates value`() {
        val cache = LruCache<Int, String>(2)

        cache.put(1, "a")
        cache.put(1, "b")
        cache.put(1, "c")

        assertEquals("c", cache.get(1))
        assertEquals(1, cache.size)
    }

    @Test
    fun `get after eviction returns null`() {
        val cache = LruCache<Int, String>(2)

        cache.put(1, "a")
        cache.put(2, "b")
        cache.put(3, "c")

        assertNull(cache.get(1))

        cache.put(4, "d")

        assertNull(cache.get(2))
    }
}
