class LruCache<K : Any, V : Any>(private val capacity: Int) {
    init {
        require(capacity > 0) { "Capacity must be greater than 0" }
    }

    private class Node<K, V>(val key: K, var value: V) {
        var prev: Node<K, V>? = null
        var next: Node<K, V>? = null
    }

    private val map = HashMap<K, Node<K, V>>(capacity)
    private var head: Node<K, V>? = null // most recently used
    private var tail: Node<K, V>? = null // least recently used

    val size: Int get() = map.size

    fun get(key: K): V? {
        val node = map[key] ?: return null
        moveToHead(node)
        return node.value
    }

    fun put(key: K, value: V) {
        val existing = map[key]
        if (existing != null) {
            existing.value = value
            moveToHead(existing)
        } else {
            val newNode = Node(key, value)
            map[key] = newNode
            addToHead(newNode)
            if (map.size > capacity) {
                removeTail()
            }
        }
    }

    private fun moveToHead(node: Node<K, V>) {
        if (head === node) return
        removeNode(node)
        addToHead(node)
    }

    private fun addToHead(node: Node<K, V>) {
        node.prev = null
        node.next = head
        head?.prev = node
        head = node
        if (tail == null) tail = node
    }

    private fun removeNode(node: Node<K, V>) {
        val prev = node.prev
        val next = node.next
        if (prev != null) prev.next = next else head = next
        if (next != null) next.prev = prev else tail = prev
        node.prev = null
        node.next = null
    }

    private fun removeTail() {
        val oldTail = tail ?: return
        removeNode(oldTail)
        map.remove(oldTail.key)
    }
}

