# Arithmetic Expression Tokenizer & Evaluator

Here's a complete implementation with a tokenizer and a recursive-descent parser that handles operator precedence.

```typescript
// ---------- Types ----------

type TokenType = 'number' | 'operator' | 'lparen' | 'rparen';

interface Token {
  type: TokenType;
  value: string;
}

// ---------- Tokenizer ----------

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    // Skip whitespace
    if (/\s/.test(ch)) {
      i++;
      continue;
    }

    // Number (integer or decimal)
    if (/[0-9.]/.test(ch)) {
      let num = '';
      while (i < input.length && /[0-9.]/.test(input[i])) {
        num += input[i++];
      }
      if ((num.match(/\./g) || []).length > 1) {
        throw new Error(`Invalid number: ${num}`);
      }
      tokens.push({ type: 'number', value: num });
      continue;
    }

    // Operators
    if ('+-*/%^'.includes(ch)) {
      tokens.push({ type: 'operator', value: ch });
      i++;
      continue;
    }

    // Parentheses
    if (ch === '(') {
      tokens.push({ type: 'lparen', value: ch });
      i++;
      continue;
    }
    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ch });
      i++;
      continue;
    }

    throw new Error(`Unexpected character: '${ch}' at position ${i}`);
  }

  return tokens;
}

// ---------- Evaluator (recursive-descent with precedence) ----------
//
// Grammar:
//   expr    := term   (('+' | '-') term)*
//   term    := factor (('*' | '/' | '%') factor)*
//   factor  := unary  ('^' factor)?           // right-associative power
//   unary   := ('-' | '+')? primary
//   primary := number | '(' expr ')'

function evaluate(tokens: Token[]): number {
  let pos = 0;

  const peek = (): Token | undefined => tokens[pos];
  const consume = (): Token => tokens[pos++];

  function parseExpr(): number {
    let left = parseTerm();

    while (true) {
      const t = peek();
      if (t && t.type === 'operator' && (t.value === '+' || t.value === '-')) {
        consume();
        const right = parseTerm();
        left = t.value === '+' ? left + right : left - right;
      } else {
        break;
      }
    }

    return left;
  }

  function parseTerm(): number {
    let left = parseFactor();

    while (true) {
      const t = peek();
      if (t && t.type === 'operator' && '*/%'.includes(t.value)) {
        consume();
        const right = parseFactor();
        if (t.value === '*') left *= right;
        else if (t.value === '/') left /= right;
        else left %= right;
      } else {
        break;
      }
    }

    return left;
  }

  function parseFactor(): number {
    const left = parseUnary();

    const t = peek();
    if (t && t.type === 'operator' && t.value === '^') {
      consume();
      const right = parseFactor(); // right-associative
      return Math.pow(left, right);
    }

    return left;
  }

  function parseUnary(): number {
    const t = peek();
    if (t && t.type === 'operator' && (t.value === '-' || t.value === '+')) {
      consume();
      const value = parseUnary();
      return t.value === '-' ? -value : value;
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const t = consume();
    if (!t) throw new Error('Unexpected end of input');

    if (t.type === 'number') {
      const n = Number(t.value);
      if (Number.isNaN(n)) throw new Error(`Invalid number: ${t.value}`);
      return n;
    }

    if (t.type === 'lparen') {
      const value = parseExpr();
      const closing = consume();
      if (!closing || closing.type !== 'rparen') {
        throw new Error('Expected closing parenthesis');
      }
      return value;
    }

    throw new Error(`Unexpected token: ${t.value}`);
  }

  const result = parseExpr();
  if (pos !== tokens.length) {
    throw new Error(`Unexpected token at position ${pos}: ${tokens[pos].value}`);
  }
  return result;
}

// ---------- Public API ----------

function calc(expression: string): number {
  return evaluate(tokenize(expression));
}

// ---------- Usage Example ----------

const examples = [
  '2 + 3 * 4',            // 14
  '(2 + 3) * 4',          // 20
  '2 ^ 3 ^ 2',            // 512 (right-associative)
  '-3 + 4 * 2',           // 5
  '10 % 3 + 1.5',         // 2.5
  '((1 + 2) * (3 + 4))',  // 21
];

for (const expr of examples) {
  console.log(`${expr.padEnd(22)} = ${calc(expr)}`);
}

// Tokens for the first expression
console.log('\nTokens for "2 + 3 * 4":');
console.log(tokenize('2 + 3 * 4'));
```

**Output:**
```
2 + 3 * 4              = 14
(2 + 3) * 4            = 20
2 ^ 3 ^ 2              = 512
-3 + 4 * 2             = 5
10 % 3 + 1.5           = 2.5
((1 + 2) * (3 + 4))    = 21

Tokens for "2 + 3 * 4":
[
  { type: 'number',   value: '2' },
  { type: 'operator', value: '+' },
  { type: 'number',   value: '3' },
  { type: 'operator', value: '*' },
  { type: 'number',   value: '4' }
]
```

## Key design points

- **Tokenizer**: single pass, character-by-character, classifies tokens as `number`, `operator`, `lparen`, or `rparen`.
- **Precedence** is encoded in the grammar layering (`expr` → `term` → `factor` → `unary` → `primary`):
  - `+`/`-` are lowest precedence
  - `*`, `/`, `%` bind tighter
  - `^` binds tightest and is **right-associative** (`2^3^2 = 2^(3^2)`)
- **Unary minus** is handled at a layer above `primary`, so `-3^2` parses as `-(3^2) = -9`, matching most conventional calculators.
- **Errors** are thrown for stray characters, missing parentheses, and trailing tokens.

# Thread-Safe Bounded Blocking Queue in CUDA C++

Below is a complete, compilable implementation with unit tests.

## Design Notes

- **Single-device GPU queue** using `cudaMallocManaged` for a shared ring buffer.
- Synchronization uses CUDA's **`cuda::atomic`** and **`cuda::thread_scope`** (from CUDA's libcu++). For host-side testing, `cuda::atomic` with `thread_scope_system` provides host/device interoperability.
- **Blocking**: spin with `__nanosleep` on device, `std::this_thread::yield` on host. (CUDA has no true blocking primitive; busy-wait is the standard approach.)
- **Bounded**: capacity is fixed at construction.
- **Thread-safe**: a single mutex-equivalent via atomic CAS guarding head/tail/count. We use atomics rather than a mutex because CUDA lacks `std::mutex`-style primitives on-device pre-CC 7.x, and this gives us lock-free fast paths.

> The pattern below uses a **single-producer / single-consumer (SPSC) lock-free** design, which is the common case for GPU pipelines. If you need MPMC, swap the atomic head/tail updates for a ticket-lock (shown in comments).

---

## `bounded_queue.cuh`

```cpp
#pragma once

#include <cuda/atomic>
#include <cuda_runtime.h>
#include <cstddef>
#include <cstdint>
#include <new>

namespace gpuq {

template <typename T>
class BoundedQueue {
public:
    using atomic_t = cuda::atomic<unsigned, cuda::thread_scope_device>;

    // ---- Construction / destruction (host only) --------------------------
    explicit BoundedQueue(std::size_t capacity) : cap_(capacity) {
        // capacity must be > 0 and rounded up to power of two for & mask trick
        std::size_t pow2 = 1;
        while (pow2 < capacity) pow2 <<= 1;
        cap_ = pow2;
        mask_ = cap_ - 1;

        // Allocate managed ring (must be trivially constructible T)
        static_assert(std::is_trivially_copyable<T>::value,
                      "T must be trivially copyable for managed memory.");
        cudaMallocManaged(&ring_, cap_ * sizeof(T));
        cudaMallocManaged(&head_, sizeof(atomic_t));
        cudaMallocManaged(&tail_, sizeof(atomic_t));
        cudaMallocManaged(&closed_, sizeof(atomic_t));

        new (head_)  atomic_t(0u);
        new (tail_)  atomic_t(0u);
        new (closed_) atomic_t(0u);
    }

    ~BoundedQueue() {
        cudaFree(ring_);
        cudaFree(head_);
        cudaFree(tail_);
        cudaFree(closed_);
    }

    BoundedQueue(const BoundedQueue&) = delete;
    BoundedQueue& operator=(const BoundedQueue&) = delete;

    // ---- Device / host API ------------------------------------------------
    __host__ __device__ std::size_t capacity() const { return cap_; }

    __host__ __device__ bool closed() const {
        return closed_->load(cuda::memory_order_acquire) != 0u;
    }

    // Called by the producing side to signal "no more items".
    __host__ __device__ void close() {
        closed_->store(1u, cuda::memory_order_release);
    }

    // Non-blocking push. Returns false if full or closed.
    __host__ __device__ bool try_put(const T& v) {
        if (closed()) return false;
        unsigned h    = head_->load(cuda::memory_order_relaxed);
        unsigned next = h + 1;
        if ((next & mask_) == (tail_->load(cuda::memory_order_acquire) & mask_))
            return false; // full
        ring_[h & mask_] = v;
        head_->store(next, cuda::memory_order_release);
        return true;
    }

    // Blocking push. Returns false only if the queue has been closed.
    __host__ __device__ bool put(const T& v) {
        while (true) {
            if (try_put(v)) return true;
            if (closed()) return false;
            spin_wait();
        }
    }

    // Non-blocking pop. Returns false if empty or (empty && closed).
    __host__ __device__ bool try_get(T& out) {
        unsigned t = tail_->load(cuda::memory_order_relaxed);
        if (t == head_->load(cuda::memory_order_acquire)) return false; // empty
        out = ring_[t & mask_];
        tail_->store(t + 1, cuda::memory_order_release);
        return true;
    }

    // Blocking pop. Returns false only if queue is closed AND drained.
    __host__ __device__ bool get(T& out) {
        while (true) {
            if (try_get(out)) return true;
            if (closed() && head_->load(cuda::memory_order_acquire)
                            == tail_->load(cuda::memory_order_acquire))
                return false;
            spin_wait();
        }
    }

private:
    __host__ __device__ static void spin_wait() {
#if defined(__CUDA_ARCH__)
        __nanosleep(64);
#else
        // On host, a noop; std::this_thread isn't allowed in device code.
        __builtin_ia32_pause();
#endif
    }

    T*           ring_   = nullptr;
    atomic_t*    head_   = nullptr;   // producer-owned write cursor
    atomic_t*    tail_   = nullptr;   // consumer-owned read cursor
    atomic_t*    closed_ = nullptr;
    std::size_t  cap_    = 0;
    std::size_t  mask_   = 0;

    static_assert(sizeof(unsigned) == sizeof(atomic_t),
                  "atomic<unsigned> must fit in unsigned storage.");
};

} // namespace gpuq
```

**Invariants**
- Ring stores at most `cap_ - 1` items (one slot left empty to distinguish full/empty).
- `head_` and `tail_` are monotonically increasing 32-bit counters; `& mask_` maps them to slots.
- Acquire/release pairs on the cursors enforce the happens-before needed for `ring_[...]` data transfer.

