## Unit tests

Because we need two concurrent contexts, tests cover:
1. **Host-only** (two `std::thread`s) — exercises the same code paths.
2. **Device SPSC** — one producer block, one consumer block, transferred via managed memory.
3. **Edge cases** — full, empty, close-while-waiting, drain-after-close, wraparound.

### `test_bounded_queue.cpp`

```cpp
#include "bounded_queue.cuh"

#include <atomic>
#include <cassert>
#include <cstdio>
#include <thread>
#include <vector>

using gpuq::BoundedQueue;

// ---------------------------------------------------------------------------
// Host-only tests use std::thread. Because spin_wait() is a noop on host,
// these are effectively busy-wait; the queue API is nonetheless exercised.
// ---------------------------------------------------------------------------

static int failures = 0;
#define CHECK(cond)                                                            \
    do {                                                                       \
        if (!(cond)) {                                                         \
            std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);        \
            ++failures;                                                        \
        }                                                                      \
    } while (0)

// 1. Empty try_get returns false.
static void test_empty_try_get() {
    BoundedQueue<int> q(4);
    int v = 123;
    CHECK(q.try_get(v) == false);
    CHECK(v == 123); // unchanged
}

// 2. Single put/get round-trip.
static void test_single_roundtrip() {
    BoundedQueue<int> q(4);
    CHECK(q.try_put(42));
    int v = 0;
    CHECK(q.try_get(v));
    CHECK(v == 42);
    CHECK(q.try_get(v) == false);
}

// 3. Bounded: capacity N => at most N-1 accepted without a consumer.
static void test_full() {
    BoundedQueue<int> q(4);      // effective capacity = 3
    CHECK(q.try_put(1));
    CHECK(q.try_put(2));
    CHECK(q.try_put(3));
    CHECK(q.try_put(4) == false); // full
    int v;
    CHECK(q.try_get(v)); CHECK(v == 1);
    CHECK(q.try_put(4));          // room now
}

// 4. FIFO ordering across many items (wraparound tested implicitly).
static void test_fifo_wraparound() {
    BoundedQueue<int> q(8);
    const int N = 1000;
    int sent = 0, recv = 0;
    while (recv < N) {
        if (sent < N) {
            if (q.try_put(sent)) sent++;
        } else {
            break;
        }
        int v;
        if (q.try_get(v)) {
            CHECK(v == recv);
            recv++;
        }
    }
    while (true) {
        int v;
        if (!q.try_get(v)) break;
        CHECK(v == recv); recv++;
    }
    CHECK(recv == N);
}

// 5. close(): put fails after close, drained get still succeeds.
static void test_close_and_drain() {
    BoundedQueue<int> q(4);
    CHECK(q.try_put(10));
    CHECK(q.try_put(20));
    q.close();

    CHECK(q.closed());
    CHECK(q.try_put(99) == false);
    CHECK(q.put(99)     == false);

    int v;
    CHECK(q.get(v)); CHECK(v == 10);
    CHECK(q.get(v)); CHECK(v == 20);
    CHECK(q.get(v) == false);  // closed and drained
    CHECK(q.try_get(v) == false);
}

// 6. two-thread stress (host producer + host consumer).
static void test_host_two_threads_stress() {
    BoundedQueue<int> q(64);
    const int N = 200'000;
    std::atomic<bool> producer_done{false};

    std::thread producer([&] {
        for (int i = 0; i < N; ++i) q.put(i);
        q.close();
        producer_done = true;
    });

    int expect = 0;
    int v;
    while (q.get(v)) {
        CHECK(v == expect);
        ++expect;
    }
    producer.join();
    CHECK(expect == N);
    CHECK(producer_done.load());
}

// 7. Blocking put wakes once consumer drains.
static void test_blocking_put_unblocks() {
    BoundedQueue<int> q(2);          // effective cap = 1
    CHECK(q.try_put(1));             // now full
    std::atomic<bool> put_done{false};
    std::thread t([&] {
        CHECK(q.put(2));             // should block until get
        put_done = true;
    });
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
    CHECK(!put_done.load());         // still blocked
    int v;
    CHECK(q.get(v)); CHECK(v == 1);
    t.join();
    CHECK(put_done.load());
    CHECK(q.get(v)); CHECK(v == 2);
}

// 8. Blocking get wakes once producer puts.
static void test_blocking_get_unblocks() {
    BoundedQueue<int> q(2);
    int v = -1;
    std::thread t([&] {
        CHECK(q.get(v));             // blocks
    });
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
    CHECK(q.try_put(77));
    t.join();
    CHECK(v == 77);
}

// 9. Blocking get returns false once closed and empty.
static void test_get_unblocks_on_close() {
    BoundedQueue<int> q(2);
    bool got = true;
    std::thread t([&] {
        int v;
        got = q.get(v);              // blocks
    });
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
    q.close();
    t.join();
    CHECK(got == false);
}

// 10. Capacity rounding: request 5 -> actual 8; request 1 -> actual 1.
static void test_capacity_rounding() {
    BoundedQueue<int> q1(1);  CHECK(q1.capacity() == 1);
    BoundedQueue<int> q2(5);  CHECK(q2.capacity() == 8);
    BoundedQueue<int> q3(16); CHECK(q3.capacity() == 16);
}

// ---------------------------------------------------------------------------
// GPU tests: launch one producer block and one consumer block.
// ---------------------------------------------------------------------------

__global__ void producer_kernel(BoundedQueue<int>* q, int n) {
    for (int i = 0; i < n; ++i) q->put(i);
    q->close();
}

__global__ void consumer_kernel(BoundedQueue<int>* q, int* out, int* count) {
    int v, c = 0;
    while (q->get(v)) {
        out[c++] = v;
    }
    *count = c;
}

static void test_gpu_spsc() {
    const int N = 100'000;
    BoundedQueue<int>* q;
    cudaMallocManaged(&q, sizeof(BoundedQueue<int>));
    new (q) BoundedQueue<int>(256);

    int* out; int* count;
    cudaMallocManaged(&out,   N * sizeof(int));
    cudaMallocManaged(&count, sizeof(int));

    producer_kernel<<<1, 1>>>(q, N);
    consumer_kernel<<<1, 1>>>(q, out, count);
    cudaDeviceSynchronize();

    CHECK(*count == N);
    for (int i = 0; i < N; ++i) CHECK(out[i] == i);

    q->~BoundedQueue<int>();
    cudaFree(q); cudaFree(out); cudaFree(count);
}

// ---------------------------------------------------------------------------
int main() {
    test_empty_try_get();
    test_single_roundtrip();
    test_full();
    test_fifo_wraparound();
    test_close_and_drain();
    test_host_two_threads_stress();
    test_blocking_put_unblocks();
    test_blocking_get_unblocks();
    test_get_unblocks_on_close();
    test_capacity_rounding();

    test_gpu_spsc();

    if (failures == 0) std::printf("All tests passed.\n");
    else               std::printf("%d test(s) FAILED.\n", failures);
    return failures == 0 ? 0 : 1;
}
