#[derive(Debug, Clone)]
pub struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    /// Creates a new union-find structure with `n` elements: 0..n.
    pub fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    /// Finds the representative/root of `x`, with path compression.
    pub fn find(&mut self, x: usize) -> usize {
        let mut root = x;

        while self.parent[root] != root {
            root = self.parent[root];
        }

        let mut current = x;
        while self.parent[current] != current {
            let next = self.parent[current];
            self.parent[current] = root;
            current = next;
        }

        root
    }

    /// Unions the sets containing `x` and `y`.
    /// Returns `true` if they were in different sets.
    pub fn union(&mut self, x: usize, y: usize) -> bool {
        let mut root_x = self.find(x);
        let mut root_y = self.find(y);

        if root_x == root_y {
            return false;
        }

        // Union by rank: attach smaller rank tree under larger rank tree.
        if self.rank[root_x] < self.rank[root_y] {
            std::mem::swap(&mut root_x, &mut root_y);
        }

        self.parent[root_y] = root_x;

        if self.rank[root_x] == self.rank[root_y] {
            self.rank[root_x] += 1;
        }

        true
    }

    /// Returns `true` if `x` and `y` are in the same set.
    pub fn connected(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}

fn main() {
    let mut uf = UnionFind::new(6);

    uf.union(0, 1);
    uf.union(1, 2);
    uf.union(3, 4);

    assert!(uf.connected(0, 2));
    assert!(!uf.connected(0, 3));

    uf.union(2, 4);

    assert!(uf.connected(0, 3));
    assert!(uf.connected(1, 4));
    assert!(!uf.connected(0, 5));

    // Direct representative checks
    let root0 = uf.find(0);
    let root2 = uf.find(2);
    assert_eq!(root0, root2);
}
```

This implementation provides:

- `find` with path compression
- `union` with union by rank
- `connected` for checking whether two elements are in the same set
- 0-based indexing for elements `0..n`

