```go
package main

import (
	"fmt"
	"strings"
)

// PrettyJSON reformats a JSON string with indentation.
// It does not validate JSON; it assumes the input is valid JSON.
func PrettyJSON(input string) string {
	var out strings.Builder
	indent := 0
	inString := false
	escaped := false

	for i := 0; i < len(input); i++ {
		c := input[i]

		if inString {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '"' {
				inString = false
			}
			continue
		}

		switch c {
		case '"':
			inString = true
			out.WriteByte(c)

		case '{', '[':
			out.WriteByte(c)

			// Check whether this is an empty object/array.
			j := i + 1
			for j < len(input) && isSpace(input[j]) {
				j++
			}

			if j < len(input) && (input[j] == '}' || input[j] == ']') {
				// Empty object/array: do not add a newline.
			} else {
				indent++
				out.WriteByte('\n')
				writeIndent(&out, indent)
			}

		case '}', ']':
			// Check whether the previous non-space char was an opening brace/bracket.
			j := i - 1
			for j >= 0 && isSpace(input[j]) {
				j--
			}

			if j >= 0 && (input[j] == '{' || input[j] == '[') {
				// Empty object/array: do not add a newline.
			} else {
				indent--
				out.WriteByte('\n')
				writeIndent(&out, indent)
			}

			out.WriteByte(c)

		case ',':
			out.WriteByte(c)
			out.WriteByte('\n')
			writeIndent(&out, indent)

		case ':':
			out.WriteByte(c)
			out.WriteByte(' ')

		default:
			if isSpace(c) {
				continue
			}
			out.WriteByte(c)
		}
	}

	return out.String()
}

func writeIndent(out *strings.Builder, n int) {
	for i := 0; i < n; i++ {
		out.WriteString("  ")
	}
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func main() {
	input := `{"name":"Alice","age":30,"tags":["go","json"],"address":{"city":"Paris"}}`
	fmt.Println(PrettyJSON(input))
}
