fun rotate90Clockwise(matrix: Array<IntArray>) {
    val n = matrix.size
    require(matrix.all { it.size == n }) { "Matrix must be NxN" }

    // 1. Transpose the matrix
    for (i in 0 until n) {
        for (j in i + 1 until n) {
            val temp = matrix[i][j]
            matrix[i][j] = matrix[j][i]
            matrix[j][i] = temp
        }
    }

    // 2. Reverse each row
    for (i in 0 until n) {
        var left = 0
        var right = n - 1
        while (left < right) {
            val temp = matrix[i][left]
            matrix[i][left] = matrix[i][right]
            matrix[i][right] = temp
            left++
            right--
        }
    }
}

fun main() {
    val matrix = arrayOf(
        intArrayOf(1, 2, 3),
        intArrayOf(4, 5, 6),
        intArrayOf(7, 8, 9)
    )

    rotate90Clockwise(matrix)

    for (row in matrix) {
        println(row.joinToString(", "))
    }
}
