// Minimal CUDA C++ Roman numeral <-> integer conversion.
// Assumes valid standard Roman numerals in [1, 3999].

__device__ __forceinline__ int romanVal(char c) {
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return 0;
    }
}

__device__ int romanToInt(const char* s) {
    int res = 0, prev = 0;
    for (int i = 0; s[i] != '\0'; ++i) {
        int cur = romanVal(s[i]);
        res += (cur > prev) ? (cur - 2 * prev) : cur;
        prev = cur;
    }
    return res;
}

__device__ void intToRoman(int num, char* out) {
    const int vals[13] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
    const char* syms[13] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL",
                            "X", "IX", "V", "IV", "I"};
    int p = 0;
    for (int i = 0; i < 13; ++i) {
        while (num >= vals[i]) {
            const char* s = syms[i];
            while (*s) out[p++] = *s++;
            num -= vals[i];
        }
    }
    out[p] = '\0';
}
```

