/**
 * Trie with exact word lookup and prefix counting.
 *
 * Semantics:
 * - Words are treated as distinct values. Re-inserting the same word is a no-op.
 * - `countPrefix("")` returns the total number of distinct words.
 * - Strings are traversed by Unicode code point (`for...of`), not by UTF-16 code unit.
 *   No normalization is performed; normalize at your service boundary if needed.
 * - Exact search and prefix lookup are case-sensitive.
 */
export class Trie {
  private readonly root: TrieNode = createNode();

  /**
   * Inserts a word.
   * @returns true if the word was not already present, false otherwise.
   */
  insert(word: string): boolean {
    let node = this.root;
    const path: TrieNode[] = [this.root];

    for (const char of word) {
      let next = node.children.get(char);

      if (next === undefined) {
        next = createNode();
        node.children.set(char, next);
      }

      node = next;
      path.push(node);
    }

    if (node.isWord) {
      return false;
    }

    node.isWord = true;

    // `wordCount` is the number of distinct words in this node's subtree.
    // Increment every node on the path, including the root.
    for (const n of path) {
      n.wordCount++;
    }

    return true;
  }

  /**
   * Exact search: true only if the entire word was inserted.
   */
  search(word: string): boolean {
    const node = this.findNode(word);
    return node?.isWord ?? false;
  }

  /**
   * Returns the number of distinct inserted words that start with `prefix`.
   */
  countPrefix(prefix: string): number {
    const node = this.findNode(prefix);
    return node?.wordCount ?? 0;
  }

  /**
   * Total number of distinct words.
   */
  get size(): number {
    return this.root.wordCount;
