Below is a production-oriented Go implementation. It treats words as case-insensitive Unicode letter/digit runs, returns deterministic results, and uses a heap so it does not sort every distinct word when `k` is small.

```go
package text

import (
	"container/heap"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

// WordCount is a word and its frequency.
type WordCount struct {
	Word  string
	Count int
}

// TopKWords returns the k most frequent words in text.
//
// Words are matched case-insensitively after Unicode lowercasing. A word is
// a maximal run of Unicode letters and digits. Punctuation, whitespace, and
// symbols are separators. This means "don't" is counted as "don" and "t".
//
// The result is sorted by Count descending, then Word ascending, so equal
// counts have deterministic ordering.
//
// k <= 0 returns nil. If there are fewer than k distinct words, all words
// are returned.
func TopKWords(text string, k int) []WordCount {
	if k <= 0 {
		return nil
	}

	counts := make(map[string]int)
	forEachWord(text, func(word string) {
		counts[word]++
	})

	if len(counts) == 0 {
		return nil
	}

	// If k is already at least the number of distinct words, sorting all
	// words is simpler and usually faster than maintaining a heap.
	if k >= len(counts) {
		out := make([]WordCount, 0, len(counts))
		for word, count := range counts {
			out = append(out, WordCount{Word: word, Count: count})
		}
		sortWordCounts(out)
		return out
	}

	// Keep a min-heap of the current best k words.
	//
	// The heap root is the "worst" word currently kept: lowest count, and
	// for ties, lexicographically largest word. That lets us replace the
	// root when a better word appears.
	h := make(wordHeap, 0, k)
	for word, count := range counts {
		wc := WordCount{Word: word, Count: count}

		if len(h) < k {
			heap.Push(&h, wc)
			continue
		}

		if better(wc, h[0]) {
			h[0] = wc
			heap.Fix(&h, 0)
		}
	}

	out := make([]WordCount, len(h))
	copy(out, h)
	sortWordCounts(out)
	return out
}

// forEachWord calls fn for each normalized word in text.
//
// It avoids allocating an intermediate []string for large inputs.
func forEachWord(text string, fn func(string)) {
	var b strings.Builder

	for i := 0; i < len(text); {
		r, size := utf8.DecodeRuneInString(text[i:])

		if !isWordRune(r) {
			i += size
			continue
		}

		b.Reset()
		for i < len(text) {
			r, size = utf8.DecodeRuneInString(text[i:])
			if !isWordRune(r) {
				break
			}

			// Unicode lowercasing is locale-independent. For full
			// case-folding, e.g. German ß -> ss, use
			// golang.org/x/text/cases.Fold.
			b.WriteRune(unicode.ToLower(r))
			i += size
		}

		// b.String() returns a string sharing the builder buffer. We call
		// b.Reset() on the next iteration, which drops that buffer, so the
		// string remains valid and does not retain the whole input text.
		fn(b.String())
	}
}

func isWordRune(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r)
}

func sortWordCounts(w []WordCount) {
	sort.Slice(w, func(i, j int) bool {
		if w[i].Count != w[j].Count {
			return w[i].Count > w[j].Count
		}
		return w[i].Word < w[j].Word
	})
}

// better reports whether a should rank before b in the final output:
// higher count first, then lexicographically smaller word.
func better(a, b WordCount) bool {
	if a.Count != b.Count {
		return a.Count > b.Count
	}
	return a.Word < b.Word
}

type wordHeap []WordCount

func (h wordHeap) Len() int { return len(h) }

// Less makes this a min-heap of the "worst" kept word.
// Worst means: lower count first; for equal counts, larger word first.
func (h wordHeap) Less(i, j int) bool {
	if h[i].Count != h[j].Count {
		return h[i].Count < h[j].Count
	}
	return h[i].Word > h[j].Word
}

func (h wordHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *wordHeap) Push(x any) {
	*h = append(*h, x.(WordCount))
}

func (h *wordHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}
```

Example usage:

```go
func main() {
	text := "Go go GO! The quick brown fox jumps over the lazy dog."
	top := TopKWords(text, 3)
	for _, wc := range top {
		fmt.Printf("%s: %d\n", wc.Word, wc.Count)
	}
}
```

Important production notes:

- **Tokenization is opinionated.** This implementation counts only Unicode letters and digits. Apostrophes and hyphens are separators, so `"don't"` becomes `"don"` and `"t"`. If you need contractions or hyphenated words, change `forEachWord` to include `'`, `’`, or `-` only when they appear between word characters.
- **Unicode lowercasing is simple lowercasing.** `unicode.ToLower` is locale-independent and does not do full case folding. For multilingual search-like behavior, consider `golang.org/x/text/cases.Fold`.
- **Deterministic output.** Equal-frequency words are sorted alphabetically, which is important for tests and stable API responses.
- **Memory behavior.** `forEachWord` uses a `strings.Builder` and resets it per word. This avoids storing substrings that point into the original large text, which can otherwise keep the whole input alive.
- **Large streams.** If the text is very large or comes from a network stream, do not read it all into memory. Replace `TopKWords(text string, k int)` with a streaming tokenizer over `io.Reader`, count into a map, and apply the same heap logic.

