package text

import (
    "container/heap"
    "sort"
    "strings"
    "unicode"
    "unicode/utf8"
)

type WordCount struct {
    Word  string
    Count int
}

// TopKWords returns the k most frequent words in text.
// Words are compared case-insensitively after Unicode lowercasing.
// A word is a maximal run of Unicode letters/digits. Apostrophes are not
// included; "don't" becomes "don" and "t". If you need contractions,
// change isWordRune.
//
// The result is sorted by Count descending, then Word ascending, so the
// output is deterministic.
//
// k <= 0 returns nil. If there are fewer than k distinct words, all are
// returned.
func TopKWords(text string, k int) []WordCount {
    if k <= 0 {
        return nil
    }

    counts := make(map[string]int)
    forEachWord(text, func(w string) {
        counts[w]++
    })

    if len(counts) == 0 {
        return nil
    }

    // If k is large relative to unique words, sorting all is simpler and
    // often faster than heap maintenance.
    if k >= len(counts) {
        out := make([]WordCount, 0, len(counts))
        for w, c := range counts {
            out = append(out, WordCount{Word: w, Count: c})
        }
        sortWordCounts(out)
        return out
    }

    // Otherwise keep a min-heap of the current best k.
    h := make(wordHeap, 0, k)
    for w, c := range counts {
        wc := WordCount{Word: w, Count: c}
        if len(h) < k {
            heap.Push(&h, wc)
            continue
        }
        // h[0] is the worst element in the heap (lowest count; for ties,
        // lexicographically largest word). Replace it if wc is better.
        if better(wc, h[0]) {
            h[0] = wc
            heap.Fix(&h, 0)
        }
    }

    out := make([]WordCount, len(h))
    copy(out, h)
    sortWordCounts(out)
    return out
}
```

