# Swift Arithmetic Expression Tokenizer & Evaluator

Here's a complete implementation using the **shunting-yard algorithm** to convert infix tokens to postfix (RPN), then evaluates via a stack.

```swift
import Foundation

// MARK: - Token

enum Token: Equatable, CustomStringConvertible {
    case number(Double)
    case plus, minus, star, slash
    case leftParen, rightParen

    var description: String {
        switch self {
        case .number(let n): return "\(n)"
        case .plus: return "+"
        case .minus: return "-"
        case .star: return "*"
        case .slash: return "/"
        case .leftParen: return "("
        case .rightParen: return ")"
        }
    }
}

enum TokenizerError: Error, CustomStringConvertible {
    case unexpectedCharacter(Character)
    case invalidNumber(String)

    var description: String {
        switch self {
        case .unexpectedCharacter(let c): return "Unexpected character: '\(c)'"
        case .invalidNumber(let s): return "Invalid number: '\(s)'"
        }
    }
}

enum EvaluatorError: Error, CustomStringConvertible {
    case mismatchedParentheses
    case invalidExpression
    case divisionByZero

    var description: String {
        switch self {
        case .mismatchedParentheses: return "Mismatched parentheses"
        case .invalidExpression: return "Invalid expression"
        case .divisionByZero: return "Division by zero"
        }
    }
}

// MARK: - Tokenizer

func tokenize(_ input: String) throws -> [Token] {
    var tokens: [Token] = []
    var numberBuffer = ""
    var index = input.startIndex

    func flushNumber() throws {
        guard !numberBuffer.isEmpty else { return }
        guard let value = Double(numberBuffer) else {
            throw TokenizerError.invalidNumber(numberBuffer)
        }
        tokens.append(.number(value))
        numberBuffer = ""
    }

    while index < input.endIndex {
        let ch = input[index]

        if ch.isWhitespace {
            try flushNumber()
        } else if ch.isNumber || ch == "." {
            numberBuffer.append(ch)
        } else {
            try flushNumber()
            switch ch {
            case "+": tokens.append(.plus)
            case "-": tokens.append(.minus)
            case "*": tokens.append(.star)
            case "/": tokens.append(.slash)
            case "(": tokens.append(.leftParen)
            case ")": tokens.append(.rightParen)
            default: throw TokenizerError.unexpectedCharacter(ch)
            }
        }
        index = input.index(after: index)
    }
    try flushNumber()
    return tokens
}

// MARK: - Precedence & Associativity

private func precedence(of token: Token) -> Int {
    switch token {
    case .plus, .minus: return 1
    case .star, .slash: return 2
    default: return 0
    }
}

// MARK: - Evaluator (shunting-yard + RPN)

func evaluate(_ expression: String) throws -> Double {
    let tokens = try tokenize(expression)

    var output: [Token] = []
    var operators: [Token] = []

    for token in tokens {
        switch token {
        case .number:
            output.append(token)

        case .plus, .minus, .star, .slash:
            while let top = operators.last,
                  top != .leftParen,
                  precedence(of: top) >= precedence(of: token) {
                output.append(operators.removeLast())
            }
            operators.append(token)

        case .leftParen:
            operators.append(token)

        case .rightParen:
            var foundLeft = false
            while let top = operators.last {
                if top == .leftParen {
                    operators.removeLast()
                    foundLeft = true
                    break
                }
                output.append(operators.removeLast())
            }
            if !foundLeft { throw EvaluatorError.mismatchedParentheses }
        }
    }

    while let top = operators.last {
        if top == .leftParen { throw EvaluatorError.mismatchedParentheses }
        output.append(operators.removeLast())
    }

    // Evaluate RPN
    var stack: [Double] = []
    for token in output {
        switch token {
        case .number(let n):
            stack.append(n)
        case .plus, .minus, .star, .slash:
            guard stack.count >= 2 else { throw EvaluatorError.invalidExpression }
            let rhs = stack.removeLast()
            let lhs = stack.removeLast()
            let result: Double
            switch token {
            case .plus:  result = lhs + rhs
            case .minus: result = lhs - rhs
            case .star:  result = lhs * rhs
            case .slash:
                if rhs == 0 { throw EvaluatorError.divisionByZero }
                result = lhs / rhs
            default: fatalError()
            }
            stack.append(result)
        default:
            throw EvaluatorError.invalidExpression
        }
    }

    guard stack.count == 1 else { throw EvaluatorError.invalidExpression }
    return stack[0]
}
```

## Usage Example

```swift
do {
    print(try evaluate("2 + 3 * 4"))            // 14.0
    print(try evaluate("(2 + 3) * 4"))          // 20.0
    print(try evaluate("10 / 2 - 3"))           // 2.0
    print(try evaluate("2 * (3 + 4) - 10 / 5")) // 12.0
    print(try evaluate("1.5 + 2.25 * 4"))       // 10.5

    // Token inspection
    print(try tokenize("2 + (3 * 4)"))
    // [2.0, +, (, 3.0, *, 4.0, )]
} catch {
    print("Error: \(error)")
}
```

## How It Works

1. **Tokenizer** — scans the string, grouping digits/dots into `Double` numbers and mapping operators to enum cases. Whitespace is ignored.
2. **Shunting-yard** — converts the infix token list into postfix (Reverse Polish Notation). It uses a stack of operators, pop-and-emit whenever the incoming operator has **lower or equal precedence** than the top of the stack (this gives left-associative behavior for `+ - * /`, matching typical math convention).
3. **RPN evaluation** — single linear pass with a value stack; each operator pops two operands and pushes the result.

Parentheses are handled by treating `(` as a barrier in the operator stack and popping back to it on `)`. Errors are surfaced for mismatched parens, division by zero, and malformed input.

# Minimal JSON Pretty-Printer in Kotlin

```kotlin
fun prettyJson(input: String, indent: String = "  "): String {
    val sb = StringBuilder()
    var level = 0
    var inString = false
    var escape = false

    for (c in input) {
        when {
            escape -> { sb.append(c); escape = false }
            c == '\\' && inString -> { sb.append(c); escape = true }
            c == '"' -> { sb.append(c); inString = !inString }
            inString -> sb.append(c)
            c == '{' || c == '[' -> {
                sb.append(c).append('\n')
                level++
                repeat(level) { sb.append(indent) }
            }
            c == '}' || c == ']' -> {
                sb.append('\n')
                level--
                repeat(level) { sb.append(indent) }
                sb.append(c)
            }
            c == ',' -> {
                sb.append(c).append('\n')
                repeat(level) { sb.append(indent) }
            }
            c == ':' -> sb.append(": ")
            c == ' ' || c == '\n' || c == '\r' || c == '\t' -> {}
            else -> sb.append(c)
        }
    }
    return sb.toString()
}
```

It's a single-pass character scan with a small state machine (in-string flag + escape flag) that re-indents based on brace depth. No parser, no validation, no dependency.

## Two Ways It Fails Under Load

**1. Memory blowup via intermediate `StringBuilder`**
Every call allocates a new `StringBuilder` (default 16 chars) and grows it via doubling. For a 100 MB JSON input, the internal `char[]` momentarily needs ~200 MB during a resize, plus the final `String` copy adds another ~200 MB — roughly 3–4× the input size in peak working memory. Under concurrent requests (say 20 in flight), this easily triggers OOM on a JVM with a modest heap, since none of it is streamed and nothing is capped.

**2. Unbounded recursion-free but stack-free… wrong axis: quadratic string concat in logs, and CPU flip-flop on pathological input**
The loop itself is O(n), but note the `repeat(level)` inside the loop. On deeply nested input (`[[[[[...]]]]]`) that's legal JSON, each opening/closing bracket re-emits `level × indent` characters. A 1 KB input that nests 500 deep produces gigabytes of output and O(n²) time. There's no depth cap, no output-size cap, and no way for the caller to abort mid-way — so a single malicious or malformed payload (e.g., from an upstream service) can pin a core and balloon memory with trivially small input.

A secondary failure mode in the same vein: the scanner never validates. A 10 GB stream of `{` will be accepted and expanded into ~10 GB × indent output without ever rejecting.

**Mitigations:** stream to a `Writer`/`OutputStream` with a bounded buffer, add a max-depth and max-output-size limit, and swap the `repeat(level)` indent emission for a pre-built indent string sliced by depth (`indents[level]`) to kill the per-bracket allocation.

```cpp
// Minimal device-side retry wrapper: exponential backoff + jitter.
// Requires compute capability >= 7.0 for __nanosleep; otherwise use a busy loop.
#pragma once
#include <cuda_runtime.h>

__device__ __forceinline__ unsigned int xorshift(unsigned int& s) {
    s ^= s << 13;
    s ^= s >> 17;
    s ^= s << 5;
    return s;
}

template <typename F>
__device__ bool retry_with_backoff(F&& op, int max_attempts = 16) {
    // Per-thread seed so threads don't retry in lockstep.
    unsigned int seed = threadIdx.x * 1664525u
                      + blockIdx.x  * 1013904223u
                      + 12345u;

    for (int attempt = 0; attempt < max_attempts; ++attempt) {
        if (op()) return true;

        int shift = attempt < 10 ? attempt : 10;
        unsigned int base = 1u << shift;              // 1..1024 ns
        unsigned int jitter = xorshift(seed) % (base + 1);
        __nanosleep(base + jitter);
    }
    return false;
}
```

Example use for a simple device lock:

```cpp
__device__ int lock = 0;

__global__ void kernel() {
    auto try_lock = [] __device__ () {
        return atomicCAS(&lock, 0, 1) == 0;
    };

    if (!retry_with_backoff(try_lock)) {
        // handle failure
    }

    // critical section
    __threadfence();
    atomicExch(&lock, 0);
}
```

Two ways it can fail under load:

1. **Thundering herd / lockstep retries**  
   If the jitter is too small, poorly seeded, or correlated across threads, many threads wake and retry the same contended resource at nearly the same time. Under heavy load this causes repeated collisions, wasted cycles, and can effectively livelock even though each thread is backing off.

2. **Starvation / retry exhaustion**  
   With a bounded `max_attempts`, heavily contended threads may exhaust all retries and give up, causing incorrect results or deadlock if they hold resources. With unbounded retries, some threads can starve indefinitely, and `__nanosleep` being a hint means sleeping threads still occupy SM slots, reducing occupancy and worsening contention.

