```typescript
class TrieNode {
  children: Map<string, TrieNode> = new Map();
  // Number of words that pass through this node (including ending here)
  prefixCount: number = 0;
  // Number of words that end exactly at this node
  wordCount: number = 0;
}

class Trie {
  private root: TrieNode = new TrieNode();

  /** Insert a word into the trie. */
  insert(word: string): void {
    let node = this.root;
    node.prefixCount++;
    for (const ch of word) {
      let next = node.children.get(ch);
      if (!next) {
        next = new TrieNode();
        node.children.set(ch, next);
      }
      node = next;
      node.prefixCount++;
    }
    node.wordCount++;
  }

  /** Returns true if the exact word exists in the trie. */
  search(word: string): boolean {
    const node = this.traverse(word);
    return node !== null && node.wordCount > 0;
  }

  /** Returns the number of words that start with the given prefix. */
  prefixCount(prefix: string): number {
    const node = this.traverse(prefix);
    return node ? node.prefixCount : 0;
  }

  /** Returns true if any word in the trie starts with the given prefix. */
  startsWith(prefix: string): boolean {
    return this.traverse(prefix) !== null;
  }

  private traverse(s: string): TrieNode | null {
    let node = this.root;
    for (const ch of s) {
      const next = node.children.get(ch);
      if (!next) return null;
      node = next;
    }
    return node;
  }
}

// --- Usage example ---
const trie = new Trie();
trie.insert('apple');
trie.insert('app');
trie.insert('apply');
trie.insert('banana');

console.log(trie.search('app'));        // true
console.log(trie.search('appl'));       // false
console.log(trie.search('apple'));      // true

console.log(trie.prefixCount('app'));   // 3  -> app, apple, apply
console.log(trie.prefixCount('appl'));  // 2  -> apple, apply
console.log(trie.prefixCount('ban'));   // 1  -> banana
console.log(trie.prefixCount('cat'));   // 0

console.log(trie.startsWith('ban'));    // true
console.log(trie.startsWith('xyz'));    // false

// Duplicate insert: wordCount increments, so search still true
trie.insert('app');
console.log(trie.search('app'));        // true
console.log(trie.prefixCount('app'));   // 4
```

**How it works**

- Each `TrieNode` keeps a map of child characters, a `prefixCount` (how many inserted words pass through this node), and a `wordCount` (how many words end here).
- `insert` walks the word character by character, creating nodes as needed, incrementing `prefixCount` along the path and `wordCount` at the terminal node.
- `search` walks the word and returns `true` only if the terminal node has `wordCount > 0` (so `"app"` is a word but `"appl"` is only a prefix).
- `prefixCount` walks the prefix and returns the node's `prefixCount` — this is O(len(prefix)) and is what makes tries efficient for autocomplete-style queries.

Complexity for all operations is **O(k)** where `k` is the length of the input string.

# Topological Sort with Cycle Detection in C

## Overview

Topological sort orders the vertices of a **Directed Acyclic Graph (DAG)** such that for every edge `u → v`, `u` appears before `v`. If the graph contains a cycle, no such ordering exists, so we must detect and report it.

There are two common approaches:
1. **Kahn's Algorithm** (BFS-based, uses in-degrees)
2. **DFS-based** (uses recursion stack)

I'll present **Kahn's algorithm** because cycle detection falls out naturally: if we process fewer than `V` vertices, a cycle exists.

---

## Implementation

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int V;              // number of vertices
    int *adj;           // flattened adjacency list (size V*V worst case)
    int *adjSize;       // current size per vertex
    int *adjCap;        // capacity per vertex
} Graph;

Graph *graph_create(int V) {
    Graph *g = malloc(sizeof(Graph));
    g->V = V;
    g->adj = malloc(sizeof(int) * V * V);   // simple fixed capacity
    g->adjSize = calloc(V, sizeof(int));
    g->adjCap = malloc(sizeof(int) * V);
    for (int i = 0; i < V; i++) g->adjCap[i] = V;
    return g;
}

void graph_free(Graph *g) {
    free(g->adj);
    free(g->adjSize);
    free(g->adjCap);
    free(g);
}

void add_edge(Graph *g, int u, int v) {
    int base = u * g->V;
    if (g->adjSize[u] >= g->adjCap[u]) return;   // capacity guard
    g->adj[base + g->adjSize[u]++] = v;
}

/* Returns 1 on success (fills *order), 0 if a cycle exists. */
int topological_sort(Graph *g, int *order) {
    int V = g->V;
    int *indegree = calloc(V, sizeof(int));
    int *queue = malloc(sizeof(int) * V);
    int front = 0, back = 0;

    /* Compute in-degrees */
    for (int u = 0; u < V; u++) {
        int base = u * V;
        for (int i = 0; i < g->adjSize[u]; i++) {
            int v = g->adj[base + i];
            indegree[v]++;
        }
    }

    /* Seed the queue with all sources (in-degree 0) */
    for (int v = 0; v < V; v++)
        if (indegree[v] == 0) queue[back++] = v;

    int idx = 0;
    while (front < back) {
        int u = queue[front++];
        order[idx++] = u;

        int base = u * V;
        for (int i = 0; i < g->adjSize[u]; i++) {
            int v = g->adj[base + i];
            if (--indegree[v] == 0) queue[back++] = v;
        }
    }

    free(indegree);
    free(queue);

    if (idx != V) {
        fprintf(stderr, "Error: graph contains a cycle.\n");
        return 0;   // cycle detected
    }
    return 1;       // success
}

int main(void) {
    /* Example 1: valid DAG */
    Graph *g = graph_create(6);
    add_edge(g, 5, 2);
    add_edge(g, 5, 0);
    add_edge(g, 4, 0);
    add_edge(g, 4, 1);
    add_edge(g, 2, 3);
    add_edge(g, 3, 1);

    int *order = malloc(sizeof(int) * 6);
    if (topological_sort(g, order)) {
        printf("Topological order: ");
        for (int i = 0; i < 6; i++) printf("%d ", order[i]);
        printf("\n");
    }
    free(order);
    graph_free(g);

    /* Example 2: cyclic graph */
    Graph *h = graph_create(3);
    add_edge(h, 0, 1);
    add_edge(h, 1, 2);
    add_edge(h, 2, 0);

    int *order2 = malloc(sizeof(int) * 3);
    if (!topological_sort(h, order2))
        printf("Cycle correctly detected.\n");
    free(order2);
    graph_free(h);

    return 0;
}
```

**Sample output:**
```
Topological order: 4 5 2 3 1 0
Cycle correctly detected.
```

---

## Why cycle detection works

In Kahn's algorithm we repeatedly remove vertices that currently have **in-degree 0**. Every time we finish a vertex, we decrement the in-degrees of its neighbors. 

- If the graph is a DAG, every vertex eventually becomes a source, so all `V` vertices get emitted.
- If a cycle exists, the vertices on the cycle (and anything that depends only on them) never reach in-degree 0, so fewer than `V` vertices are emitted.

That's why checking `idx != V` after the loop is a correct cycle test.

---

## Time Complexity

Let `V = |vertices|` and `E = |edges|`.

| Step | Cost |
|------|------|
| Compute in-degrees | `O(V + E)` |
| Initialize queue | `O(V)` |
| Process each vertex once | `O(V)` |
| Decrement in-degree across all edges | `O(E)` |
| **Total** | **`O(V + E)`** |

The algorithm is **linear** in the size of the graph. Each vertex enters the queue at most once, and each edge is examined exactly once.

---

## Space Complexity

| Structure | Size |
|-----------|------|
| `indegree` array | `O(V)` |
| `queue` array | `O(V)` |
| Output `order` | `O(V)` |
| Graph storage | `O(V + E)` (adjacency list) |

**Auxiliary space** (excluding the graph itself): **`O(V)`**.

**Total space** including the graph: **`O(V + E)`**.

> Note: the sample code uses a fixed `V×V` adjacency matrix-style allocation for simplicity. A production version would use one array of size `E` plus per-vertex offset arrays (`CSR` format) or linked lists, giving true `O(V + E)` storage.

---

## Comparison with DFS Approach

The DFS-based Kahn alternative marks vertices with three colors:
- **White**: unvisited
- **Gray**: on the current recursion stack
- **Black**: fully processed

Encountering a **gray** vertex means a back edge exists → cycle. The DFS version is also `O(V + E)` time and `O(V)` auxiliary space, but Kahn's is usually preferred because:

- It avoids recursion (no stack overflow on deep graphs).
- The queue gives you a ready-made topological order as you go.
- Cycle detection is just a count check — no color bookkeeping needed.

# LRU Cache in Swift

An LRU (Least Recently Used) cache needs to support two operations in **O(1)** time:
- `get(key)`: return the value if present, otherwise `-1`
- `put(key, value)`: insert or update; evict the least recently used entry if capacity is exceeded

To achieve O(1) for both, we combine:
1. A **hash map** for O(1) key lookup
2. A **doubly linked list** to maintain recency order and allow O(1) removal/insertion at any node

## Implementation

```swift
final class LRUCache<Key: Hashable, Value> {

    // MARK: - Node
    private final class Node {
        let key: Key
        var value: Value
        var prev: Node?
        var next: Node?

        init(key: Key, value: Value) {
            self.key = key
            self.value = value
        }
    }

    // MARK: - Storage
    private let capacity: Int
    private var map: [Key: Node] = [:]

    // Dummy head/tail to avoid nil checks at the boundaries.
    // head.next is the most recently used; tail.prev is the least recently used.
    private let head = Node(key: .init(), value: .init()) // placeholder
    private let tail = Node(key: .init(), value: .init())

    // MARK: - Init
    init(capacity: Int) {
        precondition(capacity > 0, "Capacity must be positive")
        self.capacity = capacity
        head.next = tail
        tail.prev = head
    }

    // MARK: - Public API
    func get(_ key: Key) -> Value? {
        guard let node = map[key] else { return nil }
        moveToFront(node)
        return node.value
    }

    func put(_ key: Key, _ value: Value) {
        if let node = map[key] {
            node.value = value
            moveToFront(node)
            return
        }

        // Evict if full
        if map.count == capacity {
            if let lru = tail.prev, lru !== head {
                remove(lru)
                map.removeValue(forKey: lru.key)
            }
        }

        let node = Node(key: key, value: value)
        map[key] = node
        addToFront(node)
    }

    // MARK: - Linked list helpers
    private func addToFront(_ node: Node) {
        node.prev = head
        node.next = head.next
        head.next?.prev = node
        head.next = node
    }

    private func remove(_ node: Node) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
        node.prev = nil
        node.next = nil
    }

    private func moveToFront(_ node: Node) {
        remove(node)
        addToFront(node)
    }
}
```

> ⚠️ The `Node(key: .init(), value: .init())` sentinel trick only compiles if `Key` and `Value` have default initializers. A cleaner approach is to make `key` and `value` optional, or use a dedicated `Sentinel` type. Here's a safe version of just the head/tail:

```swift
private let head = Node(key: nil, value: nil)
private let tail = Node(key: nil, value: nil)

private final class Node {
    var key: Key?
    var value: Value?
    var prev: Node?
    var next: Node?
}
```

### Example Usage

```swift
let cache = LRUCache<Int, String>(capacity: 2)
cache.put(1, "one")
cache.put(2, "two")
print(cache.get(1) ?? "nil")  // "one"  → 1 becomes most-recently used
cache.put(3, "three")         // evicts key 2 (LRU)
print(cache.get(2) ?? "nil")  // nil
cache.put(4, "four")          // evicts key 1
print(cache.get(1) ?? "nil")  // nil
print(cache.get(3) ?? "nil")  // "three"
print(cache.get(4) ?? "nil")  // "four"
```

## Why This Works

- **Hash map** gives O(1) lookup: `map[key] → Node`
- **Doubly linked list** gives O(1) splice: reordering a node only requires updating a constant number of `prev`/`next` pointers
- **Sentinel head/tail** eliminate all boundary special cases (empty list, first insert, last removal)
- The list is ordered **MRU (front) → LRU (back)**. Eviction always removes `tail.prev`.

## Complexity Analysis

Let **n** = number of entries, **c** = capacity.

### Time

| Operation | Complexity | Reason |
|---|---|---|
| `get(key)` | **O(1)** avg | Hash lookup + 4 pointer writes to move to front |
| `put(key, value)` | **O(1)** avg | Hash lookup + optional O(1) evict + O(1) insert |
| Eviction | **O(1)** | Remove `tail.prev` node and delete its map entry |

The "avg" caveat comes from Swift's `Dictionary`, which is a hash table with amortized O(1) operations. Worst-case it can degrade to O(n) under adversarial hash collisions — same as any hash-based LRU. If you need strict worst-case O(1), you'd use a different structure (e.g., a balanced tree, which gives O(log n)).

### Space

- **O(c)** total — bounded by capacity
  - `map`: c entries, each holding a `Key` and a reference to a `Node`
  - Linked list: c `Node` objects plus 2 sentinels
  - Each `Node` stores `key`, `value`, `prev`, `next` → constant overhead per entry

So space is proportional to the cache capacity, not the number of operations performed.

