```c
#include <stdlib.h>

/*
 * Kahn's algorithm.
 * Returns:
 *   1  = success, order[] filled with a topological order
 *   0  = graph has a cycle
 *  -1  = allocation/input error
 */
int topo_sort(int n, int m,
              const int *from, const int *to,
              int *order)
{
    int *indeg = NULL, *head = NULL, *next = NULL, *dest = NULL, *q = NULL;
    int rc = -1;

    if (n < 0 || m < 0) return -1;

    indeg = calloc((size_t)n, sizeof *indeg);
    head  = malloc((size_t)n * sizeof *head);
    next  = malloc((size_t)m * sizeof *next);
    dest  = malloc((size_t)m * sizeof *dest);
    q     = malloc((size_t)n * sizeof *q);

    if ((n && !indeg) || (n && !head) ||
        (m && !next)  || (m && !dest) ||
        (n && !q))
        goto done;

    for (int i = 0; i < n; ++i)
        head[i] = -1;

    for (int i = 0; i < m; ++i) {
        int u = from[i], v = to[i];

        if (u < 0 || u >= n || v < 0 || v >= n)
            goto done;

        dest[i] = v;
        next[i] = head[u];
        head[u] = i;
        ++indeg[v];
    }

    int qh = 0, qt = 0;

    for (int i = 0; i < n; ++i)
        if (indeg[i] == 0)
            q[qt++] = i;

    int cnt = 0;

    while (qh < qt) {
        int u = q[qh++];
        order[cnt++] = u;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = dest[e];

            if (--indeg[v] == 0)
                q[qt++] = v;
        }
    }

    rc = (cnt == n) ? 1 : 0;

done:
    free(q);
    free(dest);
    free(next);
    free(head);
    free(indeg);
    return rc;
}
```

