    int r = topo_sort(4, 4, from, to, order);

    if (r == 1) {
        for (int i = 0; i < 4; ++i)
            printf("%d ", order[i]);
        putchar('\n');
    } else if (r == 0) {
        puts("cycle detected");
    } else {
