const ROMAN_NUMERALS: &[(u32, &str)] = &[
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
];

/// Converts a Roman numeral to an integer.
///
/// Only canonical Roman numerals in the range 1..=3999 are accepted.
pub fn roman_to_int(s: &str) -> Result<u32, String> {
    let s = s.trim().to_uppercase();

    if s.is_empty() {
        return Err("empty Roman numeral".to_string());
    }

    let mut total = 0i32;
    let mut prev = 0i32;

    for c in s.chars().rev() {
        let value = match c {
            'I' => 1,
            'V' => 5,
            'X' => 10,
            'L' => 50,
            'C' => 100,
            'D' => 500,
            'M' => 1000,
            _ => return Err(format!("invalid Roman numeral character: {c}")),
        };

        if value < prev {
            total -= value;
        } else {
            total += value;
            prev = value;
        }
    }

    if total <= 0 || total > 3999 {
        return Err(format!("Roman numeral out of range: {total}"));
    }

    let total = total as u32;

    // Ensures the input is a canonical Roman numeral, e.g. rejects "IIII" and "IC".
    let canonical = int_to_roman(total)?;
    if canonical != s {
        return Err(format!("non-canonical Roman numeral: {s}"));
    }

    Ok(total)
}

/// Converts an integer to a Roman numeral.
///
/// Supports only values in the range 1..=3999.
pub fn int_to_roman(mut n: u32) -> Result<String, String> {
    if n == 0 || n > 3999 {
        return Err(format!("number out of range: {n}"));
    }

    let mut result = String::new();

    for &(value, numeral) in ROMAN_NUMERALS {
        while n >= value {
            n -= value;
            result.push_str(numeral);
        }
    }

    Ok(result)
}

