#include <algorithm>
#include <cassert>
#include <functional>
#include <iostream>
#include <vector>

// Returns one directed cycle if one exists.
// The returned vector contains the vertices of the cycle in order:
// cycle[0] -> cycle[1] -> ... -> cycle[n-1] -> cycle[0].
// If no cycle exists, returns an empty vector.
//
// Self-loop case: returns {u} for u -> u.
std::vector<int> findCycle(const std::vector<std::vector<int>>& graph) {
    const int n = static_cast<int>(graph.size());

    // 0 = unvisited, 1 = visiting/on current DFS stack, 2 = fully processed
    std::vector<int> state(n, 0);
    std::vector<int> parent(n, -1);
    std::vector<int> cycle;

    std::function<bool(int)> dfs = [&](int u) -> bool {
        state[u] = 1;

        for (int v : graph[u]) {
            if (state[v] == 0) {
                parent[v] = u;
                if (dfs(v)) {
                    return true;
                }
            } else if (state[v] == 1) {
                // Found a back edge u -> v, where v is an ancestor of u.
                // Reconstruct: v -> ... -> u -> v
                std::vector<int> path;
                for (int x = u; x != v; x = parent[x]) {
                    path.push_back(x);
                }
                path.push_back(v);
                std::reverse(path.begin(), path.end());
                cycle = std::move(path);
                return true;
            }
        }

        state[u] = 2;
        return false;
    };

    for (int i = 0; i < n; ++i) {
        if (state[i] == 0) {
            if (dfs(i)) {
                return cycle;
            }
        }
    }

    return {};
}

// -----------------------------------------------------------------------------
// Unit tests
// -----------------------------------------------------------------------------

namespace {

bool hasEdge(const std::vector<std::vector<int>>& graph, int u, int v) {
    return std::find(graph[u].begin(), graph[u].end(), v) != graph[u].end();
}

void assertValidCycleOrEmpty(const std::vector<std::vector<int>>& graph,
                             bool expectCycle) {
    const std::vector<int> cycle = findCycle(graph);

    if (!expectCycle) {
        assert(cycle.empty());
        return;
    }

    assert(!cycle.empty());

    if (cycle.size() == 1) {
        // A one-vertex cycle must be a self-loop.
        assert(hasEdge(graph, cycle[0], cycle[0]));
        return;
    }

    for (std::size_t i = 0; i < cycle.size(); ++i) {
        const int from = cycle[i];
        const int to = cycle[(i + 1) % cycle.size()];
        assert(hasEdge(graph, from, to));
    }
}

void testEmptyGraph() {
    const std::vector<std::vector<int>> graph;
    assert(findCycle(graph).empty());
}

void testSingleVertexNoEdges() {
    const std::vector<std::vector<int>> graph = {{}};
    assert(findCycle(graph).empty());
}

void testSingleVertexSelfLoop() {
    const std::vector<std::vector<int>> graph = {{0}};
    const std::vector<int> cycle = findCycle(graph);
    assert((cycle == std::vector<int>{0}));
}

void testDag() {
    const std::vector<std::vector<int>> graph = {
        {1, 2},
        {2},
        {}
    };
    assert(findCycle(graph).empty());
}

void testSimpleCycle() {
    const std::vector<std::vector<int>> graph = {
        {1},
        {2},
        {0}
    };
    const std::vector<int> cycle = findCycle(graph);
    assert((cycle == std::vector<int>{0, 1, 2}));
}

void testCycleNotIncludingRoot() {
    const std::vector<std::vector<int>> graph = {
        {1},
        {2},
        {1}
    };
    const std::vector<int> cycle = findCycle(graph);
    assert((cycle == std::vector<int>{1, 2}));
}

void testDisconnectedCycle() {
    const std::vector<std::vector<int>> graph = {
        {1},
        {},
        {3},
        {2}
    };
    const std::vector<int> cycle = findCycle(graph);
    assert((cycle == std::vector<int>{2, 3}));
}

void testSelfLoopInLargerGraph() {
    const std::vector<std::vector<int>> graph = {
        {1},
        {1},
        {}
    };
    const std::vector<int> cycle = findCycle(graph);
    assert((cycle == std::vector<int>{1}));
}

void testCrossEdgeToFinishedVertexIsNotCycle() {
    const std::vector<std::vector<int>> graph = {
        {1, 2},
        {2},
        {}
    };
    assert(findCycle(graph).empty());
}

void testComplexAcyclicGraph() {
    const std::vector<std::vector<int>> graph = {
        {1, 2, 3},
        {4},
        {4},
        {5},
        {},
        {}
    };
    assert(findCycle(graph).empty());
