std::vector<int> findCycle(const std::vector<std::vector<int>>& graph) {
    int n = static_cast<int>(graph.size());
    std::vector<int> state(n, 0); // 0 unvisited, 1 visiting, 2 done
    std::vector<int> parent(n, -1);
    std::vector<int> cycle;

    std::function<bool(int)> dfs = [&](int u) -> bool {
        state[u] = 1;
        for (int v : graph[u]) {
            if (state[v] == 0) {
                parent[v] = u;
                if (dfs(v)) return true;
            } else if (state[v] == 1) {
                // back edge u -> v
                std::vector<int> path;
                for (int x = u; x != v; x = parent[x]) {
                    path.push_back(x);
                }
                path.push_back(v);
                std::reverse(path.begin(), path.end());
                cycle = std::move(path);
                return true;
            }
        }
        state[u] = 2;
        return false;
    };

    for (int i = 0; i < n; ++i) {
        if (state[i] == 0) {
            if (dfs(i)) return cycle;
        }
    }
    return {};
}

