```c
#include <omp.h>
#include <stdlib.h>

/* Inclusive parallel prefix sum over a[0..n-1] */
void parallel_scan(long long *a, int n) {
    if (n <= 0) return;

    int maxth = omp_get_max_threads();
    long long *block = malloc((size_t)maxth * sizeof *block);
    if (!block) abort();

    #pragma omp parallel shared(a, n, block)
    {
        int tid = omp_get_thread_num();
        int nt  = omp_get_num_threads();

        int chunk = (n + nt - 1) / nt;
        int start = tid * chunk;
        int end   = start + chunk;

        if (start > n) start = n;
        if (end   > n) end   = n;

        /* Local sequential scan */
        long long sum = 0;
        for (int i = start; i < end; ++i) {
            sum += a[i];
            a[i] = sum;
        }

        block[tid] = (start < end) ? a[end - 1] : 0;

        #pragma omp barrier

        /* Exclusive scan of per-block sums */
        #pragma omp single
        {
            long long running = 0;
            for (int i = 0; i < nt; ++i) {
                long long v = block[i];
                block[i] = running;
                running += v;
            }
        } /* implicit barrier */

        /* Add block offset */
        long long off = block[tid];
        for (int i = start; i < end; ++i) {
            a[i] += off;
        }
    }

    free(block);
}
