// JsonPrettyPrinter.kt
fun prettyPrintJson(json: String, indentSize: Int = 2): String {
    require(indentSize >= 0) { "indentSize must be >= 0" }

    val out = StringBuilder()
    var level = 0
    var inString = false
    var escaped = false

    fun appendIndent() {
        repeat(level * indentSize) { out.append(' ') }
    }

    fun nextNonWhitespace(start: Int): Char? {
        var i = start
        while (i < json.length) {
            if (!json[i].isWhitespace()) return json[i]
            i++
        }
        return null
    }

    var i = 0
    while (i < json.length) {
        val c = json[i]

        if (inString) {
            out.append(c)
            when {
                escaped -> escaped = false
                c == '\\' -> escaped = true
                c == '"' -> inString = false
            }
            i++
            continue
        }

        when (c) {
            '"' -> {
                out.append(c)
                inString = true
            }

            '{', '[' -> {
                out.append(c)
                level++

                val matchingClose = if (c == '{') '}' else ']'
                if (nextNonWhitespace(i + 1) != matchingClose) {
                    out.append('\n')
                    appendIndent()
                }
            }

            '}', ']' -> {
                level--
                val matchingOpen = if (c == '}') '{' else '['

                if (out.isNotEmpty() && out.last() == matchingOpen) {
                    out.append(c)
                } else {
                    out.append('\n')
                    appendIndent()
                    out.append(c)
                }
            }

            ',' -> {
                out.append(',')
                out.append('\n')
                appendIndent()
            }

            ':' -> {
                out.append(": ")
            }

            else -> {
                if (!c.isWhitespace()) {
                    out.append(c)
                }
            }
        }

        i++
    }

    return out.toString()
}
```

