        assertEquals("123", prettyPrintJson("123"))
        assertEquals("true", prettyPrintJson("true"))
        assertEquals("null", prettyPrintJson("null"))
        assertEquals("\"hello\"", prettyPrintJson("\"hello\""))
    }

    @Test
    fun customIndentSize() {
        assertEquals(
            """
            {
                "a": [
                    1
                ]
            }
            """.trimIndent(),
            prettyPrintJson("""{"a":[1]}""", indentSize = 4)
        )
    }

