// test_blocking_queue.cpp
#include "blocking_queue.hpp"

#include <atomic>
#include <cassert>
#include <chrono>
#include <future>
#include <iostream>
#include <thread>
#include <vector>

using namespace std::chrono_literals;

#define CHECK(expr)                                                         \
    do {                                                                    \
        if (!(expr)) {                                                      \
