                      << ":" << __LINE__ << '\n';                           \
            std::abort();                                                   \
        }                                                                   \
    } while (false)

static void test_capacity_zero_throws() {
    bool threw = false;

    try {
        BlockingQueue<int> q(0);
        (void)q;
    } catch (const std::invalid_argument&) {
        threw = true;
    }

    CHECK(threw);
}

static void test_basic_fifo_and_close() {
    BlockingQueue<int> q(3);

    CHECK(q.put(1));
    CHECK(q.put(2));
    CHECK(q.put(3));

    auto v1 = q.get();
    auto v2 = q.get();
    auto v3 = q.get();

    CHECK(v1.has_value());
    CHECK(v2.has_value());
    CHECK(v3.has_value());
    CHECK(*v1 == 1);
    CHECK(*v2 == 2);
    CHECK(*v3 == 3);

    q.close();

    auto v4 = q.get();
    CHECK(!v4.has_value());

    CHECK(!q.put(4));
}

static void test_put_blocks_when_full() {
    BlockingQueue<int> q(1);

    CHECK(q.put(1));

    auto future = std::async(std::launch::async, [&] {
        return q.put(2);
    });

    CHECK(future.wait_for(50ms) == std::future_status::timeout);

    auto v1 = q.get();
    CHECK(v1.has_value());
    CHECK(*v1 == 1);

    CHECK(future.wait_for(1s) == std::future_status::ready);
    CHECK(future.get() == true);

    auto v2 = q.get();
    CHECK(v2.has_value());
    CHECK(*v2 == 2);

    q.close();
}

static void test_get_blocks_when_empty() {
    BlockingQueue<int> q(1);

    auto future = std::async(std::launch::async, [&] {
        return q.get();
    });

    CHECK(future.wait_for(50ms) == std::future_status::timeout);

    CHECK(q.put(42));

    auto v = future.get();
    CHECK(v.has_value());
    CHECK(*v == 42);

    q.close();
}

static void test_close_unblocks_waiting_get() {
    BlockingQueue<int> q(1);

    auto future = std::async(std::launch::async, [&] {
        return q.get();
    });

    std::this_thread::sleep_for(50ms);
    q.close();

    auto v = future.get();
    CHECK(!v.has_value());
}

static void test_close_unblocks_waiting_put() {
    BlockingQueue<int> q(1);

    CHECK(q.put(1));

    auto future = std::async(std::launch::async, [&] {
        return q.put(2);
    });

    std::this_thread::sleep_for(50ms);
    q.close();

    CHECK(future.get() == false);

    // close() does not discard already queued items.
    auto v1 = q.get();
    CHECK(v1.has_value());
    CHECK(*v1 == 1);

    auto v2 = q.get();
    CHECK(!v2.has_value());
}

static void test_fifo_with_one_producer_and_one_consumer() {
    constexpr int total = 1000;

    BlockingQueue<int> q(10);

    std::thread producer([&] {
        for (int i = 0; i < total; ++i) {
            CHECK(q.put(i));
        }
        q.close();
    });

    std::thread consumer([&] {
        for (int i = 0; i < total; ++i) {
            auto v = q.get();
            CHECK(v.has_value());
            CHECK(*v == i);
        }

        auto end = q.get();
        CHECK(!end.has_value());
    });

    producer.join();
    consumer.join();
}

static void test_multiple_producers_and_consumers() {
    constexpr int producers = 4;
    constexpr int consumers = 4;
    constexpr int per_producer = 250;
    constexpr int total = producers * per_producer;

    BlockingQueue<int> q(16);

    std::atomic<int> sum{0};
    std::atomic<int> count{0};

    std::vector<std::thread> producer_threads;
    std::vector<std::thread> consumer_threads;

    for (int p = 0; p < producers; ++p) {
        producer_threads.emplace_back([&, p] {
            for (int i = 0; i < per_producer; ++i) {
                const int value = p * per_producer + i;
                CHECK(q.put(value));
            }
        });
    }

    for (int c = 0; c < consumers; ++c) {
        consumer_threads.emplace_back([&] {
            while (true) {
                auto v = q.get();
                if (!v.has_value()) {
                    break;
                }

                sum.fetch_add(*v, std::memory_order_relaxed);
                count.fetch_add(1, std::memory_order_relaxed);
            }
        });
    }

    for (auto& t : producer_threads) {
        t.join();
    }

    while (count.load(std::memory_order_acquire) < total) {
        std::this_thread::yield();
    }

    q.close();

    for (auto& t : consumer_threads) {
        t.join();
    }

    CHECK(count.load() == total);
    CHECK(sum.load() == total * (total - 1) / 2);
}

int main() {
    test_capacity_zero_throws();
    test_basic_fifo_and_close();
    test_put_blocks_when_full();
    test_get_blocks_when_empty();
    test_close_unblocks_waiting_get();
    test_close_unblocks_waiting_put();
    test_fifo_with_one_producer_and_one_consumer();
    test_multiple_producers_and_consumers();

    std::cout << "All BlockingQueue tests passed\n";
    return 0;
}
