```go
package main

import (
	"fmt"
	"math/rand"
	"time"
)

const (
	maxLevel    = 32
	probability = 0.5
)

type node struct {
	key  int
	next []*node
}

type SkipList struct {
	head  *node
	level int
	rng   *rand.Rand
}

func NewSkipList() *SkipList {
	return &SkipList{
		head: &node{next: make([]*node, maxLevel)},
		rng:  rand.New(rand.NewSource(time.Now().UnixNano())),
	}
}

func (s *SkipList) randomLevel() int {
	lvl := 0
	for lvl < maxLevel-1 && s.rng.Float64() < probability {
		lvl++
	}
	return lvl
}

// Search returns true if key exists.
func (s *SkipList) Search(key int) bool {
	x := s.head
	for i := s.level; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
	}
	x = x.next[0]
	return x != nil && x.key == key
}

// Insert adds key. It returns false if key already exists.
func (s *SkipList) Insert(key int) bool {
	update := make([]*node, maxLevel)
	x := s.head

	for i := s.level; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}

	if x.next[0] != nil && x.next[0].key == key {
		return false
	}

	lvl := s.randomLevel()
	if lvl > s.level {
		for i := s.level + 1; i <= lvl; i++ {
			update[i] = s.head
		}
		s.level = lvl
	}

	n := &node{
		key:  key,
		next: make([]*node, lvl+1),
	}

	for i := 0; i <= lvl; i++ {
		n.next[i] = update[i].next[i]
		update[i].next[i] = n
	}

	return true
}

// Delete removes key. It returns false if key was not found.
func (s *SkipList) Delete(key int) bool {
	update := make([]*node, maxLevel)
	x := s.head

	for i := s.level; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}

	x = x.next[0]
	if x == nil || x.key != key {
		return false
	}

	for i := 0; i <= s.level; i++ {
		if update[i].next[i] != x {
			break
		}
		update[i].next[i] = x.next[i]
	}

	for s.level > 0 && s.head.next[s.level] == nil {
		s.level--
	}

	return true
}

func main() {
	sl := NewSkipList()

	sl.Insert(3)
	sl.Insert(6)
	sl.Insert(7)
	sl.Insert(9)
	sl.Insert(12)

	fmt.Println("search 7:", sl.Search(7)) // true
	fmt.Println("search 8:", sl.Search(8)) // false

	fmt.Println("delete 7:", sl.Delete(7)) // true
	fmt.Println("search 7:", sl.Search(7)) // false

	fmt.Println("delete 7 again:", sl.Delete(7)) // false
