final class SkipList {
    private final class Node {
        let value: Int
        var forward: [Node?]

        init(value: Int, level: Int) {
            self.value = value
            self.forward = Array(repeating: nil, count: level)
        }
    }

    private let maxLevel: Int
    private let probability: Double
    private var level: Int
    private let head: Node

    init(maxLevel: Int = 16, probability: Double = 0.5) {
        precondition(maxLevel > 0)
        self.maxLevel = maxLevel
        self.probability = probability
        self.level = 1
        self.head = Node(value: Int.min, level: maxLevel)
    }

    private func randomLevel() -> Int {
        var lvl = 1
        while lvl < maxLevel && Double.random(in: 0..<1) < probability {
            lvl += 1
        }
        return lvl
    }

    func search(_ target: Int) -> Bool {
        var current = head

        for i in stride(from: level - 1, through: 0, by: -1) {
            while let next = current.forward[i], next.value < target {
                current = next
            }
        }

        return current.forward[0]?.value == target
    }

    func insert(_ value: Int) {
        var update = Array(repeating: head, count: maxLevel)
        var current = head

        for i in stride(from: level - 1, through: 0, by: -1) {
            while let next = current.forward[i], next.value < value {
                current = next
            }
            update[i] = current
        }

        // No duplicates.
        if current.forward[0]?.value == value {
            return
        }

        let newLevel = randomLevel()
        if newLevel > level {
            level = newLevel
        }

        let newNode = Node(value: value, level: newLevel)

        for i in 0..<newLevel {
            newNode.forward[i] = update[i].forward[i]
            update[i].forward[i] = newNode
        }
    }

    func delete(_ value: Int) {
        var update = Array(repeating: head, count: maxLevel)
        var current = head

        for i in stride(from: level - 1, through: 0, by: -1) {
            while let next = current.forward[i], next.value < value {
                current = next
            }
            update[i] = current
        }

        guard let target = current.forward[0], target.value == value else {
            return
        }

        for i in 0..<level {
            if update[i].forward[i] === target {
                update[i].forward[i] = target.forward[i]
            } else {
                break
            }
        }

        while level > 1 && head.forward[level - 1] == nil {
            level -= 1
        }
    }
}
```

Two ways it could fail under load:

1. **Concurrent access without locking**: `insert`, `delete`, and `search` mutate/read `forward` pointers and `level` without synchronization. Under concurrent load, one thread can unlink a node while another is traversing it, causing lost updates, corrupted skip-list structure, infinite loops, or crashes.

2. **`maxLevel` too small for the working set**: This implementation caps levels at `16`. Under a very large number of inserts, the top levels become dense and searches degrade from expected `O(log n)` toward much slower behavior. In the extreme, a poorly chosen `maxLevel` or skewed random levels can make the list behave closer to a linked list, causing latency collapse under load.

