```ts
export type JitterStrategy = "none" | "full" | "equal";

export interface RetryInfo {
  /** 1-based attempt number that failed. */
  attempt: number;
  /** Error thrown by the failed attempt. */
  error: unknown;
  /** Delay before the next attempt. */
  delayMs: number;
}

export interface RetryOptions {
  /** Number of retries after the initial attempt. Default: 3 */
  retries?: number;
  /** Initial delay in milliseconds. Default: 100 */
  baseDelayMs?: number;
  /** Maximum delay in milliseconds. Default: 30_000 */
  maxDelayMs?: number;
  /** Exponential multiplier. Must be >= 1. Default: 2 */
  factor?: number;
  /**
   * Jitter strategy:
   * - "none": no jitter
   * - "full": random between 0 and cappedDelay
   * - "equal": cappedDelay / 2 + random * cappedDelay / 2
   *
   * `true` is equivalent to "full"; `false` is equivalent to "none".
   * Default: true
   */
  jitter?: JitterStrategy | boolean;
  /** Injectable RNG, useful for deterministic tests. Default: Math.random */
  random?: () => number;
  /** Return false to stop retrying immediately. Default: retry all errors. */
  shouldRetry?: (
    error: unknown,
    failedAttempt: number,
  ) => boolean | Promise<boolean>;
  /** Called before sleeping between attempts. */
  onRetry?: (info: RetryInfo) => void | Promise<void>;
  /** Optional abort signal. */
  signal?: AbortSignal;
}

export async function retry<T>(
  fn: (attempt: number, signal?: AbortSignal) => T | Promise<T>,
  options: RetryOptions = {},
): Promise<T> {
  const {
    retries = 3,
    baseDelayMs = 100,
    maxDelayMs = 30_000,
    factor = 2,
    jitter = true,
    random = Math.random,
    shouldRetry = () => true,
    onRetry,
    signal,
  } = options;

  validateOptions({ retries, baseDelayMs, maxDelayMs, factor });

  let attempt = 0;

  while (true) {
    if (signal?.aborted) {
      throw abortError(signal);
    }

    attempt += 1;

    try {
      return await fn(attempt, signal);
    } catch (error) {
      const isLastAttempt = attempt > retries;

      if (isLastAttempt || !(await shouldRetry(error, attempt))) {
        throw error;
      }

      const delayMs = computeDelay(attempt, {
        baseDelayMs,
        maxDelayMs,
        factor,
        jitter,
        random,
      });

      await onRetry?.({ attempt, error, delayMs });
      await sleep(delayMs, signal);
    }
  }
}

/**
 * Wraps a function so each call is retried according to the retry options.
 */
export function withRetry<Args extends unknown[], T>(
  fn: (...args: Args) => T | Promise<T>,
  options: RetryOptions = {},
): (...args: Args) => Promise<T> {
  return (...args) => retry(() => fn(...args), options);
}

function validateOptions(options: {
  retries: number;
  baseDelayMs: number;
  maxDelayMs: number;
  factor: number;
}): void {
  const { retries, baseDelayMs, maxDelayMs, factor } = options;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError("retries must be a non-negative integer");
  }

  if (!Number.isFinite(baseDelayMs) || baseDelayMs < 0) {
    throw new RangeError("baseDelayMs must be a finite number >= 0");
  }

  if (!Number.isFinite(maxDelayMs) || maxDelayMs < 0) {
    throw new RangeError("maxDelayMs must be a finite number >= 0");
  }

  if (!Number.isFinite(factor) || factor < 1) {
    throw new RangeError("factor must be a finite number >= 1");
  }
}

function computeDelay(
  failedAttempt: number,
  options: {
    baseDelayMs: number;
    maxDelayMs: number;
    factor: number;
    jitter: JitterStrategy | boolean;
    random: () => number;
  },
): number {
  const { baseDelayMs, maxDelayMs, factor, jitter, random } = options;

  const exponential = baseDelayMs * Math.pow(factor, failedAttempt - 1);
  const capped = Math.min(maxDelayMs, exponential);

  const strategy: JitterStrategy =
    jitter === true ? "full" : jitter === false ? "none" : jitter;

  if (strategy === "none" || capped === 0) {
    return capped;
  }

  const r = clamp(random(), 0, 1);

  if (strategy === "equal") {
    return capped / 2 + r * (capped / 2);
  }

  return r * capped;
}

function clamp(value: number, min: number, max: number): number {
  if (!Number.isFinite(value)) {
    return min;
  }

  return Math.min(max, Math.max(min, value));
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  if (ms <= 0) {
    return Promise.resolve();
  }

  if (signal?.aborted) {
    return Promise.reject(abortError(signal));
  }

  return new Promise((resolve, reject) => {
    let timer: ReturnType<typeof setTimeout>;

    const onAbort = () => {
      clearTimeout(timer);
      reject(abortError(signal));
    };

    timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

function abortError(signal: AbortSignal): unknown {
  return signal.reason ?? new Error("Operation aborted");
}
```

