```kotlin
object RomanNumerals {

    private val values = listOf(
        1000, 900, 500, 400,
        100, 90, 50, 40,
        10, 9, 5, 4, 1
    )

    private val symbols = listOf(
        "M", "CM", "D", "CD",
        "C", "XC", "L", "XL",
        "X", "IX", "V", "IV", "I"
    )

    private val charValues = mapOf(
        'I' to 1,
        'V' to 5,
        'X' to 10,
        'L' to 50,
        'C' to 100,
        'D' to 500,
        'M' to 1000
    )

    fun intToRoman(number: Int): String {
        require(number in 1..3999) {
            "Number must be between 1 and 3999, got $number"
        }

        val result = StringBuilder()
        var remaining = number

        for (i in values.indices) {
            while (remaining >= values[i]) {
                result.append(symbols[i])
                remaining -= values[i]
            }
        }

        return result.toString()
    }

    fun romanToInt(roman: String): Int {
        require(roman.isNotEmpty()) { "Roman numeral cannot be empty" }

        var total = 0
        var previous = 0

        for (ch in roman) {
            val value = charValues[ch]
                ?: throw IllegalArgumentException("Invalid Roman numeral character: $ch")

            total += if (value > previous) {
                value - 2 * previous
            } else {
                value
            }

            previous = value
        }

        // Validate canonical Roman numeral form, e.g. reject "IIII", "VX", "IM".
        if (total !in 1..3999 || intToRoman(total) != roman) {
            throw IllegalArgumentException("Invalid Roman numeral: $roman")
        }

        return total
    }
}
