# Parallel Prefix Sum (Inclusive Scan) in C++

Here's a production-ready implementation. It uses a multi-threaded two-pass (Blelloch-style "up-sweep / down-sweep" adapted for inclusive scan) approach, which is cache-friendly and easy to reason about.

```cpp
// parallel_scan.hpp
#pragma once

#include <cstddef>
#include <thread>
#include <vector>
#include <algorithm>
#include <numeric>
#include <type_traits>
#include <future>
#include <stdexcept>

namespace pps {

/// Inclusive parallel prefix sum over [first, last).
///
/// Requirements:
///   - T is an associative binary operation (addition is).
///   - InIt is a random-access iterator (we index it, not just advance).
///   - The range is not concurrently mutated by other threads.
///
/// Complexity: O(N) work, O(N/threads) span across passes.
/// Memory:     O(threads) auxiliary (just per-block partial sums).
///
/// Thread-safety: converts into `num_threads` disjoint sub-ranges; each
/// sub-range is written by exactly one worker. No false sharing on inputs
/// beyond the block boundaries.
template <class InIt, class T = typename std::iterator_traits<InIt>::value_type>
void inclusive_scan(InIt first,
                    InIt last,
                    unsigned num_threads = std::thread::hardware_concurrency())
{
    static_assert(
        std::is_same_v<typename std::iterator_traits<InIt>::iterator_category,
                       std::random_access_iterator_tag> ||
        std::is_same_v<typename std::iterator_traits<InIt>::iterator_category,
                       std::contiguous_iterator_tag>,
        "inclusive_scan requires a random-access / contiguous iterator");

    const std::ptrdiff_t n = last - first;
    if (n <= 0) return;

    num_threads = std::max(1u, num_threads);

    // Small inputs: sequential fallback avoids thread-spawn overhead.
    // 64 KiB of elements is a reasonable default crossover; tune per workload.
    constexpr std::ptrdiff_t kSequentialThreshold = 1 << 16;
    if (n < kSequentialThreshold || num_threads == 1) {
        T acc = T{};
        for (InIt it = first; it != last; ++it) {
            acc = acc + *it;
            *it = acc;
        }
        return;
    }

    // ---- Partition into roughly equal blocks -------------------------------
    // Round block_size UP so the last block is not starved; the final block
    // may be smaller. Blocks must be non-empty: enforce block_size >= 1.
    const std::ptrdiff_t block_size =
        std::max<std::ptrdiff_t>(1, (n + num_threads - 1) / num_threads);
    const std::size_t num_blocks =
        static_cast<std::size_t>((n + block_size - 1) / block_size);

    std::vector<InIt> block_begin(num_blocks);
    std::vector<InIt> block_end(num_blocks);
    for (std::size_t b = 0; b < num_blocks; ++b) {
        const std::ptrdiff_t lo = static_cast<std::ptrdiff_t>(b) * block_size;
        const std::ptrdiff_t hi = std::min<std::ptrdiff_t>(lo + block_size, n);
        block_begin[b] = first + lo;
        block_end[b]   = first + hi;
    }

    // ---- Pass 1: per-block local inclusive scan, record block total --------
    // Each thread owns one block, so writes never race. We store block totals
    // in a vector to be reduced between passes.
    std::vector<T> block_totals(num_blocks);

    {
        std::vector<std::thread> workers;
        workers.reserve(num_blocks);
        for (std::size_t b = 0; b < num_blocks; ++b) {
            workers.emplace_back([&, b]() {
                T acc = T{};
                for (InIt it = block_begin[b]; it != block_end[b]; ++it) {
                    acc = acc + *it;
                    *it = acc;
                }
                block_totals[b] = acc;
            });
        }
        for (auto& t : workers) t.join();
    }

    // ---- Exclusive scan over block totals (sequential; O(num_blocks)) ------
    // This is intentionally serial. num_blocks == num_threads is tiny, and a
    // second parallel pass here would add more barrier overhead than it saves.
    // If num_blocks grows (e.g. you explode blocks for load balancing), swap
    // this for a recursive parallel scan.
    T running = T{};
    for (std::size_t b = 0; b < num_blocks; ++b) {
        const T local_total = block_totals[b];
        block_totals[b] = running;   // exclusive prefix of previous blocks
        running = running + local_total;
    }

    // ---- Pass 2: add exclusive block prefix to every element ---------------
    // Every element of block b must be offset by block_totals[b] (which now
    // holds the sum of all earlier blocks). Still one writer per block.
    {
        std::vector<std::thread> workers;
        workers.reserve(num_blocks);
        for (std::size_t b = 0; b < num_blocks; ++b) {
            workers.emplace_back([&, b]() {
                const T offset = block_totals[b];
                if (offset == T{}) return;  // cheap no-op for the first block
                for (InIt it = block_begin[b]; it != block_end[b]; ++it) {
                    *it = offset + *it;
                }
            });
        }
        for (auto& t : workers) t.join();
    }
}

} // namespace pps
```

## Usage

```cpp
#include "parallel_scan.hpp"
#include <vector>
#include <iostream>

int main() {
    std::vector<long long> v(1'000'000);
    // ... fill v ...

    pps::inclusive_scan(v.begin(), v.end());

    // v[i] now holds sum of original v[0..i]
}
```

## Design notes (the tricky bits)

**Why two passes instead of Blelloch's tree.** Blelloch's classic work-efficient scan is a single up-sweep/down-sweep over the whole array, which forces `log N` global barriers. Two-pass "scan-then-propagate" is used in practice (Thrust, CUB) because it only needs **two** barriers regardless of `N`. Work is trivially `O(N)`; span is `O(N/num_threads)`.

**Races.** The critical invariant is that *each block is written by exactly one thread* in each pass. `block_totals[b]` is written by the owner of `b` in pass 1 and read by all threads in pass 2 — but pass 2 only starts after `join()`, so no synchronization is needed on the vector itself beyond the thread-join happens-before edges.

**Iterator requirement.** A random-access / contiguous iterator is required because we index as `first + lo`. This does not work with `std::list` iterators. (A streaming variant would partition by counting, but that's a different trade-off.)

**Small-input fallback.** Spawning `num_threads` OS threads for a 100-element array is catastrophic for latency. The `kSequentialThreshold` cutoff (default 65536) is deliberately configurable — a service with 10 µs latency targets may want it much higher; a batch job with 100 M elements may want it lower.

**`T{}` as identity.** The first block's offset is `T{}` (zero for arithmetic types). This means `T` must be default-constructible and have `T{} + x == x`. For user-defined types, supply a proper identity (or template the operation, e.g. as `std::plus<>` — but then you can't skip the first block with a `==` check). If you're comfortable requiring `operator==`, the check is a cheap win.

**`num_threads` semantics.** We don't oversubscribe: `num_blocks <= num_threads`. If `num_threads > n / block_size`, some threads do less work; we don't create extra blocks for load-balancing because that would make the sequential `block_totals` scan longer.

**Hardware concurrency can be 0.** `std::thread::hardware_concurrency()` is allowed to return 0; the `std::max(1u, ...)` guards this.

**Variants worth having in a real service.**
- `exclusive_scan` — shift the inclusive result left by one and prepend identity.
- In-place for `std::vector<T>` vs. separate output buffer — the above is in-place, which is usually what you want.
- Thread pooling: creating `num_threads` threads per call is expensive (~10–50 µs each on Linux). If `inclusive_scan` is called frequently, replace the raw `std::thread` storms with a persistent working pool and a barrier per pass. The two `join()`s above become two barrier waits.

**Correctness checklist for review.** Sum associativity holds for `int`/`float` in practice, but note that parallel scan **changes the addition order**, so results may differ in the last ULP from a sequential scan for floating-point `T`. If your service requires bit-identical results to a serial reference, you must either serialize or use a compensated/associative scheme (e.g. pairwise summation within blocks and a fixed reduction order across blocks). Document this — it's the #1 source of "works in tests, fails in prod" bug reports for numeric scans.

```go
// tree.go
package binarytree

type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

// InOrderIterative returns the in-order traversal of root without recursion.
func InOrderIterative(root *TreeNode) []int {
	values := make([]int, 0)
	stack := make([]*TreeNode, 0)
	cur := root

	for cur != nil || len(stack) > 0 {
		// Go as far left as possible.
		for cur != nil {
			stack = append(stack, cur)
			cur = cur.Left
		}

		// Visit the node.
		cur = stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		values = append(values, cur.Val)

		// Then process its right subtree.
		cur = cur.Right
	}

	return values
}
```

```go
// tree_test.go
package binarytree

import (
	"reflect"
	"testing"
)

func TestInOrderIterative(t *testing.T) {
	tests := []struct {
		name string
		root *TreeNode
		want []int
	}{
		{
			name: "nil tree",
			root: nil,
			want: []int{},
		},
		{
			name: "single node",
			root: &TreeNode{Val: 1},
			want: []int{1},
		},
		{
			name: "only left child",
			root: &TreeNode{
				Val:  2,
				Left: &TreeNode{Val: 1},
			},
			want: []int{1, 2},
		},
		{
			name: "only right child",
			root: &TreeNode{
				Val:   1,
				Right: &TreeNode{Val: 2},
			},
			want: []int{1, 2},
		},
		{
			name: "balanced tree",
			root: &TreeNode{
				Val: 4,
				Left: &TreeNode{
					Val:   2,
					Left:  &TreeNode{Val: 1},
					Right: &TreeNode{Val: 3},
				},
				Right: &TreeNode{
					Val:   6,
					Left:  &TreeNode{Val: 5},
					Right: &TreeNode{Val: 7},
				},
			},
			want: []int{1, 2, 3, 4, 5, 6, 7},
		},
		{
			name: "left chain",
			root: &TreeNode{
				Val: 3,
				Left: &TreeNode{
					Val:  2,
					Left: &TreeNode{Val: 1},
				},
			},
			want: []int{1, 2, 3},
		},
		{
			name: "right chain",
			root: &TreeNode{
				Val: 1,
				Right: &TreeNode{
					Val:   2,
					Right: &TreeNode{Val: 3},
				},
			},
			want: []int{1, 2, 3},
		},
		{
			name: "duplicate values",
			root: &TreeNode{
				Val:   2,
				Left:  &TreeNode{Val: 1},
				Right: &TreeNode{Val: 2},
			},
			want: []int{1, 2, 2},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := InOrderIterative(tt.root)
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("InOrderIterative() = %v, want %v", got, tt.want)
			}
		})
	}
}
