sealed class Token {
    data class Number(val value: Double) : Token()
    data class Operator(val symbol: Char) : Token() // + - * /
    object LParen : Token()
    object RParen : Token()
}

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0

    while (i < input.length) {
        val c = input[i]

        when {
            c.isWhitespace() -> i++

            c.isDigit() || c == '.' -> {
                val start = i
                var hasDot = false

                while (i < input.length && (input[i].isDigit() || input[i] == '.')) {
                    if (input[i] == '.') {
                        require(!hasDot) { "Invalid number at position $i" }
                        hasDot = true
                    }
                    i++
                }

                tokens += Token.Number(input.substring(start, i).toDouble())
            }

            c in "+-*/" -> {
                tokens += Token.Operator(c)
                i++
            }

            c == '(' -> {
                tokens += Token.LParen
                i++
            }

            c == ')' -> {
                tokens += Token.RParen
                i++
            }

            else -> throw IllegalArgumentException("Unexpected character '$c' at index $i")
        }
    }

    return tokens
}

class ExpressionEvaluator(private val tokens: List<Token>) {
    private var pos = 0

    fun evaluate(): Double {
        val result = parseExpression()
        require(pos == tokens.size) { "Unexpected token at index $pos" }
        return result
    }

    private fun peek(): Token? = tokens.getOrNull(pos)

    private fun parseExpression(): Double {
        var value = parseTerm()

        while (true) {
            val op = peek() as? Token.Operator ?: break
            if (op.symbol != '+' && op.symbol != '-') break

            pos++
            val rhs = parseTerm()

            value = when (op.symbol) {
                '+' -> value + rhs
                '-' -> value - rhs
                else -> error("Unreachable")
            }
        }

        return value
    }

    private fun parseTerm(): Double {
        var value = parseFactor()

        while (true) {
            val op = peek() as? Token.Operator ?: break
            if (op.symbol != '*' && op.symbol != '/') break

            pos++
            val rhs = parseFactor()

            value = when (op.symbol) {
                '*' -> value * rhs
                '/' -> {
                    require(rhs != 0.0) { "Division by zero" }
                    value / rhs
                }
                else -> error("Unreachable")
            }
        }

        return value
    }

    private fun parseFactor(): Double {
        val token = peek() ?: throw IllegalArgumentException("Unexpected end of expression")

        return when (token) {
            is Token.Number -> {
                pos++
                token.value
            }

            is Token.Operator -> {
                if (token.symbol == '+' || token.symbol == '-') {
                    pos++
                    val value = parseFactor()
                    if (token.symbol == '-') -value else value
                } else {
                    throw IllegalArgumentException("Unexpected operator '${token.symbol}'")
                }
            }

            Token.LParen -> {
                pos++
                val value = parseExpression()
                require(peek() == Token.RParen) { "Expected ')'" }
                pos++
                value
            }

            Token.RParen -> throw IllegalArgumentException("Unexpected ')'")
        }
    }
}

fun evaluate(expression: String): Double {
    return ExpressionEvaluator(tokenize(expression)).evaluate()
}

fun main() {
    val expression = "3 + 4 * (2 - 1) / 2"
    println("$expression = ${evaluate(expression)}") // 5.0
}
