# Exponential Backoff Retry with Jitter in Rust

Here's a complete implementation with tests. I'll use only the standard library plus a small PRNG (to avoid external deps), but I'll also show how to swap in `rand` if you prefer.

## Implementation

```rust
// src/lib.rs
use std::thread;
use std::time::Duration;

/// Configuration for exponential backoff with jitter.
#[derive(Debug, Clone)]
pub struct RetryConfig {
    /// Maximum number of attempts (including the first). Must be >= 1.
    pub max_attempts: u32,
    /// Base delay for the first retry.
    pub base_delay: Duration,
    /// Upper bound on any single delay.
    pub max_delay: Duration,
    /// Multiplier applied each attempt.
    pub multiplier: f64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_attempts: 5,
            base_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(10),
            multiplier: 2.0,
        }
    }
}

impl RetryConfig {
    /// Validate that the config makes sense. Returns Err with a message on bad input.
    pub fn validate(&self) -> Result<(), String> {
        if self.max_attempts == 0 {
            return Err("max_attempts must be >= 1".into());
        }
        if self.multiplier < 1.0 {
            return Err("multiplier must be >= 1.0".into());
        }
        if self.max_delay < self.base_delay {
            return Err("max_delay must be >= base_delay".into());
        }
        Ok(())
    }
}

/// Tiny xorshift64* PRNG so we don't need external crates.
/// Not cryptographically secure — fine for jitter.
struct SplitMix64(u64);

impl SplitMix64 {
    fn new(seed: u64) -> Self {
        Self(seed)
    }
    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
    /// Returns a uniform f64 in [0.0, 1.0).
    fn next_f64(&mut self) -> f64 {
        // 53 bits of randomness / 2^53
        (self.next_u64() >> 11) as f64 / ((1u64 << 53) as f64)
    }
}

/// Default seed source. We mix together a monotonic-ish counter so successive
/// calls don't produce identical jitter if called in the same nanosecond.
fn make_seed() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let c = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    now ^ c.wrapping_mul(0x9E3779B97F4A7C15)
}

/// Compute the delay for attempt `n` (0-indexed: n=0 is the first retry).
///
/// Uses "full jitter": `delay = random_uniform(0, min(max_delay, base * mult^n))`.
/// Yields excellent thundering-herd behavior.
pub fn compute_delay(cfg: &RetryConfig, n: u32, rng: &mut SplitMix64) -> Duration {
    // Cap the exponential growth to avoid f64 overflow for large n.
    let raw = cfg.base_delay.as_secs_f64() * cfg.multiplier.powi(n.min(1024) as i32);
    let capped = raw.min(cfg.max_delay.as_secs_f64()).max(0.0);
    let jittered = capped * rng.next_f64();
    Duration::from_secs_f64(jittered)
}

/// Result of a retried operation: the final value plus how many attempts it took.
#[derive(Debug)]
pub struct RetryOutcome<T, E> {
    pub value: T,
    pub attempts: u32,
    pub total_delay: Duration,
    pub last_error: Option<E>,
}

/// Retry `op` according to `cfg`. `op` receives the attempt index (0-based)
/// so callers can vary behavior if desired.
///
/// The closure must return `Result<T, E>` where `E: Display`.
/// We retry on every `Err`. For "only retry on certain errors", adapt the
/// closure to return `Ok` for non-retryable ones.
pub fn retry_with_backoff<T, E, F>(
    cfg: &RetryConfig,
    mut op: F,
) -> Result<RetryOutcome<T, E>, String>
where
    E: std::fmt::Display,
    F: FnMut(u32) -> Result<T, E>,
{
    cfg.validate()?;

    let mut rng = SplitMix64::new(make_seed());
    let mut total_delay = Duration::ZERO;
    let mut last_err: Option<E> = None;

    for attempt in 0..cfg.max_attempts {
        match op(attempt) {
            Ok(value) => {
                return Ok(RetryOutcome {
                    value,
                    attempts: attempt + 1,
                    total_delay,
                    last_error: last_err,
                });
            }
            Err(e) => {
                last_err = Some(e);
                // No sleep after the final failed attempt.
                if attempt + 1 < cfg.max_attempts {
                    let d = compute_delay(cfg, attempt, &mut rng);
                    total_delay += d;
                    thread::sleep(d);
                }
            }
        }
    }

    // All attempts failed. Fold the last error into a message.
    let msg = last_err
        .as_ref()
        .map(|e| format!("all {} attempts failed; last error: {}", cfg.max_attempts, e))
        .unwrap_or_else(|| "all attempts failed".to_string());
    Err(msg)
}
```

## Unit Tests

```rust
// tests/retry.rs  (integration tests) — or put in lib.rs under #[cfg(test)] mod tests
use std::cell::Cell;
use std::sync::atomic::{AtomicU32, Ordering};
use std::time::Duration;

use my_crate::{compute_delay, retry_with_backoff, RetryConfig};

/// Expose SplitMix64 for tests — either pub(crate) with a test submodule,
/// or make a dedicated pub constructor. We'll do the latter via a helper.
mod test_helpers {
    use super::*;
    // Re-import the internal PRNG by making it `pub(crate)` in lib.rs.
    // For a pure integration test, expose a `pub fn compute_delay_seeded`.
    pub use my_crate::rng_test_api::SplitMix64;
}

#[test]
fn succeeds_first_try_no_sleep() {
    let cfg = RetryConfig::default();
    let start = std::time::Instant::now();
    let out = retry_with_backoff(&cfg, |_| Ok::<_, &str>(42)).unwrap();
    assert_eq!(out.value, 42);
    assert_eq!(out.attempts, 1);
    assert_eq!(out.total_delay, Duration::ZERO);
    assert!(start.elapsed() < Duration::from_millis(50));
}

#[test]
fn succeeds_on_nth_attempt() {
    let cfg = RetryConfig {
        max_attempts: 5,
        base_delay: Duration::from_millis(1),
        max_delay: Duration::from_millis(5),
        multiplier: 2.0,
    };
    let calls = AtomicU32::new(0);
    let out = retry_with_backoff(&cfg, |_| {
        let n = calls.fetch_add(1, Ordering::SeqCst);
        if n < 3 { Err("nope") } else { Ok("ok") }
    })
    .unwrap();
    assert_eq!(out.value, "ok");
    assert_eq!(out.attempts, 4);
    assert_eq!(calls.load(Ordering::SeqCst), 4);
}

#[test]
fn exhausts_all_attempts() {
    let cfg = RetryConfig {
        max_attempts: 3,
        base_delay: Duration::from_millis(1),
        max_delay: Duration::from_millis(2),
        multiplier: 1.5,
    };
    let calls = AtomicU32::new(0);
    let err = retry_with_backoff(&cfg, |_| {
        calls.fetch_add(1, Ordering::SeqCst);
        Err::<(), _>("always")
    })
    .unwrap_err();
    assert_eq!(calls.load(Ordering::SeqCst), 3);
    assert!(err.contains("3 attempts failed"));
    assert!(err.contains("always"));
}

#[test]
fn max_attempts_of_one_means_no_retry() {
    let cfg = RetryConfig {
        max_attempts: 1,
        ..RetryConfig::default()
    };
    let calls = AtomicU32::new(0);
    let start = std::time::Instant::now();
    let _ = retry_with_backoff(&cfg, |_| {
        calls.fetch_add(1, Ordering::SeqCst);
        Err::<(), _>("boom")
    });
    assert_eq!(calls.load(Ordering::SeqCst), 1);
    assert!(start.elapsed() < Duration::from_millis(50));
}

#[test]
fn rejects_zero_max_attempts() {
    let cfg = RetryConfig {
        max_attempts: 0,
        ..RetryConfig::default()
    };
    let err = retry_with_backoff::<(), _, _>(&cfg, |_| Ok(())).unwrap_err();
    assert!(err.contains("max_attempts"));
}

#[test]
fn rejects_multiplier_below_one() {
    let cfg = RetryConfig {
        multiplier: 0.5,
        ..RetryConfig::default()
    };
    assert!(cfg.validate().is_err());
}

#[test]
fn rejects_max_delay_less_than_base() {
    let cfg = RetryConfig {
        base_delay: Duration::from_secs(5),
        max_delay: Duration::from_secs(1),
        ..RetryConfig::default()
    };
    assert!(cfg.validate().is_err());
}

#[test]
fn delay_is_within_bounds_and_jittered() {
    let cfg = RetryConfig {
        max_attempts: 10,
        base_delay: Duration::from_millis(100),
        max_delay: Duration::from_secs(10),
        multiplier: 2.0,
    };
    let mut rng = SplitMix64::new(0xDEADBEEF);

    // attempt 0: cap = 100ms
    for _ in 0..100 {
        let d = compute_delay(&cfg, 0, &mut rng);
        assert!(d <= Duration::from_millis(100), "got {:?}", d);
    }
    // attempt 4: cap = 100*2^4 = 1600ms
    for _ in 0..100 {
        let d = compute_delay(&cfg, 4, &mut rng);
        assert!(d <= Duration::from_millis(1600), "got {:?}", d);
    }
    // attempt 50: exponential exceeds cap → full range is [0, max_delay]
    for _ in 0..100 {
        let d = compute_delay(&cfg, 50, &mut rng);
        assert!(d <= Duration::from_secs(10), "got {:?}", d);
    }
}

#[test]
fn delay_jitters_around_zero_up_to_cap() {
    // Full jitter: with enough samples we should see values well below the cap
    // AND values near the cap — not all clustered at one extreme.
    let cfg = RetryConfig {
        max_attempts: 5,
        base_delay: Duration::from_millis(1_000),
        max_delay: Duration::from_secs(1),
        multiplier: 2.0,
