// TokenType identifies the kind of a token.
type TokenType int

const (
	TokenNumber TokenType = iota
	TokenPlus
	TokenMinus
	TokenStar
	TokenSlash
	TokenLParen
	TokenRParen
	TokenEOF
)

// Token is a lexical unit produced by the tokenizer.
type Token struct {
	Type  TokenType
	Value float64 // Only meaningful for TokenNumber.
	Pos   int     // Byte offset in the input; useful for error messages.
}

// Tokenize converts an arithmetic expression into a slice of Tokens.
//
// The grammar accepted is:
//
//	expr    := term (('+' | '-') term)*
//	term    := factor (('*' | '/') factor)*
//	factor  := number | '(' expr ')' | ('+' | '-') factor
//
// Whitespace is ignored. Numbers use Go's strconv.ParseFloat syntax
// (so "1.5", "1e-3", ".5" are all valid). Unary +/- is folded into
// the following factor, which is why we accept it both at the start
// and inside parentheses.
func Tokenize(input string) ([]Token, error) {
	tokens := make([]Token, 0, 16)
	i := 0
	for i < len(input) {
		r := rune(input[i])
		switch {
		case unicode.IsSpace(r):
			i++
		case r == '+':
			tokens = append(tokens, Token{Type: TokenPlus, Pos: i})
			i++
		case r == '-':
			tokens = append(tokens, Token{Type: TokenMinus, Pos: i})
			i++
		case r == '*':
			tokens = append(tokens, Token{Type: TokenStar, Pos: i})
			i++
		case r == '/':
			tokens = append(tokens, Token{Type: TokenSlash, Pos: i})
			i++
		case r == '(':
			tokens = append(tokens, Token{Type: TokenLParen, Pos: i})
			i++
		case r == ')':
			tokens = append(tokens, Token{Type: TokenRParen, Pos: i})
			i++
		case r == '.' || (r >= '0' && r <= '9'):
			start := i
			// Scan the numeric literal. We no longer need to hand-parse
			// the value: hand the substring to strconv, which understands
			// decimals and exponents correctly (including things like
			// "1e-3" and "1_000" if you want to enable that).
			for i < len(input) && isNumberByte(input[i]) {
				i++
			}
			text := input[start:i]
			v, err := strconv.ParseFloat(text, 64)
			if err != nil {
				return nil, fmt.Errorf("invalid number %q at position %d: %w", text, start, err)
			}
			tokens = append(tokens, Token{Type: TokenNumber, Value: v, Pos: start})
		default:
			return nil, fmt.Errorf("unexpected character %q at position %d", r, i)
		}
	}
	tokens = append(tokens, Token{Type: TokenEOF, Pos: len(input)})
	return tokens, nil
