//   - optionally followed by 'e' or 'E', an optional sign, and digits
//
// This mirrors what strconv.ParseFloat accepts for the forms we care
// about, without exposing its full grammar (hex floats, underscores).
func scanNumber(input string, i int) (string, int) {
	start := i
