		switch p.peek().Type {
		case TokenPlus:
			p.next()
			right, err := p.parseTerm()
			if err != nil {
				return 0, err
			}
			left += right
		case TokenMinus:
			p.next()
			right, err := p.parseTerm()
			if err != nil {
				return 0, err
			}
			left -= right
		default:
			return left, nil
		}
	}
}

// parseTerm handles * and /, which bind tighter than + and -.
func (p *parser) parseTerm() (float64, error) {
	left, err := p.parseFactor()
	if err != nil {
		return 0, err
	}
	for {
		switch p.peek().Type {
		case TokenStar:
			p.next()
			right, err := p.parseFactor()
			if err != nil {
				return 0, err
			}
			left *= right
		case TokenSlash:
			p.next()
			right, err := p.parseFactor()
			if err != nil {
				return 0, err
			}
			// Document the choice: returning an error on divide-by-zero
			// is friendlier for a service than silently producing Inf/NaN.
			if right == 0 {
				return 0, fmt.Errorf("division by zero at position %d", p.peek().Pos)
			}
			left /= right
		default:
			return left, nil
		}
	}
}

// parseFactor handles numbers, parenthesised sub-expressions, and
// unary +/-. Unary plus/minus is right-associative and applies to
// whatever the following factor evaluates to, so "--3" is 3 and
// "-(1+2)" is -3.
func (p *parser) parseFactor() (float64, error) {
	t := p.peek()
	switch t.Type {
	case TokenNumber:
		p.next()
		return t.Value, nil
	case TokenPlus:
		p.next()
		return p.parseFactor()
	case TokenMinus:
		p.next()
		v, err := p.parseFactor()
		if err != nil {
			return 0, err
		}
		return -v, nil
	case TokenLParen:
		p.next()
		v, err := p.parseExpr()
		if err != nil {
			return 0, err
		}
		if p.peek().Type != TokenRParen {
			return 0, fmt.Errorf("missing closing parenthesis at position %d", p.peek().Pos)
		}
		p.next()
		return v, nil
	case TokenEOF:
		return 0, fmt.Errorf("unexpected end of input")
	default:
		return 0, fmt.Errorf("unexpected token at position %d", t.Pos)
	}
}
```

### Tricky parts worth calling out

1. **Number scanning must not swallow operators.** It's tempting to accept any of `0-9 . e E + -` inside a number, but then `1-3` becomes a single token. The exponent sign must only be consumed immediately after an `e`/`E`. `scanNumber` enforces that.

2. **Precedence via function nesting.** `parseExpr` calls `parseTerm`, which calls `parseFactor`. Each level handles exactly one precedence tier. Unary `+`/`-` live at the *factor* level, so `-2*3` parses as `(-2)*3`, matching common math conventions.

3. **Left-associativity via loops.** `+`, `-`, `*`, `/` are left-associative (`1-2-3 == (1-2)-3`). We use a `for` loop rather than recursion at the operator level so that long chains stay O(n) in stack. Unary operators are right-associative, so `parseFactor` recurses for them.

4. **Explicit EOF token.** Appending a `TokenEOF` sentinel avoids off-by-one bugs when the parser peeks past the last real token. `next()` refuses to advance past EOF so looping on `peek()` is safe.

5. **Division by zero.** We return an error rather than letting IEEE-754 produce `+Inf` or `NaN`. For a production service, "invalid input" is usually what you want; change this if you need partial results.

6. **Byte indexing, not rune indexing.** The grammar only contains ASCII, so byte offsets are correct positions in source. If you later add identifier handling with Unicode, switch to rune-aware scanning.

7. **Errors carry positions.** Every token remembers its byte offset, so error messages point at the offending input. This matters a lot when users paste long expressions.

### Usage

```go
v, err := expr.Eval("2 + 3 * (4 - 1) / -1.5e1")
// v == -0.4
```

If you need higher throughput or non-float types (e.g. `big.Rat` or `int64`), the tokenizer is independent of the evaluator's numeric type, so you can swap the `Value float64` field and the arithmetic without touching the grammar.

```kotlin
data class Interval(val start: Int, val end: Int)

fun mergeIntervals(intervals: List<Interval>): List<Interval> {
    if (intervals.isEmpty()) return emptyList()

    val sorted = intervals.sortedBy { it.start }
    val merged = mutableListOf<Interval>()
    var current = sorted.first()

    for (next in sorted.drop(1)) {
        if (next.start <= current.end) {
            // Overlapping (or touching) — extend the current interval if needed.
            current = Interval(current.start, maxOf(current.end, next.end))
        } else {
            merged.add(current)
            current = next
        }
    }
    merged.add(current)

    return merged
}

fun main() {
    val input = listOf(
        Interval(1, 3),
        Interval(2, 6),
        Interval(8, 10),
        Interval(15, 18),
        Interval(9, 12)
    )

    val result = mergeIntervals(input)
    println(result) // [Interval(start=1, end=6), Interval(start=8, end=12), Interval(start=15, end=18)]
}
```

How it works:

1. Sort intervals by their `start` value.
2. Walk through them, keeping a `current` interval.
3. If the next interval starts at or before `current.end`, they overlap — merge by taking the larger `end`.
4. Otherwise, push `current` to the result and move on.
5. Don't forget to push the final `current` after the loop.

Time complexity: **O(n log n)** due to sorting. Space complexity: **O(n)** for the result.

```ts
export class ReservoirSampler<T> {
  private readonly reservoir: T[] = [];
  private seen = 0;

  constructor(private readonly k: number) {
    if (!Number.isInteger(k) || k < 0) {
      throw new Error("k must be a non-negative integer");
    }
  }

  add(item: T): void {
    this.seen++;

    if (this.k === 0) return;

    // Fill the reservoir first.
    if (this.reservoir.length < this.k) {
      this.reservoir.push(item);
      return;
    }

    // For the i-th item, choose a random index in [0, i).
    const j = Math.floor(Math.random() * this.seen);

    // Keep the new item with probability k / i.
    if (j < this.k) {
      this.reservoir[j] = item;
    }
  }

  addAll(items: Iterable<T>): void {
    for (const item of items) {
      this.add(item);
    }
  }

  getSample(): T[] {
    return this.reservoir.slice();
  }

  get count(): number {
    return this.seen;
  }
}

export function reservoirSample<T>(items: Iterable<T>, k: number): T[] {
  const sampler = new ReservoirSampler<T>(k);
  sampler.addAll(items);
  return sampler.getSample();
}
```

For an async stream:

```ts
export async function reservoirSampleAsync<T>(
  stream: AsyncIterable<T>,
  k: number
): Promise<T[]> {
  const sampler = new ReservoirSampler<T>(k);

  for await (const item of stream) {
    sampler.add(item);
  }

  return sampler.getSample();
}
```

Example usage:

```ts
const sample = reservoirSample([1, 2, 3, 4, 5, 6, 7], 3);
console.log(sample.length); // 3
```

### How it works

This is the standard reservoir sampling algorithm, often called Algorithm R.

- Keep the first `k` items in the reservoir.
- For every later item, let `i` be the number of items seen so far.
- Pick a random index `j` in `[0, i)`.
- If `j < k`, replace `reservoir[j]` with the new item.

So the `i`-th item is kept with probability:

```text
k / i
```

This guarantees that after processing `n` items, every item has probability `k / n` of being in the final sample, and every possible `k`-subset is equally likely.

### Complexity

Let `n` be the total number of items in the stream.

- **Time:** `O(n)`
  - Each item is processed once.
  - Each `add` operation is `O(1)`.
  - Returning a copy of the sample is `O(k)`.

- **Space:** `O(k)`
  - Only the reservoir of size `k` is stored.
  - Memory does not depend on the unknown stream length `n`.
  - If `k = 0`, space is `O(1)`.

So this is ideal for streaming data where `n` is very large or unknown.

