// parser.go
package csvparser

import (
	"fmt"
	"strings"
)

// Parse parses CSV data and returns records as a slice of string slices.
//
// It supports:
//   - comma-separated fields
//   - quoted fields
//   - embedded commas inside quoted fields
//   - escaped quotes inside quoted fields using ""
//   - embedded newlines inside quoted fields
//   - LF, CRLF, and CR line endings
func Parse(input string) ([][]string, error) {
	var records [][]string
	var record []string
	var field strings.Builder

	inQuotes := false
	justClosedQuote := false
	fieldStarted := false

	i := 0
	for i < len(input) {
		c := input[i]

		if inQuotes {
			if c == '"' {
				if i+1 < len(input) && input[i+1] == '"' {
					field.WriteByte('"')
					i += 2
					continue
				}
				inQuotes = false
				justClosedQuote = true
				i++
				continue
			}

			field.WriteByte(c)
			i++
			continue
		}

		if justClosedQuote {
			switch c {
			case ',':
				record = append(record, field.String())
				field.Reset()
				justClosedQuote = false
				fieldStarted = false
				i++

			case '\n':
				record = append(record, field.String())
				records = append(records, record)
				record = nil
				field.Reset()
				justClosedQuote = false
				fieldStarted = false
				i++

			case '\r':
				record = append(record, field.String())
				records = append(records, record)
				record = nil
				field.Reset()
				justClosedQuote = false
				fieldStarted = false

				if i+1 < len(input) && input[i+1] == '\n' {
					i += 2
				} else {
					i++
				}

			default:
				return nil, fmt.Errorf(
					"csv: unexpected character %q after closing quote at byte %d",
					c, i,
				)
			}
			continue
		}

		switch c {
		case '"':
			if fieldStarted {
				return nil, fmt.Errorf(
					"csv: unexpected quote in unquoted field at byte %d",
					i,
				)
			}
			inQuotes = true
			fieldStarted = true
			i++

		case ',':
			record = append(record, field.String())
			field.Reset()
			fieldStarted = false
			i++

		case '\n':
			if fieldStarted || len(record) > 0 {
				record = append(record, field.String())
				records = append(records, record)
			}
			record = nil
			field.Reset()
			fieldStarted = false
			i++

		case '\r':
			if fieldStarted || len(record) > 0 {
				record = append(record, field.String())
				records = append(records, record)
			}
			record = nil
			field.Reset()
			fieldStarted = false

			if i+1 < len(input) && input[i+1] == '\n' {
				i += 2
			} else {
				i++
			}

		default:
			field.WriteByte(c)
			fieldStarted = true
			i++
		}
	}

	if inQuotes {
		return nil, fmt.Errorf("csv: unterminated quoted field")
	}

	if justClosedQuote || fieldStarted || len(record) > 0 {
		record = append(record, field.String())
		records = append(records, record)
	}

	return records, nil
}
