func TestParse(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  [][]string
	}{
		{
			name:  "empty input",
			input: "",
			want:  nil,
		},
		{
			name:  "simple row",
			input: "a,b,c",
			want:  [][]string{{"a", "b", "c"}},
		},
		{
			name:  "multiple rows",
			input: "a,b\nc,d",
			want: [][]string{
				{"a", "b"},
				{"c", "d"},
			},
		},
		{
			name:  "trailing newline",
			input: "a,b\n",
			want:  [][]string{{"a", "b"}},
		},
		{
			name:  "empty fields",
			input: "a,,c",
			want:  [][]string{{"a", "", "c"}},
		},
		{
			name:  "trailing comma",
			input: "a,b,",
			want:  [][]string{{"a", "b", ""}},
		},
		{
			name:  "quoted field with comma",
			input: `a,"b,c",d`,
			want:  [][]string{{"a", "b,c", "d"}},
		},
		{
			name:  "escaped quotes",
			input: `a,"He said ""hello""",b`,
			want:  [][]string{{"a", `He said "hello"`, "b"}},
		},
		{
			name:  "quoted field with newline",
			input: "a,\"line1\nline2\",b",
			want:  [][]string{{"a", "line1\nline2", "b"}},
		},
		{
			name:  "quoted empty field",
			input: `a,"",b`,
			want:  [][]string{{"a", "", "b"}},
