			name:  "CRLF line endings",
			input: "a,b\r\nc,d\r\n",
			want: [][]string{
				{"a", "b"},
				{"c", "d"},
			},
		},
		{
			name:  "CR line endings",
			input: "a,b\rc,d\r",
			want: [][]string{
