		{
			name:  "blank lines are skipped",
			input: "\n\na,b\n\nc,d\n",
			want: [][]string{
				{"a", "b"},
				{"c", "d"},
			},
		},
		{
			name:  "unicode",
			input: `名前,"東京, 日本",42`,
			want:  [][]string{{"名前", "東京, 日本", "42"}},
		},
		{
			name:  "complex mixed case",
			input: "id,name,note\n1,\"Doe, John\",\"He said \"\"hi\"\"\"\n2,\"Line\nBreak\",\"\"",
			want: [][]string{
				{"id", "name", "note"},
				{"1", "Doe, John", `He said "hi"`},
				{"2", "Line\nBreak", ""},
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := Parse(tc.input)
			if err != nil {
				t.Fatalf("Parse() error = %v", err)
			}

			if !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("Parse() = %#v, want %#v", got, tc.want)
			}
		})
	}
}

func TestParseErrors(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		wantErr bool
	}{
		{
			name:    "unterminated quoted field",
			input:   `a,"b,c`,
			wantErr: true,
		},
		{
			name:    "unexpected quote in unquoted field",
			input:   `a,b"c,d`,
			wantErr: true,
		},
		{
			name:    "character after closing quote",
			input:   `a,"b"c,d`,
			wantErr: true,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := Parse(tc.input)
			if tc.wantErr && err == nil {
				t.Fatalf("Parse() expected error, got nil")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("Parse() unexpected error: %v", err)
			}
		})
	}
}
```

The parser is a small state machine. It treats `""` inside a quoted field as a single literal `"`, allows commas and newlines inside quoted fields, and rejects malformed quoting such as `"abc"def` or `ab"cd`.

### Iterative in-order traversal in CUDA C++

CUDA device code should avoid recursion, so use an explicit stack or Morris traversal.  
Below is a typical iterative version using a thread-local stack.

```cpp
#include <cuda_runtime.h>

struct Node {
    int value;
    Node* left;
    Node* right;
};

// Choose a maximum tree height. Increase it if your tree can be deeper.
// If exceeded, the traversal returns early or you can use Morris traversal.
#define MAX_DEPTH 1024

__device__ void inorderIterative(Node* root,
                                 int* out,
                                 int* count,
                                 int maxOut)
{
    // Thread-local stack. In CUDA this usually lives in local memory/registers.
    Node* stack[MAX_DEPTH];
    int top = -1;

    Node* cur = root;

    while (cur != nullptr || top >= 0) {
        // Go to the leftmost node, pushing ancestors.
        while (cur != nullptr) {
            if (top + 1 >= MAX_DEPTH) {
                // Stack overflow: tree is too deep for this fixed stack.
                return;
            }
            stack[++top] = cur;
            cur = cur->left;
        }

        // Visit the node.
        cur = stack[top--];

        int idx = atomicAdd(count, 1);
        if (idx < maxOut) {
            out[idx] = cur->value;
        }

        // Traverse right subtree.
        cur = cur->right;
    }
}

__global__ void inorderKernel(Node* root,
                              int* out,
                              int* count,
                              int maxOut)
{
    // Single-tree traversal is inherently sequential, so use one thread.
    if (blockIdx.x == 0 && threadIdx.x == 0) {
        inorderIterative(root, out, count, maxOut);
    }
}
```

Example host launch:

```cpp
void launchInorder(Node* d_root, int* d_out, int* d_count, int n)
{
    cudaMemset(d_count, 0, sizeof(int));
    inorderKernel<<<1, 1>>>(d_root, d_out, d_count, n);

    int count = 0;
    cudaMemcpy(&count, d_count, sizeof(int), cudaMemcpyDeviceToHost);
}
```

---

### Complexity

Let:

- `n` = number of nodes in the tree
- `h` = height of the tree

#### Time complexity

**O(n)**

Each node is:

1. Pushed onto the stack once.
2. Popped once.
3. Visited once.

So the total work is linear in the number of nodes.

#### Space complexity

**O(h)** per thread.

The explicit stack stores at most one path from the root to a leaf, so its maximum size is the tree height:

- Balanced tree: `h = O(log n)`, so stack space is `O(log n)`.
- Skewed tree: `h = O(n)`, so stack space is `O(n)`.

In CUDA, the stack is thread-local. If `T` threads each traverse a tree, total local-memory pressure is roughly:

```text
O(T * h)
```

or more practically:

```text
O(T * MAX_DEPTH)
```

because a fixed-size array is used.

---

### Morris traversal alternative: O(1) extra space

If you want iterative in-order traversal with `O(1)` extra space, use Morris traversal. It temporarily modifies the tree by creating threaded links.

```cpp
__device__ void morrisInorder(Node* root,
                              int* out,
                              int* count,
                              int maxOut)
{
    Node* cur = root;

    while (cur != nullptr) {
        if (cur->left == nullptr) {
            int idx = atomicAdd(count, 1);
            if (idx < maxOut) out[idx] = cur->value;

            cur = cur->right;
        } else {
            // Find inorder predecessor.
            Node* pred = cur->left;
            while (pred->right != nullptr && pred->right != cur) {
                pred = pred->right;
            }

            if (pred->right == nullptr) {
                // Create temporary thread.
                pred->right = cur;
                cur = cur->left;
            } else {
                // Remove temporary thread and visit cur.
                pred->right = nullptr;

                int idx = atomicAdd(count, 1);
                if (idx < maxOut) out[idx] = cur->value;

                cur = cur->right;
            }
        }
    }
}
```

Morris traversal:

- Time: `O(n)`
- Extra space: `O(1)`
- Caveat: it modifies the tree temporarily. It is not safe if multiple CUDA threads traverse the same tree concurrently.

So for a single tree in CUDA, use the explicit-stack version if tree mutation is not acceptable. Use Morris if you need `O(1)` auxiliary space and can temporarily modify the tree.

