# Minimal SQL Retry Wrapper with Exponential Backoff + Jitter

Most "SQL retry" is really orchestration, so the smallest honest implementation is a stored procedure that wraps a single retryable statement. Postgres flavored:

```sql
CREATE OR REPLACE PROCEDURE retry_exec(sql_text TEXT, max_attempts INT DEFAULT 5)
LANGUAGE plpgsql AS $$
DECLARE
    attempt INT := 0;
    backoff_ms INT;
BEGIN
    LOOP
        attempt := attempt + 1;
        BEGIN
            EXECUTE sql_text;
            RETURN;
        EXCEPTION
            WHEN serialization_failure OR deadlock_detected
              OR lock_not_available OR connection_exception THEN
                IF attempt >= max_attempts THEN
                    RAISE;
                END IF;
                -- base 50ms * 2^(n-1), full jitter: random in [0, backoff]
                backoff_ms := (random() * 50 * (2 ^ (attempt - 1)))::INT;
                PERFORM pg_sleep(backoff_ms / 1000.0);
        END;
    END LOOP;
END;
$$;
```

Usage:
```sql
CALL retry_exec('UPDATE accounts SET bal = bal - 10 WHERE id = 1');
```

Key properties: retries only on transient classes (serialization, deadlock, lock timeout, connection drop), caps attempts, and jitters the sleep so concurrent retriers don't re-collide in lockstep.

---

# Two Ways This Fails Under Load

**1. Synchronized thundering herd after a partial outage.**
`random()` in each backend is *not* seeded independently enough in practice — and more importantly, when a shared resource (a hot row, a table lock, a connection pool) becomes available again, all waiters wake on similar wall-clock schedules. If the base delay and retry budget are tuned for a single client, a fleet of N clients will re-issue simultaneously at t=0, 50ms, 100ms, 200ms... Missing "decorrelated jitter" (each attempt's delay based on the *previous* delay, not a fresh geometric draw) means retries cluster, the resource is immediately oversubscribed again, and you get retry storms that look like a self-inflicted DoS.

**2. Connection pool / backend starvation from sleeping inside the transaction context.**
`pg_sleep` holds the session (and in many frameworks, the pooled connection) for the entire backoff window. Under load, retriers occupy connections while doing nothing, so *new* work can't get a connection to even attempt. The failure mode is inverted: retries that were supposed to improve availability reduce it, because the pool fills with sleeping sessions and non-retrying callers time out waiting for a slot. The stored-proc approach makes this especially bad because the sleep is opaque to the client's pool — there's no way to release the connection during backoff.

Both are fixable (decorrelated jitter, releasing the connection between attempts, a jitter-tolerant admission control layer), but the minimal version above has neither.

# CSV Parser for TypeScript

Here's a production-ready RFC 4180-compliant CSV parser. It handles the three cases that break naive `split(',')` implementations: quoted fields with commas, escaped quotes (`""`), and embedded newlines.

```ts
/**
 * Parse a CSV string into a 2D array of strings (RFC 4180).
 *
 * Handles:
 *   - Quoted fields:        a,"b,c",d       -> ["a","b,c","d"]
 *   - Escaped quotes:       "he said ""hi""" -> ['he said "hi"']
 *   - Embedded newlines:    "line1\nline2"
 *   - Both \n and \r\n line endings
 *   - Empty fields and trailing newlines
 *
 * Does NOT handle (by design):
 *   - Custom delimiters/quote chars (extend if needed)
 *   - Header mapping (do that at the call site)
 */
export function parseCsv(input: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;
  let i = 0;

  // Strip a UTF-8 BOM if present — Excel loves to add one.
  if (input.charCodeAt(0) === 0xfeff) i = 1;

  const pushField = () => {
    row.push(field);
    field = "";
  };
  const pushRow = () => {
    pushField();
    rows.push(row);
    row = [];
  };

  while (i < input.length) {
    const ch = input[i];

    if (inQuotes) {
      if (ch === '"') {
        // Doubled quote inside a quoted field => literal quote.
        // Otherwise, the quote closes the field.
        if (input[i + 1] === '"') {
          field += '"';
          i += 2;
            continue;
        }
        inQuotes = false;
        i++;
        continue;
      }
      // Everything else (including \n and ,) is literal inside quotes.
      field += ch;
      i++;
      continue;
    }

    switch (ch) {
      case '"':
        // A quote should only open a field at its start. Some producers
        // (rarely) put a quote mid-field, e.g. `a"b` — treat it as literal
        // to be lenient rather than throw.
        if (field.length === 0) {
          inQuotes = true;
        } else {
          field += ch;
        }
        i++;
        break;

      case ",":
        pushField();
        i++;
        break;

      case "\r":
        // Normalize CRLF -> LF. A lone CR is treated as a row terminator.
        if (input[i + 1] === "\n") i++;
        pushRow();
        i++;
        break;

      case "\n":
        pushRow();
        i++;
        break;

      default:
        field += ch;
        i++;
    }
  }

  // Flush the last field/row unless the input ended exactly on a row
  // terminator (in which case `field` and `row` are empty).
  if (field.length > 0 || row.length > 0 || inQuotes) {
    pushRow();
  }

  return rows;
}
```

## The tricky parts

**1. Doubled quotes are the escape mechanism, not backslashes.**
RFC 4180 has no `\"` escape. To put a literal `"` inside a quoted field, you write `""`. Peeking at `input[i + 1]` and advancing by 2 when you find a pair is the whole trick.

**2. The closing quote only counts outside a doubled pair.**
The same `"` character means "start of quote", "end of quote", and (when doubled) "literal quote". The state machine (`inQuotes`) plus the lookahead disambiguates.

**3. Commas and newlines inside quotes are data, not delimiters.**
While `inQuotes` is true, every character except a quote is appended verbatim — including `,`, `\n`, and `\r`. This is why you can't `split` first and unquote later.

**4. Line endings.**
Windows CSVs use `\r\n`, Unix uses `\n`. Real-world files sometimes mix them or use lone `\r` (old Mac style). The parser absorbs `\r` before `\n` so you don't get a spurious empty row.

**5. Trailing terminator versus trailing empty field.**
`"a,b\n"` should yield `[["a","b"]]`, not `[["a","b"],[""]]`. The final flush is guarded: if we ended on a newline, both `row` and `field` are empty and we skip pushing. But `"a,"` ends with `field === ""` and `row === ["a"]`, so we do flush — giving `["a",""]` as expected.

**6. Unterminated quotes.**
If the file ends while `inQuotes` is true, we still flush what we have rather than dropping data. In a stricter pipeline you might want to throw here — swap the trailing `if` for an explicit error if your service prefers fail-fast semantics.

**7. BOM.**
The UTF-8 byte-order mark (`\uFEFF`) is invisible but rides along at the start of many exported files. Stripping it once up front prevents a phantom `\uFEFF` prefix on the first header cell.

## Usage

```ts
const rows = parseCsv(csvText);
const [headers, ...records] = rows;
const objects = records.map(r =>
  Object.fromEntries(headers.map((h, i) => [h, r[i] ?? ""]))
);
```

## Notes for production

- **Performance:** This is a character-by-character loop with `field += ch`, which is fine up to a few MB. For very large files, switch to pushing single-char strings into an array and `join` at the end, or read streaming chunks and feed a resumable state machine.
- **Memory:** The whole input and output live in memory. If you need to process GB-scale files, wrap the same state machine in a chunked reader.
- **Type coercion:** Everything comes back as `string`. Numbers, nulls, booleans — decide those rules at the boundary (a separate `coerce` pass keeps the parser honest).
- **Custom dialects:** If you ever need `;` delimiters (common in European locales), parameterize `DELIM` and `QUOTE` at the top of the function — the state machine doesn't change.

# Minimal Consistent Hashing Ring (Go)

```go
package main

import (
	"fmt"
	"hash/fnv"
	"sort"
	"sync"
)

type Ring struct {
	mu       sync.RWMutex
	replicas int
	keys     []uint32          // sorted hash positions
	hashMap  map[uint32]string // position -> node name
}

func NewRing(replicas int) *Ring {
	return &Ring{replicas: replicas, hashMap: make(map[uint32]string)}
}

func (r *Ring) Add(node string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for i := 0; i < r.replicas; i++ {
		h := hash(fmt.Sprintf("%s#%d", node, i))
		r.keys = append(r.keys, h)
		r.hashMap[h] = node
	}
	sort.Slice(r.keys, func(i, j int) bool { return r.keys[i] < r.keys[j] })
}

func (r *Ring) Remove(node string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for i := 0; i < r.replicas; i++ {
		h := hash(fmt.Sprintf("%s#%d", node, i))
		delete(r.hashMap, h)
		idx := sort.Search(len(r.keys), func(j int) bool { return r.keys[j] >= h })
		if idx < len(r.keys) && r.keys[idx] == h {
			r.keys = append(r.keys[:idx], r.keys[idx+1:]...)
		}
	}
}

func (r *Ring) Get(key string) string {
	r.mu.RLock()
	defer r.mu.RUnlock()
	if len(r.keys) == 0 {
		return ""
	}
	h := hash(key)
	idx := sort.Search(len(r.keys), func(i int) bool { return r.keys[i] >= h })
	if idx == len(r.keys) {
		idx = 0 // wrap around
	}
	return r.hashMap[r.keys[idx]]
}

func hash(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}

func main() {
	r := NewRing(100)
	for _, n := range []string{"node-a", "node-b", "node-c"} {
		r.Add(n)
	}
	for _, k := range []string{"user:1", "user:2", "session:abc"} {
		fmt.Printf("%s -> %s\n", k, r.Get(k))
	}
}
```

## Two ways this fails under load

**1. Global write lock stalls the whole cluster during rebalancing.**
`Add`/`Remove` take the exclusive `mu.Lock()` and rebuild/scan the full `keys` slice. Under load with traffic flowing through `Get`, every incoming request blocks on `RLock` while a node joins or leaves. Hot paths see a latency spike proportional to ring size × replicas. Worse, `append(r.keys[:idx], r.keys[idx+1:]...)` mutates the backing array in place, so any concurrent reader holding a prior slice could see torn state if you relaxed locking. A production ring should use copy-on-write snapshots per generation.

**2. Hash distribution + VM count aren't enough to dodge hot spots.**
With FNV-1a and default `replicas`, virtual nodes still cluster unevenly, so one physical node often absorbs a disproportionate share of keys. Add the well-known "hot key" problem (e.g., a viral user ID) and one node saturates while the ring balancer thinks everything is fine — consistent hashing only spreads *keys*, not *load*. Remedies are dedicated: jump hash, bounded-load consistent hashing (Google's paper), or per-key rate limiting — none of which this minimal version has.

```go
package retry

import (
	"context"
	"errors"
	"fmt"
	"math"
	"math/rand"
	"time"
)

var ErrInvalidConfig = errors.New("retry: invalid config")

type Config struct {
	MaxAttempts int
	BaseDelay   time.Duration
	MaxDelay    time.Duration
	Jitter      float64 // 0.0 = no jitter, 1.0 = full jitter
	RetryIf     func(error) bool
}

type Retryer struct {
	MaxAttempts int
	BaseDelay   time.Duration
	MaxDelay    time.Duration
	Jitter      float64
	RetryIf     func(error) bool

	// Injected for tests.
	Sleep func(ctx context.Context, d time.Duration) error
	Rand  func() float64
}

func New(cfg Config) (*Retryer, error) {
	if cfg.MaxAttempts <= 0 {
		return nil, fmt.Errorf("%w: MaxAttempts must be > 0", ErrInvalidConfig)
	}
	if cfg.BaseDelay < 0 {
		return nil, fmt.Errorf("%w: BaseDelay must be >= 0", ErrInvalidConfig)
	}
	if cfg.MaxDelay < 0 {
		return nil, fmt.Errorf("%w: MaxDelay must be >= 0", ErrInvalidConfig)
	}
	if cfg.Jitter < 0 || cfg.Jitter > 1 {
		return nil, fmt.Errorf("%w: Jitter must be in [0,1]", ErrInvalidConfig)
	}

	return &Retryer{
		MaxAttempts: cfg.MaxAttempts,
		BaseDelay:   cfg.BaseDelay,
		MaxDelay:    cfg.MaxDelay,
		Jitter:      cfg.Jitter,
		RetryIf:     cfg.RetryIf,
		Sleep:       sleepContext,
		Rand:        rand.Float64,
	}, nil
}

func (r *Retryer) Do(ctx context.Context, fn func(ctx context.Context) error) error {
	if fn == nil {
		return errors.New("retry: fn is nil")
	}

	var lastErr error

	for attempt := 1; attempt <= r.MaxAttempts; attempt++ {
		if err := ctx.Err(); err != nil {
			return err
		}

		lastErr = fn(ctx)
		if lastErr == nil {
			return nil
		}

		if r.RetryIf != nil && !r.RetryIf(lastErr) {
			return lastErr
		}

		if attempt == r.MaxAttempts {
			break
		}

		delay := r.delay(attempt)
		if err := r.Sleep(ctx, delay); err != nil {
			return err
		}
	}

	return lastErr
}

func (r *Retryer) delay(attempt int) time.Duration {
	if r.BaseDelay <= 0 {
		return 0
	}

	d := r.BaseDelay

	// Exponential growth: BaseDelay * 2^(attempt-1)
	for i := 1; i < attempt; i++ {
		const maxDuration = time.Duration(1<<63 - 1)

		if d > maxDuration/2 {
			d = maxDuration
			break
		}
		d *= 2

		if r.MaxDelay > 0 && d >= r.MaxDelay {
			d = r.MaxDelay
			break
		}
	}

	if r.MaxDelay > 0 && d > r.MaxDelay {
		d = r.MaxDelay
	}

	if r.Jitter <= 0 {
		return d
	}

	u := r.Rand()
	if u < 0 {
		u = 0
	}
	if u >= 1 {
		u = math.Nextafter(1, 0)
	}

	// Keep delay in [d*(1-Jitter), d].
	factor := 1 - r.Jitter*u
	return time.Duration(float64(d) * factor)
}

func sleepContext(ctx context.Context, d time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if d <= 0 {
		return nil
	}

	t := time.NewTimer(d)
	defer t.Stop()

	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}
