package retry

import (
	"context"
	"errors"
	"math/rand"
	"time"
)

type Config struct {
	MaxAttempts int
	BaseDelay   time.Duration
	MaxDelay    time.Duration // 0 = no cap
	Jitter      float64       // 0..1
	RetryIf     func(error) bool
}

type Retryer struct {
	Config
	// Injected for testing.
	Sleep func(ctx context.Context, d time.Duration) error
	Rand  func() float64
}

func New(cfg Config) (*Retryer, error) {
	switch {
	case cfg.MaxAttempts <= 0:
		return nil, errors.New("MaxAttempts must be > 0")
	case cfg.BaseDelay < 0, cfg.MaxDelay < 0:
		return nil, errors.New("delays must be >= 0")
	case cfg.Jitter < 0 || cfg.Jitter > 1:
		return nil, errors.New("Jitter must be in [0,1]")
	}
	return &Retryer{
		Config: cfg,
		Sleep:  sleepContext,
		Rand:   rand.Float64,
	}, nil
}

func (r *Retryer) Do(ctx context.Context, fn func(context.Context) error) error {
	if fn == nil {
		return errors.New("retry: nil fn")
	}
	var err error
	for i := 1; i <= r.MaxAttempts; i++ {
		if err = ctx.Err(); err != nil {
			return err
		}
		if err = fn(ctx); err == nil {
			return nil
		}
		if r.RetryIf != nil && !r.RetryIf(err) {
			return err
		}
		if i == r.MaxAttempts {
			break
		}
		if err = r.Sleep(ctx, r.delay(i)); err != nil {
			return err
		}
	}
	return err
}

func (r *Retryer) delay(attempt int) time.Duration {
	if r.BaseDelay <= 0 {
		return 0
	}
	d := r.BaseDelay
	for i := 1; i < attempt; i++ {
		if d > time.Duration(1<<62) {
			d = time.Duration(1<<63 - 1)
			break
		}
		d *= 2
		if r.MaxDelay > 0 && d >= r.MaxDelay {
			break
		}
	}
	if r.MaxDelay > 0 && d > r.MaxDelay {
		d = r.MaxDelay
	}
	if r.Jitter > 0 {
		d = time.Duration(float64(d) * (1 - r.Jitter*r.Rand()))
	}
	return d
}

func sleepContext(ctx context.Context, d time.Duration) error {
	if d <= 0 {
		return ctx.Err()
	}
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}
