    std::this_thread::sleep_for(150ms);
    CHECK(calls.load() == 1);
}

} // namespace

int main() {
    test_single_call();
    test_rapid_calls_coalesce();
    test_calls_separated_by_more_than_window_run_twice();
    test_flush_runs_immediately_and_cancels_timer();
    test_cancel_prevents_call();
    test_destructor_drops_pending_call();
    test_callback_exception_does_not_kill_worker();
    test_concurrent_calls_coalesce();

    std::cout << "All debounce tests passed\n";
}
