# Arithmetic Expression Tokenizer & Evaluator

Below is a complete implementation with a tokenizer, a precedence-aware parser (shunting-yard), and a comprehensive test suite.

## Implementation

```typescript
// arithmetic.ts

export type TokenType =
  | "NUMBER"
  | "PLUS"
  | "MINUS"
  | "STAR"
  | "SLASH"
  | "CARET"
  | "LPAREN"
  | "RPAREN";

export interface Token {
  type: TokenType;
  value: string;
  position: number;
}

export class TokenizeError extends Error {}
export class ParseError extends Error {}

const SINGLE_CHAR_TOKENS: Record<string, TokenType> = {
  "+": "PLUS",
  "-": "MINUS",
  "*": "STAR",
  "/": "SLASH",
  "^": "CARET",
  "(": "LPAREN",
  ")": "RPAREN",
};

export function tokenize(input: string): Token[] {
  if (typeof input !== "string") {
    throw new TokenizeError("Input must be a string");
  }

  const tokens: Token[] = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    // Skip whitespace
    if (/\s/.test(ch)) {
      i++;
      continue;
    }

    // Numbers: [0-9]+ ( '.' [0-9]+ )?  — supports ints and decimals.
    if (/[0-9]/.test(ch) || (ch === "." && /[0-9]/.test(input[i + 1] ?? ""))) {
      const start = i;
      let seenDot = false;
      while (i < input.length && (/[0-9]/.test(input[i]) || (!seenDot && input[i] === "."))) {
        if (input[i] === ".") seenDot = true;
        i++;
      }
      const raw = input.slice(start, i);
      // Reject things like "1." (no digits after dot) — the loop wouldn't produce
      // this, but guard against ".5" when we start on a dot with no leading digit
      // and any odd numeric forms.
      if (raw === "." || raw.endsWith(".")) {
        throw new TokenizeError(`Invalid number at position ${start}: "${raw}"`);
      }
      if (!Number.isFinite(Number(raw))) {
        throw new TokenizeError(`Invalid number at position ${start}: "${raw}"`);
      }
      tokens.push({ type: "NUMBER", value: raw, position: start });
      continue;
    }

    // Operators, parentheses
    const tokType = SINGLE_CHAR_TOKENS[ch];
    if (tokType) {
      tokens.push({ type: tokType, value: ch, position: i });
      i++;
      continue;
    }

    throw new TokenizeError(`Unexpected character "${ch}" at position ${i}`);
  }

  return tokens;
}

interface OperatorInfo {
  precedence: number;
  rightAssociative: boolean;
}

const OPERATORS: Record<string, OperatorInfo> = {
  "+": { precedence: 1, rightAssociative: false },
  "-": { precedence: 1, rightAssociative: false },
  "*": { precedence: 2, rightAssociative: false },
  "/": { precedence: 2, rightAssociative: false },
  "^": { precedence: 3, rightAssociative: true },
};

export function evaluate(expression: string): number {
  const tokens = tokenize(expression);
  if (tokens.length === 0) {
    throw new ParseError("Empty expression");
  }

  const output: Token[] = [];
  const ops: (Token & { op: string })[] = [];
  let prev: Token | null = null;
  let expectingOperand = true;

  for (const tok of tokens) {
    switch (tok.type) {
      case "NUMBER":
        output.push(tok);
        expectingOperand = false;
        break;

      case "LPAREN":
        ops.push({ ...tok, op: tok.value });
        expectingOperand = true;
        break;

      case "RPAREN": {
        let found = false;
        while (ops.length > 0) {
          const top = ops.pop()!;
          if (top.op === "(") {
            found = true;
            break;
          }
          output.push({ type: tokenFromOp(top.op), value: top.op, position: top.position });
        }
        if (!found) {
          throw new ParseError(`Mismatched ')' at position ${tok.position}`);
        }
        expectingOperand = false;
        break;
      }

      default: {
        // It's an operator
        const op = tok.value;

        // Unary plus/minus handling: if we're expecting an operand and see
        // '+' or '-', fold it into the following number via a synthetic 0 -
        // We'll use a simpler trick: push a synthetic 0 for unary minus.
        if (expectingOperand && (op === "+" || op === "-")) {
          if (op === "-") {
            output.push({ type: "NUMBER", value: "0", position: tok.position });
            ops.push({ ...tok, op: "-", type: "MINUS" });
          }
          // Unary '+' is a no-op
          break;
        }

        if (expectingOperand) {
          throw new ParseError(`Unexpected operator "${op}" at position ${tok.position}`);
        }

        const info = OPERATORS[op];
        while (ops.length > 0) {
          const top = ops[ops.length - 1];
          if (top.op === "(") break;
          const topInfo = OPERATORS[top.op];
          if (
            topInfo.precedence > info.precedence ||
            (topInfo.precedence === info.precedence && !info.rightAssociative)
          ) {
            ops.pop();
            output.push({ type: tokenFromOp(top.op), value: top.op, position: top.position });
          } else {
            break;
          }
        }
        ops.push({ ...tok, op });
        expectingOperand = true;
        break;
      }
    }
    prev = tok;
  }

  if (expectingOperand && prev && prev.type !== "LPAREN") {
    throw new ParseError(`Expression ends with operator at position ${prev.position}`);
  }

  while (ops.length > 0) {
    const top = ops.pop()!;
    if (top.op === "(") {
      throw new ParseError(`Mismatched '(' at position ${top.position}`);
    }
    output.push({ type: tokenFromOp(top.op), value: top.op, position: top.position });
  }

  // Evaluate RPN
  const stack: number[] = [];
  for (const tok of output) {
    if (tok.type === "NUMBER") {
      stack.push(Number(tok.value));
      continue;
    }
    if (stack.length < 2) {
      throw new ParseError(`Invalid expression near position ${tok.position}`);
    }
    const b = stack.pop()!;
    const a = stack.pop()!;
    let result: number;
    switch (tok.type) {
      case "PLUS":  result = a + b; break;
      case "MINUS": result = a - b; break;
      case "STAR":  result = a * b; break;
      case "SLASH":
        if (b === 0) throw new ParseError("Division by zero");
        result = a / b;
        break;
      case "CARET": result = Math.pow(a, b); break;
      default: throw new ParseError(`Unknown operator ${tok.type}`);
    }
    stack.push(result);
  }

  if (stack.length !== 1) {
    throw new ParseError("Malformed expression");
  }
  return stack[0];
}

function tokenFromOp(op: string): TokenType {
  switch (op) {
    case "+": return "PLUS";
    case "-": return "MINUS";
    case "*": return "STAR";
    case "/": return "SLASH";
    case "^": return "CARET";
    default: throw new ParseError(`Unknown operator ${op}`);
  }
}
```

## Unit Tests

Using Jest, but the assertions translate directly to Vitest or Mocha.

```typescript
// arithmetic.test.ts
import {
  tokenize,
  evaluate,
  TokenizeError,
  ParseError,
  Token,
} from "./arithmetic";

describe("tokenize", () => {
  const t = (input: string): Token[] => tokenize(input);

  test("single integer", () => {
    expect(t("42")).toEqual([{ type: "NUMBER", value: "42", position: 0 }]);
  });

  test("single decimal", () => {
    expect(t("3.14")).toEqual([{ type: "NUMBER", value: "3.14", position: 0 }]);
  });

  test("leading dot decimal", () => {
    expect(t(".5")).toEqual([{ type: "NUMBER", value: ".5", position: 0 }]);
  });

  test("all operators", () => {
    expect(t("+-*/^")).toEqual([
      { type: "PLUS", value: "+", position: 0 },
      { type: "MINUS", value: "-", position: 1 },
      { type: "STAR", value: "*", position: 2 },
      { type: "SLASH", value: "/", position: 3 },
      { type: "CARET", value: "^", position: 4 },
    ]);
  });

  test("parentheses", () => {
    expect(t("()")).toEqual([
      { type: "LPAREN", value: "(", position: 0 },
      { type: "RPAREN", value: ")", position: 1 },
    ]);
  });

  test("whitespace is skipped and positions are correct", () => {
    expect(t("  1 +  2 ")).toEqual([
      { type: "NUMBER", value: "1", position: 2 },
      { type: "PLUS", value: "+", position: 4 },
      { type: "NUMBER", value: "2", position: 7 },
    ]);
  });

  test("empty input yields empty array", () => {
    expect(t("")).toEqual([]);
    expect(t("   ")).toEqual([]);
  });

  test("throws on unknown character", () => {
    expect(() => t("1 $ 2")).toThrow(TokenizeError);
  });

  test("throws on bare dot", () => {
    expect(() => t(".")).toThrow(TokenizeError);
  });

  test("throws on multiline comment-like input", () => {
    expect(() => t("1 // 2")).toThrow(TokenizeError);
  });
});

describe("evaluate: basic arithmetic", () => {
  test.each<[string, number]>([
    ["1", 1],
    ["1 + 2", 3],
    ["10 - 3 - 2", 5],           // left-assoc
    ["2 * 3", 6],
    ["8 / 4 / 2", 1],            // left-assoc
    ["2 + 3 * 4", 14],           // precedence
    ["(2 + 3) * 4", 20],         // parentheses override
    ["2 ^ 3", 8],
    ["2 ^ 3 ^ 2", 512],          // right-assoc: 2^(3^2)
    ["2 + 3 * 4 - 5 / 5", 13],   // mix
    ["((1 + 2) * (3 + 4))", 21], // nested
    ["3.5 + 1.25", 4.75],        // decimals
    ["1 + 2 * 3 ^ 2", 19],       // precedence: 3^2=9, *2=18, +1
  ])("%s => %d", (expr, expected) => {
    expect(evaluate(expr)).toBe(expected);
  });
});

