#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <stdexcept>
#include <string>
#include <functional>
#include <utility>

using ll = long long;
const ll INF = std::numeric_limits<ll>::max() / 4;

struct Edge {
    int to;
    ll weight;
};

using Graph = std::vector<std::vector<Edge>>;

std::vector<ll> dijkstra(const Graph& graph, int source) {
    const int n = static_cast<int>(graph.size());
    if (source < 0 || source >= n) {
        throw std::out_of_range("source vertex out of range");
    }
    for (int u = 0; u < n; ++u) {
        for (const Edge& e : graph[u]) {
            if (e.to < 0 || e.to >= n) {
                throw std::out_of_range("edge destination out of range");
            }
            if (e.weight < 0) {
                throw std::invalid_argument("Dijkstra requires non-negative edge weights");
            }
        }
    }

    std::vector<ll> dist(n, INF);
    using State = std::pair<ll, int>; // (distance, vertex)
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;

    dist[source] = 0;
    pq.push({0, source});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d != dist[u]) continue; // stale entry

        for (const Edge& e : graph[u]) {
            // Avoid overflow; INF/4 leaves plenty of room for normal weights.
            if (d > INF - e.weight) continue;
            ll nd = d + e.weight;
            if (nd < dist[e.to]) {
                dist[e.to] = nd;
                pq.push({nd, e.to});
            }
        }
    }

    return dist;
}

