#include <cuda_runtime.h>
#include <thrust/device_ptr.h>
#include <thrust/scan.h>

#include <algorithm>
#include <cassert>
#include <iostream>
#include <stdexcept>
#include <vector>

#define CUDA_CHECK(call)                                                     \
    do {                                                                     \
        cudaError_t err = (call);                                            \
        if (err != cudaSuccess) {                                            \
            throw std::runtime_error(std::string("CUDA error: ") +           \
                                     cudaGetErrorString(err));               \
        }                                                                    \
    } while (0)

namespace {

// -----------------------------------------------------------------------------
// Kernels
// -----------------------------------------------------------------------------

__global__ void countOutdegreeKernel(const int* __restrict__ src,
                                     int numEdges,
                                     int* __restrict__ outdegree) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < numEdges) {
        atomicAdd(&outdegree[src[i]], 1);
    }
}

__global__ void fillAdjacencyKernel(const int* __restrict__ src,
                                    const int* __restrict__ dst,
                                    int numEdges,
                                    int* __restrict__ cursor,
                                    int* __restrict__ adjCols) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < numEdges) {
        int u = src[i];
        int pos = atomicAdd(&cursor[u], 1);
        adjCols[pos] = dst[i];
    }
}

__global__ void countIndegreeKernel(const int* __restrict__ dst,
                                    int numEdges,
                                    int* __restrict__ indegree) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < numEdges) {
        atomicAdd(&indegree[dst[i]], 1);
    }
}

__global__ void initFrontierKernel(int numVertices,
                                   const int* __restrict__ indegree,
                                   int* __restrict__ frontier,
                                   int* __restrict__ frontierCount,
                                   int* __restrict__ order,
                                   int* __restrict__ orderCount) {
    int v = blockIdx.x * blockDim.x + threadIdx.x;
    if (v < numVertices && indegree[v] == 0) {
        int pos = atomicAdd(frontierCount, 1);
        frontier[pos] = v;

        int orderPos = atomicAdd(orderCount, 1);
        order[orderPos] = v;
    }
}

__global__ void processFrontierKernel(int frontierSize,
                                      const int* __restrict__ rowOffsets,
                                      const int* __restrict__ adjCols,
                                      const int* __restrict__ frontier,
                                      int* __restrict__ indegree,
                                      int* __restrict__ nextFrontier,
                                      int* __restrict__ nextFrontierCount,
                                      int* __restrict__ order,
                                      int* __restrict__ orderCount) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= frontierSize) return;

    int u = frontier[idx];
    int begin = rowOffsets[u];
    int end = rowOffsets[u + 1];

    for (int e = begin; e < end; ++e) {
        int v = adjCols[e];

        // old is the indegree before decrement.
        int old = atomicSub(&indegree[v], 1);

        // If old == 1, indegree became 0.
        if (old == 1) {
            int pos = atomicAdd(nextFrontierCount, 1);
            nextFrontier[pos] = v;

            int orderPos = atomicAdd(orderCount, 1);
            order[orderPos] = v;
        }
    }
}

// -----------------------------------------------------------------------------
// Host helpers
// -----------------------------------------------------------------------------

inline int blocksFor(int n, int threads = 256) {
    return (n + threads - 1) / threads;
}

}  // namespace

// -----------------------------------------------------------------------------
// Public API
// -----------------------------------------------------------------------------
//
// Returns true if the graph is a DAG and h_order contains a valid topological
// order of all vertices.
//
// Returns false if the graph contains a cycle. In that case h_order contains
// only the vertices that could be processed before the cycle was detected.
//
bool topologicalSortCUDA(int numVertices,
                         const std::vector<int>& h_src,
                         const std::vector<int>& h_dst,
                         std::vector<int>& h_order) {
    h_order.clear();

    if (h_src.size() != h_dst.size()) {
        throw std::invalid_argument("src and dst must have the same size");
    }

    const int numEdges = static_cast<int>(h_src.size());

    if (numVertices < 0) {
        throw std::invalid_argument("numVertices must be non-negative");
    }

    for (int u : h_src) {
        if (u < 0 || u >= numVertices) {
            throw std::out_of_range("src vertex out of range");
        }
    }
    for (int v : h_dst) {
        if (v < 0 || v >= numVertices) {
            throw std::out_of_range("dst vertex out of range");
        }
    }

