    int* d_dst = nullptr;
    int* d_outdegree = nullptr;
    int* d_rowOffsets = nullptr;
    int* d_cursor = nullptr;
    int* d_adjCols = nullptr;
    int* d_indegree = nullptr;
    int* d_frontierA = nullptr;
    int* d_frontierB = nullptr;
    int* d_frontierCountA = nullptr;
    int* d_frontierCountB = nullptr;
    int* d_order = nullptr;
    int* d_orderCount = nullptr;

    try {
        if (numEdges > 0) {
            CUDA_CHECK(cudaMalloc(&d_src, numEdges * sizeof(int)));
            CUDA_CHECK(cudaMalloc(&d_dst, numEdges * sizeof(int)));
            CUDA_CHECK(cudaMemcpy(d_src, h_src.data(), numEdges * sizeof(int),
                                  cudaMemcpyHostToDevice));
            CUDA_CHECK(cudaMemcpy(d_dst, h_dst.data(), numEdges * sizeof(int),
                                  cudaMemcpyHostToDevice));
        }

        CUDA_CHECK(cudaMalloc(&d_outdegree, numVertices * sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_rowOffsets, (numVertices + 1) * sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_cursor, numVertices * sizeof(int)));
        if (numEdges > 0) {
            CUDA_CHECK(cudaMalloc(&d_adjCols, numEdges * sizeof(int)));
        }

        CUDA_CHECK(cudaMalloc(&d_indegree, numVertices * sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_frontierA, numVertices * sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_frontierB, numVertices * sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_frontierCountA, sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_frontierCountB, sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_order, numVertices * sizeof(int)));
        CUDA_CHECK(cudaMalloc(&d_orderCount, sizeof(int)));

        // Build CSR out-adjacency.
        CUDA_CHECK(cudaMemset(d_outdegree, 0, numVertices * sizeof(int)));

        if (numEdges > 0) {
            countOutdegreeKernel<<<blocksFor(numEdges), 256>>>(
                d_src, numEdges, d_outdegree);
            CUDA_CHECK(cudaGetLastError());

            // Inclusive scan into rowOffsets[1..numVertices].
            thrust::device_ptr<int> outdegPtr(d_outdegree);
            thrust::device_ptr<int> rowOffPtr(d_rowOffsets);
            thrust::inclusive_scan(thrust::device, outdegPtr,
