```go
package reservoir

import "math/rand"

// Sample returns k items from an unknown-length stream produced by next.
// next returns (item, true) for each item and (zero, false) at EOF.
func Sample[T any](r *rand.Rand, k int, next func() (T, bool)) []T {
	if k <= 0 {
		return nil
	}

	reservoir := make([]T, 0, k)

	for i := 0; ; i++ {
		item, ok := next()
		if !ok {
			break
		}

		if i < k {
			reservoir = append(reservoir, item)
			continue
		}

		// For the (i+1)-th item, keep it with probability k/(i+1).
		j := r.Intn(i + 1)
		if j < k {
			reservoir[j] = item
		}
	}

	return reservoir
}
```

This is reservoir sampling, Algorithm R. Memory is `O(k)` and time is `O(n)`.

Two ways it can fail under load:

1. **Randomness-source contention.**  
   If many goroutines share one `*rand.Rand`, it is not safe and will race/corrupt. If they use package-level `rand.Intn`, it is safe but serialized behind a global lock, causing contention and latency collapse at high QPS. Use per-worker RNGs or sharded RNGs.

2. **Memory/backpressure explosion.**  
   The sampler holds `k` items for the entire stream lifetime. Under high concurrency, memory becomes roughly `concurrency * k * sizeof(item)`. If `k` is large, items are large, or items retain large backing arrays, this can OOM. Also, if the stream is effectively endless and the caller cannot cancel or apply backpressure, goroutines/buffers can accumulate while waiting for a result that never comes.

SQL is a set-based language, so a true O(1) LRU cache is best implemented with a stored procedure using a doubly linked list stored in tables. The number of rows touched per operation is constant, and with a hash index on the cache key, lookups are O(1) average. Below is a PostgreSQL PL/pgSQL implementation.

### Schema

```sql
CREATE TABLE lru_cache (
    key       text PRIMARY KEY,
    value     text NOT NULL,
    prev_key  text,
    next_key  text
);

-- Optional hash index for O(1) average key lookup (PostgreSQL)
CREATE INDEX lru_cache_key_hash ON lru_cache USING hash (key);

CREATE TABLE lru_meta (
    id        int PRIMARY KEY CHECK (id = 1),
    head_key  text,
    tail_key  text,
    capacity  int NOT NULL,
    size      int NOT NULL DEFAULT 0
);

-- Initialize with capacity = 3
INSERT INTO lru_meta (id, head_key, tail_key, capacity, size)
VALUES (1, NULL, NULL, 3, 0)
ON CONFLICT (id) DO UPDATE SET capacity = EXCLUDED.capacity;
```

### Helper: move an existing key to the front

```sql
CREATE OR REPLACE FUNCTION lru_move_to_front(p_key text)
RETURNS void AS $$
DECLARE
    v_head text;
    v_tail text;
    v_prev text;
    v_next text;
BEGIN
    SELECT head_key, tail_key INTO v_head, v_tail
    FROM lru_meta WHERE id = 1 FOR UPDATE;

    IF v_head = p_key THEN
        RETURN;
    END IF;

    SELECT prev_key, next_key INTO v_prev, v_next
    FROM lru_cache WHERE key = p_key;

    -- Unlink p_key from its current position
    IF v_prev IS NOT NULL THEN
        UPDATE lru_cache SET next_key = v_next WHERE key = v_prev;
    END IF;
    IF v_next IS NOT NULL THEN
        UPDATE lru_cache SET prev_key = v_prev WHERE key = v_next;
    END IF;

    -- If p_key was the tail, update tail pointer
    IF v_tail = p_key THEN
        UPDATE lru_meta SET tail_key = v_prev WHERE id = 1;
    END IF;

    -- Link p_key at the front
    UPDATE lru_cache SET prev_key = NULL, next_key = v_head WHERE key = p_key;
    IF v_head IS NOT NULL THEN
        UPDATE lru_cache SET prev_key = p_key WHERE key = v_head;
    END IF;

    UPDATE lru_meta SET head_key = p_key WHERE id = 1;
END;
$$ LANGUAGE plpgsql;
```

### Helper: evict the least recently used (tail)

```sql
CREATE OR REPLACE FUNCTION lru_evict_tail()
RETURNS void AS $$
DECLARE
    v_tail text;
    v_prev text;
BEGIN
    SELECT tail_key INTO v_tail
    FROM lru_meta WHERE id = 1 FOR UPDATE;

    IF v_tail IS NULL THEN
        RETURN;
    END IF;

    SELECT prev_key INTO v_prev
    FROM lru_cache WHERE key = v_tail;

    DELETE FROM lru_cache WHERE key = v_tail;

    IF v_prev IS NOT NULL THEN
        UPDATE lru_cache SET next_key = NULL WHERE key = v_prev;
        UPDATE lru_meta
        SET tail_key = v_prev, size = size - 1
        WHERE id = 1;
    ELSE
        -- Only one node existed
        UPDATE lru_meta
        SET head_key = NULL, tail_key = NULL, size = size - 1
        WHERE id = 1;
    END IF;
END;
$$ LANGUAGE plpgsql;
```

### get(key)

```sql
CREATE OR REPLACE FUNCTION lru_get(p_key text)
RETURNS text AS $$
DECLARE
    v_value text;
BEGIN
    SELECT value INTO v_value
    FROM lru_cache WHERE key = p_key;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    PERFORM lru_move_to_front(p_key);
    RETURN v_value;
END;
$$ LANGUAGE plpgsql;
```

### put(key, value)

```sql
CREATE OR REPLACE FUNCTION lru_put(p_key text, p_value text)
RETURNS void AS $$
DECLARE
    v_exists   boolean;
    v_capacity int;
    v_size     int;
    v_head     text;
BEGIN
    SELECT capacity, size, head_key
    INTO v_capacity, v_size, v_head
    FROM lru_meta WHERE id = 1 FOR UPDATE;

    IF v_capacity = 0 THEN
        RETURN;
    END IF;

    SELECT EXISTS(SELECT 1 FROM lru_cache WHERE key = p_key)
    INTO v_exists;

    IF v_exists THEN
        UPDATE lru_cache SET value = p_value WHERE key = p_key;
        PERFORM lru_move_to_front(p_key);
    ELSE
        IF v_size >= v_capacity THEN
            PERFORM lru_evict_tail();
            SELECT head_key INTO v_head
            FROM lru_meta WHERE id = 1;
        END IF;

        INSERT INTO lru_cache (key, value, prev_key, next_key)
        VALUES (p_key, p_value, NULL, v_head);

        IF v_head IS NOT NULL THEN
            UPDATE lru_cache SET prev_key = p_key WHERE key = v_head;
        END IF;

        UPDATE lru_meta
        SET head_key = p_key,
            tail_key = COALESCE(tail_key, p_key),
            size = size + 1
        WHERE id = 1;
    END IF;
END;
$$ LANGUAGE plpgsql;
```

### Usage example

```sql
-- Set capacity to 3
UPDATE lru_meta SET capacity = 3 WHERE id = 1;

SELECT lru_put('a', '1');
