def matmul_tiled(A, B, block=32):
    """C = A @ B for rectangular list-of-lists matrices."""
    n = len(A)
    k = len(B)
    m = len(B[0])
    C = [[0] * m for _ in range(n)]

    for ii in range(0, n, block):
        for kk in range(0, k, block):
            for jj in range(0, m, block):
