#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

typedef struct {
    int *a;
    size_t n;
    size_t cap;
} MinHeap;

static void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

static void sift_down(MinHeap *h, size_t i) {
    for (;;) {
        size_t l = 2 * i + 1;
        size_t r = l + 1;
        size_t m = i;

        if (l < h->n && h->a[l] < h->a[m]) m = l;
        if (r < h->n && h->a[r] < h->a[m]) m = r;
        if (m == i) return;

        swap(&h->a[i], &h->a[m]);
        i = m;
    }
}

static int reserve(MinHeap *h, size_t need) {
    if (need <= h->cap) return 0;

    size_t nc = h->cap ? h->cap : 1;
    while (nc < need) {
        if (nc > SIZE_MAX / 2) {
            nc = need;
            break;
        }
        nc *= 2;
    }

    if (nc > SIZE_MAX / sizeof *h->a) return -1;

    int *p = realloc(h->a, nc * sizeof *p);
    if (!p) return -1;

    h->a = p;
    h->cap = nc;
    return 0;
}

int heap_init(MinHeap *h, size_t cap) {
    h->a = NULL;
    h->n = 0;
    h->cap = 0;
    return reserve(h, cap);
}

void heap_free(MinHeap *h) {
    free(h->a);
    h->a = NULL;
    h->n = 0;
    h->cap = 0;
}

int heap_push(MinHeap *h, int v) {
    if (reserve(h, h->n + 1) != 0) return -1;

    size_t i = h->n++;
    h->a[i] = v;

    while (i > 0) {
        size_t p = (i - 1) / 2;
        if (h->a[p] <= h->a[i]) break;
        swap(&h->a[p], &h->a[i]);
        i = p;
    }

    return 0;
}

int heap_pop(MinHeap *h, int *out) {
    if (h->n == 0) return -1;

    if (out) *out = h->a[0];

    h->a[0] = h->a[--h->n];
    if (h->n > 0) sift_down(h, 0);

    return 0;
}

int heapify(MinHeap *h, const int *arr, size_t n) {
    if (reserve(h, n) != 0) return -1;

    for (size_t i = 0; i < n; ++i) {
        h->a[i] = arr[i];
    }

    h->n = n;

    for (size_t i = n / 2; i > 0; ) {
        --i;
        sift_down(h, i);
    }

    return 0;
}
```

Two ways it could fail under load:

1. **Memory exhaustion / realloc failure.**  
   `heap_push()` and `heapify()` grow the heap with `realloc()`. Under sustained load, the heap can grow until allocation fails. The code returns `-1`, but if callers ignore that, pushes are silently dropped or later code may corrupt state.

2. **Integer overflow with unbounded growth.**  
   Expressions such as `h->n + 1`, `2 * i + 1`, or capacity growth calculations can overflow `size_t` for extremely large heaps. That can wrap to a small value and cause out-of-bounds writes.

A third practical issue: this implementation is **not thread-safe**; concurrent `push`/`pop` from multiple threads will corrupt the heap without external locking.

