import java.util.Objects;
import java.util.concurrent.Consumer;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

public final class Debouncer<T> implements AutoCloseable {
    private final long delay;
    private final TimeUnit unit;
    private final Consumer<T> action;
    private final ScheduledExecutorService scheduler;
    private final boolean ownsScheduler;
    private final Object lock = new Object();

    private ScheduledFuture<?> pendingTask;
    private long generation;
    private T latestValue;
    private boolean closed;

    /**
     * Creates a debouncer with its own single-thread scheduler.
     * The thread is daemon so it won't keep the JVM alive by itself.
     */
    public Debouncer(long delay, TimeUnit unit, Consumer<T> action) {
        this(
            delay,
            unit,
            action,
            Executors.newSingleThreadScheduledExecutor(r -> {
                Thread t = new Thread(r, "debouncer");
                t.setDaemon(true);
                return t;
            }),
            true
        );
    }

    /**
     * Creates a debouncer using a caller-provided scheduler.
     * The scheduler is not shut down by this debouncer.
     */
    public Debouncer(
            long delay,
            TimeUnit unit,
            Consumer<T> action,
            ScheduledExecutorService scheduler
    ) {
        this(delay, unit, action, scheduler, false);
    }

    private Debouncer(
            long delay,
            TimeUnit unit,
            Consumer<T> action,
            ScheduledExecutorService scheduler,
            boolean ownsScheduler
    ) {
        if (delay < 0) {
            throw new IllegalArgumentException("delay must be >= 0");
        }
        this.delay = delay;
        this.unit = Objects.requireNonNull(unit, "unit");
        this.action = Objects.requireNonNull(action, "action");
        this.scheduler = Objects.requireNonNull(scheduler, "scheduler");
        this.ownsScheduler = ownsScheduler;
    }

    /**
     * Records a call. Only the latest value will be passed to the action
     * after no more calls arrive for the configured delay window.
     */
    public void call(T value) {
        synchronized (lock) {
            if (closed) {
                throw new IllegalStateException("Debouncer is closed");
            }

            latestValue = value;
            long currentGeneration = ++generation;

            if (pendingTask != null) {
                pendingTask.cancel(false);
            }

            pendingTask = scheduler.schedule(
                () -> flush(currentGeneration),
                delay,
                unit
            );
        }
    }

    private void flush(long taskGeneration) {
        T valueToRun;

        synchronized (lock) {
            if (closed || taskGeneration != generation) {
                return;
            }

            valueToRun = latestValue;
            pendingTask = null;
        }

        action.accept(valueToRun);
    }

    @Override
    public void close() {
        synchronized (lock) {
            if (closed) {
                return;
            }

            closed = true;

            if (pendingTask != null) {
                pendingTask.cancel(false);
                pendingTask = null;
            }
        }

        if (ownsScheduler) {
            scheduler.shutdown();
        }
    }
}
```

