Here's a complete solution for cycle detection in a directed graph using Kotlin:

## Main Implementation

```kotlin
package graph

/**
 * Detects a cycle in a directed graph and returns one cycle if it exists.
 * Uses DFS with three-color marking (WHITE, GRAY, BLACK).
 *
 * @param graph adjacency list where graph[i] is the list of nodes reachable from node i
 * @return a list representing a cycle (e.g., [1, 2, 3, 1]) or null if no cycle exists
 * @throws IllegalArgumentException if an edge references a node that is not a key in the graph
 */
fun findCycle(graph: Map<Int, List<Int>>): List<Int>? {
    require(graph.isNotEmpty()) { "Graph must not be empty" }

    val white: Byte = 0
    val gray: Byte = 1
    val black: Byte = 2

    val color = mutableMapOf<Int, Byte>()
    graph.keys.forEach { color[it] = white }

    // Validate all edges
    for ((_, neighbors) in graph) {
        for (neighbor in neighbors) {
            require(graph.containsKey(neighbor)) {
                "Edge references unknown node: $neighbor"
            }
        }
    }

    // parent[node] = the node we came from, for reconstructing the cycle
    val parent = mutableMapOf<Int, Int>()
    val pathStack = ArrayDeque<Int>()

    fun dfs(node: Int): List<Int>? {
        color[node] = gray
        pathStack.addLast(node)

        for (neighbor in graph[node] ?: emptyList()) {
            when (color[neighbor]) {
                gray -> {
                    // Found a back edge: reconstruct cycle from pathStack
                    val cycle = mutableListOf<Int>()
                    val it = pathStack.iterator()
                    var started = false
                    while (it.hasNext()) {
                        val current = it.next()
                        if (current == neighbor) started = true
                        if (started) cycle.add(current)
                    }
                    cycle.add(neighbor) // close the cycle
                    return cycle
                }
                white -> {
                    parent[neighbor] = node
                    val result = dfs(neighbor)
                    if (result != null) return result
                }
                // black -> already fully explored, skip
            }
        }

        pathStack.removeLast()
        color[node] = black
        return null
    }

    for (node in graph.keys) {
        if (color[node] == white) {
            val cycle = dfs(node)
            if (cycle != null) return cycle
        }
    }
    return null
}
```

