class FindCycleTest {

    // ---------- Edge case: empty graph ----------
    @Test
    fun `empty graph throws`() {
        assertThrows<IllegalArgumentException> {
            findCycle(emptyMap())
        }
    }

    // ---------- Edge case: single node, no edges ----------
    @Test
    fun `single node no self-loop returns null`() {
        val graph = mapOf(1 to emptyList<Int>())
        assertNull(findCycle(graph))
    }

    // ---------- Edge case: single node self-loop ----------
    @Test
    fun `single node self-loop returns cycle`() {
        val graph = mapOf(1 to listOf(1))
        assertEquals(listOf(1, 1), findCycle(graph))
    }

    // ---------- Edge case: two nodes, no cycle ----------
    @Test
    fun `two nodes linear returns null`() {
        val graph = mapOf(
            1 to listOf(2),
            2 to emptyList<Int>()
        )
        assertNull(findCycle(graph))
    }

    // ---------- Edge case: two-node cycle ----------
    @Test
    fun `two node cycle`() {
        val graph = mapOf(
            1 to listOf(2),
            2 to listOf(1)
        )
        val cycle = findCycle(graph)
        assertNotNull(cycle)
        assertEquals(cycle!!.first(), cycle.last())
        assertTrue(cycle.containsAll(listOf(1, 2)))
    }

    // ---------- DAG: no cycle ----------
    @Test
    fun `diamond dag returns null`() {
        val graph = mapOf(
