            2 to emptyList<Int>(),
            3 to listOf(4),
            4 to listOf(5),
            5 to listOf(3)
        )
        val cycle = findCycle(graph)
        assertNotNull(cycle)
        assertTrue(cycle!!.containsAll(listOf(3, 4, 5)))
        assertEquals(cycle.first(), cycle.last())
    }

    // ---------- Longer cycle ----------
    @Test
    fun `long cycle of five nodes`() {
        val graph = mapOf(
            1 to listOf(2),
            2 to listOf(3),
            3 to listOf(4),
            4 to listOf(5),
            5 to listOf(1)
        )
        val cycle = findCycle(graph)
        assertNotNull(cycle)
        assertEquals(6, cycle!!.size)               // 5 nodes + closing node
        assertEquals(cycle.first(), cycle.last())
        assertEquals(setOf(1, 2, 3, 4, 5), cycle.toSet())
    }

    // ---------- Cycle reachable only through a "tail" ----------
    @Test
    fun `cycle with acyclic tail leading to it`() {
        val graph = mapOf(
            1 to listOf(2),
            2 to listOf(3),
            3 to listOf(4),
            4 to listOf(3)  // back edge to 3
        )
        val cycle = findCycle(graph)
        assertNotNull(cycle)
        assertEquals(listOf(3, 4, 3), cycle)
    }

    // ---------- Multiple cycles: should return one of them ----------
    @Test
    fun `graph with multiple disjoint cycles returns some valid cycle`() {
        val graph = mapOf(
            1 to listOf(2),
            2 to listOf(1),
            3 to listOf(4),
            4 to listOf(3)
        )
        val cycle = findCycle(graph)
        assertNotNull(cycle)
        assertEquals(cycle!!.first(), cycle.last())
        val nodeSet = cycle.toSet()
        assertTrue(nodeSet == setOf(1, 2) || nodeSet == setOf(3, 4))
    }

    // ---------- Nested cycles (figure-eight) ----------
    @Test
    fun `figure eight returns a valid cycle`() {
        // Two cycles sharing node 2
        val graph = mapOf(
            1 to listOf(2),
            2 to listOf(3, 4),
            3 to listOf(1),
            4 to listOf(2)
        )
        val cycle = findCycle(graph)
        assertNotNull(cycle)
        assertEquals(cycle!!.first(), cycle.last())
        // Every consecutive pair must be a real edge
        for (i in 0 until cycle.size - 1) {
            assertTrue(graph[cycle[i]]!!.contains(cycle[i + 1]),
                "Invalid edge: ${cycle[i]} -> ${cycle[i + 1]}")
        }
    }

    // ---------- Error case: dangling edge ----------
    @Test
    fun `edge to unknown node throws`() {
        val graph = mapOf(1 to listOf(99))
        assertThrows<IllegalArgumentException> {
            findCycle(graph)
        }
    }

    // ---------- Cycle correctness via edge validation ----------
    @Test
    fun `returned cycle edges are all valid graph edges`() {
        val graph = mapOf(
            1 to listOf(2, 3),
            2 to listOf(3),
            3 to listOf(4),
            4 to listOf(2)   // cycle 2 -> 3 -> 4 -> 2
        )
        val cycle = findCycle(graph)!!
        assertTrue(cycle.size >= 3)
        for (i in 0 until cycle.size - 1) {
            assertTrue(graph[cycle[i]]!!.contains(cycle[i + 1]))
        }
    }
