## Key Points

1. **Three-color DFS** — `WHITE` (unvisited), `GRAY` (in current recursion stack), `BLACK` (finished). A `GRAY` neighbor means a back edge → cycle.

2. **Cycle reconstruction** — The `pathStack` holds the current DFS path. When we hit a `GRAY` neighbor, we walk from the first occurrence of that neighbor in the stack to the end, then append the neighbor again to close the loop.

3. **Complexity** — `O(V + E)` time, `O(V)` space.

4. **Returned cycle format** — Starts and ends with the same node (e.g., `[3, 4, 3]`), so consumers can unambiguously identify the entry point.

5. **Edge cases covered by tests** — empty graph, single node (with/without self-loop), disconnected components, tail-before-cycle, multiple cycles, self-loop, dangling edges, and validation that returned cycle edges are real graph edges.

## LRU cache in C

This implementation uses:

- a **hash table** for `O(1)` average lookup
- a **doubly linked list** for `O(1)` recency updates and eviction

The most recently used item is at the head. The least recently used item is at the tail.

### `lru_cache.h`

```c
#ifndef LRU_CACHE_H
#define LRU_CACHE_H

#include <stddef.h>

typedef struct LRUCache LRUCache;

LRUCache *lru_cache_create(size_t capacity);
void lru_cache_destroy(LRUCache *cache);

/*
 * Returns 1 if key was found and writes value to *value.
 * Returns 0 if key was not found.
 */
int lru_cache_get(LRUCache *cache, int key, int *value);

/*
 * Inserts or updates key/value.
 * Returns 0 on success, -1 on allocation failure or NULL cache.
 */
int lru_cache_put(LRUCache *cache, int key, int value);

#endif
```

### `lru_cache.c`

```c
#include "lru_cache.h"

#include <stdlib.h>

typedef struct Node {
    int key;
    int value;
    struct Node *prev;
    struct Node *next;
    struct Node *hnext;
} Node;

struct LRUCache {
    size_t capacity;
    size_t count;
    size_t num_buckets;
    Node **buckets;
    Node *head; /* most recently used */
    Node *tail; /* least recently used */
};

static size_t hash_int(int key, size_t num_buckets)
{
    unsigned int x = (unsigned int)key;
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;
    return (size_t)x % num_buckets;
}

LRUCache *lru_cache_create(size_t capacity)
{
    LRUCache *cache = malloc(sizeof(*cache));
    if (!cache) {
        return NULL;
    }

    cache->capacity = capacity;
    cache->count = 0;
    cache->head = NULL;
    cache->tail = NULL;
    cache->num_buckets = capacity > 0 ? capacity * 2 + 1 : 1;

    cache->buckets = calloc(cache->num_buckets, sizeof(Node *));
    if (!cache->buckets) {
        free(cache);
        return NULL;
    }

    return cache;
}

static Node *find_node(LRUCache *cache, int key)
{
    size_t idx = hash_int(key, cache->num_buckets);

    for (Node *n = cache->buckets[idx]; n; n = n->hnext) {
        if (n->key == key) {
            return n;
        }
    }

    return NULL;
}

static void remove_from_list(LRUCache *cache, Node *node)
{
    if (node->prev) {
        node->prev->next = node->next;
    } else {
        cache->head = node->next;
    }

    if (node->next) {
        node->next->prev = node->prev;
    } else {
        cache->tail = node->prev;
    }

    node->prev = NULL;
    node->next = NULL;
}

static void insert_at_head(LRUCache *cache, Node *node)
{
    node->prev = NULL;
    node->next = cache->head;

    if (cache->head) {
        cache->head->prev = node;
    } else {
        cache->tail = node;
    }

    cache->head = node;
}

static void move_to_head(LRUCache *cache, Node *node)
{
    if (cache->head == node) {
        return;
    }

    remove_from_list(cache, node);
    insert_at_head(cache, node);
}

static void remove_from_hash(LRUCache *cache, Node *node)
{
    size_t idx = hash_int(node->key, cache->num_buckets);
    Node **link = &cache->buckets[idx];

    while (*link) {
        if (*link == node) {
            *link = node->hnext;
            node->hnext = NULL;
            return;
        }
        link = &(*link)->hnext;
    }
}

int lru_cache_get(LRUCache *cache, int key, int *value)
{
    if (!cache || !value) {
        return 0;
    }

    Node *node = find_node(cache, key);
    if (!node) {
        return 0;
    }

    move_to_head(cache, node);
    *value = node->value;
    return 1;
}

int lru_cache_put(LRUCache *cache, int key, int value)
{
    if (!cache) {
        return -1;
    }

    /* Capacity 0 cache stores nothing. */
    if (cache->capacity == 0) {
        return 0;
    }

    Node *node = find_node(cache, key);
    if (node) {
        node->value = value;
        move_to_head(cache, node);
        return 0;
    }

    if (cache->count == cache->capacity) {
        Node *lru = cache->tail;
        remove_from_hash(cache, lru);
        remove_from_list(cache, lru);
        free(lru);
        cache->count--;
    }

    Node *new_node = malloc(sizeof(*new_node));
    if (!new_node) {
        return -1;
    }

    new_node->key = key;
    new_node->value = value;
    new_node->prev = NULL;
    new_node->next = NULL;
    new_node->hnext = NULL;

    size_t idx = hash_int(key, cache->num_buckets);
    new_node->hnext = cache->buckets[idx];
    cache->buckets[idx] = new_node;

    insert_at_head(cache, new_node);
    cache->count++;

    return 0;
}

void lru_cache_destroy(LRUCache *cache)
{
    if (!cache) {
        return;
    }

    Node *n = cache->head;
    while (n) {
        Node *next = n->next;
        free(n);
        n = next;
    }

    free(cache->buckets);
    free(cache);
}
```

