/**
 * A probabilistic skip list: an ordered set with O(log n) expected
 * search / insert / delete and O(n) worst case.
 *
 * Invariants maintained by this implementation:
 *
 *  1. Level 0 contains every element in sorted order (a plain linked list).
 *  2. A node present at level i is present at every level < i.
 *  3. `head` is a sentinel whose `key` is never compared; it holds
 *     `maxLevel` forward pointers so we never have to grow it.
 *  4. `this.level` is the number of levels currently in use, 1-indexed.
 *     `head.next[i]` is null for every i >= this.level.
 *
 * Not thread-safe / not async-safe: use one instance per worker or guard
 * with a mutex. All operations are O(1) in allocation except insert.
 */

/** Minimal RNG contract so tests can inject a deterministic sequence. */
export type RandomFn = () => number;

export interface SkipListOptions<T> {
  /**
   * Total order over keys. Must be a total order and must be stable —
   * an inconsistent comparator silently corrupts the list.
   * Defaults to `<`/`>` comparison, which is correct for
   * number | string | bigint | Date.
   */
  compare?: (a: T, b: T) => number;

  /**
   * Probability that a node is promoted to the next level.
   * 0.25 gives slightly denser level-0 chains and better cache locality
   * than 0.5 at the cost of ~1.33 average levels vs ~2. Lower = less
   * memory, more comparisons. Tune with a benchmark, not a feeling.
   */
  probability?: number;

  /**
   * Hard cap on levels. At p = 0.25, 32 levels comfortably holds ~4e9
   * entries. This is a safety valve against a pathological RNG, not a
   * tuning knob.
   */
  maxLevel?: number;

  /** Injectable RNG in [0, 1). Defaults to Math.random. */
  random?: RandomFn;
}

/** A node in the list. `key` is the payload; there are no separate values. */
class Node<T> {
  readonly key: T;
  /** Forward pointers, one per level this node participates in. */
  readonly next: Array<Node<T> | null>;

  constructor(key: T, level: number) {
    this.key = key;
    this.next = new Array<Node<T> | null>(level).fill(null);
  }
