/**
 * Probabilistic skip list: expected O(log n) search/insert/delete.
 * Invariants: level 0 holds every key in order; a node at level i is also
 * at every level < i; `head` is a sentinel sized to maxLevel; `level` is
 * the number of levels in use (>= 1).
 *
 * Not thread-safe. Use one instance per worker or guard with a mutex.
 */

export type RandomFn = () => number;

class Node<T> {
  readonly next: Array<Node<T> | null>;
  constructor(readonly key: T, level: number) {
    this.next = new Array(level).fill(null);
  }
}

export class SkipList<T> {
  private readonly head: Node<T>;
  private level = 1;
  private count = 0;

  constructor(
    private readonly compare: (a: T, b: T) => number = (a: any, b: any) =>
      a === b ? 0 : a < b ? -1 : 1,
    private readonly probability = 0.25,
    private readonly maxLevel = 32,
    private readonly random: RandomFn = Math.random,
  ) {
    // Sentinel key is never read: every walk starts at head.next[i].
    this.head = new Node<T>(undefined as unknown as T, maxLevel);
  }

  get size(): number {
    return this.count;
  }

  /** Returns the stored key equal to `key`, or null. */
  search(key: T): T | null {
    const node = this.findPredecessor(key).next[0];
    return node !== null && this.compare(node.key, key) === 0 ? node.key : null;
  }

  /** @returns true if inserted, false if an equal key already existed. */
  insert(key: T): boolean {
    const update: Node<T>[] = new Array(this.maxLevel);
    let cur = this.head;
    for (let i = this.level - 1; i >= 0; i--) {
      // Strict `<` keeps duplicates out: stop on equality, not before it.
      while (cur.next[i] !== null && this.compare(cur.next[i]!.key, key) < 0) {
        cur = cur.next[i]!;
      }
      update[i] = cur;
    }

    const existing = cur.next[0];
    if (existing !== null && this.compare(existing.key, key) === 0) return false;

    const newLevel = this.randomLevel();

    // Above the old top there are no predecessors yet: they all start at head.
    if (newLevel > this.level) {
      for (let i = this.level; i < newLevel; i++) update[i] = this.head;
      this.level = newLevel;
    }

    const node = new Node<T>(key, newLevel);
    for (let i = 0; i < newLevel; i++) {
      node.next[i] = update[i].next[i];
      update[i].next[i] = node;
    }

    this.count++;
    return true;
  }

  /** @returns true if removed, false if not found. */
  delete(key: T): boolean {
    const update: Node<T>[] = new Array(this.maxLevel);
    let cur = this.head;
    for (let i = this.level - 1; i >= 0; i--) {
      while (cur.next[i] !== null && this.compare(cur.next[i]!.key, key) < 0) {
        cur = cur.next[i]!;
      }
      update[i] = cur;
    }

    const target = cur.next[0];
    if (target === null || this.compare(target.key, key) !== 0) return false;

    // Bail once `update[i].next[i]` stops pointing at target: target has no
    // pointers above target.next.length, so it can't reappear higher up.
    for (let i = 0; i < this.level; i++) {
      if (update[i].next[i] !== target) break;
      update[i].next[i] = target.next[i];
    }

    // Drop empty top levels so future searches don't scan dead pointers.
    while (this.level > 1 && this.head.next[this.level - 1] === null) this.level--;

    this.count--;
    return true;
  }

  private findPredecessor(key: T): Node<T> {
    let cur = this.head;
    for (let i = this.level - 1; i >= 0; i--) {
      while (cur.next[i] !== null && this.compare(cur.next[i]!.key, key) < 0) {
        cur = cur.next[i]!;
      }
    }
    return cur;
  }

