# Simple JSON Pretty-Printer in Go

Below is a self-contained implementation that parses a JSON string and re-emits it with indentation. It handles objects, arrays, strings (including escapes), numbers, `true`/`false`/`null`, and trims insignificant whitespace. Single-pass, no third-party libraries.

## Implementation

```go
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// PrettyJSON reformats a compact JSON string with the given indent step.
func PrettyJSON(src string, indent string) (string, error) {
	p := &printer{src: src, indent: indent}
	if err := p.run(); err != nil {
		return "", err
	}
	return p.out.String(), nil
}

type printer struct {
	src    string
	pos    int
	depth  int
	indent string
	out    strings.Builder
}

func (p *printer) run() error {
	p.skipWS()
	if p.pos >= len(p.src) {
		return fmt.Errorf("empty input")
	}
	if err := p.value(); err != nil {
		return err
	}
	p.skipWS()
	if p.pos != len(p.src) {
		return fmt.Errorf("trailing data at offset %d", p.pos)
	}
	return nil
}

func (p *printer) value() error {
	p.skipWS()
	if p.pos >= len(p.src) {
		return fmt.Errorf("unexpected end of input")
	}
	switch c := p.src[p.pos]; c {
	case '{':
		return p.object()
	case '[':
		return p.array()
	case '"':
		return p.string()
	case 't', 'f':
		return p.literal("true", "false")
	case 'n':
		return p.literal("null")
	default:
		if c == '-' || (c >= '0' && c <= '9') {
			return p.number()
		}
		return fmt.Errorf("unexpected char %q at %d", c, p.pos)
	}
}

func (p *printer) object() error {
	p.pos++ // consume '{'
	p.depth++
	p.skipWS()
	if p.peek() == '}' {
		p.pos++
		p.depth--
		p.out.WriteByte('}')
		return nil
	}
	p.newline()
	for {
		p.skipWS()
		if err := p.string(); err != nil {
			return err
		}
		p.skipWS()
		if p.peek() != ':' {
			return fmt.Errorf("expected ':' at %d", p.pos)
		}
		p.pos++
		p.out.WriteString(": ")
		if err := p.value(); err != nil {
			return err
		}
		p.skipWS()
		switch p.peek() {
		case ',':
			p.pos++
			p.out.WriteByte(',')
			p.newline()
		case '}':
			p.pos++
			p.depth--
			p.newline()
			p.out.WriteByte('}')
			return nil
		default:
			return fmt.Errorf("expected ',' or '}' at %d", p.pos)
		}
	}
}

func (p *printer) array() error {
	p.pos++ // consume '['
	p.depth++
	p.skipWS()
	if p.peek() == ']' {
		p.pos++
		p.depth--
		p.out.WriteByte(']')
		return nil
	}
	p.newline()
	for {
		if err := p.value(); err != nil {
			return err
		}
		p.skipWS()
		switch p.peek() {
		case ',':
			p.pos++
			p.out.WriteByte(',')
			p.newline()
		case ']':
			p.pos++
			p.depth--
			p.newline()
			p.out.WriteByte(']')
			return nil
		default:
			return fmt.Errorf("expected ',' or ']' at %d", p.pos)
		}
	}
}

func (p *printer) string() error {
	if p.peek() != '"' {
		return fmt.Errorf("expected '\"' at %d", p.pos)
	}
	start := p.pos
	p.pos++
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if c == '\\' {
			p.pos += 2
			continue
		}
		if c == '"' {
			p.pos++
			p.out.WriteString(p.src[start:p.pos])
			// Validate escapes/rune well-formedness cheaply.
			if _, err := strconv.Unquote(p.src[start:p.pos]); err != nil {
				return fmt.Errorf("bad string at %d: %w", start, err)
			}
			return nil
		}
		if c < 0x20 {
			return fmt.Errorf("control char in string at %d", p.pos)
		}
		p.pos++
	}
	return fmt.Errorf("unterminated string starting at %d", start)
}

func (p *printer) number() error {
	start := p.pos
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if (c >= '0' && c <= '9') || c == '-' || c == '+' ||
			c == '.' || c == 'e' || c == 'E' {
			p.pos++
			continue
		}
		break
	}
	tok := p.src[start:p.pos]
	if _, err := strconv.ParseFloat(tok, 64); err != nil {
		return fmt.Errorf("bad number %q: %w", tok, err)
	}
	p.out.WriteString(tok)
	return nil
}

func (p *printer) literal(words ...string) error {
	for _, w := range words {
		if strings.HasPrefix(p.src[p.pos:], w) {
			p.pos += len(w)
			p.out.WriteString(w)
			return nil
		}
	}
	return fmt.Errorf("bad literal at %d", p.pos)
}

func (p *printer) skipWS() {
	for p.pos < len(p.src) {
		switch p.src[p.pos] {
		case ' ', '\t', '\n', '\r':
			p.pos++
		default:
			return
		}
	}
}

func (p *printer) peek() byte {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *printer) newline() {
	p.out.WriteByte('\n')
	for i := 0; i < p.depth; i++ {
		p.out.WriteString(p.indent)
	}
}

// ---- demo ----
func main() {
	src := `{"user":{"id":42,"name":"Ada","tags":["eng","math"],"ok":true,"meta":null},
"items":[1,2.5,-3e2,{"deep":[{"x":1}]}]}`
	out, err := PrettyJSON(src, "  ")
	if err != nil {
		panic(err)
	}
	fmt.Println(out)
	fmt.Println("runes:", utf8.RuneCountInString(out))
}
```

## How it works

1. **Tokenizer-on-the-fly.** A cursor `pos` walks the input. `skipWS` discards insignificant whitespace; the parser never buffers tokens.
2. **Recursive descent.** `value` dispatches on the first non-whitespace byte to `object`, `array`, `string`, `number`, or `literal`.
3. **Emission with a `strings.Builder`.** Each container tracks `depth`. On entry it writes a newline and `depth × indent`; items are separated by `,"\n" + indent`; on exit a matching newline+indent precedes the closing brace/bracket.
4. **Validation.** `strconv.Unquote` validates escape sequences and rune encoding, `strconv.ParseFloat` validates numbers. That means we catch malformed input without needing a full parse tree.
5. **Strict end check.** After the top-level value, `run()` requires EOF — this rejects inputs like `1 2` or `{}[]`.

## Time and space complexity

Let **n** = length of the input in bytes.

- **Time: O(n).** Every byte is consumed at most once by `pos`; `skipWS`, the value scanners, and `strings.Builder` writes are all linear. The only non-constant per-character operation is `strconv.ParseFloat`/`Unquote`, but those run once per *token* and their combined cost is bounded by the sum of token lengths, i.e. O(n). There is no quadratic string concatenation because `strings.Builder` amortizes append cost.
- **Space: O(n)** in the worst case, dominated by the output buffer. Auxiliary space beyond the output is:
  - **O(d)** for the recursion stack, where `d` is the nesting depth of the JSON document (bounded by n in the degenerate case `[[[[...]]]]`),
  - **O(1)** for the cursor, `depth`, and constants.

  If a caller only wants to stream output (e.g. via an `io.Writer`), auxiliary memory reduces to **O(d)** for the stack. Peak total memory is `O(n + d)`, which simplifies to `O(n)`.

## Caveats

- The number scanner is permissive (`1e`, `--3` will be sliced and passed to `ParseFloat`, which rejects them). It never mis-accepts a value, but error messages may point at the token boundary rather than the offending byte.
- `strconv.Unquote` expects a Go-quoted string; JSON escapes are a superset for practical purposes but reject the JSON-only form `\uD834\uDD1E` surrogate pairs on their own. For production use, replace that check with a dedicated JSON string validator.
- The top-level value must be followed only by whitespace, matching RFC 8259.

Below is a Swift implementation that treats `0` as an empty cell. It validates that no filled cell conflicts with another filled cell in the same row, column, or 3×3 subgrid. It does **not** check whether the puzzle is solvable.

```swift
func isValidSudoku(_ board: [[Int]]) -> Bool {
    // Must be exactly 9x9.
    guard board.count == 9, board.allSatisfy({ $0.count == 9 }) else {
        return false
    }

    var rows = Array(repeating: Set<Int>(), count: 9)
    var columns = Array(repeating: Set<Int>(), count: 9)
    var boxes = Array(repeating: Set<Int>(), count: 9)

    for row in 0..<9 {
        for column in 0..<9 {
            let value = board[row][column]

            // 0 represents an empty cell.
            if value == 0 {
                continue
            }

            // Only 1...9 are valid Sudoku values.
            guard (1...9).contains(value) else {
                return false
            }

            let boxIndex = (row / 3) * 3 + (column / 3)

            if rows[row].contains(value) ||
                columns[column].contains(value) ||
                boxes[boxIndex].contains(value) {
                return false
            }

            rows[row].insert(value)
            columns[column].insert(value)
            boxes[boxIndex].insert(value)
        }
    }

    return true
}
```

