        board[0][0] = 7
        board[8][0] = 7

        XCTAssertFalse(isValidSudoku(board))
    }

    func testDuplicateIn3x3BoxIsInvalid() {
        var board = emptyBoard()
        board[0][0] = 9
        board[2][2] = 9

        XCTAssertFalse(isValidSudoku(board))
    }

