```rust
use std::collections::HashMap;

/// Performs a topological sort on a directed graph.
///
/// The graph is given as an adjacency list: for each node, the list of
/// nodes it has edges pointing to.
///
/// Returns `Ok(order)` with a valid topological ordering, or `Err(cycle)`
/// containing the nodes that form a cycle (in cycle order) if one exists.
pub fn topological_sort<N>(graph: &HashMap<N, Vec<N>>) -> Result<Vec<N>, Vec<N>>
where
    N: Clone + Eq + std::hash::Hash,
{
    #[derive(Clone, Copy, PartialEq)]
    enum Mark {
        Unvisited,
        InProgress,
        Done,
    }

    // Make sure every node mentioned as a destination is also a key,
    // so nodes with no outgoing edges are still visited.
    let mut all_nodes: Vec<N> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for (n, neighbors) in graph {
        if seen.insert(n.clone()) {
            all_nodes.push(n.clone());
        }
        for m in neighbors {
            if seen.insert(m.clone()) {
                all_nodes.push(m.clone());
            }
        }
    }

    let mut marks: HashMap<N, Mark> = HashMap::new();
    for n in &all_nodes {
        marks.insert(n.clone(), Mark::Unvisited);
    }

    let mut order: Vec<N> = Vec::new();
    // Stack of nodes currently on the DFS path, used to extract the cycle.
    let mut path: Vec<N> = Vec::new();

    // Iterative DFS to avoid recursion limits on large graphs.
    for start in &all_nodes {
        if marks[start] == Mark::Done {
            continue;
        }

        // Each entry is (node, index of next neighbor to visit).
        let mut stack: Vec<(N, usize)> = vec![(start.clone(), 0)];
        marks.insert(start.clone(), Mark::InProgress);
        path.push(start.clone());

        while let Some((node, idx)) = stack.last().cloned() {
            let neighbors = graph.get(&node).cloned().unwrap_or_default();

            if idx < neighbors.len() {
                stack.last_mut().unwrap().1 += 1;
                let next = neighbors[idx].clone();

                match marks[&next] {
                    Mark::Done => continue,
                    Mark::InProgress => {
                        // Found a cycle. Extract it from `path`.
                        let pos = path.iter().position(|x| *x == next).unwrap();
                        let cycle: Vec<N> = path[pos..].to_vec();
                        return Err(cycle);
                    }
                    Mark::Unvisited => {
                        marks.insert(next.clone(), Mark::InProgress);
                        path.push(next.clone());
                        stack.push((next, 0));
                    }
                }
            } else {
                // Finished exploring node.
                marks.insert(node.clone(), Mark::Done);
                order.push(node);
                path.pop();
                stack.pop();
            }
        }
    }

    // `order` is in reverse finishing order; reverse for a valid topo order.
    order.reverse();
    Ok(order)
}

fn main() {
    use std::collections::HashMap;

    // A DAG:
    //   5 -> 2 -> 3
    //   5 -> 0
    //   4 -> 0 -> 1
    //   4 -> 1
    //   2 -> 3
    let mut dag: HashMap<&str, Vec<&str>> = HashMap::new();
    dag.insert("5", vec!["2", "0"]);
    dag.insert("4", vec!["0", "1"]);
    dag.insert("2", vec!["3"]);
    dag.insert("3", vec!["1"]);
    dag.insert("0", vec![]);
    dag.insert("1", vec![]);

    match topological_sort(&dag) {
        Ok(order) => println!("Topological order: {:?}", order),
        Err(cycle) => println!("Cycle detected: {:?}", cycle),
    }

    // A graph with a cycle: a -> b -> c -> a
    let mut cyclic: HashMap<&str, Vec<&str>> = HashMap::new();
    cyclic.insert("a", vec!["b"]);
    cyclic.insert("b", vec!["c"]);
    cyclic.insert("c", vec!["a"]);

    match topological_sort(&cyclic) {
        Ok(order) => println!("Topological order: {:?}", order),
        Err(cycle) => println!("Cycle detected: {:?}", cycle),
    }
}
```

Key points:

- **Iterative DFS** with three-state marking (`Unvisited`, `InProgress`, `Done`) keeps stack depth bounded on large graphs.
- A node in `InProgress` reachable again means a **back edge** → cycle. We carve the cycle out of the current DFS `path`.
- **Finishing order** is the reverse topological order; we reverse it at the end.
- Nodes that appear only as destinations (no outgoing edges) are still considered—otherwise they'd be silently dropped from the result.
- On success you get `Ok(Vec<N>)`; on failure you get `Err(cycle_nodes)` where `cycle_nodes` lists one concrete cycle (e.g. `["a", "b", "c"]`).

