```kotlin
sealed interface Edit {
    data class Insert(val index: Int, val char: Char) : Edit
    data class Delete(val index: Int, val char: Char) : Edit
    data class Substitute(val index: Int, val from: Char, val to: Char) : Edit
}

data class EditResult(
    val distance: Int,
    val edits: List<Edit>
)

/**
 * Computes Levenshtein edit distance and an edit script.
 *
 * The edit script transforms `source` into `target` when applied from left to right.
 * Indices are 0-based positions in the string being edited at that point.
 */
fun editDistance(source: String, target: String): EditResult {
    val n = source.length
    val m = target.length

    // dp[i][j] = edit distance between source[0 until i] and target[0 until j]
    val dp = Array(n + 1) { IntArray(m + 1) }

    for (i in 0..n) dp[i][0] = i
    for (j in 0..m) dp[0][j] = j

    for (i in 1..n) {
        for (j in 1..m) {
            val substitutionCost = if (source[i - 1] == target[j - 1]) 0 else 1

            dp[i][j] = minOf(
                dp[i - 1][j] + 1,        // delete
                dp[i][j - 1] + 1,        // insert
                dp[i - 1][j - 1] + substitutionCost // substitute/match
            )
        }
    }

    // Backtrack to build the edit script.
    val edits = mutableListOf<Edit>()
    var i = n
    var j = m

    while (i > 0 || j > 0) {
        when {
            i > 0 && j > 0 &&
                source[i - 1] == target[j - 1] &&
                dp[i][j] == dp[i - 1][j - 1] -> {
                // Match: no edit needed.
                i--
                j--
            }

            i > 0 && j > 0 &&
                dp[i][j] == dp[i - 1][j - 1] + 1 -> {
                edits += Edit.Substitute(
                    index = i - 1,
                    from = source[i - 1],
                    to = target[j - 1]
                )
                i--
                j--
            }

            i > 0 && dp[i][j] == dp[i - 1][j] + 1 -> {
                edits += Edit.Delete(
                    index = i - 1,
                    char = source[i - 1]
                )
                i--
            }

            else -> {
                edits += Edit.Insert(
                    index = i,
                    char = target[j - 1]
                )
                j--
            }
        }
    }

    return EditResult(
        distance = dp[n][m],
        edits = edits.reversed()
    )
}
```

Usage example:

```kotlin
fun main() {
    val source = "kitten"
    val target = "sitting"

    val result = editDistance(source, target)

    println("Distance: ${result.distance}")
    println("Edit script:")

    for (edit in result.edits) {
        println(
            when (edit) {
                is Edit.Insert -> "Insert '${edit.char}' at ${edit.index}"
                is Edit.Delete -> "Delete '${edit.char}' at ${edit.index}"
                is Edit.Substitute -> "Substitute '${edit.from}' -> '${edit.to}' at ${edit.index}"
            }
        )
    }
}
