import kotlin.random.Random

class SkipList(
    private val maxLevel: Int = 16,
    private val probability: Double = 0.5,
    private val random: Random = Random.Default
) {
    private class Node(val key: Int, val level: Int) {
        val next = arrayOfNulls<Node>(level + 1)
    }

    private val head = Node(Int.MIN_VALUE, maxLevel)

    private fun randomLevel(): Int {
        var level = 0
        while (level < maxLevel && random.nextDouble() < probability) {
            level++
        }
        return level
    }

    fun insert(key: Int): Boolean {
        val update = arrayOfNulls<Node>(maxLevel + 1)
        var current = head

        for (i in maxLevel downTo 0) {
            while (true) {
                val next = current.next[i] ?: break
                if (next.key < key) current = next else break
            }
            update[i] = current
        }

        val next = current.next[0]
        if (next != null && next.key == key) {
            return false // duplicate key
        }

        val level = randomLevel()
        val newNode = Node(key, level)

        for (i in 0..level) {
            newNode.next[i] = update[i]!!.next[i]
            update[i]!!.next[i] = newNode
        }

        return true
    }

    fun delete(key: Int): Boolean {
        val update = arrayOfNulls<Node>(maxLevel + 1)
        var current = head

        for (i in maxLevel downTo 0) {
            while (true) {
                val next = current.next[i] ?: break
                if (next.key < key) current = next else break
            }
            update[i] = current
        }

        val target = current.next[0]
        if (target == null || target.key != key) {
            return false
        }

        for (i in 0..target.level) {
            if (update[i]!!.next[i] === target) {
                update[i]!!.next[i] = target.next[i]
            }
        }

        return true
    }

    fun search(key: Int): Boolean {
        var current = head

        for (i in maxLevel downTo 0) {
            while (true) {
                val next = current.next[i] ?: break
                if (next.key < key) current = next else break
            }
        }

        val next = current.next[0]
        return next != null && next.key == key
    }
}

fun main() {
    val skipList = SkipList()

    skipList.insert(3)
    skipList.insert(6)
    skipList.insert(7)
    skipList.insert(9)
    skipList.insert(12)

    println("search 6: ${skipList.search(6)}") // true
    println("search 8: ${skipList.search(8)}") // false

    println("delete 6: ${skipList.delete(6)}") // true
    println("search 6: ${skipList.search(6)}") // false

    println("delete 6 again: ${skipList.delete(6)}") // false
}
```

This skip list stores unique `Int` keys. `insert` returns `false` if the key already exists, `delete` returns `false` if the key was not found, and `search` returns whether the key exists.

