Below is a complete C implementation of a tokenizer plus a recursive-descent evaluator that respects `*`/`/` over `+`/`-`, parentheses, and unary `+`/`-`.

```c
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

typedef enum {
    TOK_END,
    TOK_NUMBER,
    TOK_PLUS,
    TOK_MINUS,
    TOK_MUL,
    TOK_DIV,
    TOK_LPAREN,
    TOK_RPAREN
} TokenType;

typedef struct {
    TokenType type;
    double value;   // used only when type == TOK_NUMBER
} Token;

typedef struct {
    Token *data;
    size_t count;
    size_t cap;
} TokenList;

static void push_token(TokenList *list, TokenType type, double value) {
    if (list->count == list->cap) {
        size_t new_cap = list->cap ? list->cap * 2 : 16;
        Token *new_data = realloc(list->data, new_cap * sizeof(Token));
        if (!new_data) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        list->data = new_data;
        list->cap = new_cap;
    }

    list->data[list->count].type = type;
    list->data[list->count].value = value;
    list->count++;
}

/*
 * Tokenize an arithmetic expression.
 * Returns 1 on success, 0 on invalid input.
 */
static int tokenize(const char *expr, TokenList *list) {
    list->data = NULL;
    list->count = 0;
    list->cap = 0;

    const char *p = expr;

    while (*p) {
        if (isspace((unsigned char)*p)) {
            p++;
            continue;
        }

        if (isdigit((unsigned char)*p) || *p == '.') {
            char *end;
            double value = strtod(p, &end);

            if (end == p) {
                return 0; // invalid number
            }

            push_token(list, TOK_NUMBER, value);
            p = end;
            continue;
        }

        switch (*p) {
            case '+': push_token(list, TOK_PLUS, 0); p++; break;
            case '-': push_token(list, TOK_MINUS, 0); p++; break;
            case '*': push_token(list, TOK_MUL, 0); p++; break;
            case '/': push_token(list, TOK_DIV, 0); p++; break;
            case '(': push_token(list, TOK_LPAREN, 0); p++; break;
            case ')': push_token(list, TOK_RPAREN, 0); p++; break;
            default:
                return 0; // unknown character
        }
    }

    push_token(list, TOK_END, 0);
    return 1;
}

typedef struct {
    Token *tokens;
    size_t pos;
    int error;
} Parser;

static Token *peek(Parser *p) {
    return &p->tokens[p->pos];
}

static void advance(Parser *p) {
    if (p->tokens[p->pos].type != TOK_END) {
