 *         | '+' factor
 *         | '-' factor
 */
static double parse_factor(Parser *p) {
    Token *tok = peek(p);

    if (tok->type == TOK_NUMBER) {
        double value = tok->value;
        advance(p);
        return value;
    }

    if (tok->type == TOK_PLUS) {
        advance(p);
        return parse_factor(p);
    }

    if (tok->type == TOK_MINUS) {
        advance(p);
        return -parse_factor(p);
    }

