 * Evaluate an arithmetic expression.
 * Returns 1 on success and stores the result in *result.
 * Returns 0 on syntax error or division by zero.
 */
int evaluate_expression(const char *expr, double *result) {
    TokenList list;

    if (!tokenize(expr, &list)) {
        free(list.data);
        return 0;
    }

    Parser parser = { list.tokens, 0, 0 };
    double value = parse_expr(&parser);

    if (!parser.error && peek(&parser)->type != TOK_END) {
        parser.error = 1;
    }

    free(list.data);

    if (parser.error) {
        return 0;
    }

    *result = value;
    return 1;
