# Exponential Backoff Retry with Jitter in Swift

Here's a clean, reusable implementation using Swift's modern `async/await` and structured concurrency.

## Implementation

```swift
import Foundation

/// Errors thrown by the retry logic itself.
enum RetryError: Error {
    case exceededMaxAttempts(lastError: Error)
}

/// Configuration for exponential backoff.
struct RetryPolicy {
    /// Maximum number of attempts (including the initial one).
    var maxAttempts: Int = 5
    /// Base delay for the first retry, in seconds.
    var baseDelay: TimeInterval = 0.5
    /// Multiplier applied to the delay for each subsequent retry.
    var multiplier: Double = 2.0
    /// Maximum delay cap, in seconds.
    var maxDelay: TimeInterval = 30.0

    static let `default` = RetryPolicy()
}

/// Executes an async operation with exponential backoff and full jitter.
///
/// - Parameters:
///   - policy: The retry policy to use. Defaults to `.default`.
///   - shouldRetry: Optional predicate to decide whether a given error is retryable.
///                  Defaults to retrying every error.
///   - operation: The async throwing operation to execute.
/// - Returns: The value returned by `operation` on success.
/// - Throws: `RetryError.exceededMaxAttempts` if all attempts fail,
///           or any non-retryable error from `operation`.
func withRetry<T>(
    policy: RetryPolicy = .default,
    shouldRetry: (Error) -> Bool = { _ in true },
    operation: () async throws -> T
) async throws -> T {
    var lastError: Error?

    for attempt in 0..<policy.maxAttempts {
        do {
            return try await operation()
        } catch {
            // Bail immediately if the error isn't retryable
            // or we've exhausted our attempts.
            guard shouldRetry(error), attempt < policy.maxAttempts - 1 else {
                if attempt == policy.maxAttempts - 1 {
                    throw RetryError.exceededMaxAttempts(lastError: error)
                }
                throw error
            }

            lastError = error

            let delay = backoffDelay(attempt: attempt, policy: policy)
            try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
        }
    }

    // Unreachable in practice, but keeps the compiler happy.
    throw RetryError.exceededMaxAttempts(lastError: lastError ?? CancellationError())
}

/// Computes the delay for a given attempt with full jitter.
///
/// "Full jitter" (per AWS's well-known post) picks a uniform random value
/// between 0 and the exponentially-computed cap.
private func backoffDelay(attempt: Int, policy: RetryPolicy) -> TimeInterval {
    let exponential = policy.baseDelay * pow(policy.multiplier, Double(attempt))
    let capped = min(exponential, policy.maxDelay)
    return Double.random(in: 0...capped)
}
```

## Usage Example

```swift
// A flaky network call that fails ~70% of the time.
func flakyFetch() async throws -> String {
    try await Task.sleep(nanoseconds: 100_000_000) // simulate latency
    if Double.random(in: 0...1) < 0.7 {
        throw URLError(.timedOut)
    }
    return "✅ data fetched"
}

// Example 1: Simple usage with default policy.
do {
    let result = try await withRetry {
        try await flakyFetch()
    }
    print(result)
} catch {
    print("Failed after retries: \(error)")
}

// Example 2: Custom policy + selective retry (only retry timeouts).
let policy = RetryPolicy(
    maxAttempts: 6,
    baseDelay: 0.25,
    multiplier: 2.0,
    maxDelay: 10.0
)

do {
    let result = try await withRetry(
        policy: policy,
        shouldRetry: { error in
            (error as? URLError)?.code == .timedOut
        }
    ) {
        try await flakyFetch()
    }
    print(result)
} catch {
    print("Gave up: \(error)")
}
```

## Key Design Notes

| Feature | Why it matters |
|---|---|
| **Full jitter** (`random(in: 0...capped)`) | Spreads retries across clients, preventing thundering-herd spikes. Alternatives: *equal jitter* (half fixed + half random) or *decorrelated jitter* for smoother distributions. |
| **`shouldRetry` predicate** | Lets callers skip retrying on 4xx errors, decoding failures, cancellation, etc. |
| **`Task.sleep`** | Cancellation-aware — if the parent task is cancelled during a backoff, the retry chain unwinds cleanly. |
| **Capped max delay** | Prevents unbounded growth after many attempts. |

If you want, I can extend this with **decorrelated jitter**, a `RetryPolicy` that also honors `Retry-After` headers, or a `Result`-based (non-throwing) variant.

```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint64_t hash;
    int node;
} Point;

typedef struct {
    Point *points;
    size_t len;
    size_t cap;
    int vnodes;   /* virtual nodes per physical node */
} Ring;

/* FNV-1a 64-bit hash */
static uint64_t fnv1a(const char *s) {
    uint64_t h = 1469598103934665603ULL;
    while (*s) {
        h ^= (unsigned char)*s++;
        h *= 1099511628211ULL;
    }
    return h;
}

static int cmp_point(const void *a, const void *b) {
    const Point *pa = a;
    const Point *pb = b;

    if (pa->hash < pb->hash) return -1;
    if (pa->hash > pb->hash) return 1;
    if (pa->node < pb->node) return -1;
    if (pa->node > pb->node) return 1;
    return 0;
}

Ring *ring_create(int vnodes) {
    Ring *r = malloc(sizeof *r);
    if (!r) return NULL;

    r->points = NULL;
    r->len = 0;
    r->cap = 0;
    r->vnodes = vnodes > 0 ? vnodes : 1;
    return r;
}

void ring_free(Ring *r) {
    if (!r) return;
    free(r->points);
    free(r);
}

int ring_add_node(Ring *r, int node_id, const char *name) {
    size_t need = r->len + (size_t)r->vnodes;

    if (need > r->cap) {
        size_t newcap = r->cap ? r->cap * 2 : 16;
        while (newcap < need) newcap *= 2;

        Point *p = realloc(r->points, newcap * sizeof *p);
        if (!p) return -1;

        r->points = p;
        r->cap = newcap;
    }

    for (int i = 0; i < r->vnodes; ++i) {
        char buf[512];
        snprintf(buf, sizeof buf, "%s#%d", name, i);

        r->points[r->len].hash = fnv1a(buf);
        r->points[r->len].node = node_id;
        ++r->len;
    }

    qsort(r->points, r->len, sizeof *r->points, cmp_point);
    return 0;
}

int ring_remove_node(Ring *r, int node_id) {
    size_t j = 0;

    for (size_t i = 0; i < r->len; ++i) {
        if (r->points[i].node != node_id) {
            r->points[j++] = r->points[i];
        }
    }

    if (j == r->len) return -1; /* node not found */

    r->len = j;
    return 0;
}

int ring_get_node(const Ring *r, const char *key) {
    if (r->len == 0) return -1;

    uint64_t h = fnv1a(key);

    /* Find first point with hash >= h */
    size_t lo = 0, hi = r->len;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (r->points[mid].hash < h) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    /* Wrap around */
    if (lo == r->len) lo = 0;

    return r->points[lo].node;
}

/* ---------- usage example ---------- */

int main(void) {
    Ring *ring = ring_create(3); /* 3 virtual nodes per server */
    if (!ring) return 1;

    ring_add_node(ring, 0, "server-A");
    ring_add_node(ring, 1, "server-B");
    ring_add_node(ring, 2, "server-C");

    const char *keys[] = {
        "user:1", "user:2", "user:3", "user:4", "user:5"
    };

    for (size_t i = 0; i < sizeof keys / sizeof keys[0]; ++i) {
        printf("%-8s -> node %d\n", keys[i], ring_get_node(ring, keys[i]));
    }

    printf("\nRemoving server-B (node 1)...\n");
    ring_remove_node(ring, 1);

    for (size_t i = 0; i < sizeof keys / sizeof keys[0]; ++i) {
        printf("%-8s -> node %d\n", keys[i], ring_get_node(ring, keys[i]));
    }

    ring_free(ring);
    return 0;
}
```

In production, you would usually use more virtual nodes, such as `100` to `1000` per physical node, and a stronger hash such as MurmurHash, xxHash, or SipHash.

