    const Point *pa = a;
    const Point *pb = b;
    if (pa->hash < pb->hash) return -1;
    if (pa->hash > pb->hash) return 1;
    if (pa->node < pb->node) return -1;
    if (pa->node > pb->node) return 1;
    return 0;
}

