fn parse_iso8601_duration(s: &str) -> Result<u64, &'static str> {
    let mut chars = s.chars();

    if chars.next() != Some('P') {
        return Err("missing P");
    }

    let mut total = 0u64;
    let mut num = 0u64;
    let mut have_num = false;
    let mut in_time = false;
    let mut have_component = false;

    for c in chars {
        match c {
            '0'..='9' => {
                num = num
                    .checked_mul(10)
                    .ok_or("overflow")?
                    .checked_add(c as u64 - '0' as u64)
                    .ok_or("overflow")?;
                have_num = true;
            }
            'T' => {
                if have_num {
                    return Err("missing designator before T");
                }
                if in_time {
                    return Err("duplicate T");
                }
                in_time = true;
            }
            'D' => {
                if in_time {
                    return Err("D after T");
                }
                if !have_num {
                    return Err("missing number");
                }
                total = total
                    .checked_add(num.checked_mul(86_400).ok_or("overflow")?)
                    .ok_or("overflow")?;
                num = 0;
                have_num = false;
                have_component = true;
            }
            'H' => {
                if !in_time {
                    return Err("H before T");
                }
                if !have_num {
                    return Err("missing number");
                }
                total = total
                    .checked_add(num.checked_mul(3_600).ok_or("overflow")?)
                    .ok_or("overflow")?;
                num = 0;
                have_num = false;
                have_component = true;
            }
            'M' => {
                // Minimal version treats M as minutes only, so it must be after T.
                if !in_time {
                    return Err("months not supported");
                }
                if !have_num {
                    return Err("missing number");
                }
                total = total
                    .checked_add(num.checked_mul(60).ok_or("overflow")?)
                    .ok_or("overflow")?;
                num = 0;
                have_num = false;
                have_component = true;
            }
            'S' => {
                if !in_time {
                    return Err("S before T");
                }
                if !have_num {
                    return Err("missing number");
                }
                total = total.checked_add(num).ok_or("overflow")?;
                num = 0;
                have_num = false;
                have_component = true;
            }
            _ => return Err("invalid character"),
        }
    }

    if have_num {
        return Err("missing designator");
    }
    if !have_component {
