```rust
#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;
    use rand_chacha::ChaCha8Rng;

    #[test]
    fn fills_during_prefix() {
        let mut s = ReservoirSampler::new(3, ChaCha8Rng::seed_from_u64(0));
        for i in 0..3 { assert!(s.offer(i)); }
        assert_eq!(s.len(), 3);
        assert!(s.is_full());
    }

    #[test]
    fn never_exceeds_capacity() {
        let mut s = ReservoirSampler::new(10, ChaCha8Rng::seed_from_u64(0));
        for i in 0..10_000 { s.offer(i); }
        assert_eq!(s.len(), 10);
        assert_eq!(s.seen(), 10_000);
    }

    #[test]
    fn distribution_is_uniform() {
        // 10_000 trials sampling 1 of 3 items should be near-uniform.
        let mut counts = [0usize; 3];
        let trials = 10_000;
        for seed in 0..trials {
            let mut s = ReservoirSampler::new(1, ChaCha8Rng::seed_from_u64(seed));
            for i in 0..3 { s.offer(i); }
            counts[s.into_sample()[0]] += 1;
        }
        for c in counts {
            let p = c as f64 / trials as f64;
            assert!((p - 1.0 / 3.0).abs() < 0.03, "biased: {counts:?}");
        }
    }
}
```

The distribution test is the one that actually catches logic bugs — a poorly-placed `<` vs `<=` in `offer` will pass everything else and fail this.

Here's a production-ready Dijkstra implementation with a binary heap, using an adjacency list:

```cpp
#include <cstdint>
#include <functional>
#include <limits>
#include <queue>
#include <unordered_map>
#include <vector>

// Graph representation: adjacency list keyed by node id.
// Nodes are int32_t; edge weight is int64_t to avoid overflow when summing
// many edge weights. If your weights fit in int32_t and path lengths are
// bounded, you can switch to int32_t for Hal's sake, but int64_t is the
// safe default.
using NodeId = int32_t;
using Weight = int64_t;

struct Edge {
    NodeId to;
    Weight weight;
};

using AdjacencyList = std::unordered_map<NodeId, std::vector<Edge>>;

constexpr Weight kInfinity = std::numeric_limits<Weight>::max();

struct Result {
    // dist[v] is the shortest distance from source to v. Unreachable nodes
    // are omitted from the map (not present as a key).
    std::unordered_map<NodeId, Weight> dist;
    // parent[v] is the predecessor of v on a shortest path from source.
    // source has no entry. Unreachable nodes have no entry.
    std::unordered_map<NodeId, NodeId> parent;
};

// Compute single-source shortest paths using Dijkstra's algorithm.
//
// Requirements:
//   - All edge weights must be non-negative. This is not checked at runtime;
//     it is the caller's responsibility (Dijkstra is incorrect otherwise).
//   - The adjacency list must contain an entry for every node you want to
//     reach, including nodes with no outgoing edges (use an empty vector).
//     The source need not have an entry if it has no outgoing edges.
//
// Complexity: O((V + E) log V) time, O(V) auxiliary space beyond the graph.
//
// Notes on the heap:
//   std::priority_queue is a max-heap; we flip the comparison to get a
//   min-heap. We push a (distance, node) pair whenever we improve a node's
//   distance. This means the heap may contain multiple entries per node —
//   "stale" entries with an outdated distance. We discard them lazily by
//   comparing the popped distance against dist[node]. This is the standard
//   "lazy deletion" pattern and is preferred over a decrease-key heap
//   because std::priority_queue has no decrease-key and hand-rolled
//   Fibonacci heaps are rarely worth the complexity in practice.
Result Dijkstra(const AdjacencyList& graph, NodeId source) {
    Result result;
    auto& dist = result.dist;
    auto& parent = result.parent;

    // Min-heap of (distance, node). The greater<> comparator makes the
    // "largest" element the one with the smallest distance.
    using QueueEntry = std::pair<Weight, NodeId>;
    std::priority_queue<QueueEntry,
                        std::vector<QueueEntry>,
                        std::greater<QueueEntry>>
        frontier;

    dist[source] = 0;
    frontier.emplace(0, source);

    while (!frontier.empty()) {
        auto [d, u] = frontier.top();
        frontier.pop();

        // Stale entry: we already found a shorter path to u. Skip it.
        //
        // This check is what makes lazy deletion correct. Without it, we
        // would relax u's edges again with an outdated distance, which can
        // only fail to improve anything (or worse, corrupt parent links if
        // we weren't careful). We short-circuit rather than re-check each
        // edge.
        auto it = dist.find(u);
        if (it != dist.end() && d > it->second) {
            continue;
        }

        // u is now finalized: d == dist[u] is the true shortest distance.
        // (Invariant: once a node is popped with a non-stale entry, its
        // distance is final. This is why Dijkstra requires non-negative
        // weights.)
        auto adj_it = graph.find(u);
        if (adj_it == graph.end()) {
            continue;
        }

        for (const Edge& e : adj_it->second) {
            // Guard against overflow when adding weights. If d + e.weight
            // would overflow, treat this candidate as unreachable (it
            // cannot be a shortest path if it wraps around).
            if (d > kInfinity - e.weight) {
                continue;
            }
            const Weight candidate = d + e.weight;

            auto existing = dist.find(e.to);
            if (existing == dist.end() || candidate < existing->second) {
                dist[e.to] = candidate;
                parent[e.to] = u;
                frontier.emplace(candidate, e.to);
            }
        }
    }

    return result;
}
```

### Key design decisions

**Adjacency list as `unordered_map`.** This lets you handle sparse node id spaces (e.g., ids from an external system) without a separate id-remapping pass. If your nodes are dense `0..N-1`, replace it with `std::vector<std::vector<Edge>>` — it'll be faster and simpler.

**`int64_t` weights.** Summing many `int32_t` weights can silently overflow on long paths. `int64_t` costs nothing meaningful and removes the footgun. The overflow guard in the relaxation step handles the case where users pass `INT64_MAX` as "infinity."

**Lazy deletion instead of decrease-key.** `std::priority_queue` has no `decrease_key`. The classic alternative — pushing a new entry and discarding stale ones on pop — is well-understood, cache-friendly, and avoids a hand-rolled indexed heap. The cost is up to O(E) entries in the heap, but that's fine for typical workloads (see complexity note).

**Early termination.** The implementation runs to completion. If you only need the distance to a single target, add a `if (u == target) break;` after the stale check — the invariant that popped nodes are finalized guarantees correctness.

**Returning a `Result` struct.** Distances and parents together are what callers actually want. Omitted keys (rather than `INT64_MAX`) make "unreachable" easy to detect via `contains()` and avoid mixing sentinel values into business logic.

### Things that commonly bite people

1. **Negative edges silently produce wrong answers.** Dijkstra assumes that once a node is popped, no cheaper path exists. A negative edge violates this. If your data might have negative weights, use Bellman-Ford (or Johnson's algorithm for all-pairs).
2. **Missing entries in the adjacency map.** Nodes with no outgoing edges don't need an empty vector if they're never sources *from* — the `find(u) == end()` check handles it. But if you `find` the source and it's absent, that's fine too. Just don't confuse "node doesn't exist" with "node has no edges."
3. **Stale-entry check placement.** It must come *before* relaxing `u`'s edges. If you check inside the edge loop, you'll relax with an outdated `d`.
4. **Self-loops with weight 0** are harmless; self-loops with positive weight are harmless; self-loops with negative weight are the negative-edge problem in disguise.
5. **Thread safety.** The function is pure w.r.t. the input graph and allocates its own state, so it's safe to call concurrently on the same graph as long as no one mutates it concurrently.

### If you need to go faster

- Replace the `unordered_map`s with `std::vector` indexed by a dense node id. This alone is often a 2–5× speedup.
- Use `std::pair<Weight, NodeId>` ordering: `std::greater` on `pair` compares the `Weight` first, which is what you want. Don't accidentally store `(node, dist)`.
- If your graph is dense (E ≈ V²), use the O(V²) array-based Dijkstra instead — it beats heap-based for sufficiently dense graphs.

For most production services, this version is the right balance: correct, readable, and fast enough that the network I/O around it will dominate.

Below is a complete CUDA C++ implementation of a host function `lcs_cuda` that computes the longest common subsequence (LCS) of two `std::string`s. It uses a device kernel that fills the DP table by anti‑diagonals, then copies the table back to the host and reconstructs the LCS.

It also includes a set of unit tests written with Google Test that cover the main edge cases.

---

## `lcs_cuda.h`

```cpp
#pragma once

#include <string>

// Computes the longest common subsequence of `a` and `b` using CUDA.
// Returns the LCS as a std::string.
std::string lcs_cuda(const std::string& a, const std::string& b);
```

---

## `lcs_cuda.cu`

```cpp
#include "lcs_cuda.h"

#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <vector>

#include <cuda_runtime.h>

#define CUDA_CHECK(call)                                                     \
    do {                                                                     \
        cudaError_t err = (call);                                            \
        if (err != cudaSuccess) {                                            \
            std::cerr << "CUDA error at " << __FILE__ << ":" << __LINE__     \
                      << " code=" << err << " \"" << cudaGetErrorString(err) \
                      << "\"" << std::endl;                                  \
            std::exit(EXIT_FAILURE);                                         \
        }                                                                    \
    } while (0)

// Each thread computes one cell dp[i][j] on the anti-diagonal d = i + j.
// All dependencies of a cell lie on previous anti-diagonals, so cells on the
// same anti-diagonal are independent.
__global__ void lcs_diag_kernel(const char* a, int m,
                                const char* b, int n,
                                int d, int* dp) {
    const int t = blockIdx.x * blockDim.x + threadIdx.x;

    // Valid i for this diagonal: 1 <= i <= m, 1 <= j <= n, j = d - i
    const int i_start = max(1, d - n);
    const int i_end   = min(m, d - 1);
    const int count   = i_end - i_start + 1;

    if (t >= count) return;

    const int i = i_start + t;
    const int j = d - i;
    const int idx = i * (n + 1) + j;

    const int up    = dp[(i - 1) * (n + 1) + j];
    const int left  = dp[i * (n + 1) + (j - 1)];
    const int diag  = dp[(i - 1) * (n + 1) + (j - 1)];

    const int eq = (a[i - 1] == b[j - 1]) ? 1 : 0;
    const int cand = diag + eq;
    const int best = (up > left) ? up : left;

    dp[idx] = (best > cand) ? best : cand;
}

std::string lcs_cuda(const std::string& a, const std::string& b) {
    const int m = static_cast<int>(a.size());
    const int n = static_cast<int>(b.size());

    if (m == 0 || n == 0) {
        return "";
    }

    // Allocate DP table (m+1) x (n+1) and initialize to zero.
    const size_t dp_size = static_cast<size_t>(m + 1) * (n + 1) * sizeof(int);
    int* d_dp = nullptr;
    CUDA_CHECK(cudaMalloc(&d_dp, dp_size));
    CUDA_CHECK(cudaMemset(d_dp, 0, dp_size));

    // Copy input strings to device.
    char* d_a = nullptr;
    char* d_b = nullptr;
    CUDA_CHECK(cudaMalloc(&d_a, m));
    CUDA_CHECK(cudaMalloc(&d_b, n));
    CUDA_CHECK(cudaMemcpy(d_a, a.data(), m, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(d_b, b.data(), n, cudaMemcpyHostToDevice));

    // Launch one kernel per anti-diagonal.
    const int max_diag = m + n;
    const int threads = 256;

    for (int d = 2; d <= max_diag; ++d) {
        const int i_start = std::max(1, d - n);
        const int i_end   = std::min(m, d - 1);
        const int count   = i_end - i_start + 1;
        if (count <= 0) continue;

        const int blocks = (count + threads - 1) / threads;
        lcs_diag_kernel<<<blocks, threads>>>(d_a, m, d_b, n, d, d_dp);
        CUDA_CHECK(cudaGetLastError());
    }

    CUDA_CHECK(cudaDeviceSynchronize());

    // Copy DP table back to host.
    std::vector<int> dp((m + 1) * (n + 1));
    CUDA_CHECK(cudaMemcpy(dp.data(), d_dp, dp_size, cudaMemcpyDeviceToHost));

    // Reconstruct the LCS by backtracking.
    std::string result;
    int i = m;
    int j = n;
    while (i > 0 && j > 0) {
        if (a[i - 1] == b[j - 1] &&
            dp[i * (n + 1) + j] == dp[(i - 1) * (n + 1) + (j - 1)] + 1) {
            result.push_back(a[i - 1]);
            --i;
            --j;
        } else if (dp[(i - 1) * (n + 1) + j] >=
                   dp[i * (n + 1) + (j - 1)]) {
            --i;
        } else {
            --j;
        }
    }

    std::reverse(result.begin(), result.end());

    // Clean up.
    CUDA_CHECK(cudaFree(d_dp));
    CUDA_CHECK(cudaFree(d_a));
    CUDA_CHECK(cudaFree(d_b));

    return result;
}
```

