## Unit tests (`test_lcs_cuda.cpp`)

```cpp
#include <gtest/gtest.h>

#include <string>

#include "lcs_cuda.h"

TEST(LCS_CudaTest, EmptyStrings) {
    EXPECT_EQ(lcs_cuda("", ""), "");
}

TEST(LCS_CudaTest, OneEmpty) {
    EXPECT_EQ(lcs_cuda("abc", ""), "");
    EXPECT_EQ(lcs_cuda("", "abc"), "");
}

TEST(LCS_CudaTest, NoCommonCharacters) {
    EXPECT_EQ(lcs_cuda("abc", "def"), "");
}

TEST(LCS_CudaTest, IdenticalStrings) {
    EXPECT_EQ(lcs_cuda("abcdef", "abcdef"), "abcdef");
}

TEST(LCS_CudaTest, SingleCharacterMatch) {
    EXPECT_EQ(lcs_cuda("a", "a"), "a");
}

TEST(LCS_CudaTest, SingleCharacterMismatch) {
    EXPECT_EQ(lcs_cuda("a", "b"), "");
}

TEST(LCS_CudaTest, SimpleSubsequence) {
    EXPECT_EQ(lcs_cuda("abcde", "ace"), "ace");
    EXPECT_EQ(lcs_cuda("AGGTAB", "GXTXAYB"), "GTAB");
}

TEST(LCS_CudaTest, RepeatingCharacters) {
    // LCS length is 2; our backtracking returns "aa" for these inputs.
    EXPECT_EQ(lcs_cuda("aaaa", "aa"), "aa");
    EXPECT_EQ(lcs_cuda("aba", "baa"), "aa");
}

TEST(LCS_CudaTest, OrderMatters) {
    EXPECT_EQ(lcs_cuda("abc", "cba"), "a"); // any one character is valid, but our algorithm returns "a"
}

TEST(LCS_CudaTest, LongStrings) {
    std::string a(1000, 'a');
    std::string b(1000, 'a');
    EXPECT_EQ(lcs_cuda(a, b), a);

    std::string c;
    std::string d;
    for (int i = 0; i < 500; ++i) {
        c += 'a';
        d += 'a';
    }
    EXPECT_EQ(lcs_cuda(c, d), c);
}

TEST(LCS_CudaTest, MixedContent) {
    EXPECT_EQ(lcs_cuda("dynamic programming", "programming"),
              "programming");
    EXPECT_EQ(lcs_cuda("hello world", "world hello"), "hello");
}
```

