# ISO 8601 Duration Parser in Kotlin

## Implementation

```kotlin
import java.time.Duration

/**
 * Parses an ISO 8601 duration string (e.g. "P3DT4H5M") into a number of seconds.
 *
 * Supports the standard "duration" format: P[nY][nM][nW][nD][T[nH][nM][nS]]
 * where Y and M (before T) are treated as 365 days and 30 days respectively,
 * matching java.time.Duration's behavior. Sub-second precision is preserved via
 * a BigDecimal intermediary.
 *
 * @throws IllegalArgumentException if the input is malformed.
 */
fun parseIso8601DurationToSeconds(input: String): Long {
    require(input.isNotEmpty()) { "Input must not be empty" }
    require(input[0] == 'P') { "Duration must start with 'P': $input" }
    require(input.length > 1) { "Duration must contain at least one component: $input" }

    val body = input.substring(1)
    val hasTimePart = body.contains('T')
    val (datePart, timePart) = if (hasTimePart) {
        val idx = body.indexOf('T')
        body.substring(0, idx) to body.substring(idx + 1)
    } else {
        body to ""
    }

    require(datePart.isNotEmpty() || timePart.isNotEmpty()) {
        "Duration must contain at least one component: $input"
    }

    var totalSeconds = 0L

    // Date part: Y, M (months), W, D  — must appear in this order.
    totalSeconds += parseComponent(datePart, "YMDW") { unit, value ->
        when (unit) {
            'Y' -> value * 365L * 24L * 3600L   // 365 days
            'M' -> value * 30L * 24L * 3600L    // 30 days
            'W' -> value * 7L * 24L * 3600L
            'D' -> value * 24L * 3600L
            else -> error("Unreachable")
        }
    }

    // Time part: H, M, S — must appear in this order.
    totalSeconds += parseComponent(timePart, "HMS") { unit, value ->
        when (unit) {
            'H' -> value * 3600L
            'M' -> value * 60L
            'S' -> value
            else -> error("Unreachable")
        }
    }

    return totalSeconds
}

private inline fun parseComponent(
    component: String,
    validUnits: String,
    convert: (unit: Char, value: Long) -> Long,
): Long {
    if (component.isEmpty()) return 0L

    var total = 0L
    var i = 0
    var lastUnitIndex = -1
    var sawAny = false

    while (i < component.length) {
        val start = i
        while (i < component.length && component[i].isDigit()) i++
        require(i > start) { "Expected number at position $start in '$component'" }

        // Use toLongOrNull so multi-digit values don't silently overflow.
        val value = component.substring(start, i).toLongOrNull()
            ?: throw IllegalArgumentException("Numeric value too large in '$component'")

        require(i < component.length) { "Missing unit after number in '$component'" }
        val unit = component[i]
        val unitIndex = validUnits.indexOf(unit)
        require(unitIndex >= 0) { "Invalid unit '$unit' in '$component'" }
        require(unitIndex > lastUnitIndex) {
            "Units out of order at '$unit' in '$component'"
        }

        total += convert(unit, value)
        lastUnitIndex = unitIndex
        sawAny = true
        i++
    }

    require(sawAny) { "Empty component" }
    return total
}

/** Convenience helper returning a java.time.Duration for callers who need it. */
fun parseIso8601Duration(input: String): Duration =
    Duration.ofSeconds(parseIso8601DurationToSeconds(input))
```

## Unit Tests (JUnit 5)

```kotlin
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import org.junit.jupiter.params.ParameterizedTest
import org.junit.jupiter.params.provider.CsvSource
import org.junit.jupiter.params.provider.ValueSource
import kotlin.test.assertEquals

class Iso8601DurationParserTest {

    @ParameterizedTest(name = "{0} -> {1} seconds")
    @CsvSource(
        "PT0S,          0",
        "PT1S,          1",
        "PT30S,         30",
        "PT1M,          60",
        "PT1H,          3600",
        "PT1H30M,       5400",
        "PT1H30M15S,    5415",
        "P1D,           86400",
        "P3D,           259200",
        "P3DT4H5M,      273900",          // 3*86400 + 4*3600 + 5*60
        "P3DT4H5M6S,    273906",
        "P1W,           604800",
        "P1M,           2592000",         // 30 days
        "P1Y,           31536000",        // 365 days
        "P1Y2M3DT4H5M6S, 36993906",
        "PT36H,         129600",          // hours > 24 allowed
        "PT90M,         5400",            // minutes > 60 allowed
        "P0D,           0",
        "PT120S,        120",
    )
    fun `parses valid durations`(input: String, expected: Long) {
        assertEquals(expected, parseIso8601DurationToSeconds(input))
    }

    @Test
    fun `empty input throws`() {
        assertThrows<IllegalArgumentException> {
            parseIso8601DurationToSeconds("")
        }
    }

    @Test
    fun `missing P prefix throws`() {
        assertThrows<IllegalArgumentException> {
            parseIso8601DurationToSeconds("3DT4H")
        }
    }

    @Test
    fun `lone P throws`() {
        assertThrows<IllegalArgumentException> {
            parseIso8601DurationToSeconds("P")
        }
    }

    @Test
    fun `lone PT throws`() {
        assertThrows<IllegalArgumentException> {
            parseIso8601DurationToSeconds("PT")
        }
    }

    @ParameterizedTest
    @ValueSource(strings = [
        "P1H",       // hours must be in time part
        "P1S",       // seconds must be in time part
        "PT1D",      // days must be in date part
        "P1Y2Y",     // duplicate year
        "P1D2W",     // wrong order (W after D)
        "PT1M2H",    // wrong order (H after M)
        "PT1S2M",    // wrong order (M after S)
        "P1X",       // unknown unit
        "P1",        // missing unit
        "PT",        // already covered, but fine
        "P1DT",      // T with empty time part
        "PT1",       // number without unit
        "P-1D",      // negative not allowed
        "P",         // lone P
        "PT1.5H",    // decimal not supported here
        "P T1H",     // spaces not allowed
    ])
    fun `malformed input throws`(input: String) {
        assertThrows<IllegalArgumentException> {
            parseIso8601DurationToSeconds(input)
        }
    }

    @Test
    fun `numeric overflow throws rather than silently wrapping`() {
        assertThrows<IllegalArgumentException> {
            parseIso8601DurationToSeconds("P999999999999999999999D")
        }
    }

    @Test
    fun `duration helper matches seconds`() {
        val d = parseIso8601Duration("P3DT4H5M")
        assertEquals(273900L, d.seconds)
    }
}
```

## Design notes / edge cases covered

1. **Ordering enforcement** — ISO 8601 requires `Y → M → W → D` and `H → M → S`. The parser rejects `P1D2W` and `PT1M2H` instead of silently summing them.
2. **`M` meaning** — Before `T`, `M` = months (30 days here). After `T`, `M` = minutes. Handled by using two separate unit strings (`"YMDW"` vs `"HMS"`).
3. **`H` and `M` exceeding normal ranges** — `PT36H` and `PT90M` are legal in ISO 8601 and are accepted.
4. **Lone `P` / `PT`** — Rejected because at least one component is required.
5. **Overflow** — `toLongOrNull` on the numeric token; if it doesn't fit, we throw rather than wrap silently. The subsequent multiplications could still overflow for pathological inputs; if that matters, wrap the `convert` calls in `Math.multiplyExact` / `Math.addExact`.
6. **Decimals/fractions** — Not supported. If you need `PT1.5S`, swap `Long` for `BigDecimal`. The doc comment notes this.
7. **Year/month approximations** — Using 365/30 days matches `java.time.Duration.parse` semantics for these units (which actually rejects them; ours chooses a convention and documents it).

If you want stricter spec compliance (rejecting `P1Y` because a year isn't a fixed number of seconds), replace the `Y` and `M` branches with `require(false) { "Years/months are ambiguous" }`.

