type EditOperation =
  | { type: "insert"; index: number; char: string }
  | { type: "delete"; index: number; char: string }
  | { type: "substitute"; index: number; from: string; to: string };

interface EditDistanceResult {
  distance: number;
  script: EditOperation[];
}

/**
 * Computes the Levenshtein edit distance from `source` to `target`,
 * and returns the operations needed to transform `source` into `target`.
 *
 * Costs:
 * - insert: 1
 * - delete: 1
 * - substitute: 1
 */
export function editDistanceAndScript(
  source: string,
  target: string
): EditDistanceResult {
  const m = source.length;
  const n = target.length;

  // dp[i][j] = edit distance between source[0..i) and target[0..j)
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    Array(n + 1).fill(0)
  );

  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const substitutionCost = source[i - 1] === target[j - 1] ? 0 : 1;

      dp[i][j] = Math.min(
        dp[i - 1][j] + 1, // delete
        dp[i][j - 1] + 1, // insert
        dp[i - 1][j - 1] + substitutionCost // substitute or match
      );
    }
  }

  const script: EditOperation[] = [];
  let i = m;
  let j = n;

  while (i > 0 || j > 0) {
    if (
      i > 0 &&
      j > 0 &&
      source[i - 1] === target[j - 1] &&
      dp[i][j] === dp[i - 1][j - 1]
    ) {
      // Characters match: no edit operation needed.
      i--;
      j--;
    } else if (
      i > 0 &&
      j > 0 &&
      dp[i][j] === dp[i - 1][j - 1] + 1
    ) {
      script.push({
        type: "substitute",
        index: i - 1,
        from: source[i - 1],
        to: target[j - 1],
      });
      i--;
      j--;
    } else if (j > 0 && dp[i][j] === dp[i][j - 1] + 1) {
      script.push({
        type: "insert",
        index: i,
        char: target[j - 1],
      });
      j--;
    } else if (i > 0 && dp[i][j] === dp[i - 1][j] + 1) {
      script.push({
        type: "delete",
        index: i - 1,
        char: source[i - 1],
      });
      i--;
    } else {
      throw new Error("Unreachable edit-distance backtracking state");
    }
  }

  script.reverse();

  return {
    distance: dp[m][n],
    script,
  };
}

// Usage example
const result = editDistanceAndScript("kitten", "sitting");

console.log(result.distance); // 3

console.log(result.script);
