#include <cuda_runtime.h>
#include <cstdio>

__global__ void validateSudokuKernel(const int* __restrict__ board,
                                     int* __restrict__ valid)
{
    const int tid = threadIdx.x;
    if (tid >= 27) return;

    unsigned int seen = 0;

    // Threads 0..8  : validate rows
    // Threads 9..17 : validate columns
    // Threads 18..26: validate 3x3 boxes
    if (tid < 9) {
        const int r = tid;
        #pragma unroll
        for (int c = 0; c < 9; ++c) {
            const int v = board[r * 9 + c];
            if (v == 0) continue;                 // empty cell
            if (v < 1 || v > 9) {                 // malformed input
                atomicExch(valid, 0);
                return;
            }
            const unsigned int bit = 1u << (v - 1);
            if (seen & bit) {
                atomicExch(valid, 0);
                return;
            }
            seen |= bit;
        }
    } else if (tid < 18) {
        const int c = tid - 9;
        #pragma unroll
        for (int r = 0; r < 9; ++r) {
            const int v = board[r * 9 + c];
            if (v == 0) continue;
            if (v < 1 || v > 9) {
                atomicExch(valid, 0);
                return;
            }
            const unsigned int bit = 1u << (v - 1);
            if (seen & bit) {
                atomicExch(valid, 0);
                return;
            }
            seen |= bit;
        }
    } else {
        const int b = tid - 18;
        const int br = (b / 3) * 3;
        const int bc = (b % 3) * 3;

        #pragma unroll
        for (int i = 0; i < 3; ++i) {
            #pragma unroll
            for (int j = 0; j < 3; ++j) {
                const int v = board[(br + i) * 9 + (bc + j)];
                if (v == 0) continue;
                if (v < 1 || v > 9) {
                    atomicExch(valid, 0);
                    return;
                }
                const unsigned int bit = 1u << (v - 1);
                if (seen & bit) {
                    atomicExch(valid, 0);
                    return;
                }
                seen |= bit;
            }
        }
    }
}

bool validateSudoku(const int* h_board)
{
    int* d_board = nullptr;
    int* d_valid = nullptr;
    int h_valid = 1;

    cudaMalloc(&d_board, 81 * sizeof(int));
    cudaMalloc(&d_valid, sizeof(int));

    cudaMemcpy(d_board, h_board, 81 * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_valid, &h_valid, sizeof(int), cudaMemcpyHostToDevice);

    // One block, 27 active threads: 9 rows + 9 columns + 9 boxes
    validateSudokuKernel<<<1, 32>>>(d_board, d_valid);

    cudaMemcpy(&h_valid, d_valid, sizeof(int), cudaMemcpyDeviceToHost);

    cudaFree(d_board);
    cudaFree(d_valid);

    return h_valid != 0;
}
```

### How it works

- `0` represents an empty cell and is ignored.
- Each of the 27 threads checks one Sudoku unit:
  - 9 threads check rows,
  - 9 threads check columns,
  - 9 threads check the 3×3 boxes.
- A bitmask `seen` tracks digits already seen in that unit.
- If a non-zero digit repeats, or is outside `1..9`, the kernel atomically sets `valid = 0`.
- The host copies the final `valid` flag back and returns it.

### Complexity

For a fixed 9×9 Sudoku board:

- **Time:**  
  The kernel launches 27 threads. Each thread checks at most 9 cells, so total work is at most  
  `27 * 9 = 243` cell checks.  
  Therefore the kernel is **O(1)** for a standard 9×9 Sudoku.  
  The host-device memory transfers are `O(81)`, also effectively `O(1)`.

- **Space:**  
  Device memory uses:
  - `81` integers for the board,
  - `1` integer for the validity flag.  
  Each thread uses one `unsigned int` bitmask.  
  Extra space is **O(1)** for a fixed 9×9 board.

If generalized to an `n² × n²` Sudoku board, the work becomes proportional to the number of cells, so time and space are **O(N)**, where `N` is the number of cells. For the standard 9×9 case, this is constant.

