__global__ void validateSudokuKernel(const int* __restrict__ board,
                                     int* __restrict__ valid)
{
    int tid = threadIdx.x;
    if (tid >= 27) return;

    unsigned int seen = 0;

    if (tid < 9) {
        int r = tid;
        #pragma unroll
        for (int c = 0; c < 9; ++c) {
            int v = board[r * 9 + c];
            if (v == 0) continue;
            if (v < 1 || v > 9) { atomicExch(valid, 0); return; }
            unsigned int bit = 1u << (v - 1);
            if (seen & bit) { atomicExch(valid, 0); return; }
            seen |= bit;
        }
    } else if (tid < 18) {
        int c = tid - 9;
        #pragma unroll
        for (int r = 0; r < 9; ++r) {
            int v = board[r * 9 + c];
            ...
        }
    } else {
        int b = tid - 18;
        int br = (b / 3) * 3;
        int bc = (b % 3) * 3;
        #pragma unroll
        for (int i = 0; i < 3; ++i) {
            #pragma unroll
            for (int j = 0; j < 3; ++j) {
                int v = board[(br + i) * 9 + (bc + j)];
                ...
            }
        }
    }
}
