        }

        assert_eq!(heap.peek(), Some(&1));

        let mut popped = Vec::new();
        while let Some(x) = heap.pop() {
            popped.push(x);
        }

        assert_eq!(popped, vec![1, 2, 3, 4, 5, 7, 8]);
    }

