```swift
/// Returns one directed cycle if the graph contains one, otherwise `nil`.
///
/// The returned cycle is a path whose first and last elements are the same node,
/// e.g. `[A, B, C, A]`. A self-loop is returned as `[A, A]`.
///
/// Nodes that only appear as edge destinations are handled as nodes with no
/// outgoing edges.
///
/// Complexity: O(V + E) time and O(V) memory.
func findCycle<Node: Hashable>(in graph: [Node: [Node]]) -> [Node]? {
    enum VisitState {
        case white // unvisited
        case gray  // currently on the DFS stack
        case black // fully explored
    }

    // Copy the graph so we can add nodes that only appear as destinations.
    var adjacency = graph
    for neighbors in graph.values {
        for neighbor in neighbors where adjacency[neighbor] == nil {
            adjacency[neighbor] = []
        }
    }

    var state: [Node: VisitState] = [:]
    var path: [Node] = []
    var pathIndex: [Node: Int] = [:]

    // Iterative DFS. This avoids stack overflow on large or adversarial graphs.
    for start in adjacency.keys {
        if (state[start] ?? .white) != .white {
            continue
        }

        var stack: [(node: Node, nextNeighborIndex: Int)] = [(start, 0)]

        state[start] = .gray
        path.append(start)
        pathIndex[start] = path.count - 1

        while let top = stack.last {
            let node = top.node
            let neighbors = adjacency[node] ?? []

            if top.nextNeighborIndex < neighbors.count {
                let neighbor = neighbors[top.nextNeighborIndex]

                // Advance the frame before descending or detecting a cycle.
                stack[stack.count - 1].nextNeighborIndex += 1

                switch state[neighbor] ?? .white {
                case .white:
                    state[neighbor] = .gray
                    path.append(neighbor)
                    pathIndex[neighbor] = path.count - 1
                    stack.append((neighbor, 0))

                case .gray:
                    // Finding a gray node means we found a back edge.
                    // The gray node is on the current DFS path, so the cycle is
                    // path[cycleStart...] + neighbor.
                    guard let cycleStart = pathIndex[neighbor] else {
                        // This should be impossible: gray nodes are exactly the
                        // nodes currently in `path`.
                        continue
                    }

                    var cycle = Array(path[cycleStart...])
                    cycle.append(neighbor)
                    return cycle

                case .black:
                    // Already fully explored and known to be safe.
                    continue
                }
            } else {
                // Finish this node.
                stack.removeLast()
                state[node] = .black
                path.removeLast()
                pathIndex[node] = nil
            }
        }
    }

    return nil
}
```

Usage:

```swift
let graph = [
    "A": ["B"],
    "B": ["C"],
    "C": ["A"]
]

if let cycle = findCycle(in: graph) {
    print(cycle) // e.g. ["A", "B", "C", "A"]
