```ts
type TopologicalSortResult =
  | { ok: true; order: string[] }
  | { ok: false; cycle: true };

export function topologicalSort(
  graph: Map<string, string[]>
): TopologicalSortResult {
  const indegree = new Map<string, number>();

  const ensureNode = (node: string) => {
    if (!indegree.has(node)) indegree.set(node, 0);
  };

  // Make sure every node appears in indegree, including edge targets
  for (const [node, neighbors] of graph) {
    ensureNode(node);
    for (const neighbor of neighbors) ensureNode(neighbor);
  }

  // Count incoming edges
  for (const [, neighbors] of graph) {
    for (const neighbor of neighbors) {
      indegree.set(neighbor, indegree.get(neighbor)! + 1);
    }
  }

  const queue: string[] = [];
  for (const [node, degree] of indegree) {
    if (degree === 0) queue.push(node);
  }

  const order: string[] = [];
  let head = 0;

  while (head < queue.length) {
    const node = queue[head++];
    order.push(node);

    for (const neighbor of graph.get(node) ?? []) {
      const nextDegree = indegree.get(neighbor)! - 1;
      indegree.set(neighbor, nextDegree);

      if (nextDegree === 0) {
        queue.push(neighbor);
      }
    }
  }

  // If not all nodes were processed, there is a cycle
  if (order.length !== indegree.size) {
    return { ok: false, cycle: true };
  }

  return { ok: true, order };
}
```

