const graph = new Map<string, string[]>([
  ["A", ["C"]],
  ["B", ["C", "D"]],
  ["C", ["E"]],
  ["D", ["E"]],
  ["E", []],
]);

const result = topologicalSort(graph);

if (result.ok) {
  console.log("Topological order:", result.order.join(" -> "));
} else {
  console.log("Cycle detected");
}

// Cycle example
const cyclicGraph = new Map<string, string[]>([
  ["A", ["B"]],
  ["B", ["A"]],
]);

const cyclicResult = topologicalSort(cyclicGraph);

if (!cyclicResult.ok) {
  console.log("Cycle detected"); // This will print
}
```

