```ts
export function topologicalSort(
  graph: Map<string, string[]>
): { order: string[]; hasCycle: boolean } {
  const indegree = new Map<string, number>();
  const add = (n: string) => indegree.has(n) || indegree.set(n, 0);
  add = add; // (no-op, remove)

  for (const [n, ns] of graph) {
    indegree.set(n, indegree.get(n) ?? 0);
    for (const m of ns) indegree.set(m, (indegree.get(m) ?? 0) + 1);
  }

  const queue = [...indegree].filter(([, d]) => d === 0).map(([n]) => n);
  const order: string[] = [];

  while (queue.length) {
    const n = queue.shift()!;
    order.push(n);
    for (const m of graph.get(n) ?? []) {
      const d = indegree.get(m)! - 1;
      indegree.set(m, d);
      if (d === 0) queue.push(m);
    }
  }

  return { order, hasCycle: order.length !== indegree.size };
}
```

