```go
package tree

// Node is a node in a binary tree.
type Node[T any] struct {
	Value T
	Left  *Node[T]
	Right *Node[T]
}

// InOrder visits every non-nil node in in-order: Left, Node, Right.
//
// It uses an explicit stack instead of recursion, so it is safe for very deep
// trees: goroutine stack usage is O(1), while the explicit stack is O(h) on
// the heap. The tree must not be mutated while traversal is in progress.
//
// visit is called exactly once per non-nil node. It must not be nil.
func InOrder[T any](root *Node[T], visit func(T)) {
	// Small initial capacity. Do not pre-size to tree height unless you know
	// it; pathological trees can be deep, and a large up-front allocation is
	// usually wasteful.
	stack := make([]*Node[T], 0, 16)

	cur := root

	for cur != nil || len(stack) > 0 {
		// Tricky part 1:
		// Walk down the left spine, pushing every node. The top of the stack
		// is then the next node in in-order, because all of its left subtree
		// has already been traversed.
		for cur != nil {
			stack = append(stack, cur)
			cur = cur.Left
		}

		// Pop the next node to visit.
		top := stack[len(stack)-1]

		// Tricky part 2:
		// Slicing alone leaves the popped pointer in the backing array.
		// Clearing it avoids retaining the node until that slot is overwritten.
		// This is optional for correctness, but good hygiene in a long-running
		// service.
		stack[len(stack)-1] = nil
		stack = stack[:len(stack)-1]

		visit(top.Value)

		// Tricky part 3:
		// After visiting a node, its right subtree is next in in-order.
		// If Right is nil, the next loop iteration pops the nearest ancestor
		// whose left side we have finished.
		cur = top.Right
	}
}
```

If you need a slice instead of streaming values, wrap it:

```go
func InOrderSlice[T any](root *Node[T]) []T {
	out := make([]T, 0)
	InOrder(root, func(v T) {
		out = append(out, v)
	})
	return out
}
```

For production services that need cancellation or error propagation, prefer a callback that can stop early:

```go
func InOrderErr[T any](root *Node[T], visit func(T) error) error {
	stack := make([]*Node[T], 0, 16)
	cur := root

	for cur != nil || len(stack) > 0 {
		for cur != nil {
			stack = append(stack, cur)
			cur = cur.Left
		}

		top := stack[len(stack)-1]
		stack[len(stack)-1] = nil
		stack = stack[:len(stack)-1]

		if err := visit(top.Value); err != nil {
			return err
		}

		cur = top.Right
	}

	return nil
}
