```python
import bisect
import hashlib

class ConsistentHashRing:
    def __init__(self, nodes=None, vnodes=100):
        self.vnodes = vnodes
        self._ring = {}       # hash -> node
        self._keys = []       # sorted hashes
        for node in nodes or []:
            self.add_node(node)

    @staticmethod
    def _hash(key):
        return int(hashlib.md5(str(key).encode()).hexdigest()[:8], 16)

    def add_node(self, node):
        for i in range(self.vnodes):
            h = self._hash(f"{node}:{i}")
            if h not in self._ring:
                self._ring[h] = node
        self._keys = sorted(self._ring)

    def remove_node(self, node):
        for i in range(self.vnodes):
            h = self._hash(f"{node}:{i}")
            if self._ring.get(h) == node:
                del self._ring[h]
        self._keys = sorted(self._ring)

    def get_node(self, key):
        if not self._ring:
            return None
        h = self._hash(key)
        idx = bisect.bisect(self._keys, h) % len(self._keys)
        return self._ring[self._keys[idx]]
```

Two ways it can fail under load:

1. **Hotspot / uneven distribution**  
   With too few virtual nodes, or a skewed hash distribution, one physical node can own a disproportionate share of hot keys. Under load, that node saturates while others sit mostly idle.

2. **Cascading overload after membership change**  
   When a node dies or is removed, its keys are remapped to successor nodes. If those successors are already near capacity, or if many clients miss cache at once after the ring changes, they can overload and fail too, shifting even more load onward.

```go
// unionfind.go
package unionfind

// UnionFind is a disjoint-set data structure using path compression and
// union by rank.
type UnionFind struct {
	parent []int
	rank   []int
	count  int
}

// New returns a UnionFind containing n singleton sets: 0..n-1.
// It panics if n is negative.
func New(n int) *UnionFind {
	if n < 0 {
		panic("unionfind: negative size")
	}

	parent := make([]int, n)
	rank := make([]int, n)
	for i := range parent {
		parent[i] = i
	}

	return &UnionFind{
		parent: parent,
		rank:   rank,
		count:  n,
	}
}

// Find returns the representative/root of the set containing x.
// It uses path compression.
func (uf *UnionFind) Find(x int) int {
	uf.mustBeValid(x)

	root := x
	for uf.parent[root] != root {
		root = uf.parent[root]
	}

	// Compress the path from x to root.
	for uf.parent[x] != x {
		next := uf.parent[x]
		uf.parent[x] = root
		x = next
	}

	return root
}

// Union merges the sets containing x and y.
// It returns true if a merge happened, or false if x and y were already
// in the same set.
func (uf *UnionFind) Union(x, y int) bool {
	rx := uf.Find(x)
	ry := uf.Find(y)

	if rx == ry {
		return false
	}

	// Union by rank: attach the shorter tree under the taller tree.
	if uf.rank[rx] < uf.rank[ry] {
		rx, ry = ry, rx
	}
	uf.parent[ry] = rx

	if uf.rank[rx] == uf.rank[ry] {
		uf.rank[rx]++
	}

	uf.count--
	return true
}

// Connected reports whether x and y belong to the same set.
func (uf *UnionFind) Connected(x, y int) bool {
	return uf.Find(x) == uf.Find(y)
}

// Count returns the number of disjoint sets.
func (uf *UnionFind) Count() int {
	return uf.count
}

func (uf *UnionFind) mustBeValid(x int) {
	if x < 0 || x >= len(uf.parent) {
		panic("unionfind: index out of range")
	}
}
