			t.Fatalf("Count() = %d, want 0", got)
		}
	})

	t.Run("one element", func(t *testing.T) {
		uf := New(1)

		if got := uf.Count(); got != 1 {
			t.Fatalf("Count() = %d, want 1", got)
		}
		if got := uf.Find(0); got != 0 {
			t.Fatalf("Find(0) = %d, want 0", got)
		}
		if !uf.Connected(0, 0) {
			t.Fatal("Connected(0, 0) = false, want true")
		}
		if uf.Union(0, 0) {
			t.Fatal("Union(0, 0) = true, want false")
		}
	})

	t.Run("negative size", func(t *testing.T) {
		assertPanics(t, func() {
			New(-1)
		})
	})
}

