	uf := New(5)

	if got := uf.Count(); got != 5 {
		t.Fatalf("initial Count() = %d, want 5", got)
	}

	if !uf.Union(0, 1) {
		t.Fatal("Union(0, 1) = false, want true")
	}
	if got := uf.Count(); got != 4 {
		t.Fatalf("Count() after Union(0, 1) = %d, want 4", got)
	}
	if !uf.Connected(0, 1) {
		t.Fatal("Connected(0, 1) = false, want true")
	}

	// Already connected: reverse order should not merge again.
	if uf.Union(1, 0) {
		t.Fatal("Union(1, 0) = true, want false")
	}
	if got := uf.Count(); got != 4 {
		t.Fatalf("Count() after redundant Union(1, 0) = %d, want 4", got)
	}

	if !uf.Union(1, 2) {
		t.Fatal("Union(1, 2) = false, want true")
	}
	if !uf.Connected(0, 2) {
		t.Fatal("Connected(0, 2) = false, want true")
	}

	if !uf.Union(3, 4) {
		t.Fatal("Union(3, 4) = false, want true")
	}
	if uf.Connected(0, 3) {
		t.Fatal("Connected(0, 3) = true before merge, want false")
	}

	if !uf.Union(2, 3) {
		t.Fatal("Union(2, 3) = false, want true")
	}
	if got := uf.Count(); got != 1 {
		t.Fatalf("Count() after merging all = %d, want 1", got)
	}

	for i := 0; i < 5; i++ {
		for j := 0; j < 5; j++ {
			if !uf.Connected(i, j) {
				t.Fatalf("Connected(%d, %d) = false, want true", i, j)
			}
		}
	}

	if uf.Union(0, 4) {
		t.Fatal("Union(0, 4) = true, want false")
	}
}

func TestFindPathCompression(t *testing.T) {
