package unionfind

type UnionFind struct {
	parent []int
	rank   []int
	count  int
}

// New returns a UnionFind with n singleton sets.
func New(n int) *UnionFind {
	if n < 0 {
		panic("unionfind: negative size")
	}
	parent := make([]int, n)
	rank := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	return &UnionFind{
		parent: parent,
		rank:   rank,
		count:  n,
	}
}

// Find returns the representative of x's set.
func (uf *UnionFind) Find(x int) int {
	uf.mustBeValid(x)

	root := x
	for uf.parent[root] != root {
		root = uf.parent[root]
	}

	for uf.parent[x] != x {
		next := uf.parent[x]
		uf.parent[x] = root
		x = next
	}
	return root
}

// Union merges sets containing x and y. It reports whether a merge happened.
func (uf *UnionFind) Union(x, y int) bool {
	rx := uf.Find(x)
	ry := uf.Find(y)
	if rx == ry {
		return false
	}

	if uf.rank[rx] < uf.rank[ry] {
		rx, ry = ry, rx
	}
	uf.parent[ry] = rx
	if uf.rank[rx] == uf.rank[ry] {
		uf.rank[rx]++
	}
	uf.count--
	return true
}

// Connected reports whether x and y are in the same set.
func (uf *UnionFind) Connected(x, y int) bool {
	return uf.Find(x) == uf.Find(y)
}

// Count returns the number of disjoint sets.
func (uf *UnionFind) Count() int {
	return uf.count
}

func (uf *UnionFind) mustBeValid(x int) {
	if x < 0 || x >= len(uf.parent) {
		panic("unionfind: index out of range")
	}
}

