package scan

import (
	"runtime"
	"sync"
)

// minParallelLen is a tuning knob. Below this, goroutine overhead usually
// costs more than it saves. Benchmark for your workload.
const minParallelLen = 1 << 14 // 16,384 elements

// InclusiveScan replaces data with its inclusive prefix sums:
//
//	data[i] = sum(data[0:i+1])
//
// It modifies data in place.
//
// This implementation uses a chunked two-pass scan:
//
//  1. Split data into chunks. In parallel, compute each chunk's local
//     inclusive prefix sum and record the chunk total.
//  2. Sequentially scan the small chunk-total array to get an exclusive
//     offset for every chunk.
//  3. In parallel, add each chunk's offset to every element in that chunk.
//
// The result is an inclusive scan.
//
// Notes for production use:
//   - Safe for distinct slices, but do not mutate the same slice concurrently.
//   - Uses sync.WaitGroup for happens-before synchronization. The second pass
//     must not start until all chunk totals are written.
//   - Caps parallelism by GOMAXPROCS and by a minimum amount of work per
//     goroutine to avoid goroutine explosion on small or medium inputs.
//   - For float types, parallel addition changes associativity, so results may
//     differ slightly from a sequential scan. For integer types, overflow
//     wraps consistently modulo the type width in Go.
func InclusiveScan(data []int64) {
	n := len(data)
	if n < 2 {
		return
	}

	if n < minParallelLen {
		inclusiveScanSeq(data)
		return
	}

	maxWorkers := runtime.GOMAXPROCS(0)
	if maxWorkers < 1 {
		maxWorkers = 1
	}

	// Start with one chunk per minParallelLen, then cap by available workers.
	numChunks := (n + minParallelLen - 1) / minParallelLen
	if numChunks > maxWorkers {
		numChunks = maxWorkers
	}
	if numChunks <= 1 {
		inclusiveScanSeq(data)
		return
	}

	// Make chunks as even as possible. Recompute numChunks because the final
	// chunk may be shorter.
	chunkSize := (n + numChunks - 1) / numChunks
	numChunks = (n + chunkSize - 1) / chunkSize

	chunkSums := make([]int64, numChunks)

	// Pass 1: local inclusive prefix sum per chunk.
	var wg sync.WaitGroup
	wg.Add(numChunks)

	for c := 0; c < numChunks; c++ {
		start := c * chunkSize
		end := start + chunkSize
		if end > n {
			end = n
		}

		go func(c, start, end int) {
			defer wg.Done()

			var sum int64
			for i := start; i < end; i++ {
				sum += data[i]
				data[i] = sum
			}
			chunkSums[c] = sum
		}(c, start, end)
	}
	wg.Wait()

	// Convert chunk sums into exclusive offsets.
	//
	// chunkSums[c] becomes the sum of all elements before chunk c.
	var acc int64
	for c := 0; c < numChunks; c++ {
		s := chunkSums[c]
		chunkSums[c] = acc
		acc += s
	}

	// Pass 2: add each chunk's exclusive offset to every element in it.
	for c := 0; c < numChunks; c++ {
		off := chunkSums[c]
		if off == 0 {
			// First chunk, or a prefix that happens to be zero.
			continue
		}

		start := c * chunkSize
		end := start + chunkSize
		if end > n {
			end = n
		}

		wg.Add(1)
		go func(start, end int, off int64) {
			defer wg.Done()
			for i := start; i < end; i++ {
				data[i] += off
			}
		}(start, end, off)
	}
	wg.Wait()
}

func inclusiveScanSeq(data []int64) {
	var sum int64
	for i, v := range data {
		sum += v
		data[i] = sum
	}
}
