```rust
#[derive(Debug)]
pub struct AudioRingBuffer<T> {
    buf: Vec<T>,
    capacity: usize,
    head: usize, // index of the oldest sample
    len: usize,
}

impl<T: Copy + Default> AudioRingBuffer<T> {
    /// Creates a new ring buffer.
    ///
    /// # Panics
    ///
    /// Panics if `capacity == 0`.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be greater than zero");

        Self {
            buf: vec![T::default(); capacity],
            capacity,
            head: 0,
            len: 0,
        }
    }

    pub fn capacity(&self) -> usize {
        self.capacity
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn is_full(&self) -> bool {
        self.len == self.capacity
    }

    /// Pushes a sample into the buffer.
    ///
    /// If the buffer is full, the oldest sample is overwritten.
    pub fn push(&mut self, sample: T) {
        if self.is_full() {
            // Overwrite the oldest sample and advance the read head.
            self.buf[self.head] = sample;
            self.head = (self.head + 1) % self.capacity;
            // `len` stays equal to `capacity`.
        } else {
            let tail = (self.head + self.len) % self.capacity;
            self.buf[tail] = sample;
            self.len += 1;
        }
    }

    /// Pops the oldest sample from the buffer.
    ///
    /// Returns `None` if the buffer is empty.
    pub fn pop(&mut self) -> Option<T> {
        if self.is_empty() {
            return None;
        }

        let sample = self.buf[self.head];
        self.head = (self.head + 1) % self.capacity;
        self.len -= 1;
        Some(sample)
    }

    /// Removes all samples logically, but keeps the allocated storage.
    pub fn clear(&mut self) {
        self.head = 0;
        self.len = 0;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_buffer_is_empty() {
        let rb = AudioRingBuffer::<f32>::new(4);

        assert_eq!(rb.capacity(), 4);
        assert_eq!(rb.len(), 0);
        assert!(rb.is_empty());
        assert!(!rb.is_full());
    }

    #[test]
    fn push_and_pop_basic() {
        let mut rb = AudioRingBuffer::new(3);

        rb.push(1);
        rb.push(2);

        assert_eq!(rb.len(), 2);
        assert!(!rb.is_empty());
        assert!(!rb.is_full());

        assert_eq!(rb.pop(), Some(1));
        assert_eq!(rb.pop(), Some(2));
        assert_eq!(rb.pop(), None);
        assert!(rb.is_empty());
    }

    #[test]
    fn pop_empty_returns_none() {
        let mut rb = AudioRingBuffer::<i16>::new(4);

        assert_eq!(rb.pop(), None);
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn overwrite_on_full_keeps_newest_samples() {
        let mut rb = AudioRingBuffer::new(3);

        rb.push(1);
        rb.push(2);
        rb.push(3);

        assert!(rb.is_full());
        assert_eq!(rb.len(), 3);

        rb.push(4); // overwrites 1

        assert!(rb.is_full());
        assert_eq!(rb.len(), 3);

        assert_eq!(rb.pop(), Some(2));
        assert_eq!(rb.pop(), Some(3));
        assert_eq!(rb.pop(), Some(4));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn capacity_one_overwrites_immediately() {
        let mut rb = AudioRingBuffer::new(1);

        rb.push(1);
        rb.push(2);
        rb.push(3);

        assert_eq!(rb.len(), 1);
        assert!(rb.is_full());

        assert_eq!(rb.pop(), Some(3));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn interleaved_push_and_pop() {
        let mut rb = AudioRingBuffer::new(3);

        rb.push(1);
        rb.push(2);

        assert_eq!(rb.pop(), Some(1));

        rb.push(3);
        rb.push(4);

        assert_eq!(rb.pop(), Some(2));
        assert_eq!(rb.pop(), Some(3));

        rb.push(5);

        assert_eq!(rb.pop(), Some(4));
        assert_eq!(rb.pop(), Some(5));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn clear_resets_buffer() {
        let mut rb = AudioRingBuffer::new(3);

        rb.push(1);
        rb.push(2);
        rb.push(3);

        assert!(rb.is_full());

        rb.clear();

        assert_eq!(rb.len(), 0);
        assert!(rb.is_empty());
        assert!(!rb.is_full());
        assert_eq!(rb.pop(), None);

        rb.push(4);
        assert_eq!(rb.pop(), Some(4));
    }

    #[test]
    #[should_panic(expected = "capacity must be greater than zero")]
    fn zero_capacity_panics() {
        let _ = AudioRingBuffer::<f32>::new(0);
    }
}
```

