# Debounce Helper in Swift

Here's a clean, testable implementation of a debounce helper, plus unit tests covering the tricky edge cases.

## Implementation

```swift
import Foundation

/// Debounces calls to a closure: only the last call within the `delay`
/// window is actually executed. Note: this helper requires a run loop
/// (useful for UI code); it is NOT thread-safe across queues.
final class Debouncer {
    private let delay: TimeInterval
    private let queue: DispatchQueue
    private var workItem: DispatchWorkItem?
    private let lock = NSLock()

    init(delay: TimeInterval, queue: DispatchQueue = .main) {
        self.delay = delay
        self.queue = queue
    }

    /// Schedule `action` to run after `delay` seconds from the last call.
    /// Any previously scheduled action that has not yet fired is cancelled.
    func call(_ action: @escaping () -> Void) {
        lock.lock()
        workItem?.cancel()
        let item = DispatchWorkItem(block: action)
        workItem = item
        lock.unlock()
        queue.asyncAfter(deadline: .now() + delay, execute: item)
    }

    /// Cancel any pending action without executing it.
    func cancel() {
        lock.lock()
        workItem?.cancel()
        workItem = nil
        lock.unlock()
    }

    /// Flush: run the pending action immediately (if any) and cancel the delay.
    func flush() {
        lock.lock()
        let item = workItem
        workItem = nil
        lock.unlock()
        item?.perform()
    }
}
```

### Why a class, not a free function?

Debounce requires **state** (the pending `DispatchWorkItem`), so a reference type with a persistent handle is the natural fit. This makes it easy to test deterministically by injecting the queue and delay.

## Unit Tests

Using XCTest. The key trick for deterministic tests is a **custom serial queue** plus expectations, plus small delays that don't make tests flaky.

```swift
import XCTest

final class DebouncerTests: XCTestCase {

    /// Small delay so tests run fast; use a serial utility queue so calls
    /// are ordered but still asynchronous to the test thread.
    private func makeSUT(delay: TimeInterval = 0.05) -> (Debouncer, DispatchQueue) {
        let queue = DispatchQueue(label: "test.debounce")
        return (Debouncer(delay: delay, queue: queue), queue)
    }

    // MARK: - Happy path

    func testExecutesOnceAfterDelay() {
        let (sut, _) = makeSUT(delay: 0.05)
        let exp = expectation(description: "runs once")
        var count = 0

        sut.call {
            count += 1
            exp.fulfill()
        }

        wait(for: [exp], timeout: 1.0)
        // Give any spurious extra runs a chance to appear.
        let extra = expectation(description: "sanity")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { extra.fulfill() }
        wait(for: [extra], timeout: 1.0)

        XCTAssertEqual(count, 1)
    }

    // MARK: - Coalescing

    func testCoalescesRapidCalls() {
        let (sut, _) = makeSUT(delay: 0.1)
        let exp = expectation(description: "final call")
        var count = 0
        var lastValue = -1

        // Fire 5 rapid calls; only the last should execute.
        for i in 0..<5 {
            sut.call {
                count += 1
                lastValue = i
                if i == 4 { exp.fulfill() }
            }
        }

        wait(for: [exp], timeout: 1.0)

        // Allow any erroneously scheduled earlier ones to fire before asserting.
        let settle = expectation(description: "settle")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) { settle.fulfill() }
        wait(for: [settle], timeout: 1.0)

        XCTAssertEqual(count, 1, "Only the last call should run")
        XCTAssertEqual(lastValue, 4, "The last-scheduled closure wins")
    }

    // MARK: - Calls with gap > delay both run

    func testCallsSeparatedByMoreThanDelayBothRun() {
        let (sut, _) = makeSUT(delay: 0.05)
        let exp1 = expectation(description: "first")
        let exp2 = expectation(description: "second")

        sut.call { exp1.fulfill() }

        // Wait long enough that the first fires.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
            sut.call { exp2.fulfill() }
        }

        wait(for: [exp1, exp2], timeout: 1.0)
    }

    // MARK: - Cancel

    func testCancelPreventsExecution() {
        let (sut, _) = makeSUT(delay: 0.05)
        var ran = false

        sut.call { ran = true }
        sut.cancel()

        let settle = expectation(description: "settle")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) { settle.fulfill() }
        wait(for: [settle], timeout: 1.0)

        XCTAssertFalse(ran)
    }

    func testCancelThenNewCallStillRuns() {
        let (sut, _) = makeSUT(delay: 0.05)
        let exp = expectation(description: "runs")

        sut.call { XCTFail("should have been cancelled") }
        sut.cancel()
        sut.call { exp.fulfill() }

        wait(for: [exp], timeout: 1.0)
    }

    // MARK: - Flush

    func testFlushExecutesImmediately() {
        let (sut, _) = makeSUT(delay: 10.0) // huge delay
        var ran = false

        sut.call { ran = true }
        XCTAssertFalse(ran, "Should not have run yet")

        sut.flush()
        XCTAssertTrue(ran, "Flush should run the pending action immediately")
    }

    func testFlushWithNothingPendingIsNoOp() {
        let (sut, _) = makeSUT()
        sut.flush() // should not crash
    }

    func testFlushThenOriginalDelayDoesNotDoubleRun() {
        let (sut, _) = makeSUT(delay: 0.05)
        var count = 0

        sut.call { count += 1 }
        sut.flush()

        let settle = expectation(description: "settle")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) { settle.fulfill() }
        wait(for: [settle], timeout: 1.0)

        XCTAssertEqual(count, 1, "Flushed action must not run again after the delay")
    }

    // MARK: - Edge: very small delay

    func testZeroDelayStillCoalescesSynchronouslyScheduledCalls() {
        // With zero delay the asyncAfter still schedules on the queue, so
        // back-to-back calls from the same thread should coalesce.
        let (sut, _) = makeSUT(delay: 0)
        let exp = expectation(description: "final")
        var count = 0

        for _ in 0..<3 { sut.call { count += 1 } }
        sut.call { count += 1; exp.fulfill() }

        wait(for: [exp], timeout: 1.0)

        let settle = expectation(description: "settle")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) { settle.fulfill() }
        wait(for: [settle], timeout: 1.0)

