// calc.go
package calc

import (
	"errors"
	"fmt"
	"strconv"
)

type TokenType int

const (
	TokenNumber TokenType = iota
	TokenPlus
	TokenMinus
	TokenStar
	TokenSlash
	TokenLParen
	TokenRParen
	TokenEOF
)

type Token struct {
	Type TokenType
	Text string
}

func Tokenize(input string) ([]Token, error) {
	tokens := make([]Token, 0, len(input))

	for i := 0; i < len(input); {
		c := input[i]

		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++

		case c == '+':
			tokens = append(tokens, Token{Type: TokenPlus, Text: "+"})
			i++

		case c == '-':
			tokens = append(tokens, Token{Type: TokenMinus, Text: "-"})
			i++

		case c == '*':
			tokens = append(tokens, Token{Type: TokenStar, Text: "*"})
			i++

		case c == '/':
			tokens = append(tokens, Token{Type: TokenSlash, Text: "/"})
			i++

		case c == '(':
			tokens = append(tokens, Token{Type: TokenLParen, Text: "("})
			i++

		case c == ')':
			tokens = append(tokens, Token{Type: TokenRParen, Text: ")"})
			i++

		case isDigit(c) || c == '.':
			start := i
			dotCount := 0
			hasDigit := false

			for i < len(input) && (isDigit(input[i]) || input[i] == '.') {
				if input[i] == '.' {
					dotCount++
				}
				if isDigit(input[i]) {
					hasDigit = true
				}
				i++
			}

			text := input[start:i]

			if dotCount > 1 {
				return nil, fmt.Errorf("invalid number %q", text)
			}
			if !hasDigit {
				return nil, fmt.Errorf("invalid number %q", text)
			}

			tokens = append(tokens, Token{Type: TokenNumber, Text: text})

		default:
			return nil, fmt.Errorf("unexpected character %q", c)
		}
	}

	tokens = append(tokens, Token{Type: TokenEOF})
	return tokens, nil
}

func Evaluate(input string) (float64, error) {
	tokens, err := Tokenize(input)
