        Self {
            value,
            left: None,
            right: None,
        }
    }
}

/// Iterative in-order traversal using an explicit stack.
fn inorder_iterative<'a, T>(root: &'a Option<Box<Node<T>>>) -> Vec<&'a T> {
    let mut result = Vec::new();
    let mut stack: Vec<&Node<T>> = Vec::new();
    let mut current = root.as_deref();

    while current.is_some() || !stack.is_empty() {
        // Go as far left as possible.
        while let Some(node) = current {
            stack.push(node);
            current = node.left.as_deref();
        }

        // Visit the node and move to its right subtree.
        current = stack.pop();
        if let Some(node) = current {
            result.push(&node.value);
            current = node.right.as_deref();
        }
    }

    result
}

fn main() {
    //        2
    //       / \
    //      1   3
    let root = Some(Box::new(Node {
        value: 2,
        left: Some(Box::new(Node::new(1))),
        right: Some(Box::new(Node::new(3))),
    }));

    let values = inorder_iterative(&root);
    println!("{:?}", values); // [1, 2, 3]
}
```

This avoids recursion entirely by keeping a `Vec` stack of borrowed nodes. The returned `Vec<&T>` contains references to values in the tree in in-order order.

