In Go, here is a rune-based longest common subsequence implementation, which handles Unicode correctly.

```go
package lcs

// LongestCommonSubsequence returns the longest common subsequence of a and b.
// If there are multiple valid LCSs, the returned one depends on the DP
// backtracking order used below.
func LongestCommonSubsequence(a, b string) string {
	ar := []rune(a)
	br := []rune(b)

	n, m := len(ar), len(br)

	// dp[i][j] = LCS length of ar[:i] and br[:j]
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}

	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if ar[i-1] == br[j-1] {
				dp[i][j] = dp[i-1][j-1] + 1
			} else if dp[i-1][j] >= dp[i][j-1] {
				dp[i][j] = dp[i-1][j]
			} else {
				dp[i][j] = dp[i][j-1]
			}
		}
	}

	// Backtrack to construct the actual subsequence.
	i, j := n, m
	result := make([]rune, 0, dp[n][m])

	for i > 0 && j > 0 {
		if ar[i-1] == br[j-1] {
			result = append(result, ar[i-1])
			i--
			j--
		} else if dp[i-1][j] >= dp[i][j-1] {
			i--
		} else {
			j--
		}
	}

	// The result was built backwards.
	for left, right := 0, len(result)-1; left < right; left, right = left+1, right-1 {
		result[left], result[right] = result[right], result[left]
	}

	return string(result)
}
```

