		},
		{
			name: "one is a subsequence",
			a:    "ace",
			b:    "abcdef",
			want: "ace",
		},
		{
			name: "classic example",
			a:    "AGGTAB",
			b:    "GXTXAYB",
			want: "GTAB",
		},
		{
			name: "repeated characters",
			a:    "aaaa",
			b:    "aa",
			want: "aa",
		},
		{
			name: "case sensitive",
			a:    "ABC",
			b:    "abc",
			want: "",
		},
		{
			name: "unicode",
			a:    "こんにちは",
			b:    "こにちわ",
			want: "こにち",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := LongestCommonSubsequence(tt.a, tt.b)
			if got != tt.want {
				t.Fatalf(
					"LongestCommonSubsequence(%q, %q) = %q, want %q",
					tt.a, tt.b, got, tt.want,
				)
			}
		})
	}
}
```

A few notes:

- The function uses `[]rune`, so it treats strings as sequences of Unicode code points rather than raw bytes.
- The DP table uses `O(n*m)` time and memory.
- If multiple LCSs exist, the function returns one valid LCS, not necessarily every possible one.

# Roman Numeral Converter in C++

## Implementation

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <stdexcept>
#include <cctype>

class RomanConverter {
private:
    // Ordered from largest to smallest for efficient greedy conversion
    static const std::vector<std::pair<int, std::string>>& valueMap() {
        static const std::vector<std::pair<int, std::string>> map = {
            {1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"},
            {100,  "C"}, {90,  "XC"}, {50,  "L"}, {40,  "XL"},
            {10,   "X"}, {9,   "IX"}, {5,   "V"}, {4,   "IV"},
            {1,    "I"}
        };
        return map;
    }

public:
    // ---------- Roman -> Integer ----------
    static int romanToInt(const std::string& roman) {
        if (roman.empty()) throw std::invalid_argument("Empty Roman numeral");

        std::unordered_map<char, int> values = {
            {'I', 1}, {'V', 5}, {'X', 10}, {'L', 50},
            {'C', 100}, {'D', 500}, {'M', 1000}
        };

        int result = 0;
        int n = static_cast<int>(roman.size());

        for (int i = 0; i < n; ++i) {
            char c = std::toupper(roman[i]);
            auto it = values.find(c);
            if (it == values.end())
                throw std::invalid_argument(std::string("Invalid Roman character: ") + c);

            int current = it->second;
            // If current value is less than next, it's a subtractive pair
            if (i + 1 < n) {
                char nextChar = std::toupper(roman[i + 1]);
                auto nextIt = values.find(nextChar);
                if (nextIt != values.end() && current < nextIt->second) {
                    result -= current;
                    continue;
                }
            }
            result += current;
        }
        return result;
    }

    // ---------- Integer -> Roman ----------
    static std::string intToRoman(int num) {
        if (num <= 0 || num > 3999)
            throw std::out_of_range("Number must be in range [1, 3999]");

        std::string result;
        result.reserve(15); // Max length for valid range is 15 ("MMMDCCCLXXXVIII")

        for (const auto& [value, symbol] : valueMap()) {
            while (num >= value) {
                result += symbol;
                num -= value;
            }
        }
        return result;
    }
};

// ---------- Demo ----------
int main() {
    std::string examples[] = {"III", "IV", "IX", "LVIII", "MCMXCIV", "MMMCMXCIX"};

    for (const auto& r : examples) {
        int n = RomanConverter::romanToInt(r);
        std::string back = RomanConverter::intToRoman(n);
        std::cout << r << " -> " << n << " -> " << back << '\n';
    }
    return 0;
}
```

**Sample output:**
```
III -> 3 -> III
IV -> 4 -> IV
IX -> 9 -> IX
LVIII -> 58 -> LVIII
MCMXCIV -> 1994 -> MCMXCIV
MMMCMXCIX -> 3999 -> MMMCMXCIX
```

## How It Works

### Roman → Integer
Iterate left-to-right. For each character:
- If its value is **less than** the next character's value, subtract it (subtractive notation like `IV`, `IX`, `CM`).
- Otherwise, add it.

This single-pass check handles all six subtractive cases (`IV`, `IX`, `XL`, `XC`, `CD`, `CM`).

### Integer → Roman
Greedy approach using a **descending** table of values, including the six subtractive pairs. Repeatedly subtract the largest value that fits and append its symbol.

---

## Complexity Analysis

Let **n** = length of the Roman numeral string, **d** = number of entries in the value table.

### `romanToInt`
| Resource | Complexity | Explanation |
|---|---|---|
| **Time** | **O(n)** | One pass over the string; each hash lookup is O(1). |
| **Space** | **O(1)** | Hash map has a fixed 7 entries regardless of input; only scalar variables used. |

### `intToRoman`
| Resource | Complexity | Explanation |
|---|---|---|
| **Time** | **O(log num)** — effectively **O(1)** | The output length grows logarithmically with `num` (Roman numerals are a base-10-ish system). Since `num` is capped at 3999, at most 15 symbols are appended. The greedy loop runs a constant number of iterations for any valid input. |
| **Space** | **O(1)** | Output string is at most 15 characters; the value table is constant size. |

### Combined round-trip
- **Time:** `O(n)` — dominated by parsing.
- **Space:** `O(1)` — everything is constant-bounded because the maximum representable value is constrained.

---

## Notes and Extensions

1. **Validation** — The strict Roman numeral parser here accepts some non-canonical-but-arithmetically-correct forms (e.g., `IIII` = 4). If strict canonical validation is required, add a post-check: convert the integer back and compare with the original string.
2. **Range limit** — Standard Roman numerals don't express 0 or negatives. The conventional upper bound is **3999** (`MMMCMXCIX`). Values ≥ 4000 require overbars (vinculum), which is out of scope here.
3. **Thread safety** — `valueMap()` uses a function-local `static`, initialized once (C++11 guarantees thread-safe initialization).
4. **Performance tweaks** — For very large batch workloads, replace the `unordered_map` in `romanToInt` with a 128-element lookup array indexed by ASCII code to avoid any hashing overhead — still O(1) but with a smaller constant factor.

