1. An iterative in-order traversal using an explicit stack (no recursion).
2. Unit tests covering empty tree, single node, skewed trees, balanced tree, duplicates/negative values, small output buffer, `NULL` output buffer, and a deep tree.

```c
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *left;
    struct Node *right;
} Node;

/*
 * Iterative in-order traversal without recursion.
 *
 * Writes node data into out[] in in-order. If out is NULL or the buffer
 * capacity is exceeded, writing stops, but the function still visits/counts
 * every node.
 *
 * Returns the total number of nodes visited.
 */
size_t inorder_iterative(const Node *root, int *out, size_t capacity) {
    const Node **stack = NULL;
    size_t top = 0;
    size_t stack_cap = 0;
    size_t count = 0;

    const Node *cur = root;

    while (cur != NULL || top > 0) {
        /* Go as far left as possible, pushing nodes onto the stack. */
        while (cur != NULL) {
            if (top == stack_cap) {
                size_t new_cap = stack_cap ? stack_cap * 2 : 16;
                const Node **tmp = realloc(stack, new_cap * sizeof *tmp);
                if (tmp == NULL) {
                    free(stack);
