package main

import "fmt"

// MinHeap is a min-heap backed by a slice.
type MinHeap []int

// NewMinHeap copies values and heapifies them in O(n).
func NewMinHeap(values []int) *MinHeap {
	h := MinHeap(append([]int(nil), values...))
	h.Heapify()
	return &h
}

// Len returns the number of elements in the heap.
func (h *MinHeap) Len() int {
	return len(*h)
}

// Push adds a value to the heap.
func (h *MinHeap) Push(x int) {
	*h = append(*h, x)
	h.siftUp(len(*h) - 1)
}

// Pop removes and returns the smallest value.
// The second return value is false if the heap is empty.
func (h *MinHeap) Pop() (int, bool) {
	n := len(*h)
	if n == 0 {
		return 0, false
	}

	root := (*h)[0]
	last := n - 1

	(*h)[0] = (*h)[last]
	*h = (*h)[:last]

	if len(*h) > 0 {
		h.siftDown(0)
	}

	return root, true
}

// Peek returns the smallest value without removing it.
func (h *MinHeap) Peek() (int, bool) {
	if len(*h) == 0 {
		return 0, false
	}
	return (*h)[0], true
}

// Heapify turns the underlying slice into a valid min-heap in O(n).
func (h *MinHeap) Heapify() {
	n := len(*h)
	for i := n/2 - 1; i >= 0; i-- {
		h.siftDown(i)
	}
}

func (h *MinHeap) siftUp(i int) {
	for i > 0 {
		parent := (i - 1) / 2
		if (*h)[parent] <= (*h)[i] {
			break
		}
		(*h)[parent], (*h)[i] = (*h)[i], (*h)[parent]
		i = parent
	}
}

func (h *MinHeap) siftDown(i int) {
	n := len(*h)

	for {
		left := 2*i + 1
		right := 2*i + 2
		smallest := i

		if left < n && (*h)[left] < (*h)[smallest] {
			smallest = left
		}
		if right < n && (*h)[right] < (*h)[smallest] {
			smallest = right
		}

		if smallest == i {
			break
		}

		(*h)[i], (*h)[smallest] = (*h)[smallest], (*h)[i]
		i = smallest
	}
}

func main() {
	h := NewMinHeap([]int{5, 3, 8, 1, 9, 2})

	h.Push(0)
	h.Push(4)

	for h.Len() > 0 {
		v, _ := h.Pop()
		fmt.Print(v, " ")
	}
	// Output: 0 1 2 3 4 5 8 9
}
