object CsvParser {

    /**
     * Parses a CSV string into rows of fields.
     *
     * Supports:
     * - comma-separated values
     * - quoted fields containing commas
     * - escaped quotes inside quoted fields as `""`
     * - quoted fields containing newlines
     * - both `\n` and `\r\n` line endings
     */
    fun parse(input: String): List<List<String>> {
        val rows = mutableListOf<List<String>>()
        var row = mutableListOf<String>()
        val field = StringBuilder()

        var i = 0
        var inQuotes = false

        while (i < input.length) {
            val c = input[i]

            if (inQuotes) {
                when {
                    c == '"' && i + 1 < input.length && input[i + 1] == '"' -> {
                        // Escaped quote: "" -> "
                        field.append('"')
                        i += 2
                    }

                    c == '"' -> {
                        // Closing quote
                        inQuotes = false
                        i++
                    }

                    else -> {
                        field.append(c)
                        i++
                    }
                }
            } else {
                when (c) {
                    '"' -> {
                        // A quote starts a quoted field only at the beginning of a field.
                        if (field.isEmpty()) {
                            inQuotes = true
                        } else {
                            field.append(c)
                        }
                        i++
                    }

                    ',' -> {
                        row.add(field.toString())
                        field.clear()
                        i++
                    }

                    '\r' -> {
                        row.add(field.toString())
                        field.clear()
                        rows.add(row)
                        row = mutableListOf()

                        i++
                        if (i < input.length && input[i] == '\n') {
                            i++
                        }
                    }

                    '\n' -> {
                        row.add(field.toString())
                        field.clear()
                        rows.add(row)
                        row = mutableListOf()
                        i++
                    }

                    else -> {
                        field.append(c)
                        i++
                    }
                }
            }
        }

        // Add the last field/row if there is pending data.
        // Avoids adding an extra empty row when the input ends with a newline.
        if (field.isNotEmpty() || row.isNotEmpty() || (input.isNotEmpty() && !input.endsWith('\n') && !input.endsWith('\r'))) {
            row.add(field.toString())
            rows.add(row)
        }

        return rows
    }
}
