```java
import java.util.ArrayList;
import java.util.List;

public final class CSVParser {
    private CSVParser() {}

    /**
     * Parses a CSV string into rows of fields.
     * Supports:
     *  - quoted fields: "a,b"
     *  - escaped quotes: "He said ""Hi"""
     *  - newlines inside quoted fields
     *  - CRLF and LF line endings
     */
    public static List<List<String>> parse(String csv) {
        List<List<String>> rows = new ArrayList<>();
        if (csv == null || csv.isEmpty()) {
            return rows;
        }

        List<String> currentRow = new ArrayList<>();
        StringBuilder currentField = new StringBuilder();
        boolean inQuotes = false;

        for (int i = 0; i < csv.length(); i++) {
            char c = csv.charAt(i);

            if (inQuotes) {
                if (c == '"') {
                    // Check for escaped quote ("")
                    if (i + 1 < csv.length() && csv.charAt(i + 1) == '"') {
                        currentField.append('"');
                        i++; // skip the second quote
                    } else {
                        inQuotes = false;
                    }
                } else {
                    currentField.append(c);
                }
            } else {
                if (c == '"' && currentField.length() == 0) {
                    inQuotes = true;
                } else if (c == ',') {
                    currentRow.add(currentField.toString());
                    currentField.setLength(0);
                } else if (c == '\n') {
                    currentRow.add(currentField.toString());
                    currentField.setLength(0);
                    rows.add(currentRow);
                    currentRow = new ArrayList<>();
                } else if (c == '\r') {
                    currentRow.add(currentField.toString());
                    currentField.setLength(0);
                    rows.add(currentRow);
                    currentRow = new ArrayList<>();
                    // Handle CRLF: skip the following \n
                    if (i + 1 < csv.length() && csv.charAt(i + 1) == '\n') {
                        i++;
                    }
                } else {
                    currentField.append(c);
                }
            }
        }

        // Add the last field and row if there is any data.
        if (currentField.length() > 0 || currentRow.size() > 0 || inQuotes) {
            currentRow.add(currentField.toString());
            rows.add(currentRow);
        }

        return rows;
    }

    // Usage example
    public static void main(String[] args) {
        String csv = "name,quote\nAlice,\"Hello, \"\"world\"\"\"\nBob,\"a,b,c\"";

        List<List<String>> rows = CSVParser.parse(csv);
        for (List<String> row : rows) {
            System.out.println(row);
        }
    }
}
```

Output:

```text
[name, quote]
[Alice, Hello, "world"]
[Bob, a,b,c]
```

