Below is a production-oriented C implementation. It uses:

- a local hash table to count words,
- a min-heap to keep the top `k`,
- ASCII-only tokenization and case folding (documented below),
- no global state, so it is reentrant.

For real Unicode text, you would normally plug in ICU or another Unicode-aware tokenizer/case-folder.

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *word;
    size_t count;
} WordFreq;

typedef struct {
    WordFreq *items;
    size_t len;
} WordFreqList;

/* ------------------------------------------------------------------------- */
/* Small helpers                                                             */
/* ------------------------------------------------------------------------- */

static char *xstrdup(const char *s)
{
    size_t len = strlen(s);
    char *copy = malloc(len + 1);
    if (copy == NULL) {
        return NULL;
    }
    memcpy(copy, s, len + 1);
    return copy;
}

static int is_ascii_word_char(unsigned char c)
{
    return (c >= 'a' && c <= 'z') ||
           (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9');
}

static unsigned char ascii_to_lower(unsigned char c)
{
    if (c >= 'A' && c <= 'Z') {
        return (unsigned char)(c + ('a' - 'A'));
    }
    return c;
}

/* ------------------------------------------------------------------------- */
/* Growable word buffer                                                      */
/* ------------------------------------------------------------------------- */

typedef struct {
    char *data;
    size_t len;
    size_t cap;
} WordBuf;

static int wordbuf_init(WordBuf *buf)
{
    buf->cap = 64;
    buf->len = 0;
    buf->data = malloc(buf->cap);
    if (buf->data == NULL) {
        return -1;
    }
    return 0;
}

static void wordbuf_free(WordBuf *buf)
{
